                               Game::Switches Game::Timer Game::MessageConfig
                               Game::Screen Game::ChipSet Game::Interpreter
                               RPG2k::Scene::Menu RPG2k::Scene::DebugMenu
                               RPG2k::Scene::ItemMenu Game::NumberInput
