    out << "      mrb_value r#{offset} = self;\n"
    out << "      r#{key_reg} = bc2cpp_ary_entry(M, bc2cpp_ekey_keys_#{region[:block_addr]}, " \
           "bc2cpp_ekey_i_#{region[:block_addr]});\n"
    out << body
    out << "      #{iter_label}:;\n"
    out << "    }\n"
    out << "    #{break_label}:;\n"
    out << "  }\n"
    out
  end

  # INTERP_UNLOCK: the inlined-loop replacement for one recognized
  # `Range#each` region (recognize_range_each_regions), or nil when the
  # block body doesn't come out clean -- same all-or-nothing contract
  # as emit_each_inline above, whose loop this clones with four
  # deliberate differences (each grounded in mrblib/range.rb's own
  # integer fast path, never assumed):
  #   - COUNTER, not fetch: the element is the loop index itself as a
  #     fixnum (`r<param> = mrb_fixnum_value(i)`), no `mrb_ary_ref`.
  #   - SNAPSHOT bounds: beg/end/excl read ONCE before looping (Ranges
  #     are frozen -- `range_initialize` freezes -- so no
  #     push-during-iteration analogue exists; unlike Array's live
  #     `RARRAY_LEN` re-check, a snapshot is exactly sound here).
  #   - OVERFLOW-SAFE comparison: `excl ? i < e : i <= e` instead of
  #     mrblib's own `lim = end + 1; i < lim` (which overflows at
  #     MRB_INT_MAX -- this formulation cannot).
  #   - GUARD is two-part: `mrb_range_p` (right class) AND Integer
  #     beg/end (the `succ`-path, Float edges, and nil-ended/endless
  #     ranges -- an endless range would be an infinite loop -- all
  #     raise rather than miscompile; unproven sites keep the honest
  #     `#error`). Uses the REAL excl flag from `mrb_range_excl_p`,
  #     never `begin == end` (a `1...1` exclusive range is empty while
  #     `begin == end` -- the source-level shortcut in
  #     do_control_switches is only valid because `range()` never
  #     builds `...`, and the emitter must not replicate that
  #     assumption).
  # Fall-through leaves dest holding the receiver (Range#each returns
  # self, mrblib/range.rb) -- no assignment, same as each. BREAK,
  # RETURN_BLK, upvars, jumps: identical handling via
  # compile_block_body_insn (same break_dest/break_label wiring).
  def emit_range_each_inline(region, irep, d)
    block_irep = region[:block_irep]
    offset = irep.nregs
    dest_reg = region[:dest_reg]
    recv = "r#{dest_reg}"
    param_reg = 1 + offset
    addr = region[:block_addr]

    label_prefix = "LBLK#{addr}_"
    iter_label = "Lbc2cpp_range_iter_#{addr}"
    break_label = "Lbc2cpp_range_end_#{addr}"
    body = String.new
    # INLINE_NESTED_BLOCK_SUPPORT: claim any nested block-carrying call in
    # this body BEFORE compiling it (see inline_nested_block_pass), so a
    # region this emitter's own recognizer already fully proved is no
    # longer discarded merely because its block body contains another
    # block. `@inline_nested` is consumed by compile_block_body_insn's own
    # BLOCK/SENDB cases and RESTORED again below, before any `return`.
    # SAVED and restored rather than simply cleared, the same discipline
    # emit_proc_fallback_fn's own @blk_param_name already follows and for
    # the same reason: compile_method is genuinely RE-ENTRANT (its own
    # `compiles_clean?` -> `monomorphic_target` -> `compile_send` ->
    # `compile_insn` path can re-enter it from inside this very body loop,
    # to decide a MONO devirtualization target), so nil-ing this would
    # silently disarm an enclosing inlined body's own perfectly valid
    # nested-region map. Caught live building this, as a real crash.
    bc2cpp_saved_nested = @inline_nested
    @inline_nested = inline_nested_block_pass(block_irep, irep, d, offset, region[:block_addr])
    body_targets = @inline_nested.targets(jump_targets(block_irep))
    block_irep.instructions.each_with_index do |insn, i|
      next if insn.op == 'ENTER'

      body << "    #{label_prefix}#{insn.addr}:;\n" if body_targets.include?(insn.addr)
      body << '  ' << compile_block_body_insn(insn, block_irep, d, offset, iter_label, label_prefix,
                                              break_dest: dest_reg, break_label: break_label, idx: i)
    end
    # INLINE_NESTED_BLOCK_SUPPORT: consume-and-clear, BEFORE the early
    # return -- the ivar must never outlive this one body loop. The claimed
    # regions' own standalone cfunc code is handed to compile_method (which
    # emits it at file scope ahead of this method's own function) only on
    # success; on failure this whole region is abandoned, so emitting its
    # nested functions would leave real but permanently unreferenced code
    # behind.
    bc2cpp_nested_pre = @inline_nested.pre
    @inline_nested = bc2cpp_saved_nested
    return nil if body.include?('#error')

    @inline_nested_pre << bc2cpp_nested_pre

    out = String.new
    out << "  {\n"
    out << "    if (!mrb_range_p(#{recv})) { mrb_raise(M, mrb_exc_get_id(M, mrb_intern_lit(M, \"TypeError\")), \"bc2cpp: expected Range receiver for inlined #each\"); }\n"
    out << "    mrb_value bc2cpp_range_b_#{addr} = mrb_range_beg(M, #{recv});\n"
    out << "    mrb_value bc2cpp_range_e_#{addr} = mrb_range_end(M, #{recv});\n"
    out << "    if (!mrb_integer_p(bc2cpp_range_b_#{addr}) || !mrb_integer_p(bc2cpp_range_e_#{addr})) { mrb_raise(M, mrb_exc_get_id(M, mrb_intern_lit(M, \"TypeError\")), \"bc2cpp: non-Integer Range#each left to interpreter\"); }\n"
    out << "    mrb_int bc2cpp_range_a_#{addr} = mrb_integer(bc2cpp_range_b_#{addr});\n"
    out << "    mrb_int bc2cpp_range_z_#{addr} = mrb_integer(bc2cpp_range_e_#{addr});\n"
    out << "    mrb_bool bc2cpp_range_x_#{addr} = mrb_range_excl_p(M, #{recv});\n"
    out << "    for (mrb_int bc2cpp_range_i_#{addr} = bc2cpp_range_a_#{addr}; " \
           "bc2cpp_range_x_#{addr} ? bc2cpp_range_i_#{addr} < bc2cpp_range_z_#{addr} : bc2cpp_range_i_#{addr} <= bc2cpp_range_z_#{addr}; " \
           "++bc2cpp_range_i_#{addr}) {\n"
    (0...block_irep.nregs).each do |i|
      next if i.zero?

      out << "      mrb_value r#{i + offset} = mrb_nil_value();\n"
    end
    out << "      mrb_value r#{offset} = self;\n"
    out << "      r#{param_reg} = mrb_fixnum_value(bc2cpp_range_i_#{addr});\n"
    out << body
    out << "      #{iter_label}:;\n"
    out << "    }\n"
    out << "    #{break_label}:;\n"
    out << "  }\n"
    out
  end

  # MAP_BLOCK_SUPPORT: the inlined-loop replacement for one recognized
  # collection-block region (recognize_collect_regions), or nil when the
  # block body doesn't come out clean -- same all-or-nothing contract as
  # emit_each_inline above, whose loop this clones with four deliberate
  # differences (each grounded in measured semantics, not analogy):
  #   - RESULT slot: `map` collects each iteration's yielded value
  #     (block-body RETURN/RETNIL -- a real `next value` -- pushes
  #     `r<off>` into a fresh `mrb_ary_new` accumulator, the SENDB
  #     destination takes the accumulator, never the receiver);
  #     `select`/`reject` push the ELEMENT on truthy/falsy result;
  #     `find` assigns the first truthy-result element and exits early
  #     (nil default when nothing matches); `each_with_index` discards
  #     like `each` but binds a second param to the loop index as a
  #     fixnum each iteration.
  #   - YIELDED VALUE capture: the block body's own `RETURN Rv` (and the
  #     RETNIL/RETFALSE/RETTRUE family -- a real `next`, possibly with a
  #     value) is the per-element result, NOT a bare end-of-iteration the
  #     way `each` treats it. So the body is translated by
  #     compile_collect_body_insn below (not compile_block_body_insn):
  #     each return-form stores its own value into the per-iteration
  #     result local, then jumps to iter-end. A value-less `next`
  #     (RETNIL) stores nil -- correct: real `map { next if c }`
  #     collects nil for that element (confirmed against CRuby).
  #   - `BREAK Rv` (value) assigns the SENDB destination and jumps past
  #     the loop (same L_UNWINDING semantics as each -- `map { break 99
  #     }` is 99, confirmed against CRuby); bare `break` behaves the
  #     same with the BREAK register's own (nil) value.
  #   - Live `RARRAY_LEN` loop + `mrb_array_p` raise-guard, identical to
  #     each (map-push-during-iteration visits new elements -- confirmed
  #     against CRuby above -- so no snapshot).
  def emit_collect_inline(region, irep, d)
    block_irep = region[:block_irep]
    offset = irep.nregs
    dest_reg = region[:dest_reg]
    recv_expr = region[:ssendb] ? 'self' : "r#{dest_reg}"
    meth = region[:method_name]
    param_reg = 1 + offset
    param2_reg = 2 + offset # each_with_index's own index arg, R2 in block numbering.

    label_prefix = "LBLK#{region[:block_addr]}_"
    iter_label = "Lbc2cpp_collect_iter_#{region[:block_addr]}"
    break_label = "Lbc2cpp_collect_end_#{region[:block_addr]}"
    result_var = "bc2cpp_collect_v_#{region[:block_addr]}"
    body = String.new
    # INLINE_NESTED_BLOCK_SUPPORT: claim any nested block-carrying call in
    # this body BEFORE compiling it (see inline_nested_block_pass), so a
    # region this emitter's own recognizer already fully proved is no
    # longer discarded merely because its block body contains another
    # block. `@inline_nested` is consumed by compile_block_body_insn's own
    # BLOCK/SENDB cases and RESTORED again below, before any `return`.
    # SAVED and restored rather than simply cleared, the same discipline
    # emit_proc_fallback_fn's own @blk_param_name already follows and for
    # the same reason: compile_method is genuinely RE-ENTRANT (its own
    # `compiles_clean?` -> `monomorphic_target` -> `compile_send` ->
    # `compile_insn` path can re-enter it from inside this very body loop,
    # to decide a MONO devirtualization target), so nil-ing this would
    # silently disarm an enclosing inlined body's own perfectly valid
    # nested-region map. Caught live building this, as a real crash.
    bc2cpp_saved_nested = @inline_nested
    @inline_nested = inline_nested_block_pass(block_irep, irep, d, offset, region[:block_addr])
    body_targets = @inline_nested.targets(jump_targets(block_irep))
    block_irep.instructions.each_with_index do |insn, i|
      next if insn.op == 'ENTER'

      body << "    #{label_prefix}#{insn.addr}:;\n" if body_targets.include?(insn.addr)
      # ELEMENT_CLASS_SUPPORT: R1 in the block's own numbering is the
      # ELEMENT for every method this recognizer admits -- including
      # `each_with_index`, whose second parameter (R2) is the fixnum index
      # and is deliberately NOT hinted (it is not an element, and its
      # class is already known to codegen anyway).
      with_element_hint(block_irep, insn, i, '1', region[:elem_class]) do
        body << '  ' << compile_collect_body_insn(insn, block_irep, d, offset, iter_label, label_prefix,
                                                  result_var: result_var, break_dest: dest_reg,
                                                  break_label: break_label,
                                                  broke_flag: "bc2cpp_collect_broke_#{region[:block_addr]}", idx: i)
      end
    end
    # INLINE_NESTED_BLOCK_SUPPORT: consume-and-clear, BEFORE the early
    # return -- the ivar must never outlive this one body loop. The claimed
    # regions' own standalone cfunc code is handed to compile_method (which
    # emits it at file scope ahead of this method's own function) only on
    # success; on failure this whole region is abandoned, so emitting its
    # nested functions would leave real but permanently unreferenced code
    # behind.
    bc2cpp_nested_pre = @inline_nested.pre
    @inline_nested = bc2cpp_saved_nested
    return nil if body.include?('#error')

    @inline_nested_pre << bc2cpp_nested_pre

    out = String.new
    out << "  {\n"
    out << "    if (!mrb_array_p(#{recv_expr})) { mrb_raise(M, mrb_exc_get_id(M, mrb_intern_lit(M, \"TypeError\")), \"bc2cpp: expected Array receiver for inlined ##{meth}\"); }\n"
    out << "    mrb_value bc2cpp_collect_acc_#{region[:block_addr]} = mrb_ary_new(M);\n" if %w[map select reject flat_map filter_map].include?(meth)
    out << "    mrb_value bc2cpp_collect_found_#{region[:block_addr]} = mrb_nil_value();\n" if meth == 'find'
    out << "    mrb_bool bc2cpp_collect_broke_#{region[:block_addr]} = FALSE;\n" if meth != 'each_with_index'
    out << "    for (mrb_int bc2cpp_collect_i_#{region[:block_addr]} = 0; " \
           "bc2cpp_collect_i_#{region[:block_addr]} < RARRAY_LEN(#{recv_expr}); " \
           "++bc2cpp_collect_i_#{region[:block_addr]}) {\n"
    (0...block_irep.nregs).each do |i|
      next if i.zero?

      out << "      mrb_value r#{i + offset} = mrb_nil_value();\n"
    end
    out << "      mrb_value r#{offset} = self;\n"
    out << "      mrb_value #{result_var} = mrb_nil_value();\n"
    out << "      r#{param_reg} = bc2cpp_ary_entry(M, #{recv_expr}, bc2cpp_collect_i_#{region[:block_addr]});\n"
    out << "      r#{param2_reg} = mrb_fixnum_value(bc2cpp_collect_i_#{region[:block_addr]});\n" if meth == 'each_with_index'
    out << body
    out << "      #{iter_label}:;\n"
    case meth
    when 'map'
      out << "      mrb_ary_push(M, bc2cpp_collect_acc_#{region[:block_addr]}, #{result_var});\n"
    when 'flat_map'
      # INTERP_UNLOCK: mruby's own flat_map (enum-ext/mrblib/enum.rb):
      # each yielded value is pushed whole when it does NOT respond to
      # `each`, else each of ITS elements is pushed (one level only --
      # `e2.each { |e3| ary.push(e3) }`, never recursive). Mirror with
      # the same respond_to? gate. The inner expansion loops over
      # RARRAY_LEN -- but ONLY after an `mrb_array_p` tripwire on the
      # yielded value (same trust class as every receiver guard: a
      # Hash/Range yielder responds to `each` but is not an Array, and
      # RARRAY_LEN on it would misread memory -- the tripwire raises
      # loudly instead, never silently wrong). Divergence from the VM
      # ONLY when a program yields a non-Array each-responder from
      # flat_map AND expects expansion. Real game code never does
      # (verified: the flat_map sites yield id-arrays); the tripwire
      # message says exactly this. Documented as a known, deliberate
      # narrowing (same class as the Integer-edges guard on Range#each,
      # which also raises where the VM would iterate).
      out << "      if (mrb_test(mrb_funcall(M, #{result_var}, \"respond_to?\", 1, mrb_symbol_value(mrb_intern_cstr(M, \"each\"))))) {\n"
      out << "      if (!mrb_array_p(#{result_var})) { mrb_raise(M, mrb_exc_get_id(M, mrb_intern_lit(M, \"TypeError\")), \"bc2cpp: flat_map yielded non-Array\"); }\n"
      out << "      mrb_int bc2cpp_collect_fm_n_#{region[:block_addr]} = RARRAY_LEN(#{result_var});\n"
      out << "      for (mrb_int bc2cpp_collect_fm_i_#{region[:block_addr]} = 0; bc2cpp_collect_fm_i_#{region[:block_addr]} < bc2cpp_collect_fm_n_#{region[:block_addr]}; ++bc2cpp_collect_fm_i_#{region[:block_addr]}) {\n"
      out << "        mrb_ary_push(M, bc2cpp_collect_acc_#{region[:block_addr]}, bc2cpp_ary_entry(M, #{result_var}, bc2cpp_collect_fm_i_#{region[:block_addr]}));\n"
      out << "      }\n"
      out << "      } else {\n"
      out << "        mrb_ary_push(M, bc2cpp_collect_acc_#{region[:block_addr]}, #{result_var});\n"
      out << "      }\n"
    when 'select'
      out << "      if (mrb_test(#{result_var})) mrb_ary_push(M, bc2cpp_collect_acc_#{region[:block_addr]}, r#{param_reg});\n"
    when 'reject'
      out << "      if (!mrb_test(#{result_var})) mrb_ary_push(M, bc2cpp_collect_acc_#{region[:block_addr]}, r#{param_reg});\n"
    when 'find'
      out << "      if (mrb_test(#{result_var})) { bc2cpp_collect_found_#{region[:block_addr]} = r#{param_reg}; goto #{break_label}; }\n"
    when 'filter_map'
      # COLLECT_BLOCK_SUPPORT / filter_map: pushes the block's own RESULT
      # (not the element, unlike select/reject) when truthy -- real
      # Enumerable#filter_map (cited in COLLECT_BLOCK_METHODS' own
      # comment) reassigns `x = blk.call(*x)` before the `ary.push x if
      # x` truthiness test, so the pushed value and the tested value are
      # the same block-result register.
      out << "      if (mrb_test(#{result_var})) mrb_ary_push(M, bc2cpp_collect_acc_#{region[:block_addr]}, #{result_var});\n"
    end
    out << "    }\n"
    out << "    #{break_label}:;\n"
    # BREAK inside the loop jumps here with the destination ALREADY
    # holding the break value (BREAK's own `r<dest> = r<v>` assignment,
    # wired with this emitter's own broke-flag below) -- so the final
    # accumulator assignment must NOT run on the break path (it would
    # overwrite the break value with a partial accumulator, the exact
    # `[1, 2]`-instead-of-`99` bug caught by the runtime harness).
    # A loop-index comparison (fall-through exits with i == len, break
    # with i < len) was considered and rejected: pop-during-iteration
    # can shrink len below a later break index, misreading break as
    # fall-through. A dedicated boolean, set only on the break path,
    # has zero per-iteration cost and no such edge. each_with_index
    # needs no guard at all (fall-through leaves the receiver, break
    # already set dest -- no assignment either way), so it skips both
    # the flag declaration and the guarded assignment.
    if meth != 'each_with_index'
      out << "    if (!bc2cpp_collect_broke_#{region[:block_addr]}) {\n"
      case meth
      when 'map', 'select', 'reject', 'flat_map', 'filter_map'
        out << "    r#{dest_reg} = bc2cpp_collect_acc_#{region[:block_addr]};\n"
      when 'find'
        out << "    r#{dest_reg} = bc2cpp_collect_found_#{region[:block_addr]};\n"
      end
      out << "    }\n"
    end
    out << "  }\n"
    out
  end

  # ACCUM_BLOCK_SUPPORT: the inlined-loop replacement for one recognized
  # accumulator/predicate region (recognize_accum_regions), or nil when
  # the block body doesn't come out clean -- same all-or-nothing
  # contract as every emitter above. Clones emit_collect_inline's loop
  # with three deliberate differences (each grounded in measured CRuby
  # semantics, listed in recognize_accum_regions' own comment):
  #   - PREDICATE result: `any?`/`all?`/`none?` produce a boolean
  #     destination with early exit (any?: false default, first truthy
  #     result sets true + goto end; all?: true default, first falsy
  #     sets false + goto end; none?: true default, first truthy sets
  #     false + goto end). A `break v` inside overrides with v (same
  #     broke-flag pattern as collect -- BREAK assigns dest + sets the
  #     flag + jumps past; the final boolean assignment is flag-
  #     guarded). Empty-array defaults fall out with zero iterations.
  #   - COUNT tally: `count` keeps a fixnum tally local (no early exit),
  #     destination takes the tally past the broke-guard (a `break v`
  #     overrides with v -- confirmed against CRuby: `count { break 7 }`
  #     is 7).
  #   - FOLD threading: `reduce`/`inject(init)` seeds a block-local
  #     accumulator from the SENDB's own R(dest+1) init register ONCE
  #     before the loop (never re-initialized per iteration -- the whole
  #     point of a fold); each iteration binds block param 1 to the
  #     accumulator and param 2 to the element, and takes the block's
  #     yielded value back as the next accumulator. Destination takes
  #     the accumulator past the broke-guard. The init register is read
  #     before the loop starts, so a body that later writes the same
  #     enclosing register (possible only through a level-0 SETUPVAR
  #     aliasing that local) cannot affect iteration -- sound by copy
  #     timing, documented because subtle.
  def emit_accum_inline(region, irep, d)
    block_irep = region[:block_irep]
    offset = irep.nregs
    dest_reg = region[:dest_reg]
    recv_expr = region[:ssendb] ? 'self' : "r#{dest_reg}"
    meth = region[:method_name]
    is_fold = !region[:init_reg].nil?
    param_reg = 1 + offset
    param2_reg = 2 + offset
    acc_var = "bc2cpp_accum_acc_#{region[:block_addr]}"

    label_prefix = "LBLK#{region[:block_addr]}_"
    iter_label = "Lbc2cpp_accum_iter_#{region[:block_addr]}"
    break_label = "Lbc2cpp_accum_end_#{region[:block_addr]}"
    result_var = "bc2cpp_accum_v_#{region[:block_addr]}"
    body = String.new
    # INLINE_NESTED_BLOCK_SUPPORT: claim any nested block-carrying call in
    # this body BEFORE compiling it (see inline_nested_block_pass), so a
    # region this emitter's own recognizer already fully proved is no
    # longer discarded merely because its block body contains another
    # block. `@inline_nested` is consumed by compile_block_body_insn's own
    # BLOCK/SENDB cases and RESTORED again below, before any `return`.
    # SAVED and restored rather than simply cleared, the same discipline
    # emit_proc_fallback_fn's own @blk_param_name already follows and for
    # the same reason: compile_method is genuinely RE-ENTRANT (its own
    # `compiles_clean?` -> `monomorphic_target` -> `compile_send` ->
    # `compile_insn` path can re-enter it from inside this very body loop,
    # to decide a MONO devirtualization target), so nil-ing this would
    # silently disarm an enclosing inlined body's own perfectly valid
    # nested-region map. Caught live building this, as a real crash.
    bc2cpp_saved_nested = @inline_nested
    @inline_nested = inline_nested_block_pass(block_irep, irep, d, offset, region[:block_addr])
    body_targets = @inline_nested.targets(jump_targets(block_irep))
    block_irep.instructions.each_with_index do |insn, i|
      next if insn.op == 'ENTER'

      body << "    #{label_prefix}#{insn.addr}:;\n" if body_targets.include?(insn.addr)
      # ELEMENT_CLASS_SUPPORT: which parameter register holds the ELEMENT
      # depends on the shape this region actually is -- a predicate block
      # (`any?`/`all?`/`none?`/`count`) takes the element as its single
      # parameter R1, while a fold (`reduce`/`inject`) takes the
      # ACCUMULATOR as R1 and the element as R2. Read straight off the
      # same `is_fold` flag that decides the register binding a few lines
      # below, so the two can never disagree.
      with_element_hint(block_irep, insn, i, is_fold ? '2' : '1', region[:elem_class]) do
        body << '  ' << compile_collect_body_insn(insn, block_irep, d, offset, iter_label, label_prefix,
                                                  result_var: result_var, break_dest: dest_reg,
                                                  break_label: break_label,
                                                  broke_flag: "bc2cpp_accum_broke_#{region[:block_addr]}", idx: i)
      end
    end
    # INLINE_NESTED_BLOCK_SUPPORT: consume-and-clear, BEFORE the early
    # return -- the ivar must never outlive this one body loop. The claimed
    # regions' own standalone cfunc code is handed to compile_method (which
    # emits it at file scope ahead of this method's own function) only on
    # success; on failure this whole region is abandoned, so emitting its
    # nested functions would leave real but permanently unreferenced code
    # behind.
    bc2cpp_nested_pre = @inline_nested.pre
    @inline_nested = bc2cpp_saved_nested
    return nil if body.include?('#error')

    @inline_nested_pre << bc2cpp_nested_pre

    out = String.new
    out << "  {\n"
    out << "    if (!mrb_array_p(#{recv_expr})) { mrb_raise(M, mrb_exc_get_id(M, mrb_intern_lit(M, \"TypeError\")), \"bc2cpp: expected Array receiver for inlined ##{meth}\"); }\n"
    out << "    mrb_bool bc2cpp_accum_broke_#{region[:block_addr]} = FALSE;\n"
    case meth
    when 'any?'
      out << "    mrb_value bc2cpp_accum_res_#{region[:block_addr]} = mrb_false_value();\n"
    when 'all?', 'none?'
      out << "    mrb_value bc2cpp_accum_res_#{region[:block_addr]} = mrb_true_value();\n"
    when 'count'
      out << "    mrb_int bc2cpp_accum_n_#{region[:block_addr]} = 0;\n"
    when 'reduce', 'inject'
      out << "    mrb_value #{acc_var} = r#{region[:init_reg]};\n"
    end
    out << "    for (mrb_int bc2cpp_accum_i_#{region[:block_addr]} = 0; " \
           "bc2cpp_accum_i_#{region[:block_addr]} < RARRAY_LEN(#{recv_expr}); " \
           "++bc2cpp_accum_i_#{region[:block_addr]}) {\n"
    (0...block_irep.nregs).each do |i|
      next if i.zero?

      out << "      mrb_value r#{i + offset} = mrb_nil_value();\n"
    end
    out << "      mrb_value r#{offset} = self;\n"
    out << "      mrb_value #{result_var} = mrb_nil_value();\n"
    if is_fold
      out << "      r#{param_reg} = #{acc_var};\n"
      out << "      r#{param2_reg} = bc2cpp_ary_entry(M, #{recv_expr}, bc2cpp_accum_i_#{region[:block_addr]});\n"
    else
      out << "      r#{param_reg} = bc2cpp_ary_entry(M, #{recv_expr}, bc2cpp_accum_i_#{region[:block_addr]});\n"
    end
    out << body
    out << "      #{iter_label}:;\n"
    case meth
    when 'any?'
      out << "      if (mrb_test(#{result_var})) { bc2cpp_accum_res_#{region[:block_addr]} = mrb_true_value(); goto #{break_label}; }\n"
    when 'all?'
      out << "      if (!mrb_test(#{result_var})) { bc2cpp_accum_res_#{region[:block_addr]} = mrb_false_value(); goto #{break_label}; }\n"
    when 'none?'
      out << "      if (mrb_test(#{result_var})) { bc2cpp_accum_res_#{region[:block_addr]} = mrb_false_value(); goto #{break_label}; }\n"
    when 'count'
      out << "      if (mrb_test(#{result_var})) ++bc2cpp_accum_n_#{region[:block_addr]};\n"
    when 'reduce', 'inject'
      out << "      #{acc_var} = #{result_var};\n"
    end
    out << "    }\n"
    out << "    #{break_label}:;\n"
    out << "    if (!bc2cpp_accum_broke_#{region[:block_addr]}) {\n"
    case meth
    when 'any?', 'all?', 'none?'
      out << "    r#{dest_reg} = bc2cpp_accum_res_#{region[:block_addr]};\n"
    when 'count'
      out << "    r#{dest_reg} = mrb_fixnum_value(bc2cpp_accum_n_#{region[:block_addr]});\n"
    when 'reduce', 'inject'
      out << "    r#{dest_reg} = #{acc_var};\n"
    end
    out << "    }\n"
    out << "  }\n"
    out
  end

  # MAP_BLOCK_SUPPORT: translate one instruction from an INLINED
  # collection-block body -- identical to compile_block_body_insn
  # (RETURN_BLK, BREAK, GETUPVAR/SETUPVAR@0, JMP-family, delegated
  # everything-else) EXCEPT the block's own ordinary return forms
  # (`RETURN`/`RETNIL`/`RETFALSE`/`RETTRUE` -- a real `next`, possibly
  # with a value): where each-inline treats them as bare end-of-
  # iteration, collection methods USE the yielded value, so each such
  # form first stores its own value register into `result_var`, then
  # jumps to iter-end. `RETURN_BLK` (real `return`) is unchanged --
  # still a plain C++ return. BREAK/BREAK-value, upvars, jumps, and the
  # delegated remainder are line-for-line the each behavior.
  def compile_collect_body_insn(insn, block_irep, owner_def, offset, iter_end_label, label_prefix,
                                result_var:, break_dest:, break_label:, broke_flag:, idx: nil)
    case insn.op
    when 'RETURN', 'RETNIL', 'RETFALSE', 'RETTRUE'
      r = insn.op == 'RETURN' ? (insn.args.strip.empty? ? '0' : insn.args[/^R(\d+)/, 1]) : nil
      store = case insn.op
              when 'RETURN' then "r#{r.to_i + offset}"
              when 'RETNIL' then 'mrb_nil_value()'
              when 'RETFALSE' then 'mrb_false_value()'
              when 'RETTRUE' then 'mrb_true_value()'
              end
      "  #{result_var} = #{store};\n  goto #{iter_end_label};\n"
    when 'BREAK'
      # Same L_UNWINDING value semantics as compile_block_body_insn's
      # own BREAK case, PLUS setting this emitter's own broke-flag so
      # the post-loop accumulator assignment knows not to run (see
      # emit_collect_inline's own comment -- without the flag the break
      # value would be overwritten by a partial accumulator).
      r = insn.args.strip.empty? ? '0' : insn.args[/^R(\d+)/, 1]
      "  r#{break_dest} = r#{r.to_i + offset};\n  #{broke_flag} = TRUE;\n  goto #{break_label};\n"
    else
      compile_block_body_insn(insn, block_irep, owner_def, offset, iter_end_label, label_prefix,
                              break_dest: break_dest, break_label: break_label, idx: idx)
    end
  end

  # EACH_BLOCK_SUPPORT: the inlined-loop replacement for one recognized
  # `&:sym` site (recognize_sym_regions) -- `ary.reject(&:dead?)` and
  # friends. No closure exists (the VM packs the LOADSYM symbol via
  # `ensure_block`), so instead of a translated block body each
  # iteration performs one real `mrb_funcall(M, elem, "<sym>", 0)` --
  # ordinary dynamic dispatch of the NAMED method, exactly what
  # `Symbol#to_proc` does at runtime -- and accumulates per the call
  # method's own real Enumerable semantics:
  #   each: discard the result (destination keeps the receiver);
  #   map: push each result into a fresh Array;
  #   select/reject: push the ELEMENT when the result is truthy/falsy;
  #   find: destination is the first element with a truthy result
  #     (else nil), loop exits early;
  #   any?/all?/none?: boolean destination with early exit
  #     (all?/none? default true, any? defaults false);
  #   count: destination is the fixnum tally of truthy results.
  # Same live-length loop and `mrb_array_p` raise-guard as
  # emit_each_inline above (same mutation-during-iteration and
  # wrong-receiver reasoning -- confirmed the same way). Returns nil
  # (caller falls back to `#error` stubs) only when the method name is
  # outside the recognizer's own set, which cannot happen -- the
  # recognizer is the sole caller and already gates on it.
  def emit_sym_inline(region, _irep, _d)
    dest_reg = region[:dest_reg]
    recv_expr = region[:ssendb] ? 'self' : "r#{dest_reg}"
    meth = region[:method_name]
    sym = region[:sym_name]
    return nil unless SYM_BLOCK_METHODS.include?(meth)

    iter_label = "Lbc2cpp_sym_iter_#{region[:sym_addr]}"
    end_label = "Lbc2cpp_sym_end_#{region[:sym_addr]}"
    out = String.new
    out << "  {\n"
    out << "    if (!mrb_array_p(#{recv_expr})) { mrb_raise(M, mrb_exc_get_id(M, mrb_intern_lit(M, \"TypeError\")), \"bc2cpp: expected Array receiver for inlined &:#{sym}\"); }\n"
    case meth
    when 'map', 'select', 'reject'
      out << "    mrb_value bc2cpp_sym_acc_#{region[:sym_addr]} = mrb_ary_new(M);\n"
    when 'find'
      out << "    mrb_value bc2cpp_sym_acc_#{region[:sym_addr]} = mrb_nil_value();\n"
    when 'any?', 'none?'
      out << "    mrb_value bc2cpp_sym_acc_#{region[:sym_addr]} = mrb_false_value();\n"
    when 'all?'
      out << "    mrb_value bc2cpp_sym_acc_#{region[:sym_addr]} = mrb_true_value();\n"
    when 'count'
      out << "    mrb_int bc2cpp_sym_acc_#{region[:sym_addr]} = 0;\n"
    end
    out << "    for (mrb_int bc2cpp_sym_i_#{region[:sym_addr]} = 0; " \
           "bc2cpp_sym_i_#{region[:sym_addr]} < RARRAY_LEN(#{recv_expr}); " \
           "++bc2cpp_sym_i_#{region[:sym_addr]}) {\n"
    out << "      mrb_value bc2cpp_sym_e_#{region[:sym_addr]} = " \
           "bc2cpp_ary_entry(M, #{recv_expr}, bc2cpp_sym_i_#{region[:sym_addr]});\n"
    if meth == 'each'
      out << "      #{sym_call_line(sym, "bc2cpp_sym_e_#{region[:sym_addr]}")}\n"
    else
      out << "      #{sym_call_value(sym, "bc2cpp_sym_e_#{region[:sym_addr]}", "bc2cpp_sym_r_#{region[:sym_addr]}")}\n"
      case meth
      when 'map'
        out << "      mrb_ary_push(M, bc2cpp_sym_acc_#{region[:sym_addr]}, bc2cpp_sym_r_#{region[:sym_addr]});\n"
      when 'select'
        out << "      if (mrb_test(bc2cpp_sym_r_#{region[:sym_addr]})) " \
               "mrb_ary_push(M, bc2cpp_sym_acc_#{region[:sym_addr]}, bc2cpp_sym_e_#{region[:sym_addr]});\n"
      when 'reject'
        out << "      if (!mrb_test(bc2cpp_sym_r_#{region[:sym_addr]})) " \
               "mrb_ary_push(M, bc2cpp_sym_acc_#{region[:sym_addr]}, bc2cpp_sym_e_#{region[:sym_addr]});\n"
      when 'find'
        out << "      if (mrb_test(bc2cpp_sym_r_#{region[:sym_addr]})) { " \
               "bc2cpp_sym_acc_#{region[:sym_addr]} = bc2cpp_sym_e_#{region[:sym_addr]}; " \
               "goto #{end_label}; }\n"
      when 'any?'
        out << "      if (mrb_test(bc2cpp_sym_r_#{region[:sym_addr]})) { " \
               "bc2cpp_sym_acc_#{region[:sym_addr]} = mrb_true_value(); goto #{end_label}; }\n"
      when 'all?'
        out << "      if (!mrb_test(bc2cpp_sym_r_#{region[:sym_addr]})) { " \
               "bc2cpp_sym_acc_#{region[:sym_addr]} = mrb_false_value(); goto #{end_label}; }\n"
      when 'none?'
        out << "      if (mrb_test(bc2cpp_sym_r_#{region[:sym_addr]})) { " \
               "bc2cpp_sym_acc_#{region[:sym_addr]} = mrb_false_value(); goto #{end_label}; }\n"
      when 'count'
        out << "      if (mrb_test(bc2cpp_sym_r_#{region[:sym_addr]})) ++bc2cpp_sym_acc_#{region[:sym_addr]};\n"
      end
    end
    out << "      #{iter_label}:;\n"
    out << "    }\n"
    out << "    #{end_label}:;\n"
    case meth
    when 'each'
      # `each` returns the receiver, already in the destination register.
    when 'count'
      out << "    r#{dest_reg} = mrb_fixnum_value(bc2cpp_sym_acc_#{region[:sym_addr]});\n"
    else
      out << "    r#{dest_reg} = bc2cpp_sym_acc_#{region[:sym_addr]};\n"
    end
    out << "  }\n"
    out
  end

  # SYM_DEVIRT: the per-element call for a `&:sym` site, devirtualized
  # where sym_call_target allows. Both helpers emit full STATEMENTS
  # (never bare expressions): `sym_call_value` declares
  # `mrb_value <result_var> = ...` for valued methods, `sym_call_line`
  # emits the discard-result call for `each`. Both take the element
  # expression (always the loop's own `bc2cpp_sym_e_N` local -- a plain
  # `mrb_value`, so the TYPED guard shape needs no register-specific
  # adaptation).
  #
  # A POLY chain is a statement-level if/else-if/else (NOT a C
  # conditional expression -- `if` is not an expression in C, caught by
  # g++ building the first real chain), which is why valued and void
  # cases need separate helpers rather than one shared expression core.
  #
  # Soundness: the `mrb_funcall` fallback is exact `Symbol#to_proc`
  # semantics (unlike a literal block, a symbol-call carries no closure
  # `mrb_funcall` would drop), so every fallback path is merely slower,
  # never wrong. The MONO direct call needs no guard at all (one def
  # program-wide); each POLY branch guards exact-class `==` (subclass
  # elements take the fallback -- same as compile_send's TYPED path).
  def sym_call_value(sym, elem_expr, result_var)
    kind, target = sym_call_target(sym) || [nil, nil]
    fallback = "mrb_funcall(M, #{elem_expr}, \"#{sym}\", 0)"
    return "mrb_value #{result_var} = #{fallback};" unless kind

    if kind == :mono
      impl = cpp_name(target.owner, target.name) + '_impl'
      return "// MONO &:#{sym} -> #{target.owner}##{target.name}, direct C++ call (no mrb_funcall)\n" \
             "      mrb_value #{result_var} = #{impl}(M, #{elem_expr});"
    end

    out = String.new
    out << "// POLY &:#{sym} (#{target.size} defs) -- per-element exact-class guard chain, mrb_funcall fallback\n"
    out << "      mrb_value #{result_var} = mrb_nil_value();\n"
    target.each_with_index do |d, i|
      impl = cpp_name(d.owner, d.name) + '_impl'
      check = "#{owner_class_ptr_expr(d.owner)} == mrb_obj_class(M, #{elem_expr})"
      out << (i.zero? ? '      ' : '      else ')
      out << "if (#{check}) { #{result_var} = #{impl}(M, #{elem_expr}); }\n"
    end
    out << "      else { #{result_var} = #{fallback}; }\n"
    out
  end

  def sym_call_line(sym, elem_expr)
    kind, target = sym_call_target(sym) || [nil, nil]
    fallback = "mrb_funcall(M, #{elem_expr}, \"#{sym}\", 0);"
    return fallback unless kind

    if kind == :mono
      impl = cpp_name(target.owner, target.name) + '_impl'
      return "// MONO &:#{sym} -> #{target.owner}##{target.name}, direct C++ call (no mrb_funcall)\n" \
             "      #{impl}(M, #{elem_expr});"
    end

    out = String.new
    out << "// POLY &:#{sym} (#{target.size} defs) -- per-element exact-class guard chain, mrb_funcall fallback\n"
    target.each_with_index do |d, i|
      impl = cpp_name(d.owner, d.name) + '_impl'
      check = "#{owner_class_ptr_expr(d.owner)} == mrb_obj_class(M, #{elem_expr})"
      out << (i.zero? ? '      ' : '      else ')
      out << "if (#{check}) { #{impl}(M, #{elem_expr}); }\n"
    end
    out << "      else { #{fallback} }\n"
    out
  end

  # SORT_BLOCK_SUPPORT: the inlined replacement for one recognized
  # sort-family region (recognize_sort_regions), or nil when the block
  # body doesn't come out clean -- same all-or-nothing contract as
  # every emitter above. Two strategies, split by what the block MEANS:
  #
  # - `sort { |a, b| ... }` (comparator): delegate the WHOLE call to
  #   the interpreter. A comparator block cannot inline as a loop at
  #   all -- it runs O(n log n) times inside the VM's own sort, driven
  #   by native code this file cannot reproduce. So `sort`-with-block
  #   is NOT compiled here (returns nil -- honest `#error`, stays
  #   interpreted). Recognized-and-rejected deliberately: the shape is
  #   claimed so a future round (comparator-as-callback via retained
  #   Proc, or key-extraction) has a named place to extend. Bare
  #   `sort` with NO block (`n=0`, no BLOCK -- plain SEND, never
  #   reaches this recognizer) already compiles as an ordinary call.
  #
  # - `sort_by { |x| key }` / `uniq { |x| key }` (key extraction): the
  #   Schwartzian transform, expressed with/or ordinary compiled
  #   operations only --
  #     1. keys[i] = <block>(elem[i]) for each element (the inlined
  #        block body, yielded-value capture shared with collect via
  #        compile_collect_body_insn -- same `next`-collects-nil,
  #        same `break`-overrides, same broke-flag);
  #     2. decorate: pairs[i] = [keys[i], i, elem[i]] (index decoration
  #        keeps the sort STABLE -- mruby's own sort is not stable, but
  #        CRuby's sort_by IS stable, confirmed by oracle above:
  #        `[[0,"b"],[0,"a"]].sort_by` keeps order -- and game code
  #        like turn-order ties depends on it);
  #     3. sort pairs by (key, index) with `mrb_cmp` (mruby.h's own
  #        public three-way comparison: fixnum/float/string fast paths,
  #        `<=>` dispatch otherwise, -2 on incomparable -- exactly the
  #        comparison native sort itself uses);
  #     4. undecorate: dest[i] = pairs[i][2].
  #   `uniq` differs only in step 3-4: keep the FIRST element per key
  #   (consecutive-key dedup after sorting by key -- sort stably by
  #   key, then drop adjacent equal keys via `mrb_cmp == 0`).
  #   All temporaries are fresh `mrb_ary_new` locals (never the
  #   receiver -- `sort_by`/`uniq` return new arrays, confirmed by
  #   oracle; the receiver is only ever READ via `mrb_ary_ref`).
  #   A `break v` inside the key block overrides the whole expression
  #   with v (same broke-flag pattern as collect/accum).
  def emit_sort_inline(region, irep, d)
    return nil if region[:method_name] == 'sort'

    block_irep = region[:block_irep]
    offset = irep.nregs
    dest_reg = region[:dest_reg]
    recv_expr = region[:ssendb] ? 'self' : "r#{dest_reg}"
    meth = region[:method_name]
    param_reg = 1 + offset

    label_prefix = "LBLK#{region[:block_addr]}_"
    iter_label = "Lbc2cpp_sort_iter_#{region[:block_addr]}"
    break_label = "Lbc2cpp_sort_end_#{region[:block_addr]}"
    result_var = "bc2cpp_sort_v_#{region[:block_addr]}"
    body = String.new
    # INLINE_NESTED_BLOCK_SUPPORT: claim any nested block-carrying call in
    # this body BEFORE compiling it (see inline_nested_block_pass), so a
    # region this emitter's own recognizer already fully proved is no
    # longer discarded merely because its block body contains another
    # block. `@inline_nested` is consumed by compile_block_body_insn's own
    # BLOCK/SENDB cases and RESTORED again below, before any `return`.
    # SAVED and restored rather than simply cleared, the same discipline
    # emit_proc_fallback_fn's own @blk_param_name already follows and for
    # the same reason: compile_method is genuinely RE-ENTRANT (its own
    # `compiles_clean?` -> `monomorphic_target` -> `compile_send` ->
    # `compile_insn` path can re-enter it from inside this very body loop,
    # to decide a MONO devirtualization target), so nil-ing this would
    # silently disarm an enclosing inlined body's own perfectly valid
    # nested-region map. Caught live building this, as a real crash.
    bc2cpp_saved_nested = @inline_nested
    @inline_nested = inline_nested_block_pass(block_irep, irep, d, offset, region[:block_addr])
    body_targets = @inline_nested.targets(jump_targets(block_irep))
    block_irep.instructions.each_with_index do |insn, i|
      next if insn.op == 'ENTER'

      body << "    #{label_prefix}#{insn.addr}:;\n" if body_targets.include?(insn.addr)
      # ELEMENT_CLASS_SUPPORT: a `sort_by`/`uniq` key block takes the
      # element as its single parameter R1, same as the collect family.
      with_element_hint(block_irep, insn, i, '1', region[:elem_class]) do
        body << '  ' << compile_collect_body_insn(insn, block_irep, d, offset, iter_label, label_prefix,
                                                  result_var: result_var, break_dest: dest_reg,
                                                  break_label: break_label,
                                                  broke_flag: "bc2cpp_sort_broke_#{region[:block_addr]}", idx: i)
      end
    end
    # INLINE_NESTED_BLOCK_SUPPORT: consume-and-clear, BEFORE the early
    # return -- the ivar must never outlive this one body loop. The claimed
    # regions' own standalone cfunc code is handed to compile_method (which
    # emits it at file scope ahead of this method's own function) only on
    # success; on failure this whole region is abandoned, so emitting its
    # nested functions would leave real but permanently unreferenced code
    # behind.
    bc2cpp_nested_pre = @inline_nested.pre
    @inline_nested = bc2cpp_saved_nested
    return nil if body.include?('#error')

    @inline_nested_pre << bc2cpp_nested_pre

    addr = region[:block_addr]
    out = String.new
    out << "  {\n"
    out << "    if (!mrb_array_p(#{recv_expr})) { mrb_raise(M, mrb_exc_get_id(M, mrb_intern_lit(M, \"TypeError\")), \"bc2cpp: expected Array receiver for inlined ##{meth}\"); }\n"
    out << "    mrb_bool bc2cpp_sort_broke_#{addr} = FALSE;\n"
    out << "    mrb_int bc2cpp_sort_n_#{addr} = RARRAY_LEN(#{recv_expr});\n"
    out << "    mrb_value bc2cpp_sort_keys_#{addr} = mrb_ary_new_capa(M, bc2cpp_sort_n_#{addr});\n"
    out << "    for (mrb_int bc2cpp_sort_i_#{addr} = 0; bc2cpp_sort_i_#{addr} < RARRAY_LEN(#{recv_expr}); ++bc2cpp_sort_i_#{addr}) {\n"
    (0...block_irep.nregs).each do |i|
      next if i.zero?

      out << "      mrb_value r#{i + offset} = mrb_nil_value();\n"
    end
    out << "      mrb_value r#{offset} = self;\n"
    out << "      mrb_value #{result_var} = mrb_nil_value();\n"
    out << "      r#{param_reg} = bc2cpp_ary_entry(M, #{recv_expr}, bc2cpp_sort_i_#{addr});\n"
    out << body
    out << "      #{iter_label}:;\n"
    out << "      mrb_ary_push(M, bc2cpp_sort_keys_#{addr}, #{result_var});\n"
    out << "    }\n"
    # Key loop uses a snapshot length (n) for allocation but re-checks
    # live RARRAY_LEN per element -- push-during-key-block visits new
    # elements (same live-length rule as every emitter above); keys and
    # elements can only diverge if the body mutates the receiver, in
    # which case the SORT phase below re-reads live length and the key
    # array is shorter -- guarded: iterate min(keys, len) by indexing
    # keys with the same live loop and pushing only while i < keys len.
    # Simpler exact rule: sort phase loops over the KEY array's own
    # length (keys are 1:1 with visited elements by construction), and
    # element fetch uses mrb_ary_ref on the receiver at the same index
    # (nil-padded by mrb_ary_ref semantics if the receiver shrank --
    # matches interpreted sort_by-on-mutated-array within reason; a
    # body that mutates mid-sort is already VM-undefined -- native sort
    # RAISES "array modified during sort" -- so any sane behavior here
    # is acceptable, and non-mutating bodies are exact).
    out << "    #{break_label}:;\n"
    out << "    if (!bc2cpp_sort_broke_#{addr}) {\n"
    out << "    mrb_int bc2cpp_sort_m_#{addr} = RARRAY_LEN(bc2cpp_sort_keys_#{addr});\n"
    out << "    mrb_value bc2cpp_sort_pairs_#{addr} = mrb_ary_new_capa(M, bc2cpp_sort_m_#{addr});\n"
    out << "    for (mrb_int bc2cpp_sort_j_#{addr} = 0; bc2cpp_sort_j_#{addr} < bc2cpp_sort_m_#{addr}; ++bc2cpp_sort_j_#{addr}) {\n"
    out << "      mrb_value bc2cpp_sort_e_#{addr} = bc2cpp_ary_entry(M, #{recv_expr}, bc2cpp_sort_j_#{addr});\n"
    out << "      mrb_value bc2cpp_sort_k_#{addr} = bc2cpp_ary_entry(M, bc2cpp_sort_keys_#{addr}, bc2cpp_sort_j_#{addr});\n"
    out << "      mrb_value bc2cpp_sort_trip_#{addr} = mrb_ary_new_capa(M, 3);\n"
    out << "      mrb_ary_push(M, bc2cpp_sort_trip_#{addr}, bc2cpp_sort_k_#{addr});\n"
    out << "      mrb_ary_push(M, bc2cpp_sort_trip_#{addr}, mrb_fixnum_value(bc2cpp_sort_j_#{addr}));\n"
    out << "      mrb_ary_push(M, bc2cpp_sort_trip_#{addr}, bc2cpp_sort_e_#{addr});\n"
    out << "      mrb_ary_push(M, bc2cpp_sort_pairs_#{addr}, bc2cpp_sort_trip_#{addr});\n"
    out << "    }\n"
    # Insertion sort on (key, index) -- O(n^2) worst case, but game
    # arrays here are tiny (turn order, event lists, transition bands:
    # single-to-double digits), and insertion sort is STABLE, which the
    # index decoration would otherwise have to supply alone. The index
    # tiebreak below makes stability explicit regardless of algorithm,
    # so this is correct for any size, just tuned for small n.
    # mrb_cmp: 1/0/-1, -2 on incomparable (same contract native
    # sort_cmp relies on -- incomparable keys raise, matching the VM).
    # mrb_integer on the decorated index: always a real fixnum (emitted
    # above as mrb_fixnum_value(j)), never user data -- no TypeError
    # path possible, matching native sort's own unchecked index ints.
    out << "    for (mrb_int bc2cpp_sort_a_#{addr} = 1; bc2cpp_sort_a_#{addr} < bc2cpp_sort_m_#{addr}; ++bc2cpp_sort_a_#{addr}) {\n"
    out << "      mrb_value bc2cpp_sort_tmp_#{addr} = bc2cpp_ary_entry(M, bc2cpp_sort_pairs_#{addr}, bc2cpp_sort_a_#{addr});\n"
    out << "      mrb_int bc2cpp_sort_b_#{addr} = bc2cpp_sort_a_#{addr} - 1;\n"
    out << "      while (bc2cpp_sort_b_#{addr} >= 0) {\n"
    out << "        mrb_value bc2cpp_sort_pa_#{addr} = bc2cpp_ary_entry(M, bc2cpp_sort_pairs_#{addr}, bc2cpp_sort_b_#{addr});\n"
    out << "        mrb_value bc2cpp_sort_ka_#{addr} = bc2cpp_ary_entry(M, bc2cpp_sort_pa_#{addr}, 0);\n"
    out << "        mrb_value bc2cpp_sort_ia_#{addr} = bc2cpp_ary_entry(M, bc2cpp_sort_pa_#{addr}, 1);\n"
    out << "        mrb_value bc2cpp_sort_kb_#{addr} = bc2cpp_ary_entry(M, bc2cpp_sort_tmp_#{addr}, 0);\n"
    out << "        mrb_value bc2cpp_sort_ib_#{addr} = bc2cpp_ary_entry(M, bc2cpp_sort_tmp_#{addr}, 1);\n"
    out << "        mrb_int bc2cpp_sort_c_#{addr} = mrb_cmp(M, bc2cpp_sort_kb_#{addr}, bc2cpp_sort_ka_#{addr});\n"
    out << "        if (bc2cpp_sort_c_#{addr} == -2) { mrb_raise(M, mrb_exc_get_id(M, mrb_intern_lit(M, \"ArgumentError\")), \"bc2cpp: sort_by comparison failed\"); }\n"
    out << "        if (bc2cpp_sort_c_#{addr} == 0) { bc2cpp_sort_c_#{addr} = (mrb_integer(bc2cpp_sort_ib_#{addr}) < mrb_integer(bc2cpp_sort_ia_#{addr})) ? -1 : 1; }\n"
    out << "        if (bc2cpp_sort_c_#{addr} >= 0) break;\n"
    out << "        mrb_ary_set(M, bc2cpp_sort_pairs_#{addr}, bc2cpp_sort_b_#{addr} + 1, bc2cpp_sort_pa_#{addr});\n"
    out << "        --bc2cpp_sort_b_#{addr};\n"
    out << "      }\n"
    out << "      mrb_ary_set(M, bc2cpp_sort_pairs_#{addr}, bc2cpp_sort_b_#{addr} + 1, bc2cpp_sort_tmp_#{addr});\n"
    out << "    }\n"
    out << "    r#{dest_reg} = mrb_ary_new_capa(M, bc2cpp_sort_m_#{addr});\n"
    if meth == 'uniq'
      out << "    mrb_value bc2cpp_sort_lastk_#{addr} = mrb_nil_value();\n"
      out << "    mrb_bool bc2cpp_sort_havek_#{addr} = FALSE;\n"
      out << "    for (mrb_int bc2cpp_sort_u_#{addr} = 0; bc2cpp_sort_u_#{addr} < bc2cpp_sort_m_#{addr}; ++bc2cpp_sort_u_#{addr}) {\n"
      out << "      mrb_value bc2cpp_sort_pu_#{addr} = bc2cpp_ary_entry(M, bc2cpp_sort_pairs_#{addr}, bc2cpp_sort_u_#{addr});\n"
      out << "      mrb_value bc2cpp_sort_ku_#{addr} = bc2cpp_ary_entry(M, bc2cpp_sort_pu_#{addr}, 0);\n"
      out << "      mrb_int bc2cpp_sort_eq_#{addr} = (bc2cpp_sort_havek_#{addr} && mrb_cmp(M, bc2cpp_sort_ku_#{addr}, bc2cpp_sort_lastk_#{addr}) == 0) ? 1 : 0;\n"
      out << "      if (!bc2cpp_sort_eq_#{addr}) { mrb_ary_push(M, r#{dest_reg}, bc2cpp_ary_entry(M, bc2cpp_sort_pu_#{addr}, 2)); }\n"
      out << "      bc2cpp_sort_lastk_#{addr} = bc2cpp_sort_ku_#{addr};\n"
      out << "      bc2cpp_sort_havek_#{addr} = TRUE;\n"
      out << "    }\n"
    else
      out << "    for (mrb_int bc2cpp_sort_u_#{addr} = 0; bc2cpp_sort_u_#{addr} < bc2cpp_sort_m_#{addr}; ++bc2cpp_sort_u_#{addr}) {\n"
      out << "      mrb_ary_push(M, r#{dest_reg}, bc2cpp_ary_entry(M, bc2cpp_ary_entry(M, bc2cpp_sort_pairs_#{addr}, bc2cpp_sort_u_#{addr}), 2));\n"
      out << "    }\n"
    end
    out << "    }\n"
    out << "  }\n"
    out
  end

  # BLOCK_CFUNC_FALLBACK_SUPPORT: recognize a `BLOCK`/`SENDB`(`SSENDB`)
  # region NOT already claimed by any of the specific inliners above
  # (`.times`/`.each`/`.map`/... -- compile_method's own caller only ever
  # runs this recognizer's own results through the `suppressed` set those
  # already populated, so a region this DOES match but one of those
  # already claimed never double-fires). Unlike every inliner above, this
  # one names no specific method at all -- it fires for ANY block-
  # carrying call, gated purely on the block BODY being safe to run as a
  # free-standing computation (block_fallback_safe? above) rather than on
  # the receiver's proven class.
  #
  # `n=0` only (no explicit positional args alongside the block) --
  # deliberately narrower than SPLAT_UNROLL_SUPPORT's own `n=N` case:
  # real `OP_SENDB` (3rd/mruby/src/vm.c) places the block register at
  # `a + c + 1` (`c` == the call's own real positional arg count), so
  # `BLOCK R(a+1)` immediately preceding the SENDB/SSENDB is only a
  # sound, confirmed layout when `c == 0` -- every OTHER block recognizer
  # in this file (`.times`/`.each`/...) already only ever matches real
  # `n=0` call sites too, for the exact same reason, never independently
  # exercised for `n>0` anywhere in this whole file. Combining this with
  # a real positional arg list is a natural follow-up once that layout
  # is independently confirmed, not this round's own scope.
  #
  # See recognize_lambda_fallback_regions below for the LAMBDA_FALLBACK_
  # SUPPORT sibling of this recognizer -- a single-instruction `LAMBDA`
  # region (build-only, no paired SENDB, no dispatch) instead of this
  # BLOCK/SENDB pair.
  # NESTED_BLOCK_FALLBACK_SUPPORT: does this region's own block body
  # contain a real `RETURN_BLK`, at ANY nesting depth -- either directly,
  # or inside one of ITS OWN nested BLOCK_FALLBACK regions (recursively).
  # compile_method's own `needs_return_catch` needs this whole-subtree
  # answer, not just the region's own immediate instructions, or a
  # `return` buried two levels deep would silently lose the top-level
  # `try`/`catch` it needs to ever be caught by (emit_proc_fallback_fn's
  # own recursive pass always throws `bc2cpp_method_return` regardless of
  # nesting depth -- only WHERE it's caught depends on this).
  def block_fallback_region_has_return_blk?(region)
    block_irep = region[:block_irep]
    return true if block_irep.instructions.any? { |i| i.op == 'RETURN_BLK' }

    # DEEP_UPVAR_CAPTURE_SUPPORT: `available_upvars` must be this region's
    # OWN captured set here, exactly the value emit_proc_fallback_fn will
    # later pass when it really compiles this same body -- otherwise this
    # pre-scan would recognize a strictly SMALLER set of nested regions
    # than the real emit pass does, and a `RETURN_BLK` living inside a
    # nested region that only the real pass can see would get no
    # `needs_return_catch` wrapper at all: a thrown `bc2cpp_method_return`
    # with nothing to catch it, i.e. `std::terminate`, not a wrong value.
    # One shared expression, so the two passes cannot drift.
    recognize_block_fallback_regions(block_irep, available_upvars: region[:upvars] || [])
      .any? { |nregion| block_fallback_region_has_return_blk?(nregion) }
  end

  # DEEP_UPVAR_CAPTURE_SUPPORT: every enclosing-scope register this irep
  # needs, INCLUDING the ones only its own nested block bodies reference,
  # as real `[level, index]` pairs (`level` counted exactly the way the
  # `GETUPVAR`/`SETUPVAR` third operand counts it: 0 = the immediately
  # enclosing scope).
  #
  # The nested half is the whole point. A block that never mentions an
  # enclosing local ITSELF still has to capture one when a block nested
  # inside IT does -- real, verified shape (`mrbc -v`, this program's own
  # `Game::ChipsetLayout.quads_from_quarters`): the outer `2.times do |j|`
  # block's own irep contains NO `GETUPVAR` at all, while the inner
  # `2.times do |i|` block's does (`GETUPVAR R5 1 1` -> the method's
  # `quarters`, `GETUPVAR R5 3 1` -> the method's `out`). Those level-1
  # references resolve, from the OUTER block's own standalone C++
  # function, to that function's own captured pointer parameters -- which
  # only exist if the outer block captured them, which it will only do
  # because of this propagation. Hence `[l, x]` in a CHILD contributes
  # `[l - 1, x]` here for every `l >= 1` (a child's level 0 is this
  # irep's OWN registers -- ordinary C++ locals in this irep's own
  # function, nothing to capture), applied recursively so an arbitrarily
  # deep nest still lands every pointer it needs in every intermediate
  # frame along the way.
  #
  # Deliberately walks EVERY child irep in `reps`, not only the ones that
  # will really be compiled as nested BLOCK_FALLBACK regions: capturing a
  # pointer nothing ends up reading costs one unused env slot and one
  # unused parameter, while MISSING one would be a dangling C++ name, so
  # the over-approximation is the safe direction. (It cannot cost a
  # regression either: a region this widens into needing a level>0
  # pointer its own enclosing frame cannot supply is declined by the
  # recognizer below and simply stays on today's `#error` path, and a
  # named inliner -- `.times`/`.each`/... -- always claims its own call
  # site BEFORE the BLOCK_FALLBACK pass ever sees it, so an inlined site's
  # codegen is unaffected by anything decided here.)
  #
  # `nil` means "not modelable" -- a malformed operand pair. Recursion is
  # bounded by `MAX_UPVAR_NEST_DEPTH` purely as a guard against a
  # pathological irep graph; real bytecode nests a handful of levels at
  # most.
  MAX_UPVAR_NEST_DEPTH = 16

  def block_upvar_needs(irep, depth = 0)
    return nil if depth > MAX_UPVAR_NEST_DEPTH

    needs = []
    irep.instructions.each do |insn|
      next unless %w[GETUPVAR SETUPVAR].include?(insn.op)

      _reg, upvar_idx, level = insn.args.split(/\s+/)
      return nil unless upvar_idx =~ /\A\d+\z/ && level =~ /\A\d+\z/

      needs << [level.to_i, upvar_idx.to_i]
    end
    (irep.reps || []).each do |child_label|
      child = child_label && @ireps[child_label]
      next unless child

      child_needs = block_upvar_needs(child, depth + 1)
      return nil if child_needs.nil?

      child_needs.each { |(l, x)| needs << [l - 1, x] if l >= 1 }
    end
    needs.uniq.sort
  end

  # BLOCK_FALLBACK_YIELD_SUPPORT: the BLKPUSH analogue of block_upvar_needs
  # above -- which enclosing frame's own received block does this irep (or
  # anything nested inside it) need in order to run its `yield`s?
  #
  # Real `mrbc -v` disassembly of the exact shape this exists for
  # (`def each; @data.size.times { |i| v = self[i]; yield i, v unless
  # v.nil?; }; end`, this program's own LCF::Array2D#each):
  #
  #     irep (method each)  nregs=4 nlocals=2      -- R1 is the block slot
  #       GETIV R2 @data / SEND0 R2 :size
  #       BLOCK R3 I[0] / SENDB R2 :times n=0
  #     irep (block |i|)    nregs=8 nlocals=4  R1:i  R3:v
  #       ...
  #       BLKPUSH  R4  0:0:0:0 (1)     ; <-- lv == 1
  #       BLKCALL  R4  2
  #
  # versus the same `yield` written directly in a method body
  # (`def plain; yield 1, 2; end`), which is what BLKPUSH_YIELD_SUPPORT
  # already handles:
  #
  #       BLKPUSH  R2  0:0:0:0 (0)     ; <-- lv == 0
  #       BLKCALL  R2  2
  #
  # The trailing parenthesised field is `lv`. 3rd/mruby/src/vm.c's own
  # `CASE(OP_BLKPUSH, BS)` decodes the 16-bit operand as
  # `m1=(b>>11)&0x3f, r=(b>>10)&0x1, m2=(b>>5)&0x1f, kd=(b>>4)&0x1,
  # lv=(b>>0)&0xf`, then `if (lv == 0) stack = regs + 1; else { struct REnv
  # *e = uvenv(mrb, lv-1); ...; stack = e->stack + 1; }` and reads
  # `stack[m1+r+m2+kd]`. So `lv` names a FRAME (0 = this one, L = L frames
  # out) exactly the way GETUPVAR's own level operand does -- this is not
  # an assumption carried over from GETUPVAR, it is the real decode.
  #
  # Unlike an upvar, though, there is only ever ONE possible answer, and no
  # index to disambiguate: mrbc's own codegen_yield (3rd/mruby/mrbgems/
  # mruby-compiler/core/codegen.c) computes `lv` as
  #
  #     int lv = 0; codegen_scope *s2 = s;
  #     while (!s2->mscope) { lv++; s2 = s2->prev; if (!s2) break; }
  #     if (s2) ainfo = (int)s2->ainfo;
  #     if (ainfo < 0) codegen_error(s, "invalid yield (SyntaxError)");
  #
  # -- it walks strictly OUTWARD until it hits the first METHOD scope and
  # stops there, taking that method's own `ainfo` (its ENTER argument
  # counts, which is what supplies `m1:r:m2:kd` and hence the register
  # offset of that method's own block slot). A block scope is never
  # `mscope`, so `lv` inside a block body is always >= 1 and always lands
  # on the enclosing METHOD -- never on an intervening block (a block has
  # no block of its own to yield to), and never on a method further out
  # than the first one (the walk stops). `yield` outside any method scope
  # at all is a compile-time SyntaxError, so there is no "no answer" case
  # to model either.
  #
  # Returns the sorted, de-duplicated set of levels `irep`'s own frame
  # would have to supply, with the same child-propagation rule
  # block_upvar_needs uses (a child's `l` becomes `l - 1` here, for
  # `l >= 1`). A child's `l == 0` deliberately contributes NOTHING: that is
  # a nested `def`'s own irep asking for its OWN block, which is that
  # method's business, not this frame's. `nil` means "not modelable" -- a
  # BLKPUSH whose operand text this function could not parse.
  def block_blk_needs(irep, depth = 0)
    return nil if depth > MAX_UPVAR_NEST_DEPTH

    needs = []
    irep.instructions.each do |insn|
      next unless insn.op == 'BLKPUSH'

      lv = insn.args[/\((\d+)\)\s*\z/, 1]
      return nil unless lv

      needs << lv.to_i
    end
    (irep.reps || []).each do |child_label|
      child = child_label && @ireps[child_label]
      next unless child

      child_needs = block_blk_needs(child, depth + 1)
      return nil if child_needs.nil?

      child_needs.each { |l| needs << l - 1 if l >= 1 }
    end
    needs.uniq.sort
  end

  # FIBER_NEW_BLOCK_UNSAFE_SUPPORT: `Fiber.new { ... }`/`Fiber.new do ... end`
  # must never be compiled through the generic BLOCK_FALLBACK path below --
  # mruby's own `Fiber#initialize` (`mrbgems/mruby-fiber/src/fiber.c`'s
  # `init_fiber`) explicitly checks `MRB_PROC_CFUNC_P(p)` and raises
  # `FiberError` for exactly the kind of cfunc-backed `RProc` `emit_rproc_
  # construction` builds -- confirmed the real, 100%-reproducible crash
  # `tools/optcarrot_probe/README.md`'s own "Compiled runtime check" section
  # documents for `Optcarrot::PPU#run`'s `@fiber ||= Fiber.new { ... }`.
  # Patching that check alone would not help: mruby's own Fiber resume/
  # yield machinery works by saving/restoring a bytecode program counter
  # into the proc's own irep (`fiber_switch`'s `mrb_vm_exec(mrb, c->ci->proc,
  # c->ci->pc)`, and `init_fiber` itself reads `p->body.irep->nregs` before
  # that) -- a cfunc-backed proc has no irep and no PC to resume, so
  # removing the check would trade one raised `FiberError` for a null-
  # pointer dereference two lines earlier in `init_fiber`. There is no safe
  # way to hand `Fiber.new` a cfunc-backed proc at all.
  #
  # Recognized here by refusing to admit this shape as a region in the
  # first place, so the `BLOCK`/`SENDB` pair falls through unclaimed to the
  # identical, already-proven-safe path every other genuinely unsupported
  # construct already takes (see the `BLOCK`/`SENDB`/`SSENDB` case in the
  # main instruction switch: an unclaimed pair reaches `compile_insn`, which
  # has no case for either opcode and emits the honest `#error unhandled
  # opcode BLOCK`). `SKIP_UNSUPPORTED=1` then drops the whole containing
  # method back to interpreted, exactly like any other unmodeled opcode --
  # `PPU#run` keeps running through the ordinary mruby VM, which already
  # handles a real, bytecode-backed block literal correctly (this is
  # exactly how it behaved before bc2cpp ever attempted to compile `PPU` at
  # all), while devirtualization can still reach every OTHER compiled `PPU`
  # method fine, since none of them contain this one dangerous shape.
  #
  # Matched narrowly and conservatively: a bare `GETCONST ... Fiber` (never
  # `GETMCNST` -- idiomatic Ruby, and every real call site in this closed
  # world, always references mruby's own top-level `Fiber` class by its
  # bare name, never a namespaced path) written into the exact register
  # the call reads as its receiver, found by the same short backward walk
  # `IvarLayout.trace_type` uses elsewhere in this file: only `MOVE` is
  # followed through, any other write to the register stops the walk and
  # answers false. A miss here (an indirect receiver, a differently-
  # shaped load, a real user class that happens to also be named `Fiber`
  # under some namespace) is always SAFE, never a new risk -- the call site
  # just falls through to whatever it would otherwise have done, exactly
  # as it always has for every call site either of this method's own two
  # callers does not recognize. Named generically (not `fiber_new_
  # receiver?`) because `calls_fiber_yield?` below reuses it verbatim for
  # a plain `SEND`'s own receiver, not just `Fiber.new`'s `SENDB`.
  def fiber_const_receiver?(irep, call_idx, dest_reg)
    reg = dest_reg
    (call_idx - 1).downto(0) do |i|
      insn = irep.instructions[i]
      case insn.op
      when 'MOVE'
        d, s = insn.args.scan(/R(\d+)/).flatten
        next unless d == reg

        reg = s
      when 'GETCONST'
        d = insn.args[/^R(\d+)/, 1]
        next unless d == reg

        return insn.args.split(/\s+/)[1] == 'Fiber'
      else
        d = insn.args[/^R(\d+)/, 1]
        return false if d == reg
      end
    end
    false
  end

  # FIBER_YIELD_UNSAFE_SUPPORT: `Fiber.yield` -- unlike `Fiber.new { block
  # }` above, this is a plain `SEND`/`SEND0` (no `BLOCK` operand at all,
  # confirmed via a fresh `mrbc -v` disassembly: `GETCONST R2 Fiber` +
  # `SEND R2 :yield n=1` / `SEND0 R2 :yield`), so it already compiles
  # successfully through bc2cpp's ordinary dynamic-dispatch codegen --
  # nothing recognizes `:yield` as special, so it becomes an ordinary
  # `mrb_funcall`-style call reaching mruby's own `fiber_yield`/
  # `mrb_fiber_yield` (`mrbgems/mruby-fiber/src/fiber.c`) directly from
  # whatever native C++ frame this compiled method's own body happens to
  # be running in.
  #
  # Confirmed unsafe empirically, not by inspection alone: excluding only
  # the `Fiber.new` construction site (`fiber_const_receiver?`'s other
  # caller, above) and recompiling `Optcarrot::PPU`'s own `main_loop`/
  # `wait_frame`/`wait_zero_clocks`/`wait_one_clock`/`wait_two_clocks` --
  # the fiber body's own real payload, all of which reach `Fiber.yield`
  # directly -- still crashed the real 180-frame benchmark with
  # `FiberError: resuming dead fiber`, a *different* failure from the one
  # excluding `Fiber.new` alone already fixed. Traced to mruby's own
  # `vmexec`-reentrant fiber-resume path (`fiber_switch`/`fiber_resume` in
  # `fiber.c`) getting confused once a native, VM-invisible compiled frame
  # sits between the fiber's own entry point and wherever it actually
  # yields -- see `tools/optcarrot_probe/README.md` for the full traced
  # mechanism.
  #
  # The fix is the same shape as `Fiber.new`'s own: a method whose own
  # bytecode directly calls `Fiber.yield` is refused compilation entirely
  # (an early `#error` stub, the same shape `compile_method`'s own "has
  # non-mandatory arguments" rejection already returns) rather than left
  # to compile into code that is syntactically fine but unsound at
  # runtime. Deliberately scoped to DIRECT calls only, not a full whole-
  # program reachability closure from every `Fiber.new`'s own block body
  # forward -- see `compile_method`'s own call site for what that would
  # still need to cover (a `Fiber.yield` reached only transitively,
  # through another compiled method that itself calls neither `Fiber.new`
  # nor `Fiber.yield` directly, is not caught by this) and why this
  # narrower fix was the one actually verified end-to-end this session.
  def calls_fiber_yield?(irep)
    irep.instructions.each_with_index do |insn, idx|
      next unless %w[SEND SEND0].include?(insn.op)

      name = insn.args[/:([\w+\-*\/<>=!?\[\]&|^~%@]+)/, 1]
      next unless name == 'yield'

      dest_reg = insn.args[/^R(\d+)/, 1]
      next unless dest_reg
      next unless fiber_const_receiver?(irep, idx, dest_reg)

      return true
    end
    false
  end

  # FIBER_REACHABILITY_UNSAFE_SUPPORT: FIBER_YIELD_UNSAFE_SUPPORT
  # (calls_fiber_yield? above) refuses a method that DIRECTLY calls
  # `Fiber.yield` -- verified, empirically, NOT sufficient on its own.
  # Excluding `Optcarrot::PPU#run` (`Fiber.new`) and its 4 direct
  # `Fiber.yield` callers (`wait_frame`/`wait_zero_clocks`/`wait_one_clock`/
  # `wait_two_clocks`) and recompiling the real 180-frame Optcarrot
  # benchmark still crashed with the identical `resuming dead fiber
  # (FiberError)`. `main_loop` -- the fiber body's own real payload,
  # compiled, calling those 4 methods through ordinary bare self-sends --
  # still sat, compiled, between the fiber's own entry point and every
  # yield, which is evidently just as unsound as `Fiber.yield` itself
  # living in compiled code (see tools/optcarrot_probe/README.md for the
  # full traced mechanism: mruby's own `vmexec`-reentrant fiber-resume path
  # getting confused by ANY native, VM-invisible frame in that chain, not
  # only the one that happens to call `Fiber.yield` itself).
  #
  # This computes the full transitive closure instead: starting from every
  # `Fiber.new { block }` call site's own block body (found the same way
  # `recognize_block_fallback_regions`' own gate finds one, scanned across
  # the WHOLE program here rather than one method at a time), follow every
  # bare/self-implicit send (`SSEND`/`SSEND0`/`SSENDB` -- a call written
  # without an explicit receiver, which Ruby resolves to `self`
  # unambiguously) to another method of the SAME owner class, and refuse
  # to compile every method reached this way, however many hops out.
  #
  # Deliberately scoped to same-owner self-sends only, not a general
  # whole-program call graph: every real call inside a Fiber body in this
  # closed world (`main_loop` calling `open_name`/`wait_two_clocks`/...,
  # `run` calling `@fiber.resume`, ...) already has this exact shape,
  # since a Fiber body is ordinary instance-method code written within one
  # class. An explicit-receiver call (`@cpu.something`) crossing OUT of
  # the fiber's own class is out of scope here -- a real gap if such a
  # call itself eventually reaches a `Fiber.yield`, but no such call
  # exists anywhere in this closed world, and missing one here is safe in
  # the direction that matters: the method in question simply stays
  # eligible to compile, at worst reproducing the exact crash this whole
  # mechanism exists to prevent (loud and immediate, the same FiberError
  # already documented), never a silent wrong answer from a false proof.
  def compute_fiber_unsafe_methods
    by_owner_name = {} # [owner, name] -> irep label, registered methods only
    irep_owner = {} # irep label -> owner, registered methods AND every block nested inside them
    @registry.each_value do |defs|
      defs.each do |d|
        next unless d.irep

        by_owner_name[[d.owner, d.name]] = d.irep
        irep_owner[d.irep] = d.owner
      end
    end

    # A block always shares its enclosing method's self/owner in real
    # Ruby, so propagating each registered method's own owner down through
    # its own nested block ireps (irep.reps, transitively) is exact, not a
    # guess -- this is what lets a Fiber.new seed found several block
    # levels deep (not this closed world's own shape today, but not
    # assumed away either) resolve to the right owner below.
    propagate = irep_owner.keys.dup
    until propagate.empty?
      label = propagate.shift
      irep = @ireps[label]
      next unless irep

      owner = irep_owner[label]
      (irep.reps || []).each do |child_label|
        next unless child_label
        next if irep_owner.key?(child_label)

        irep_owner[child_label] = owner
        propagate << child_label
      end
    end

    seeds = []
    @ireps.each_value do |irep|
      irep.instructions.each_with_index do |insn, idx|
        next unless insn.op == 'BLOCK'

        paired = irep.instructions[idx + 1]
        next unless paired && paired.op == 'SENDB'
        next unless paired.args[/:([\w+\-*\/<>=!?\[\]&|^~%@]+)/, 1] == 'new'

        dest_reg = paired.args[/^R(\d+)/, 1]
        next unless dest_reg && fiber_const_receiver?(irep, idx, dest_reg)

        block_irep_idx = insn.args[/I\[(\d+)\]/, 1]
        next unless block_irep_idx

        block_label = irep.reps[block_irep_idx.to_i]
        seeds << block_label if block_label
      end
    end

    unsafe = Set.new
    # SEEDS_MULTIPLE_OWNERS_SUPPORT: resolved per seed, not against one
    # shared owner -- a second Fiber.new under a different class must
    # never be mis-attributed to the first one's owner.
    queue = seeds.flat_map do |label|
      seed_irep = @ireps[label]
      next [] unless seed_irep

      owner = irep_owner[label]
      next [] unless owner

      self_call_targets(seed_irep).filter_map { |name| by_owner_name[[owner, name]] }
    end
    until queue.empty?
      label = queue.shift
      next unless unsafe.add?(label)

      irep = @ireps[label]
      next unless irep

      owner = irep_owner[label]
      next unless owner

      self_call_targets(irep).each do |name|
        target = by_owner_name[[owner, name]]
        queue << target if target
      end
    end
    @fiber_unsafe_methods = unsafe
  end

  # Every bare/self-implicit send name (`SSEND`/`SSEND0`/`SSENDB`) reachable
  # from `irep`, INCLUDING every send inside its own nested block ireps
  # (`irep.reps`, recursively) -- a nested block literal (`341.step(589, 8)
  # do ... end`'s own body) is never independently compiled or dispatched;
  # its instructions are part of whichever top-level method contains it, so
  # a self-send buried inside one has to be found here too, not just at the
  # top level, or compute_fiber_unsafe_methods above would silently miss a
  # real call the fiber body actually makes.
  def self_call_targets(irep, seen = Set.new.compare_by_identity)
    return [] unless seen.add?(irep)

    names = []
    irep.instructions.each do |insn|
      next unless %w[SSEND SSEND0 SSENDB].include?(insn.op)

      name = insn.args[/:([\w+\-*\/<>=!?\[\]&|^~%@]+)/, 1]
      names << name if name
    end
    (irep.reps || []).each do |child_label|
      child = child_label && @ireps[child_label]
      names.concat(self_call_targets(child, seen)) if child
    end
    names
  end

  def recognize_block_fallback_regions(irep, available_upvars: [], blk_available: false)
    regions = []
    irep.instructions.each_with_index do |insn, idx|
      next unless insn.op == 'BLOCK'

      paired = irep.instructions[idx + 1]
      next unless paired && %w[SENDB SSENDB].include?(paired.op)

      # EXPLICIT_ARGS_BLOCK_FALLBACK_SUPPORT: `n=0` was this mechanism's
      # own original, narrowest gate (a block call with no OTHER explicit
      # positional args, e.g. `ary.each { ... }`); generalized here to any
      # fixed positional count (`ary.inject(0) { ... }`,
      # `ary.each_slice(2) { ... }`, ...). Deliberately still `\d+` only,
      # never `*` (a real splat -- SPLAT_CALL_ARGS, a genuinely dynamic
      # argument count with no static register layout to build `argv`
      # from) and never followed by anything but whitespace/end-of-string
      # (excludes a keyword call, `n=3|nk=1` -- KEYWORD_CALLSITE_SUPPORT's
      # own comment: `mrb_funcall_with_block` can never carry keywords at
      # all, `ci->nk = 0` in mruby's own funcall_args_capture, so a
      # keyword-plus-block call site has no sound dynamic-dispatch
      # translation here regardless of upvar/break/return support).
      n_match = paired.args.match(/n=(\d+)(?:\s|$)/)
      next unless n_match

      n = n_match[1].to_i
      dest, _rest = paired.args.split(/\s+/, 2)
      dest_reg = dest[/^R(\d+)/, 1]
      block_reg = insn.args[/^R(\d+)/, 1]
      # Register layout confirmed against the identical `reduce(init)`
      # shape recognize_accum_regions already established (`dest, then n
      # positional args, then the block` -- real `mrbc -v`: `BLOCK R4` +
      # `SENDB R2 :reduce n=1` has the block two past dest, matching
      # `dest + n + 1` for n=1; `n=0` keeps the original `dest + 1`).
      next unless dest_reg && block_reg && block_reg == (dest_reg.to_i + n + 1).to_s

      name = paired.args[/:([\w+\-*\/<>=!?\[\]&|^~%@]+)/, 1]
      next unless name

      # FIBER_NEW_BLOCK_UNSAFE_SUPPORT: see that method's own comment --
      # never admit `Fiber.new { ... }` as a BLOCK_FALLBACK region.
      next if paired.op == 'SENDB' && name == 'new' && fiber_const_receiver?(irep, idx, dest_reg)

      block_irep_idx = insn.args[/I\[(\d+)\]/, 1]
      next unless block_irep_idx

      block_label = irep.reps[block_irep_idx.to_i]
      block_irep = block_label && @ireps[block_label]
      next unless block_irep && block_fallback_safe?(block_irep)

      upvars = block_upvar_needs(block_irep)
      next if upvars.nil?

      # DEEP_UPVAR_CAPTURE_SUPPORT: a level-0 need is always suppliable --
      # it names a register of the function this call site sits in, an
      # ordinary C++ local there (`&r<idx>`), exactly as UPVAR_CAPTURE_
      # SUPPORT always did. A level-L need for L >= 1 names a register
      # L more frames out, which this call site can only forward if the
      # function it sits in ALREADY holds that pointer itself -- i.e. if
      # `[L - 1, idx]` is in `available_upvars`, the captured set of the
      # enclosing block body being compiled right now (empty at ordinary
      # method level, where there is no enclosing Ruby scope to capture
      # from at all, so every L >= 1 is correctly refused there).
      # `block_upvar_needs`' own child propagation is exactly what makes
      # this hold rather than merely be checked: the enclosing block's own
      # needs were computed with the same function, from the same child
      # ireps, so whatever a nested region asks for here was already
      # propagated into that enclosing capture set. The check is kept as a
      # real gate rather than an assertion so that any shape the
      # propagation does NOT cover degrades to today's honest `#error`
      # instead of emitting a dangling C++ name.
      next unless upvars.all? { |(l, x)| l.zero? || available_upvars.include?([l - 1, x]) }

      # UPVAR_CAPTURE_SUPPORT: a NON-EMPTY capture set still needs the
      # call-site's own method name to be on the hand-vetted synchronous-
      # dispatch allowlist -- see BLOCK_FALLBACK_UNSAFE_OPS's own comment
      # for why pointer-capture is unsound for a receiver that might store
      # the block rather than invoke it synchronously. An empty set (no
      # upvars at all) needs no such gate.
      #
      # DEEP_UPVAR_CAPTURE_SUPPORT: this gate is what makes a DEEPER
      # capture sound too, with no new argument needed. A level-1 pointer
      # forwarded from here points into the frame of the method two calls
      # out, and stays valid exactly as long as that frame is live. It is
      # live because EVERY level between here and it is itself gated by
      # this same allowlist: the inner block only runs while the outer
      # block that forwarded the pointer is running, and the outer block
      # only runs while the enclosing method is, because the outer call
      # site's own capture set is non-empty by construction (the
      # propagation above put the forwarded index in it) and so the outer
      # site had to pass this identical check. Synchronous invocation at
      # every level chains into "the whole frame chain is live", which is
      # precisely the property the level-0 argument already relied on.
      next if upvars.any? && !BLOCK_FALLBACK_UPVAR_SAFE_METHODS.include?(name)

      # BLOCK_FALLBACK_YIELD_SUPPORT: does this block body's own `yield`
      # (`BLKPUSH`, see block_blk_needs above) need the ENCLOSING METHOD's
      # own received block forwarded into the standalone cfunc?
      #
      # `[1]` -- and ONLY `[1]` -- is the shape this round models: every
      # BLKPUSH in the whole subtree resolves to the frame exactly one level
      # out from the block body, i.e. the frame THIS call site sits in. That
      # is the frame whose own block value the emitter below can actually
      # name as a C++ local, so it is the frame it can actually capture.
      #
      # Deliberately a bounded slice. A deeper need (`[2]`, a `yield` inside
      # a block inside a block, reaching back through TWO frames) is real,
      # modelable in principle by forwarding the already-captured value one
      # more level exactly the way DEEP_UPVAR_CAPTURE_SUPPORT forwards an
      # upvar pointer -- but no such site exists anywhere in this whole
      # closed world today (a real whole-program sweep: every BLKPUSH inside
      # a block body is `lv == 1`), so it is left at the honest `#error`
      # rather than shipped untested. `blk_available` is the other half of
      # the same "can this level actually SUPPLY it?" question the
      # `available_upvars` gate above asks: only compile_method's own
      # top-level call passes it true, and only for a method whose entry
      # wrapper can really extract a block (`pure_mandatory_arity?`, the
      # same `mandatory_ok` condition `needs_blk_param` itself is gated on,
      # so the two can never disagree about whether the parameter exists).
      #
      # `needs_blk` never gates region ADMISSION -- a body whose BLKPUSH
      # this cannot answer still produces its region here, exactly as
      # before, and still fails later on the `#error` its own unhandled
      # BLKPUSH emits (emit_proc_fallback_fn's own ALL_OR_NOTHING_SUPPORT
      # check), which is precisely today's behaviour. So every shape not
      # newly supported keeps byte-for-byte identical output.
      #
      # The synchronous-dispatch allowlist is required here for the same
      # reason UPVAR_CAPTURE_SUPPORT requires it, though for a subtly
      # different failure mode. The captured block is an `mrb_value` COPY
      # (see emit_rproc_construction), not a pointer into a frame, so it
      # cannot dangle and is independently GC-rooted by the RProc's own env
      # array -- but the block it names is itself an ordinary irep-backed
      # RProc whose OWN env is on the caller's stack, so invoking it after
      # the enclosing method's caller has returned would be exactly the
      # escaped-block hazard. Real vm.c refuses that case itself
      # (`if (!e || (!MRB_ENV_ONSTACK_P(e) && e->mid == 0) ...) RAISE_LIT(
      # mrb, E_LOCALJUMP_ERROR, "unexpected yield")`); the allowlist is
      # what keeps this compiler from having to. Every receiver on it has
      # already been hand-vetted to invoke its block synchronously and never
      # store it -- so the enclosing method's frame, and therefore its
      # caller's, is still live for the whole duration of the call.
      blk_needs = block_blk_needs(block_irep)
      needs_blk = blk_available && blk_needs == [1] &&
                  BLOCK_FALLBACK_UPVAR_SAFE_METHODS.include?(name)

      regions << { block_addr: insn.addr, sendb_addr: paired.addr, dest_reg: dest_reg,
                   block_irep: block_irep, name: name, n: n,
                   self_implicit: paired.op == 'SSENDB', upvars: upvars, needs_blk: needs_blk,
                   parent_irep: irep }
    end
    regions
  end

  # BLOCK_FALLBACK_ELEMENT_SUPPORT: carry an exact element class into the
  # standalone cfunc only for a known Array or Hash iterator with a proven
  # yield shape. Reuse the existing receiver and element proofs; other
  # iterators and untyped containers keep dynamic dispatch.
  def block_fallback_element_class(irep, region, owner_name)
    return nil unless irep && !region[:self_implicit]

    shape = case region[:name]
            when 'each' then [:array, 0, 1]
            when 'each_with_index' then [:array, 0, 2]
            when 'each_with_object' then [:array, 1, 2]
            when 'each_value' then [:hash, 0, 1]
            end
    return nil unless shape && region[:n] == shape[1]
    return nil unless mandatory_arity(region[:block_irep]) == shape[2]

    idx = irep.instructions.index { |insn| insn.addr == region[:sendb_addr] }
    return nil unless idx

    insn = irep.instructions[idx]
    return nil unless insn.op == 'SENDB'

    mand = mandatory_arity(irep)
    ivar_classes = @class_layout[owner_name] || {}
    arg_classes = @class_annotations[irep.label]&.args
    recv_class = trace_new_target(irep, idx, region[:dest_reg], ivar_classes, mand, arg_classes,
                                  owner: owner_name, class_layout: @class_layout, registry: @registry,
                                  container_constants: @container_constants,
                                  element_annotations: @element_annotations)
    if shape[0] == :array
      recv_class = proven_array_source(irep, idx, region[:dest_reg]) unless recv_class == 'Array'
      return nil unless recv_class == 'Array'

      proven_element_class(irep, idx, region[:dest_reg], ivar_classes, mand, arg_classes, owner_name)
    else
      return nil unless recv_class == 'Hash'

      proven_hash_element_class(irep, idx, region[:dest_reg], ivar_classes, mand, arg_classes, owner_name)
    end
  end

  # BLOCK_CFUNC_FALLBACK_SUPPORT / LAMBDA_FALLBACK_SUPPORT: the block/
  # lambda body's own standalone top-level function pair -- a real `_impl`
  # (this body's own instructions, translated exactly like any other
  # irep's body via the same compile_insn every other emitter here
  # reuses) plus a genuine `mrb_func_t`-shaped cfunc entry
  # (`mrb_value(mrb_state*, mrb_value)`, `mrb_proc_new_cfunc_with_env`'s
  # own required signature) that extracts the real yielded/called
  # arguments via `mrb_get_args` -- the identical mechanism
  # `compile_method`'s own plain-mandatory-arity entry wrapper already
  # uses, reused here because a CFUNC-backed proc invoked either as a
  # yielded block or an ordinary `.call` (`exec_irep`, 3rd/mruby/src/
  # vm.c: `ci->stack[0] = self; return MRB_PROC_CFUNC(p)(mrb, self);`)
  # receives its real call arguments on the VM stack in exactly the same
  # shape an ordinary call does.
  #
  # Shared verbatim by both features -- called from BLOCK_CFUNC_FALLBACK_
  # SUPPORT's own recognize_block_fallback_regions/emit_block_fallback_
  # glue (a BLOCK/SENDB pair, dispatched with mrb_funcall_with_block) and
  # LAMBDA_FALLBACK_SUPPORT's own recognize_lambda_fallback_regions/
  # emit_lambda_fallback_glue (a single LAMBDA instruction, stored into
  # its destination register with no dispatch at all) below: this
  # function only ever needs `region[:block_irep]` (the child irep to
  # compile) and `region[:block_addr]` (for a globally-unique function
  # name) -- both recognizers populate them the same way, so nothing
  # about the call-site shape ever needs to leak in here.
  #
  # SELF_CAPTURE_SUPPORT: the entry point's own `self` PARAMETER (what
  # mruby itself passes in) is deliberately never used for anything --
  # it's whatever `mrb_yield`/`mrb_proc_get_self` guessed, always `nil`
  # for a CFUNC-backed proc (see block_fallback_safe?'s own comment).
  # The REAL self this body should see is instead read back out of the
  # RProc's own captured env slot 0 (`mrb_proc_cfunc_env_get`) --
  # emit_rproc_construction below is the OTHER half of this, shared by
  # both glue emitters: it captures the enclosing method's own real
  # `self` C++ variable into that exact slot at RProc-construction time,
  # the one place this compiler actually knows the correct value.
  def emit_proc_fallback_fn(region, d, fn_prefix = nil)
    block_irep = region[:block_irep]
    mand = mandatory_arity(block_irep)
    arg_names = (1..mand).map { |i| "bc2cpp_barg#{i}" }
    # UPVAR_CAPTURE_SUPPORT: `region[:upvars]` is set by
    # recognize_block_fallback_regions and -- since CONFINED_LAMBDA_UPVAR_
    # SUPPORT -- by recognize_lambda_fallback_regions too, for a LAMBDA
    # whose own proc value was PROVED never to leave the frame it is built
    # in (lambda_proc_frame_confined?; see LAMBDA_FALLBACK_UNSAFE_OPS' own
    # comment for why that proof is what a lambda needs in place of a
    # BLOCK_FALLBACK site's synchronous-dispatch allowlist). Either way the
    # capture mechanism below is byte-for-byte the same one, so `|| []`
    # here is still the plain "no upvars" case, not a defensive guess.
    # DEEP_UPVAR_CAPTURE_SUPPORT: each entry is a real `[level, index]`
    # pair now, never a bare index -- see upvar_var_name's own comment for
    # the real disassembly showing why the level has to be part of the
    # identity. A level-0 entry still spells its parameter exactly as
    # before, so every already-shipping level-0-only body's generated C++
    # is unchanged.
    upvar_regs = region[:upvars] || []
    upvar_params = upvar_regs.map { |(l, b)| "mrb_value* #{upvar_var_name(l, b)}" }
    # BLOCK_FALLBACK_YIELD_SUPPORT: one more captured value when this body
    # really does `yield` to the ENCLOSING METHOD's own block -- see
    # recognize_block_fallback_regions' own `needs_blk` comment for the real
    # disassembly and the exact gate. Only ever set by
    # recognize_block_fallback_regions, never by recognize_lambda_fallback_
    # regions (a LAMBDA-constructed proc can genuinely escape and outlive
    # the frame whose block it would be capturing -- exactly the hazard the
    # synchronous-dispatch allowlist rules out for a BLOCK_FALLBACK site and
    # nothing rules out for a lambda), so `false` here is the plain "no
    # forwarded block" case for LAMBDA_FALLBACK, not a defensive guess.
    needs_blk = region[:needs_blk] ? true : false
    blk_param = needs_blk ? ['mrb_value bc2cpp_blk'] : []
    # `block_addr` alone is only unique WITHIN one irep -- two unrelated
    # methods can easily have a BLOCK/LAMBDA at the same numeric bytecode
    # offset (a real, caught-before-shipping bug: the first version of
    # this named the function off `block_addr` alone, which would have
    # emitted duplicate top-level C++ symbols the moment two different
    # methods' own fallback bodies happened to share an address).
    # `cpp_name(d.owner, d.name)` is already this whole program's own
    # established globally-unique per-method key (every `_impl`/entry
    # function name here is built from it) -- prefixing with it, exactly
    # like emit_rescue_try_body's own `"#{impl_name}_rescue_try#{i}"`,
    # makes the combination unique too. `region[:kind]` (`block_fallback`
    # by default, `lambda_fallback` from recognize_lambda_fallback_
    # regions) only affects the generated C++ symbol's own readability --
    # both recognizers already guarantee `block_addr` uniqueness the same
    # way, so it plays no role in the uniqueness argument itself.
    # NESTED_BLOCK_FALLBACK_SUPPORT: `fn_prefix`, when this call is itself
    # the recursive processing of a region NESTED inside another block
    # body, is that OUTER level's own already-unique `fn_name` -- a nested
    # region's own `block_addr` lives in the block irep's OWN local
    # address space, which can numerically collide with an unrelated
    # region elsewhere using `cpp_name(d.owner, d.name)` alone (the same
    # `d`, an unrelated top-level or sibling-nested region happening to
    # share a numeric offset); chaining through the parent's own name --
    # itself unique by the same recursive argument -- keeps every level
    # unique without needing a separate global counter.
    fn_name = "#{fn_prefix || cpp_name(d.owner, d.name)}_#{region[:kind] || 'block_fallback'}_#{region[:block_addr]}"
    impl_name = "#{fn_name}_impl"

    # NESTED_BLOCK_FALLBACK_SUPPORT: recursively recognize/emit/suppress
    # any BLOCK/SENDB(SSENDB) region NESTED inside THIS block's own body,
    # exactly the same recognize_block_fallback_regions -> emit_proc_
    # fallback_fn -> emit_block_fallback_glue pipeline compile_method's own
    # top-level loop already runs -- see BLOCK_FALLBACK_UNSAFE_OPS's own
    # NESTED_BLOCK_FALLBACK_SUPPORT comment for why this composes safely
    # with upvar capture and the two exception carriers with no other
    # change needed. Runs BEFORE this level's own `@block_fallback_upvars`/
    # `@block_fallback_active` are set below -- a recursive call fully
    # sets, uses, and clears its OWN copies of those same two ivars before
    # returning, so by the time this level sets its own there is nothing
    # left to clobber (never concurrent -- one call frame at a time).
    # Emitted into `nested_pre`, prepended to this level's own returned
    # code below, so a nested function is always textually defined before
    # this level's own trampoline/glue references it.
    nested_pre = String.new
    nested_suppressed = []
    nested_glue_at = {}
    # BLOCK_FALLBACK_RESCUE_SUPPORT: pre-claim every real `rescue`
    # region's own address range in `nested_suppressed` BEFORE the
    # nested-BLOCK_FALLBACK pass just below ever runs, so a block-carrying
    # call sitting INSIDE a rescue clause here is never independently
    # (mis)claimed by that pass -- `recognize_rescue_regions` itself is a
    # pure, side-effect-free function of `block_irep` alone, safe to call
    # this early, but the actual extraction (`emit_rescue_try_body`, a few
    # lines below) has to wait until `@block_fallback_upvars`/
    # `@block_fallback_active` are set (its own compile_insn calls need
    # them) -- exactly the ordering constraint the nested-BLOCK_FALLBACK
    # pass's own comment states the other way around (it has to run
    # BEFORE those ivars are set). Splitting "claim the addresses" from
    # "emit the real code" is what lets both constraints hold at once.
    rescue_regions = top_level_rescue_regions(recognize_rescue_regions(block_irep))
    rescue_regions.each do |rregion|
      nested_suppressed.concat((rregion[:begin_addr]..rregion[:end_addr]).to_a)
      nested_suppressed << rregion[:except_addr]
    end
    # DEEP_UPVAR_CAPTURE_SUPPORT: `available_upvars` is THIS body's own
    # captured-pointer set -- exactly the parameters `upvar_params` above
    # declares and therefore exactly what a nested region is allowed to
    # forward one level further in (see the recognizer's own comment).
    recognize_block_fallback_regions(block_irep, available_upvars: upvar_regs).each do |nregion|
      # BLOCK_FALLBACK_RESCUE_SUPPORT: skip a region already pre-claimed
      # above by a rescue region's own address range -- it belongs to
      # THAT region's own separate, restricted-range recognize/emit pass
      # (a few lines below, via emit_rescue_try_body's own internal
      # emit_block_fallback_glue_pass call), never this unrestricted one,
      # or it would be emitted twice.
      next if nested_suppressed.include?(nregion[:block_addr]) || nested_suppressed.include?(nregion[:sendb_addr])

      fn_result = emit_proc_fallback_fn(nregion, d, fn_name)
      next unless fn_result

      nfn_name, nfn_code = fn_result
      nested_pre << nfn_code
      nested_suppressed << nregion[:block_addr] << nregion[:sendb_addr]
      nested_glue_at[nregion[:block_addr]] = emit_block_fallback_glue(nregion, nfn_name)
    end
    # EXPLICIT_BLOCK_ARG_SUPPORT: same recursive composition as the
    # nested BLOCK_FALLBACK pass just above -- a `&expr`-shaped SENDB/
    # SSENDB inside THIS block's own body needs no recursive compile of
    # its own (see that recognizer's own comment, no block body exists to
    # compile at all here either), just the same suppress/glue wiring.
    recognize_explicit_block_arg_regions(block_irep).each do |nregion|
      next if nested_suppressed.include?(nregion[:sendb_addr])

      nested_suppressed << nregion[:sendb_addr]
      nested_glue_at[nregion[:sendb_addr]] = emit_explicit_block_arg_glue(nregion)
    end

    # RUNTIME_DEF_FALLBACK_SUPPORT: a real `def` inside an EXEC-opened class
    # body (`class << Graphics; def update; ...; end; end`) compiles to a
    # TDEF instruction whose `I[c]` operand names the method body's own child
    # irep. That body is compiled here by exactly the same recursive
    # emit_proc_fallback_fn call the nested-BLOCK_FALLBACK pass just above
    # already makes -- same all-or-nothing contract, same unique-name
    # chaining through `fn_name` -- just with `self_source: :receiver` and a
    # `tdef_fallback` kind, and installed by emit_tdef_fallback_glue rather
    # than wrapped in an RProc.
    #
    # Deliberately gated on `exec_fallback`: a TDEF is only translatable when
    # this body's own `self` is provably the target class, which is true for
    # an EXEC-opened class body (OP_EXEC's own `recv`/`c` identity, see the
    # self_source comment below) and is NOT true anywhere else this function
    # is ever reached from -- inside a block or lambda body, `check_target_
    # class(mrb)` walks out to whatever lexical scope the proc was built in,
    # which compiled code has no handle on at all. Everywhere else a TDEF
    # keeps its honest `#error`, exactly as before this mechanism existed.
    #
    # Runs BEFORE `@block_fallback_upvars`/`@block_fallback_active` are set,
    # for the identical reason the nested-BLOCK_FALLBACK pass above states:
    # the recursive call manages its own copies of those ivars and needs them
    # still unset when it runs.
    if region[:kind] == 'exec_fallback'
      block_irep.instructions.each do |tinsn|
        next unless tinsn.op == 'TDEF'
        next if nested_suppressed.include?(tinsn.addr)

        tregion = tdef_fallback_region(tinsn, block_irep)
        next unless tregion

        tfn_result = emit_proc_fallback_fn(tregion, d, fn_name)
        next unless tfn_result

        tfn_name, tfn_code = tfn_result
        nested_pre << tfn_code
        nested_suppressed << tinsn.addr
        nested_glue_at[tinsn.addr] = emit_tdef_fallback_glue(tregion, tfn_name)
      end
    end

    # ALL_OR_NOTHING_SUPPORT: same contract every other block emitter in
    # this file already holds itself to (emit_sort_inline's own explicit
    # `return nil if body.include?('#error')`, emit_times_inline's own
    # caller comment) -- a block body that itself hits an unsupported
    # opcode must produce NO region at all, not a real-looking RProc/
    # cfunc wrapper around a function that still can't compile. Without
    # this check the caller would still correctly leave the WHOLE
    # enclosing method uncompiled (compiles_clean? scans the complete
    # returned code string, this function's own embedded `#error`
    # included -- confirmed nothing unsound could ship even without this
    # check), but it would waste a real region slot and, worse, sit
    # there miscounting this site as a genuine BLOCK_FALLBACK win in the
    # coverage report's own diagnostic. Caught live: BLKCALL/BLKPUSH's
    # own whole-program #error counts ticked up by exactly 1 each the
    # first time this check was missing, from a block body that itself
    # used one of those two still-unsupported opcodes.
    # UPVAR_CAPTURE_SUPPORT: consume-and-clear, exactly like
    # compile_send's own @elem_class_hint -- set for exactly this one
    # body-compile loop (never any other call to compile_insn, including
    # a nested call this same loop might make for an unrelated irep), so
    # compile_insn's own GETUPVAR/SETUPVAR cases can only ever see a real
    # captured-pointer variable name that this function ITSELF is about
    # to declare a parameter for, never a stale value left over from a
    # previous, unrelated block-fallback body.
    @block_fallback_upvars = upvar_regs
    # EXCEPTION_BREAK_SUPPORT: same consume-and-clear discipline, gating
    # compile_insn's own BREAK case between two real, already-established
    # translations -- LAMBDA_FALLBACK (region[:kind] == 'lambda_fallback')
    # keeps the existing plain `return` (a LAMBDA-constructed proc is
    # unconditionally strict, see that case's own comment), BLOCK_FALLBACK
    # gets the new `throw`. Never both at once (this function only ever
    # compiles one region's own body per call).
    # RUNTIME_DEF_FALLBACK_SUPPORT: a method body / EXEC-opened class body is
    # neither of the two pre-existing kinds, and must NOT get BLOCK_FALLBACK's
    # throwing BREAK -- see RUNTIME_DEF_FALLBACK_KINDS' own comment. Spelled
    # as an explicit membership test on the two kinds that have always set
    # this true (`nil`, the recognizer's own default, and the literal
    # 'block_fallback') rather than as a second `!=` exclusion, so every
    # future kind added to this function is opted OUT by default instead of
    # silently inheriting a translation it may not be entitled to. The
    # runtime_def_fallback_kind? assertion below states the same fact the
    # other way round, so the two can never drift apart unnoticed.
    raise "unexpected self_source for #{region[:kind]}" if
      runtime_def_fallback_kind?(region[:kind]) && region[:self_source] != :receiver
    @block_fallback_active = [nil, 'block_fallback'].include?(region[:kind])
    # BLOCK_FALLBACK_YIELD_SUPPORT: same consume-and-restore discipline,
    # gating compile_insn's own BLKPUSH case. SAVED and RESTORED rather than
    # cleared, unlike the two ivars just above: compile_method's own
    # top-level body loop sets @blk_param_name too (BLKPUSH_YIELD_SUPPORT),
    # and this function can also be reached recursively for a nested region,
    # so simply nil-ing it afterwards would silently disarm an enclosing
    # context's own perfectly valid BLKPUSH translation. Level 1 is the only
    # value ever set here, matching exactly the `blk_needs == [1]` shape the
    # recognizer admitted -- a direct child block of the method, whose own
    # `yield` disassembles as `BLKPUSH Rx m1:r:m2:kd (1)`.
    saved_blk_param_name = @blk_param_name
    saved_blk_param_level = @blk_param_level
    @blk_param_name = needs_blk ? 'bc2cpp_blk' : nil
    @blk_param_level = 1
    # BLOCK_FALLBACK_RESCUE_SUPPORT: a real `rescue` clause INSIDE a
    # block's own body -- `cached_bitmap(cache, key) { Bitmap.new(...)
    # rescue StandardError => e; ...; end }`, `RPG2k::Scene::Battle#
    # actor_battlecharset_bitmap`'s own real shape -- was still
    # unconditionally rejected by `BLOCK_FALLBACK_UNSAFE_OPS`
    # (RESCUE/RAISEIF/EXCEPT) even after NESTED_BLOCK_FALLBACK_SUPPORT
    # taught this function to recurse into a nested BLOCK/SENDB: a rescue
    # clause needs `recognize_rescue_regions`/`emit_rescue_try_body`/
    # `emit_rescue_glue`'s own real `mrb_protect_error` extraction, a
    # completely different mechanism, never attempted from inside a block
    # body before. Reuses that exact same top-level machinery unchanged
    # (must run AFTER `@block_fallback_upvars`/`@block_fallback_active`
    # are set just above, unlike the nested-BLOCK_FALLBACK pass above --
    # `emit_rescue_try_body`'s own compile_insn calls need those ivars
    # live too, whereas a recursive emit_proc_fallback_fn call manages
    # its own copies independently and needs them still unset when IT
    # runs). `extra_fields`/`extra_field_values` thread this block's own
    # captured upvar pointers into the extracted try-body function by
    # name -- the same real variable name the enclosing block's own
    # `_impl` function already has in scope, so GETUPVAR/SETUPVAR's own
    # compile_insn case needs no special-casing to find it there too.
    # `arg_names`/an all-nil `arg_native_types` (no NATIVE_ARG_TARGETS
    # equivalent for a block's own mandatory params) are this function's
    # own already-computed values, exactly matching what the block's own
    # `_impl` signature/preamble already binds `r1..r<mand>` from.
    # `rescue_regions` itself and its own address ranges were already
    # computed and pre-claimed into `nested_suppressed` above, before the
    # nested-BLOCK_FALLBACK pass ran -- reused verbatim here, not
    # recomputed (one real region list, not two that could drift).
    rescue_regions.each_with_index do |rregion, i|
      try_name = "#{impl_name}_rescue_try#{rescue_regions.size > 1 ? "_#{i}" : ''}"
      # BLOCK_FALLBACK_YIELD_SUPPORT: the forwarded block rides into the
      # extracted try-body function through the exact same `extra_fields`
      # channel the captured upvar pointers already use -- an `mrb_value`
      # rather than an `mrb_value*` (the block slot is only ever READ:
      # vm.c's own OP_BLKPUSH is `regs[a] = stack[offset]`, and no opcode
      # anywhere writes back through it), landing in that function under the
      # identical name `bc2cpp_blk`, which is exactly what @blk_param_name
      # (still set, deliberately, for emit_rescue_try_body's own compile_insn
      # calls) is about to emit references to.
      extra_fields = upvar_regs.map { |(l, b)| { name: upvar_var_name(l, b), c_type: 'mrb_value*' } }
      extra_fields += [{ name: 'bc2cpp_blk', c_type: 'mrb_value' }] if needs_blk
      saved = rescue_entry_saved_fields(block_irep, rregion)
      nested_pre << emit_rescue_try_body(try_name, rregion, block_irep, d, arg_names, Array.new(arg_names.size),
                                          extra_fields: extra_fields + saved, available_upvars: upvar_regs)
      nested_glue_at[rregion[:begin_addr]] =
        emit_rescue_glue(try_name, rregion, arg_names, Array.new(arg_names.size),
                         extra_field_values: extra_fields.map { |f| f[:name] } +
                                             saved.map { |f| f[:name].sub('bc2cpp_saved_', '') })
    end
    body = String.new
    # NESTED_BLOCK_FALLBACK_SUPPORT: same `targets - (suppressed -
    # glue_at.keys)` shape compile_method's own top-level loop already
    # uses -- a nested region's own `sendb_addr` (suppressed, no glue_at
    # entry of its own) still correctly loses any label a stray jump might
    # otherwise target, while `block_addr` (suppressed WITH a glue_at
    # entry) keeps one, since real code starts exactly there.
    targets = jump_targets(block_irep) - (nested_suppressed - nested_glue_at.keys)
    elem_class = block_fallback_element_class(region[:parent_irep], region, d.owner)
    block_irep.instructions.each_with_index do |insn, idx|
      next if insn.op == 'ENTER'
      next if nested_suppressed.include?(insn.addr) && !nested_glue_at.key?(insn.addr)

      body << "  L#{insn.addr}:;\n" if targets.include?(insn.addr)
      if nested_glue_at.key?(insn.addr)
        body << nested_glue_at[insn.addr]
      else
        with_element_hint(block_irep, insn, idx, '1', elem_class) do
          body << compile_insn(insn, block_irep, d, idx)
        end
      end
    end
    @block_fallback_upvars = nil
    @block_fallback_active = false
    @blk_param_name = saved_blk_param_name
    @blk_param_level = saved_blk_param_level
    return nil if nested_pre.include?('#error') || body.include?('#error')

    out = nested_pre
    # BLOCK_FALLBACK_YIELD_SUPPORT: the forwarded block sits AFTER the
    # captured upvar pointers and BEFORE this block's own mandatory
    # parameters, matching the env-slot order below exactly (self, upvars,
    # blk). A body that doesn't need it declares nothing, so every one of
    # the already-shipping BLOCK_FALLBACK bodies generates byte-for-byte
    # identical C++.
    out << "static mrb_value #{impl_name}(mrb_state* M, mrb_value self" \
           "#{upvar_params.map { |p| ", #{p}" }.join}#{blk_param.map { |p| ", #{p}" }.join}" \
           "#{arg_names.map { |a| ", mrb_value #{a}" }.join}) {\n"
    (0...block_irep.nregs).each { |i| out << "  mrb_value r#{i}" << (i.zero? ? ' = self;' : ' = mrb_nil_value();') << "\n" }
    arg_names.each_with_index { |a, i| out << "  r#{i + 1} = #{a};\n" }
    out << body
    out << "  return mrb_nil_value(); // unreachable if every path RETURNs\n"
    out << "}\n\n"

    # RUNTIME_DEF_FALLBACK_SUPPORT: a method body installed on a real runtime
    # class, and an EXEC-opened class body, both take `self` from the REAL
    # RECEIVER mruby passes this cfunc -- the exact opposite of a block/lambda
    # body, which deliberately ignores it in favour of the lexically-captured
    # one in env slot 0 (see emit_rproc_construction's own header for why a
    # block has to).
    #
    # For an installed method that receiver is whatever object the call site
    # dispatched on, which is the only correct `self` there is -- capturing
    # anything at definition time would pin every later call to whatever
    # object happened to be around when the `def` ran.
    #
    # For an EXEC-opened class body it is the target class itself, and this
    # is a real proven identity rather than a convenience: src/vm.c's own
    # OP_EXEC does `struct RClass *c = mrb_class_ptr(recv);` and then
    # `cipush(mrb, a, 0, c, p, NULL, 0, 0)` -- the pushed frame's regs[0]
    # (i.e. `self`) IS `recv`, and its target_class IS `mrb_class_ptr(recv)`,
    # the same object. So inside a class body `self` and the class that
    # `def`/`alias`/`private` act on are interchangeable, which is exactly
    # what emit_tdef_fallback_glue below relies on to spell TDEF's own
    # `check_target_class(mrb)` as `mrb_class_ptr(self)`.
    if region[:self_source] == :receiver
      out << "static mrb_value #{fn_name}(mrb_state* M, mrb_value bc2cpp_recv_self) {\n"
      out << "  mrb_value bc2cpp_captured_self = bc2cpp_recv_self;\n"
    else
      out << "static mrb_value #{fn_name}(mrb_state* M, mrb_value bc2cpp_unused_self) {\n"
      out << "  (void)bc2cpp_unused_self;\n"
      out << "  mrb_value bc2cpp_captured_self = mrb_proc_cfunc_env_get(M, 0);\n"
    end
    # UPVAR_CAPTURE_SUPPORT: slot 0 is always `self` (SELF_CAPTURE_SUPPORT,
    # above) -- each captured upvar's own pointer sits at slot `i + 1`, in
    # the exact same order emit_rproc_construction below builds its own
    # env array in (both read `region[:upvars]`/`upvar_regs` verbatim, so
    # this ordering can never drift between the two).
    upvar_args = upvar_regs.each_with_index.map do |(l, b), i|
      vname = upvar_var_name(l, b)
      out << "  mrb_value* #{vname} = static_cast<mrb_value*>(mrb_cptr(mrb_proc_cfunc_env_get(M, #{i + 1})));\n"
      vname
    end
    # BLOCK_FALLBACK_YIELD_SUPPORT: the forwarded block is the LAST env slot
    # -- after `self` (slot 0) and after every captured upvar pointer --
    # matching emit_rproc_construction's own env array construction exactly
    # (both derive the position the same way from the same two flags, so the
    # ordering can never drift between them). Read back as a plain
    # `mrb_value`, not unboxed through mrb_cptr like an upvar pointer is:
    # what was captured IS the block value itself, a copy, which is also why
    # the RProc's own env keeps it GC-reachable for the whole call.
    if needs_blk
      out << "  mrb_value bc2cpp_blk = mrb_proc_cfunc_env_get(M, #{upvar_regs.size + 1});\n"
    end
    call_args = (['bc2cpp_captured_self'] + upvar_args + (needs_blk ? ['bc2cpp_blk'] : [])).join(', ')
    if mand.zero?
      out << "  return #{impl_name}(M, #{call_args});\n"
    elsif (region[:kind] || 'block_fallback') == 'block_fallback' && mand > 1
      # Ordinary blocks are lenient about their argument count, and mruby's
      # Hash#each passes a single [key, value] Array to the block. The
      # interpreter expands that Array for a multi-parameter block; a C
      # function-backed Proc does not, so reproduce that adjustment here.
      out << "  mrb_value* bc2cpp_argv;\n"
      out << "  mrb_int bc2cpp_argc;\n"
      out << "  mrb_get_args(M, \"*\", &bc2cpp_argv, &bc2cpp_argc);\n"
      arg_names.each { |a| out << "  mrb_value #{a};\n" }
      out << "  if (bc2cpp_argc == 1 && mrb_array_p(bc2cpp_argv[0])) {\n"
      arg_names.each_with_index do |a, i|
        out << "    #{a} = mrb_ary_ref(M, bc2cpp_argv[0], #{i});\n"
      end
      out << "  } else {\n"
      arg_names.each_with_index do |a, i|
        out << "    #{a} = bc2cpp_argc > #{i} ? bc2cpp_argv[#{i}] : mrb_nil_value();\n"
      end
      out << "  }\n"
      out << "  return #{impl_name}(M, #{call_args}, #{arg_names.join(', ')});\n"
    else
      arg_names.each { |a| out << "  mrb_value #{a};\n" }
      fmt = 'o' * mand
      ptrs = arg_names.map { |a| "&#{a}" }.join(', ')
      out << "  mrb_get_args(M, \"#{fmt}\", #{ptrs});\n"
      out << "  return #{impl_name}(M, #{call_args}, #{arg_names.join(', ')});\n"
    end
    out << "}\n\n"
    [fn_name, out]
  end

  # BLOCK_CFUNC_FALLBACK_SUPPORT / LAMBDA_FALLBACK_SUPPORT: the shared
  # RProc-construction snippet both glue emitters below build on --
  # `mrb_proc_new_cfunc_with_env` (not the plain `mrb_proc_new_cfunc`)
  # with a one-element env array holding this enclosing method's own real
  # `self` C++ variable -- captured HERE, not inside the block/lambda
  # body, because this is the one place the real value is actually in
  # scope as an ordinary local. emit_proc_fallback_fn's own entry point
  # reads it straight back via `mrb_proc_cfunc_env_get(M, 0)`, giving the
  # body the correct, lexically-captured self a real Ruby closure would
  # have -- see that function's own comment for why the self mruby itself
  # would otherwise pass in is useless. Returns `[rproc_var, code]` --
  # what the caller does with `rproc_var` (dispatch it, as
  # emit_block_fallback_glue does, or just store it, as
  # emit_lambda_fallback_glue does) is entirely up to it.
  #
  # INLINE_NESTED_BLOCK_SUPPORT: `inline_offset` is non-nil for exactly one
  # caller -- a region nested inside an INLINED loop body (see
  # inline_nested_block_pass' own comment for the full argument). It
  # switches the two capture levels that can occur there from "forward a
  # pointer this function holds as a parameter" to "take the address of a
  # local this function actually declares", because that is what an inlined
  # body really has: level 0 names the inlined block's own register, the
  # local `r<b + inline_offset>` the emitter re-declares at the top of every
  # iteration; level 1 names the enclosing METHOD's register, the local
  # `r<b>` compile_method's own preamble declares. Level >= 2 cannot reach
  # here at all -- the recognizer's own `available_upvars` gate refuses it
  # (that comment states exactly why), so the `else` arm below is the
  # pre-existing pointer-forwarding path, reached only when `inline_offset`
  # is nil, i.e. from every caller that existed before this keyword did.
  # Defaulted to nil precisely so those callers emit byte-for-byte the code
  # they emitted before.
  def emit_rproc_construction(addr, fn_name, upvar_regs = [], needs_blk = false, inline_offset: nil)
    var = "bc2cpp_blk_proc_#{addr}"
    out = String.new
    # UPVAR_CAPTURE_SUPPORT: `&r#{b}` takes the address of THIS enclosing
    # method's own already-declared `mrb_value r#{b}` local (compile_
    # method's own register-declaration preamble -- the same one every
    # ordinary instruction in this method already reads/writes as a plain
    # C++ local) -- boxed via `mrb_cptr_value` the same way any other
    # opaque native pointer crosses the mrb_value boundary in this file.
    # Order matches emit_proc_fallback_fn's own env-slot reads exactly
    # (both iterate `upvar_regs` verbatim, self always first).
    # DEEP_UPVAR_CAPTURE_SUPPORT: a level-0 entry is this enclosing
    # function's OWN register, so its address is what gets boxed (`&r<b>`,
    # unchanged). A level-L entry for L >= 1 names a register L more
    # frames out, which this enclosing function does not hold as a local
    # at all -- it holds the POINTER to it, as its own captured parameter
    # `upvar_var_name(l - 1, b)` (the recognizer only ever admits such an
    # entry after checking that exact pair is in the enclosing capture
    # set). So the pointer is forwarded straight through, never
    # re-addressed: `&` here would box a pointer-to-pointer and read back
    # as garbage.
    # BLOCK_FALLBACK_YIELD_SUPPORT: the enclosing frame's own received block
    # value, appended as the last env slot. Captured HERE for exactly the
    # same reason `self` is: this glue is emitted INSIDE the enclosing
    # function, which is the one place the real value is in scope as an
    # ordinary C++ local. That local is `bc2cpp_blk` -- compile_method's own
    # `needs_blk_param` parameter (BLKPUSH_YIELD_SUPPORT's `mrb_get_args(M,
    # "&", &bc2cpp_blk)` extraction) at method level, or this same forwarded
    # capture again one level in. Stored BY VALUE, never by address: unlike
    # an upvar there is nothing to write back through (vm.c's OP_BLKPUSH
    # only ever reads `stack[offset]`), and a value in the env array is
    # GC-rooted by the RProc itself rather than merely borrowed from a
    # frame.
    env_entries = ['self'] + upvar_regs.map do |(l, b)|
      if inline_offset
        "mrb_cptr_value(M, &r#{l.zero? ? b + inline_offset : b})"
      elsif l.zero?
        "mrb_cptr_value(M, &r#{b})"
      else
        "mrb_cptr_value(M, #{upvar_var_name(l - 1, b)})"
      end
    end
    env_entries << 'bc2cpp_blk' if needs_blk
    out << "    mrb_value bc2cpp_blk_env_#{addr}[] = { #{env_entries.join(', ')} };\n"
    out << "    struct RProc* #{var} = mrb_proc_new_cfunc_with_env(M, #{fn_name}, #{env_entries.size}, " \
           "bc2cpp_blk_env_#{addr});\n"
    [var, out]
  end

  # BLOCK_CFUNC_FALLBACK_SUPPORT: the call-site glue -- build a real
  # `RProc` around the standalone cfunc entry (emit_rproc_construction
  # above), then an ordinary dynamic call carrying it as the block
  # argument (`mrb_funcall_with_block`, mruby's own public API for
  # exactly this -- 3rd/mruby/src/vm.c). Deliberately still dynamic
  # dispatch, never MONO/POLY/TYPED devirtualization -- getting a
  # previously-#error'd block-carrying call site to compile correctly at
  # all is this round's own goal (the exact same "proven, wired, not yet
  # the fastest path" shape idea 1's own SPLAT_UNROLL_SUPPORT already
  # established for its own dynamic-dispatch fallback).
  #
  # See emit_lambda_fallback_glue below for the LAMBDA_FALLBACK_SUPPORT
  # sibling of this glue -- same RProc construction, no dispatch at all.
  #
  # INLINE_NESTED_BLOCK_SUPPORT: `inline_offset`, when non-nil, shifts this
  # region's own destination/argument registers out of the nested block's
  # numbering into the enclosing function's (`+ offset`, the identical
  # shift compile_block_body_insn's own `else` arm already applies to every
  # other instruction of an inlined body) and is forwarded to
  # emit_rproc_construction for the capture levels -- see that function's
  # own comment and inline_nested_block_pass'. `self` is deliberately NOT
  # shifted: a block inherits its enclosing method's `self` unchanged (real
  # mruby semantics), which is exactly the `self` C++ parameter already in
  # scope here, and is also what the inlined body's own `r<offset> = self`
  # alias holds. Defaulted to nil so every pre-existing caller is unchanged.
  def emit_block_fallback_glue(region, fn_name, inline_offset: nil)
    dest_reg = region[:dest_reg].to_i + (inline_offset || 0)
    recv = region[:self_implicit] ? 'self' : "r#{dest_reg}"
    argv = (1..region[:n]).map { |k| "r#{dest_reg + k}" }
    rproc_var, ctor = emit_rproc_construction(region[:block_addr], fn_name, region[:upvars] || [],
                                              region[:needs_blk] ? true : false, inline_offset: inline_offset)
    out = String.new
    out << "  // BLOCK_FALLBACK :#{region[:name]} -- block body compiled as a standalone cfunc, wrapped as a real RProc " \
           "(self captured at construction time), dynamic dispatch\n"
    out << "  {\n"
    out << ctor
    # EXCEPTION_BREAK_SUPPORT: wraps the dispatch unconditionally (cheap
    # under the zero-cost exception model this project already relies on
    # -- see BLOCK_FALLBACK_UNSAFE_OPS's own comment -- and avoids needing
    # to track, from all the way back in recognize_block_fallback_regions,
    # whether THIS particular block body happens to contain a real BREAK)
    # rather than conditionally. A block with no BREAK at all simply never
    # throws bc2cpp_block_break, so this catch clause never fires for it
    # -- functionally identical to today's own bare call.
    out << "    Bc2cppVmMark bc2cpp_brk_mark = bc2cpp_vm_mark(M);\n    try {\n"
    if argv.empty?
      out << "      r#{dest_reg} = mrb_funcall_with_block(M, #{recv}, mrb_intern_cstr(M, \"#{region[:name]}\"), 0, NULL, " \
             "mrb_obj_value(#{rproc_var}));\n"
    else
      out << "      mrb_value bc2cpp_blk_argv_#{region[:block_addr]}[] = { #{argv.join(', ')} };\n"
      out << "      r#{dest_reg} = mrb_funcall_with_block(M, #{recv}, mrb_intern_cstr(M, \"#{region[:name]}\"), " \
             "#{argv.size}, bc2cpp_blk_argv_#{region[:block_addr]}, mrb_obj_value(#{rproc_var}));\n"
    end
    out << "    } catch (bc2cpp_block_break& bc2cpp_brk) {\n"
    out << "      bc2cpp_vm_restore(M, bc2cpp_brk_mark);\n"
    out << "      r#{dest_reg} = bc2cpp_brk.value;\n"
    out << "    }\n"
    out << "  }\n"
    out
  end

  # EXPLICIT_BLOCK_ARG_SUPPORT: `ary.select(&:defending)` /
  # `ary.each(&proc_var)` / `ary.map(&method(:bar))` -- real Ruby's
  # `&expr` explicit-block-argument syntax, confirmed via a fresh `mrbc
  # -v` run to compile to a COMPLETELY DIFFERENT bytecode shape than a
  # literal `{ }`/`do...end` block: no `BLOCK` instruction at all, just
  # `expr`'s own ordinary evaluation landing in `R(dest+n+1)` immediately
  # before the `SENDB`/`SSENDB`. Every recognizer in this file that
  # handles a block-carrying call (this one included, until now) gates on
  # a `BLOCK` instruction immediately preceding the call -- so this whole
  # shape fell through to the raw `#error unhandled opcode SENDB`/
  # `SSENDB` unconditionally, regardless of how simple `expr` itself was.
  #
  # No block BODY exists to compile here at all -- `expr` is just an
  # ordinary value already sitting in a register (a Symbol, an existing
  # Proc, whatever `&` was applied to) -- so this needs none of
  # BLOCK_CFUNC_FALLBACK_SUPPORT's own machinery (no standalone cfunc, no
  # RProc construction, no self/upvar capture). Real `mrb_funcall_with_
  # block` (3rd/mruby/src/vm.c) already calls `ensure_block` on whatever
  # it's handed: `if (!mrb_nil_p(blk) && !mrb_proc_p(blk)) blk =
  # mrb_type_convert(mrb, blk, MRB_TT_PROC, MRB_SYM(to_proc));` -- the
  # exact real `#to_proc` coercion a Symbol/Method/anything else `&`
  # accepts needs, and a real `nil` (`&nil`, "explicitly no block") passes
  # straight through unchanged, both already handled by mruby's own
  # public API with no special-casing needed here. So the whole
  # translation is just handing that register straight to
  # `mrb_funcall_with_block` in place of the RProc `emit_block_fallback_
  # glue` above builds -- same `try`/`catch (bc2cpp_block_break&)`
  # wrapping, unconditional, for the identical reason that comment gives
  # (a forwarded Proc might itself be one of THIS program's own
  # BLOCK_FALLBACK-compiled RProcs, whose own `break` throws that exact
  # type; harmless, never-thrown overhead otherwise).
  def recognize_explicit_block_arg_regions(irep)
    regions = []
    irep.instructions.each_with_index do |insn, idx|
      next unless %w[SENDB SSENDB].include?(insn.op)

      prev = idx.positive? ? irep.instructions[idx - 1] : nil
      next if prev && prev.op == 'BLOCK'

      # EXPLICIT_BLOCK_ARG_DYNAMIC_SPLAT_SUPPORT: `n=*` (a plain positional
      # splat, no `|nk=` -- a double-splat/keyword tail alongside `&expr`
      # keeps the honest #error, same scope decision compile_dynamic_
      # splat_send's own comment already makes for the non-`&expr` case)
      # combines with `&expr` for real -- `__send__(name, *args, &block)`,
      # `RGSS::ErrorReport::Tee#method_missing`'s own real body. Confirmed
      # via a fresh `mrbc -v` disassembly (`def f(name,*args,&block);
      # @io.__send__(name,*args,&block); end`): the real args Array is
      # already fully built into R(dest+1) by the time this SENDB runs --
      # same ARRAY/LOADNIL-then-ARYCAT guarantee compile_dynamic_splat_
      # send's own comment establishes -- with the block's own value
      # sitting in the very next register, R(dest+2), not R(dest+n+1)
      # (n isn't a compile-time constant here at all).
      n_match = insn.args.match(/n=(\d+|\*)(?:\s|$)/)
      next unless n_match

      dest, = insn.args.split(/\s+/, 2)
      dest_reg = dest[/^R(\d+)/, 1]
      next unless dest_reg

      name = insn.args[/:([\w+\-*\/<>=!?\[\]&|^~%@]+)/, 1]
      next unless name

      if n_match[1] == '*'
        regions << { sendb_addr: insn.addr, dest_reg: dest_reg, n: '*',
                     argv_reg: (dest_reg.to_i + 1).to_s,
                     blk_reg: (dest_reg.to_i + 2).to_s, name: name,
                     self_implicit: insn.op == 'SSENDB' }
      else
        n = n_match[1].to_i
        regions << { sendb_addr: insn.addr, dest_reg: dest_reg, n: n,
                     blk_reg: (dest_reg.to_i + n + 1).to_s, name: name,
                     self_implicit: insn.op == 'SSENDB' }
      end
    end
    regions
  end

  def emit_explicit_block_arg_glue(region)
    dest_reg = region[:dest_reg].to_i
    recv = region[:self_implicit] ? 'self' : "r#{dest_reg}"
    out = String.new
    out << "  // EXPLICIT_BLOCK_ARG :#{region[:name]} -- &expr forwarded directly as the block " \
           "(mrb_funcall_with_block's own ensure_block coerces Symbol/Proc/anything with #to_proc), dynamic dispatch\n"
    out << "  {\n  Bc2cppVmMark bc2cpp_brk_mark = bc2cpp_vm_mark(M);\n  try {\n"
    if region[:n] == '*'
      # EXPLICIT_BLOCK_ARG_DYNAMIC_SPLAT_SUPPORT: R(dest+1) is already a
      # real, fully-built Array by construction (see recognize_explicit_
      # block_arg_regions' own comment) -- RARRAY_LEN/RARRAY_PTR straight
      # into mrb_funcall_with_block, same shape compile_dynamic_splat_
      # send's own mrb_funcall_argv call already trusts.
      out << "    r#{dest_reg} = mrb_funcall_with_block(M, #{recv}, mrb_intern_cstr(M, \"#{region[:name]}\"), " \
             "RARRAY_LEN(r#{region[:argv_reg]}), RARRAY_PTR(r#{region[:argv_reg]}), r#{region[:blk_reg]});\n"
    else
      argv = (1..region[:n]).map { |k| "r#{dest_reg + k}" }
      if argv.empty?
        out << "    r#{dest_reg} = mrb_funcall_with_block(M, #{recv}, mrb_intern_cstr(M, \"#{region[:name]}\"), 0, NULL, " \
               "r#{region[:blk_reg]});\n"
      else
        out << "    mrb_value bc2cpp_ebarg_argv_#{region[:sendb_addr]}[] = { #{argv.join(', ')} };\n"
        out << "    r#{dest_reg} = mrb_funcall_with_block(M, #{recv}, mrb_intern_cstr(M, \"#{region[:name]}\"), " \
               "#{argv.size}, bc2cpp_ebarg_argv_#{region[:sendb_addr]}, r#{region[:blk_reg]});\n"
      end
    end
    out << "  } catch (bc2cpp_block_break& bc2cpp_brk) {\n"
    out << "    bc2cpp_vm_restore(M, bc2cpp_brk_mark);\n"
    out << "    r#{dest_reg} = bc2cpp_brk.value;\n"
    out << "  }\n"
    out << "  }\n"
    out
  end

  # RESCUE_BODY_BLOCK_SUPPORT: the shared BLOCK_FALLBACK/EXPLICIT_BLOCK_ARG
  # suppress-and-glue pass, factored out so `emit_rescue_try_body` below
  # can run the identical recognize -> emit -> suppress pipeline
  # `compile_method`'s own top-level loop already runs, against its own
  # extracted try-body function instead. Takes already-recognized region
  # lists (both recognizers are pure functions of `irep` alone, so the
  # caller decides whether to scan the whole irep or a filtered subset)
  # and mutates the caller's own `suppressed`/`glue_at` in place -- the
  # same two collections every other named block recognizer in this file
  # already accumulates into, so a region this pass claims is exactly as
  # invisible to a caller's own later, unrelated instruction-loop pass as
  # any of them. Returns the accumulated nested-function pre-code (empty
  # string when neither region list has anything to emit).
  def emit_block_fallback_glue_pass(block_regions, explicit_arg_regions, d, suppressed, glue_at)
    pre = String.new
    block_regions.each do |region|
      next if suppressed.include?(region[:block_addr]) || suppressed.include?(region[:sendb_addr])

      fn_result = emit_proc_fallback_fn(region, d)
      next unless fn_result

      fn_name, fn_code = fn_result
      pre << fn_code
      suppressed << region[:block_addr] << region[:sendb_addr]
      glue_at[region[:block_addr]] = emit_block_fallback_glue(region, fn_name)
    end
    explicit_arg_regions.each do |region|
      next if suppressed.include?(region[:sendb_addr])

      suppressed << region[:sendb_addr]
      glue_at[region[:sendb_addr]] = emit_explicit_block_arg_glue(region)
    end
    pre
  end

  # LAMBDA_FALLBACK_SUPPORT: recognize a `LAMBDA` instruction whose own
  # child irep is safe to compile as a standalone cfunc (lambda_fallback_
  # safe? above) -- the single-instruction analogue of
  # recognize_block_fallback_regions above: `LAMBDA Ra I[b]` (ops.h:
  # `R[a] = lambda(Irep[b],L_LAMBDA)`) just BUILDS the proc value into
  # register `a`; unlike a BLOCK/SENDB(SSENDB) pair there is no paired
  # call instruction to also recognize or suppress, and no `n`/receiver/
  # method-name to record -- the whole region is this one instruction.
  #
  # CONFINED_LAMBDA_UPVAR_SUPPORT: `available_upvars` is the same
  # captured-pointer set recognize_block_fallback_regions takes, for the
  # identical "can this level actually SUPPLY that pointer?" gate -- empty
  # at ordinary method level (compile_method's own call), where there is no
  # enclosing Ruby scope to forward anything from, so every level >= 1 need
  # is correctly refused there.
  def recognize_lambda_fallback_regions(irep, available_upvars: [])
    regions = []
    irep.instructions.each do |insn|
      next unless insn.op == 'LAMBDA'

      dest_reg = insn.args[/^R(\d+)/, 1]
      next unless dest_reg

      lambda_irep_idx = insn.args[/I\[(\d+)\]/, 1]
      next unless lambda_irep_idx

      lambda_label = irep.reps[lambda_irep_idx.to_i]
      lambda_irep = lambda_label && @ireps[lambda_label]
      next unless lambda_irep && lambda_fallback_safe?(lambda_irep)

      # CONFINED_LAMBDA_UPVAR_SUPPORT: exactly the same two questions
      # recognize_block_fallback_regions already asks of a block body --
      # what does it need captured (`block_upvar_needs`, `nil` for a
      # shape that isn't modelable at all), and can THIS level supply it
      # -- followed by the one question that is genuinely different for a
      # LAMBDA, because it has no call site to reason about: does the
      # resulting proc value provably never escape this frame?
      upvars = block_upvar_needs(lambda_irep)
      next if upvars.nil?
      next unless upvars.all? { |(l, x)| l.zero? || available_upvars.include?([l - 1, x]) }

      call_sites = lambda_confined_call_sites(irep, insn, dest_reg.to_i, lambda_irep)
      next if upvars.any? && call_sites.nil?

      regions << { block_addr: insn.addr, dest_reg: dest_reg, block_irep: lambda_irep,
                   kind: 'lambda_fallback', upvars: upvars, call_sites: call_sites || [] }
    end
    regions
  end

  # CONFINED_LAMBDA_UPVAR_SUPPORT: the whole safety argument for letting a
  # LAMBDA body capture upvar POINTERS (`mrb_cptr_value(M, &r<b>)` into the
  # enclosing C++ function's own frame -- see LAMBDA_FALLBACK_UNSAFE_OPS'
  # own comment for why this is the one question a lambda cannot answer the
  # way a BLOCK_FALLBACK call site answers it).
  #
  # Proves: the proc value this `LAMBDA R<d> I[n]` builds is CONFINED to the
  # frame it is built in -- it is never returned, stored, or passed to
  # anything, so nothing can still be holding it once this C++ function
  # returns and `&r<b>` goes dead. Everything below is a real
  # over-approximation: anything this cannot positively account for is
  # declined, leaving today's honest `#error`.
  #
  # Real `mrbc -v` disassembly of the one shape this recognizes -- this
  # program's own `RPG2k::Scene::Menu#draw_status_row`, `line = ->(n) { y +
  # n * LINE_H }` then three `line.call(k)` (irep nregs=19 nlocals=9,
  # `R6:line`):
  #
  #     531 013 LAMBDA  R6   I[0]
  #     532 022 MOVE    R12  R6      ; R6:line
  #     532 025 LOADI_0 R13  (0)
  #     532 027 SEND    R12  :call   n=1
  #     534 058 MOVE    R9   R6      ; R6:line
  #     534 061 LOADI_1 R10  (1)
  #     534 063 SEND    R9   :call   n=1
  #     541 204 MOVE    R9   R6      ; R6:line
  #     541 207 LOADI_2 R10  (2)
  #     541 209 SEND    R9   :call   n=1
  #
  # Three separate gates, each load-bearing:
  #
  # (1) `d` is a NAMED LOCAL (`1 <= d < irep.nlocals`). This is what makes
  #     the purely TEXTUAL scan below sound. mrbc's own register allocator
  #     sets `s->nlocals = s->nregs = s->sp` at scope creation and only ever
  #     `push_n_`/`pop_n_`es temporaries ABOVE that (3rd/mruby/mrbgems/
  #     mruby-compiler/core/codegen.c; the peephole optimizer's own repeated
  #     `data.a < s->nlocals` guards are the same boundary, respected from
  #     the other side), so no opcode's IMPLICIT register window -- the
  #     registers a counted opcode touches without the disassembly ever
  #     printing them, `SEND Ra :m n=N` reading `Ra+1..Ra+N`, `ARRAY Ra n`
  #     reading `Ra..Ra+n-1`, and so on -- can ever reach down into the
  #     named-local region. Verified empirically as well as from the
  #     allocator source: a whole-closed-world sweep (3944 ireps, 14595
  #     implicit-window instructions across every mrblib source this build
  #     compiles) found ZERO instructions whose implicit window dips below
  #     its own irep's `nlocals`. So every reference to `R<d>` anywhere in
  #     this irep is one the disassembly really prints, and finding them all
  #     with `\bR<d>\b` really is finding all of them.
  #
  # (2) The enclosing irep contains no ARGARY and no BLKPUSH. These are the
  #     only two opcodes in the whole VM that read a frame register WITHOUT
  #     naming it and without going through a temporary window -- both index
  #     the raw parameter slots (3rd/mruby/src/vm.c: `CASE(OP_ARGARY)`'s
  #     `stack[m1+r+m2]`, `CASE(OP_BLKPUSH)`'s `regs[a] = stack[offset]`),
  #     which ARE named locals and so are exactly the case gate (1) cannot
  #     cover. A bare `super` (ARGARY) forwarding a parameter a lambda had
  #     been assigned into, or a `yield` (BLKPUSH) of a block parameter
  #     likewise reassigned, would both hand the proc straight out of the
  #     frame. Checked directly rather than reasoned around.
  #
  # (3) Every OTHER textual occurrence of `R<d>` is a `MOVE R<t> R<d>` whose
  #     copy is consumed, on a straight-line stretch, as the RECEIVER of a
  #     `:call` SEND -- and nothing else. `Proc#call` is mruby's own static
  #     `call_proc` (3rd/mruby/src/proc.c's `mrb_init_proc`, a one-opcode
  #     `OP_CALL` body): it invokes the proc synchronously and never retains
  #     it, so passing the value there is not an escape. The SEND then
  #     OVERWRITES `R<t>` with its own result, so the copy's lifetime ends
  #     exactly there.
  #
  #     `R<t>` is a temporary (`t >= nlocals`), so gate (1)'s argument does
  #     NOT apply to it and an intervening instruction's implicit window
  #     really could cover it (`SSEND R9 :draw_system_text n=7` reads
  #     R9..R16 -- which is precisely how `R12` at address 022 above would
  #     escape into a call if the `.call` had not already consumed it).
  #     That is why the instructions between the MOVE and the SEND are
  #     checked against an explicit WHITELIST of opcodes that touch only the
  #     registers they print, rather than merely scanned for the text
  #     `R<t>`. Real argument setup for the shape this exists for is a
  #     single literal load, so the whitelist is deliberately small: a
  #     richer argument expression simply declines to today's `#error`.
  LAMBDA_CONFINED_CALL_SETUP_OPS = %w[
    LOADI LOADI_0 LOADI_1 LOADI_2 LOADI_3 LOADI_4 LOADI_5 LOADI_6 LOADI_7
    LOADI__1 LOADI8 LOADI16 LOADI32 LOADINEG LOADL LOADL16
    LOADSYM LOADSYM16 LOADNIL LOADSELF LOADTRUE LOADFALSE
    STRING STRING16 MOVE GETIV GETGV GETCV GETCONST GETMCNST GETUPVAR
    ADDI SUBI
  ].freeze

  #
  # Returns the real `.call` sites (each `{ send_addr:, dest_reg:, n: }`) on
  # success, or `nil` when the proof fails. The sites are returned, not just
  # counted, because the emitter needs them: see emit_lambda_confined_call_
  # glue for why a confined site must NOT be dispatched through the VM.
  def lambda_confined_call_sites(irep, lambda_insn, d, lambda_irep)
    nlocals = irep.nlocals.to_i
    # (1) a named local, so no implicit register window can alias it.
    return nil unless d >= 1 && d < nlocals
    # (2) the two opcodes that read a named local without printing it.
    return nil if irep.instructions.any? { |i| %w[ARGARY BLKPUSH].include?(i.op) }

    # A child irep capturing `R<d>` as an upvar would hold a pointer to it
    # from a scope this proof says nothing about (a block body that may be
    # a BLOCK_FALLBACK region of its own, or stay on the interpreter) --
    # `block_upvar_needs` already propagates a grandchild's own deeper need
    # up as `[level - 1, idx]`, so `[0, d]` here covers any depth.
    return nil if (irep.reps || []).any? do |child_label|
      child = child_label && @ireps[child_label]
      needs = child && block_upvar_needs(child)
      needs.nil? || needs.include?([0, d])
    end

    mand = mandatory_arity(lambda_irep)
    sites = []
    insns = irep.instructions
    insns.each_with_index do |insn, i|
      next if insn.equal?(lambda_insn)
      next unless insn.args =~ /\bR#{d}\b/

      # (3) the only permitted consumer: `MOVE R<t> R<d>` into a temporary.
      m = insn.op == 'MOVE' && insn.args.match(/\AR(\d+)\s+R#{d}\b/)
      return nil unless m

      t = m[1].to_i
      return nil unless t >= nlocals

      site = lambda_confined_call_consumes?(irep, i, t)
      return nil unless site
      # A real Ruby lambda is STRICT about arity (unlike a proc/block): a
      # wrong-arity `.call` raises ArgumentError. The direct call the
      # emitter is about to generate cannot raise that, so a site whose
      # argument count does not exactly match the lambda's own mandatory
      # arity is declined outright rather than silently given different
      # behavior.
      return nil unless site[:n] == mand

      sites << site
    end
    sites
  end

  # CONFINED_LAMBDA_UPVAR_SUPPORT: gate (3)'s straight-line half -- walk
  # forward from the `MOVE R<t> R<d>` at `i` to the `SEND R<t> :call`/
  # `SEND0 R<t> :call` that consumes it, allowing only whitelisted
  # argument-setup opcodes in between, and requiring that stretch to be
  # genuinely straight-line: no jump/branch opcode inside it (control cannot
  # leave with the proc still sitting live in `R<t>`) and no jump TARGET
  # inside it (control cannot arrive mid-stretch either, which would put the
  # `.call` after instructions this proof never examined). Together those
  # make "once the MOVE runs, the very next thing that touches `R<t>` is the
  # `:call` receiver read, which then overwrites it" a real property of
  # every execution, not just of the printed instruction order.
  #
  # Returns `{ send_addr:, dest_reg:, n: }` for the consuming `.call`, or
  # `nil`.
  def lambda_confined_call_consumes?(irep, i, t)
    insns = irep.instructions
    targets = jump_targets(irep)
    ((i + 1)...insns.size).each do |j|
      nxt = insns[j]
      if %w[SEND SEND0].include?(nxt.op) &&
         (m = nxt.args.match(/\AR#{t}\s+:call(?:\s+n=(\d+))?(?:\s|\z)/))
        return { send_addr: nxt.addr, dest_reg: t, n: m[1].to_i }
      end

      return nil unless LAMBDA_CONFINED_CALL_SETUP_OPS.include?(nxt.op)
      return nil if nxt.args =~ /\bR#{t}\b/
      return nil if targets.include?(nxt.addr)
    end
    nil
  end

  # CONFINED_LAMBDA_UPVAR_SUPPORT: replace a confined site's `.call` with a
  # DIRECT C++ call to the lambda body's own `_impl` -- never a dynamic
  # `mrb_funcall(..., "call", ...)` through the VM.
  #
  # This is not an optimization, it is a correctness requirement, and it was
  # found by a real end-to-end run rather than reasoned about in advance.
  # `Proc#call` (and its alias `Proc#[]`) is mruby's own static `call_proc`,
  # whose whole body is one `OP_CALL`; 3rd/mruby/src/vm.c's `CASE(OP_CALL)`
  # has a dedicated arm for a CFUNC-backed proc -- which is exactly what
  # emit_rproc_construction builds -- and that arm ends with
  #
  #     ci = cipop(mrb);
  #     ci[1].stack[0] = recv;
  #     irep = ci->proc->body.irep;     /* <-- unconditional deref */
  #
  # with no check on the popped-to frame's own `cci`. When the caller is a
  # real C frame -- and a bc2cpp-compiled method registered with
  # mrb_define_method IS one -- that frame's `ci->proc` is NULL
  # (mrb_funcall_with_block's own `ci->proc = MRB_METHOD_PROC_P(m) ?
  # MRB_METHOD_PROC(m) : NULL`), so this dereferences NULL and segfaults.
  # Confirmed under gdb on a real linked binary, not inferred: `ci->proc =
  # (const struct RProc *) 0x0`, `ci->cci = 0` (CINFO_DIRECT), crashing at
  # that exact line. So "compiled method builds a cfunc-backed proc and then
  # `.call`s it" is a shape that cannot go through the VM at all on this
  # mruby.
  #
  # The confinement proof already hands over everything a direct call needs,
  # which is what makes this small rather than a new mechanism: the receiver
  # is provably this exact lambda (gate 3 admits no other writer of `R<d>`),
  # `self` is the same enclosing-function local emit_rproc_construction
  # captures into env slot 0, the captured upvar pointers are the very same
  # `&r<b>` / forwarded-parameter expressions it boxes into the slots after
  # it (identical order, so the two can never drift), and the arguments are
  # the call site's own `R<t+1>..R<t+n>` with `n` already checked equal to
  # the lambda's mandatory arity. The RProc is still constructed at the
  # LAMBDA itself and still stored into `R<d>`: it costs one allocation and
  # keeps that register holding a genuine, correct Proc value rather than
  # something this file would then have to reason about the absence of.
  def emit_lambda_confined_call_glue(region, fn_name, site)
    dest = site[:dest_reg]
    args = (1..site[:n]).map { |k| "r#{dest + k}" }
    upvar_args = (region[:upvars] || []).map do |(l, b)|
      l.zero? ? "&r#{b}" : upvar_var_name(l - 1, b)
    end
    out = String.new
    out << "  // CONFINED_LAMBDA_CALL -- provably this frame's own lambda (never escapes); " \
           "direct C++ call, not mrb_funcall(:call)\n"
    out << "  r#{dest} = #{fn_name}_impl(M, self#{(upvar_args + args).map { |x| ", #{x}" }.join});\n"
    out
  end

  # LAMBDA_FALLBACK_SUPPORT: the call-site glue -- build a real `RProc`
  # around the standalone cfunc entry (emit_rproc_construction above,
  # shared verbatim with emit_block_fallback_glue) and just STORE it into
  # its destination register (`mrb_obj_value`) -- unlike
  # emit_block_fallback_glue's own mrb_funcall_with_block, a LAMBDA never
  # calls anything: the resulting value is an ordinary callable/passable
  # Proc that may be invoked (or not) arbitrarily later, exactly like any
  # other real Ruby lambda value.
  # CONFINED_LAMBDA_UPVAR_SUPPORT: `region[:upvars]` rides into the exact
  # same emit_rproc_construction a BLOCK_FALLBACK site already uses -- the
  # env-slot layout, the `&r<b>` boxing and the read-back order in
  # emit_proc_fallback_fn are all shared verbatim, so there is no
  # lambda-specific codegen here at all. It is only ever non-empty for a
  # site recognize_lambda_fallback_regions proved frame-confined (see
  # lambda_proc_frame_confined?); an escaping lambda still has to have no
  # upvars, exactly as before.
  def emit_lambda_fallback_glue(region, fn_name)
    dest_reg = region[:dest_reg].to_i
    rproc_var, ctor = emit_rproc_construction(region[:block_addr], fn_name, region[:upvars] || [])
    out = String.new
    out << "  // LAMBDA_FALLBACK -- lambda body compiled as a standalone cfunc, wrapped as a real RProc " \
           "(self captured at construction time), stored -- not dispatched\n"
    out << "  {\n"
    out << ctor
    out << "    r#{dest_reg} = mrb_obj_value(#{rproc_var});\n"
    out << "  }\n"
    out
  end

  # RUNTIME_DEF_FALLBACK_SUPPORT: parse one `SDEF R3 :read I[0]` /
  # `TDEF R1 :update I[0]` instruction into a region emit_proc_fallback_fn
  # can compile. Both opcodes print with the identical three-operand layout
  # (src/codedump.c: `"%cDEF\t\tR%d\t:%s\tI[%d]\n"`), so one parser serves
  # both -- only the `kind` and the install site differ.
  #
  # Returns nil (leave the original `#error` marker alone) for anything this
  # mechanism cannot honour: a disassembly line that doesn't match the
  # expected shape, a child-irep index this irep's own reps[] doesn't
  # actually contain, or a body whose arity isn't purely mandatory
  # (runtime_def_body_safe?).
  def runtime_def_region(insn, irep, kind)
    m = insn.args.match(/\AR(\d+)\s+:(\S+)\s+I\[(\d+)\]\z/)
    return nil unless m

    child_label = irep.reps[m[3].to_i]
    return nil unless child_label

    child = @ireps[child_label]
    return nil unless child && runtime_def_body_safe?(child)

    # RUNTIME_DEF_FALLBACK_SUPPORT: the ENCLOSING irep's own declared register
    # count, carried along so emit_runtime_def_install can tell whether this
    # opcode's `a` register is one that irep actually has. It genuinely may
    # not be -- see that method's own comment for the real mrbc output.
    { block_irep: child, block_addr: insn.addr, kind: kind, self_source: :receiver,
      dest_reg: m[1].to_i, name: m[2], mand: mandatory_arity(child),
      enclosing_nregs: irep.nregs.to_i }
  end

  def tdef_fallback_region(insn, irep)
    runtime_def_region(insn, irep, 'tdef_fallback')
  end

  # RUNTIME_DEF_DEVIRT_GUARD: the class-body sends whose installed method
  # names this file can read straight off the bytecode, given literal Symbol
  # arguments. Everything else in a class body is treated as "installs an
  # unknown set of names" -- see class_body_installed_names below.
  CLASS_BODY_INSTALLER_SENDS = {
    'alias_method' => :alias,
    'attr_reader' => :reader,
    'attr_writer' => :writer,
    'attr_accessor' => :accessor
  }.freeze

  # RUNTIME_DEF_DEVIRT_GUARD: opcodes that provably touch no method table at
  # all, so a class body made only of these (plus the two cases handled
  # explicitly above) has a fully-known installed-name set. Deliberately a
  # tiny allowlist rather than a denylist: an opcode nobody thought about
  # lands in the "unknown" bucket, which is the safe side.
  CLASS_BODY_INERT_OPS = %w[LOADSYM MOVE LOADNIL LOADSELF ENTER JMP RETURN].freeze

  # RUNTIME_DEF_DEVIRT_GUARD: the `n` literal-Symbol arguments a class-body
  # send at `idx` was handed, read off the `LOADSYM R(dest+k) :name`
  # instructions that must immediately precede it -- the shape mrbc emits
  # for `alias_method :a, :b` / `attr_accessor :x`. nil for anything less
  # than a complete literal set (a computed symbol, a splat, a symbol that
  # came from somewhere this backward scan can't see), the same "only a
  # statically-certain fact counts" discipline every other backward scan in
  # this file uses.
  def literal_symbol_args(irep, idx, dest, n)
    return [] if n.zero?
    return nil if idx < n

    # Deliberately the n instructions IMMEDIATELY before the send, each
    # loading its own argument register in ascending order -- not a loose
    # backward search for "the last LOADSYM that wrote this register".
    # A loose search would have to prove nothing in between clobbered the
    # register (a MOVE is in CLASS_BODY_INERT_OPS and could), whereas an
    # exact contiguous match needs no such proof: there is nothing in
    # between. This is the shape mrbc actually emits --
    #
    #   000 LOADSYM R2 :_probe_update
    #   003 LOADSYM R3 :update
    #   006 SSEND   R1 :alias_method  n=2
    #
    # -- and anything else falls out as nil, i.e. "installed names unknown",
    # which is the safe side.
    (1..n).map do |k|
      insn = irep.instructions[idx - n + k - 1]
      return nil unless insn && insn.op == 'LOADSYM'

      m = insn.args.to_s.match(/\AR(\d+)\s+:(\S+)\z/)
      return nil unless m && m[1].to_i == dest + k

      m[2]
    end
  end

  # RUNTIME_DEF_DEVIRT_GUARD: every method name an EXEC-opened class body
  # installs, or nil meaning "cannot be bounded".
  #
  # This exists because of a real, differential-test-caught bug, not a
  # theoretical one. Installing a method on an object's SINGLETON class at
  # runtime is invisible to `mrb_obj_class`, which src/class.c defines as
  # `mrb_class_real(mrb_class(mrb, obj))` -- it walks PAST MRB_TT_SCLASS and
  # returns the underlying class. Every class-identity devirtualization in
  # this file (MONO's unguarded direct call, POLY_SMALL_N's
  # `mrb_obj_class(...) == C` chain, TYPED, the ivar-accessor inlines) is
  # therefore blind to a singleton method: it happily calls the CLASS's
  # implementation for a receiver whose singleton class overrides it.
  #
  # Before this mechanism existed that was unreachable from compiled code
  # for a method that does its own patching, because such a method never
  # compiled at all (the EXEC/SCLASS/SDEF `#error` left it on the
  # interpreter). Compiling it is exactly what re-opens the hole, so
  # closing it belongs here. Measured, not assumed -- a minimal
  # `class << a; alias_method :_orig, :shared_name; def shared_name; ...;
  # end; end` followed by `a.shared_name` in the same method returned the
  # UNPATCHED string under compilation and the patched one under
  # interpretation, purely because of POLY_SMALL_N's own class check.
  #
  # The fix is name-scoped rather than a blanket "turn devirtualization off
  # in this method": only a name this method might install at runtime is
  # unsafe to bind statically, and for the real shapes that set is small and
  # exactly known. Both real sites in this closed world keep every one of
  # their existing devirtualized call sites as a result (`effect_probe`
  # installs `update`/`_probe_update` and devirtualizes neither;
  # `audio_probe` installs `read` and devirtualizes neither).
  #
  # nil ("unknown") is returned for any body this cannot fully account for,
  # and blocks devirtualization of EVERY name in the enclosing method. That
  # still COMPILES the method, just entirely dynamically -- strictly better
  # than refusing it, and still exactly as correct.
  #
  # NOTE on scope, deliberately: this guards the method that does the
  # patching. A devirtualized call site in some OTHER compiled method can
  # still miss a runtime singleton patch -- but that is true of this
  # compiler today, unchanged, whether the patching method runs compiled or
  # interpreted, so it is not something this mechanism introduces or can
  # close on its own.
  def class_body_installed_names(body)
    names = Set.new
    body.instructions.each_with_index do |insn, idx|
      case insn.op
      when 'TDEF'
        m = insn.args.match(/\AR\d+\s+:(\S+)\s+I\[\d+\]\z/)
        return nil unless m

        names << m[1]
      when 'SSEND', 'SSEND0'
        m = insn.args.match(/\AR(\d+)\s+:(\S+?)(?:\s+n=(\d+))?\z/)
        return nil unless m

        kind = CLASS_BODY_INSTALLER_SENDS[m[2]]
        return nil unless kind

        syms = literal_symbol_args(body, idx, m[1].to_i, m[3].to_i)
        return nil unless syms && !syms.empty?

        case kind
        # `alias_method(new_name, old_name)` installs the FIRST argument;
        # the second is only READ (src/class.c's mrb_alias_method).
        when :alias then names << syms.first
        when :reader then names.merge(syms)
        when :writer then names.merge(syms.map { |s| "#{s}=" })
        when :accessor then names.merge(syms).merge(syms.map { |s| "#{s}=" })
        end
      else
        return nil unless CLASS_BODY_INERT_OPS.include?(insn.op)
      end
    end
    names
  end

  # RUNTIME_DEF_DEVIRT_GUARD: the complete set of names this METHOD may
  # install at runtime -- every SDEF's own name plus every EXEC-opened class
  # body's contribution -- or nil if any one body could not be bounded.
  def runtime_installed_names_for(irep, exec_regions)
    names = Set.new
    irep.instructions.each do |insn|
      next unless insn.op == 'SDEF'

      m = insn.args.match(/\AR\d+\s+:(\S+)\s+I\[\d+\]\z/)
      return nil unless m

      names << m[1]
    end
    exec_regions.each do |region|
      body_names = class_body_installed_names(region[:block_irep])
      return nil unless body_names

      names.merge(body_names)
    end
    names
  end

  # RUNTIME_DEF_DEVIRT_GUARD: may a call to `name` be bound statically in
  # the method currently being compiled? False for every method that does no
  # runtime patching at all (@runtime_installed_names nil), which is all but
  # two in this whole closed world -- so this changes nothing anywhere else.
  def devirt_blocked_name?(name)
    return false unless @runtime_installed_names
    return true if @runtime_installed_names == :unknown

    @runtime_installed_names.include?(name.to_s)
  end

  # RUNTIME_DEF_DEVIRT_GUARD: the marker kinds that are REAL dynamic
  # dispatch -- the receiver's own runtime method lookup decides, so a
  # runtime singleton patch is honoured automatically and there is nothing
  # to guard.
  #
  # Everything else this file can print as `// KIND :name` is treated as a
  # static binding by the audit below. That polarity is deliberate:
  # devirtualization markers are added to this file regularly, and a new one
  # that nobody remembered to list here lands on the SAFE side (audited, and
  # at worst costing one method its compilation) rather than shipping an
  # unguarded static bind.
  RUNTIME_DEF_DYNAMIC_MARKERS = %w[
    POLY SPLAT KEYWORD_HASH_POSITIONAL EXPLICIT_BLOCK_ARG
    BLOCK_FALLBACK LAMBDA_FALLBACK SDEF_FALLBACK TDEF_FALLBACK
    SCLASS_FALLBACK
  ].freeze

  # RUNTIME_DEF_DEVIRT_GUARD: the belt-and-braces half of the guard.
  #
  # devirt_blocked_name? already refuses to devirtualize a runtime-installed
  # name at the two selectors that actually produced the bug
  # (monomorphic_target, poly_small_n_targets). This re-reads the FINISHED
  # generated text of the method -- the exact thing that would ship -- and
  # turns any remaining static bind of a blocked name into an ordinary
  # `#error`, which SKIP_UNSUPPORTED then drops, leaving the method on the
  # interpreter exactly as it was before this mechanism existed.
  #
  # Reading the emitted text rather than re-deriving the decision is the
  # whole point: it cannot drift from what the code generator actually did,
  # so a devirtualization path that does NOT run through either gated
  # selector still cannot silently ship a wrong bind. Returns "" -- costing
  # nothing and changing nothing -- for every method that installs no
  # methods at runtime.
  def runtime_def_devirt_audit(code)
    return '' unless @runtime_installed_names

    # `/` is part of the kind, not a separator: one real marker spells itself
    # `IVAR_ACCESSOR/ELEMENT`, and a kind pattern that stopped at the slash
    # would simply fail to match that whole line -- i.e. silently skip
    # auditing it. A compound kind is not in RUNTIME_DEF_DYNAMIC_MARKERS, so
    # it lands on the audited side, which is the correct default.
    offenders = code.scan(%r{^\s*// ([A-Z][A-Z_0-9/]*) :(\S+?)(?:\s|,|$)}).reject do |kind, _name|
      RUNTIME_DEF_DYNAMIC_MARKERS.include?(kind)
    end.select { |_kind, name| devirt_blocked_name?(name) }
    return '' if offenders.empty?

    offenders.uniq.map do |kind, name|
      "  #error #{kind} devirtualization of :#{name}, which this method installs on a runtime " \
        "singleton class -- not in this prototype's supported subset\n"
    end.join
  end

  def sdef_fallback_region(insn, irep)
    runtime_def_region(insn, irep, 'sdef_fallback')
  end

  # RUNTIME_DEF_FALLBACK_SUPPORT: the shared install snippet for SDEF and
  # TDEF -- the one line that actually mutates a live method table.
  #
  # `mrb_define_method_id(M, tc, mid, fn, MRB_ARGS_REQ(n))` is proven
  # equivalent to what OP_SDEF/OP_TDEF really do, checked against
  # src/class.c's own mrb_define_method_raw rather than assumed:
  #
  #   * VISIBILITY. The VM installs with MRB_METHOD_VDEFAULT_FL; this
  #     installs with MRB_METHOD_PUBLIC_FL. Those resolve to the SAME thing
  #     here, because mrb_define_method_raw resolves VDEFAULT itself and its
  #     very first branch is `/* singleton methods are always public */ if
  #     (c->tt == MRB_TT_SCLASS) MRB_SET_VISIBILITY_FLAGS(flags,
  #     MRB_METHOD_PUBLIC_FL);`. Every target class this mechanism ever
  #     installs onto is a singleton class by construction -- SDEF's is
  #     `mrb_singleton_class(...)` by definition, and TDEF's is only ever
  #     reached from an SCLASS-opened body (see the exec_fallback gate) --
  #     so the VDEFAULT path this code skips would have produced PUBLIC
  #     anyway. Note this is NOT true of a TDEF in an ordinary `class Foo`
  #     body, where VDEFAULT consults the enclosing `private`/`public`
  #     scope; that is one of the reasons EXEC support here is confined to
  #     the SCLASS shape.
  #   * THE FORCED-PRIVATE NAMES. `initialize`/`initialize_copy`/
  #     `respond_to_missing?` are forced private by mrb_define_method_raw
  #     unconditionally, BEFORE the visibility branch above and regardless
  #     of the flag passed in -- and `mrb_define_method_id` funnels into
  #     that same mrb_define_method_raw. So those three names get identical
  #     treatment on both paths with nothing needed here.
  #   * ARITY. MRB_ARGS_REQ(n) matches the `mrb_get_args(M, "o"*n, ...)` the
  #     compiled entry wrapper performs, and runtime_def_body_safe? has
  #     already refused every non-mandatory-only ENTER.
  #
  # THE method_added HOOK is the one thing `mrb_define_method_id` does NOT
  # do and OP_SDEF/OP_TDEF do: each of them runs `mrb_method_added(mrb, tc,
  # mid)` right after installing. That function is declared in
  # include/mruby/internal.h, NOT exported as MRB_API, so generated code
  # cannot call it -- but it is three lines of src/class.c and every piece
  # it needs IS public:
  #
  #   added = (c->tt == MRB_TT_SCLASS) ? singleton_method_added : method_added;
  #   recv  = (c->tt == MRB_TT_SCLASS) ? mrb_iv_get(.., c, __attached__) : c;
  #   if (!mrb_func_basic_p(mrb, recv, added, mrb_do_nothing))
  #     mrb_funcall_argv(mrb, recv, added, 1, &sym);
  #
  # Only the SCLASS arm is ever needed here: every target class this
  # mechanism installs onto is a singleton class, by the same construction
  # the VISIBILITY proof above relies on.
  #
  # The `mrb_func_basic_p` guard is DROPPED rather than reproduced, and that
  # is a real equivalence rather than a shortcut. `mrb_do_nothing`
  # (src/class.c) is literally `{ return mrb_nil_value(); }`, and it is what
  # mruby's own method table installs for BasicObject#singleton_method_added
  # (src/class.c's MRB_MT_ENTRY table). So the guard's only job is to SKIP a
  # call to a function that provably does nothing -- calling it anyway
  # produces the identical program state, just without the optimization.
  # Every other outcome is unchanged: a program that really has overridden
  # the hook gets it invoked exactly as the interpreter would.
  #
  # Neither the guard nor `mrb_do_nothing` is exported, so reproducing the
  # skip would have meant reaching into VM internals; this way the whole
  # mechanism stays on public API with no closed-world assumption about
  # whether anything overrides the hook at all. (An earlier revision of this
  # code instead REFUSED to compile whenever the closed-world registry knew
  # a definition of either hook name -- which turned out to refuse
  # everything, because mruby's own core C sources define both names, as
  # `mrb_do_nothing`, and the NATIVE_SRCS scan correctly sees them. That
  # false positive is exactly what this approach removes.)
  #
  # `mrb_funcall_argv` is the same public entry point mrb_method_added
  # itself uses, and it deliberately performs no visibility check -- which
  # matters, because both hooks are installed MRB_MT_PRIVATE.
  #
  # What is NOT identical, and is inherent to this whole compiler rather
  # than to this mechanism: the installed body is a cfunc method, not a
  # bytecode RProc, so it has no irep for introspection to walk. Every
  # method bc2cpp compiles already has exactly that property.
  def emit_runtime_def_install(target_class_expr, region, fn_name, indent)
    tc_var = "bc2cpp_def_tc_#{region[:block_addr]}"
    mid_var = "bc2cpp_def_mid_#{region[:block_addr]}"
    sym_var = "bc2cpp_def_sym_#{region[:block_addr]}"
    out = String.new
    # Bound to a local first: `target_class_expr` can be a real call with a
    # real side effect (SDEF's own `mrb_singleton_class`, which CREATES the
    # singleton class if the object doesn't have one yet), and the hook call
    # below needs the very same class the install used.
    out << "#{indent}struct RClass* #{tc_var} = #{target_class_expr};\n"
    out << "#{indent}mrb_sym #{mid_var} = mrb_intern_cstr(M, \"#{region[:name]}\");\n"
    out << "#{indent}mrb_define_method_id(M, #{tc_var}, #{mid_var}, #{fn_name}, " \
           "MRB_ARGS_REQ(#{region[:mand]}));\n"
    out << "#{indent}mrb_value #{sym_var} = mrb_symbol_value(#{mid_var});\n"
    out << "#{indent}mrb_funcall_argv(M, mrb_iv_get(M, mrb_obj_value(#{tc_var}), " \
           "mrb_intern_cstr(M, \"__attached__\")), mrb_intern_cstr(M, \"singleton_method_added\"), " \
           "1, &#{sym_var});\n"
    # Both opcodes leave the defined method's NAME, as a Symbol, in their own
    # `a` register (src/vm.c: `regs[a] = mrb_symbol_value(mid);`) -- the value
    # a real `def` expression evaluates to. Written AFTER the hook call, the
    # same order vm.c uses. Emitted whenever the enclosing irep actually HAS
    # that register: `private def foo...` and a bare `def` used as a statement
    # disassemble identically up to this point, so the write is not something
    # this file can decide to skip by looking at the `def` alone.
    #
    # It CAN be skipped -- and must be -- when the register is past the end of
    # the enclosing irep's own declared `nregs`, which is a real thing mrbc
    # emits rather than a defensive guess. A class body whose only statement
    # is a `def` disassembles as:
    #
    #   irep ... nregs=1 nlocals=1 pools=0 syms=1 reps=1 ilen=6
    #     000 TDEF  R1  :who  I[0]
    #     004 RETURN  R0
    #
    # -- `nregs=1`, so R0 is the only register that exists, yet the TDEF names
    # R1. The interpreter gets away with it because OP_EXEC's own
    # `stack_extend(mrb, irep->nregs)` leaves slack above the declared count,
    # but compiled code declares exactly `nregs` C++ locals (emit_proc_
    # fallback_fn's own preamble), so emitting the write would name a variable
    # that does not exist -- a hard g++ error, which is exactly how this was
    # found.
    #
    # Dropping the write is not merely convenient, it is provably lossless:
    # mrbc's own register allocator sets `nregs` to bound every register the
    # irep can still READ, so a register at or beyond it is dead by
    # construction -- nothing in this body can observe the value. (Confirmed
    # against the disassembly above: the very next instruction returns R0 and
    # R1 is never read.)
    if region[:dest_reg] < region[:enclosing_nregs].to_i
      out << "#{indent}r#{region[:dest_reg]} = #{sym_var};\n"
    else
      out << "#{indent}(void)#{sym_var}; // R#{region[:dest_reg]} is past the enclosing irep's " \
             "nregs=#{region[:enclosing_nregs]} -- dead by construction, see above\n"
    end
    out
  end

  # SDEF_FALLBACK: `def archive.read(name); @entries[name]; end` -- one
  # method installed on ONE runtime object's real singleton class.
  #
  # src/vm.c's OP_SDEF is `struct RClass *tc = mrb_class_ptr(mrb_singleton_
  # class(mrb, regs[a]));` followed by the install. `mrb_singleton_class` is
  # public MRB_API and is the raising wrapper around mrb_singleton_class_ptr
  # (`if (c == NULL) mrb_raise(mrb, E_TYPE_ERROR, "can't define singleton")`)
  # -- so spelling it exactly the way vm.c does, rather than reaching for
  # the non-raising `_ptr` variant, keeps the real TypeError for a receiver
  # that cannot have a singleton class (an Integer, a Symbol, a Float).
  #
  # Note what this case does NOT need, and why it is strictly simpler than
  # the EXEC/SCLASS one below: there is no arbitrary class BODY to execute.
  # The receiver is an ordinary value already sitting in a register, the
  # method body is a single child irep compiled like any other, and the
  # whole translation is "take that object's singleton class, install".
  # No RProc, no env capture, no new VM call frame.
  def emit_sdef_fallback_glue(region, fn_name)
    out = String.new
    out << "  // SDEF_FALLBACK :#{region[:name]} -- singleton method body compiled as a standalone cfunc, " \
           "installed on the receiver's real runtime singleton class\n"
    out << "  {\n"
    out << emit_runtime_def_install("mrb_class_ptr(mrb_singleton_class(M, r#{region[:dest_reg]}))",
                                     region, fn_name, '    ')
    out << "  }\n"
    out
  end

  # TDEF_FALLBACK: a `def` inside an EXEC-opened class body. src/vm.c's
  # OP_TDEF installs onto `check_target_class(mrb)`, this frame's own
  # target class. Inside a body entered by OP_EXEC that is provably the same
  # object as `self` (see emit_proc_fallback_fn's own self_source comment for
  # the `recv`/`c` identity straight out of OP_EXEC), and `self` is something
  # compiled code genuinely holds -- so `mrb_class_ptr(self)` is an exact
  # translation of check_target_class here, not an approximation.
  #
  # check_target_class's own failure mode (`if (!tc) goto L_RAISE`, a
  # "no class/module to add method" RuntimeError) cannot arise on this path:
  # it only returns NULL for a frame with no target class at all, and this
  # frame's was supplied explicitly by emit_exec_fallback_glue below.
  def emit_tdef_fallback_glue(region, fn_name)
    out = String.new
    out << "  // TDEF_FALLBACK :#{region[:name]} -- `def` inside a class-reopen body, compiled as a standalone " \
           "cfunc, installed on this body's own target class (== self, per OP_EXEC)\n"
    out << "  {\n"
    out << emit_runtime_def_install('mrb_class_ptr(self)', region, fn_name, '    ')
    out << "  }\n"
    out
  end

  # SCLASS_FALLBACK + EXEC_FALLBACK: `class << Graphics; alias_method
  # :_probe_update, :update; def update; ...; end; end` sitting in the
  # middle of an ordinary method body -- the real shape at
  # `RGSS.singleton#effect_probe` (mruby-rgss/mrblib/lib.rb).
  #
  # Recognizes exactly one bytecode shape: an `SCLASS Ra` immediately
  # followed by an `EXEC Ra I[c]` on the SAME register. That is what mrbc
  # emits for a `class << expr ... end` and nothing else emits it --
  # codegen.c's NODE_SCLASS arm evaluates the receiver, emits OP_SCLASS on
  # its register, then OP_EXEC on that same register with the body's own
  # child irep. Requiring adjacency AND register identity means an SCLASS
  # whose result is used for anything else (there is no such shape today,
  # but the guard costs nothing) keeps its honest `#error`.
  #
  # Deliberately NOT extended to `CLASS`/`MODULE`+`EXEC` (an ordinary
  # `class Foo ... end` nested in a method body), even though the EXEC half
  # would translate identically. Two reasons, both real:
  #   * A TDEF in a NON-singleton class body resolves its VDEFAULT
  #     visibility against the enclosing `private`/`public` scope
  #     (src/class.c's mrb_define_method_raw), which the plain
  #     `mrb_define_method_id` install used here does not reproduce. The
  #     SCLASS shape sidesteps that entirely because singleton methods are
  #     unconditionally public -- see emit_runtime_def_install's own proof.
  #   * CLASS/MODULE also CREATE a constant, which this compiler's
  #     closed-world registry has no way to learn about.
  # Neither shape occurs in this closed world today; both keep their
  # existing `#error`.
  #
  # The body itself is compiled by the same emit_proc_fallback_fn every
  # BLOCK_FALLBACK body goes through, so everything that already works
  # inside a block body -- ordinary sends (which is what `alias_method`,
  # `attr_reader`, `attr_accessor`, `include`, `private` and friends all
  # are), nested blocks, rescue regions, the all-or-nothing contract --
  # works inside a class-reopen body with no further code. `def` is the one
  # thing a class body can contain that a block body cannot, and that is
  # exactly what the TDEF pass in emit_proc_fallback_fn adds.
  def recognize_exec_fallback_regions(irep)
    regions = []
    irep.instructions.each_with_index do |insn, idx|
      next unless insn.op == 'SCLASS'

      nxt = irep.instructions[idx + 1]
      next unless nxt && nxt.op == 'EXEC'

      reg = insn.args[/\AR(\d+)\z/, 1]
      m = nxt.args.match(/\AR(\d+)\s+I\[(\d+)\]\z/)
      next unless reg && m && m[1] == reg

      child_label = irep.reps[m[2].to_i]
      next unless child_label

      child = @ireps[child_label]
      next unless child

      regions << { block_irep: child, block_addr: insn.addr, exec_addr: nxt.addr,
                   kind: 'exec_fallback', self_source: :receiver, dest_reg: reg.to_i }
    end
    regions
  end

  # SCLASS_FALLBACK + EXEC_FALLBACK call-site glue -- the two opcodes
  # translated together, because the singleton class OP_SCLASS computes is
  # the only thing OP_EXEC then consumes.
  #
  #   OP_SCLASS: `regs[a] = mrb_singleton_class(mrb, regs[a]);` -- spelled
  #   verbatim, raising wrapper included, exactly as in emit_sdef_fallback_
  #   glue above.
  #
  #   OP_EXEC: builds an RProc over the class body with MRB_PROC_SCOPE, sets
  #   its target class to that singleton class, and pushes a call frame
  #   whose self is the same value. `mrb_yield_with_class` (public MRB_API,
  #   src/vm.c) is mruby's own entry point for precisely that: its
  #   yield_with_attr does `ci->u.target_class = c; ci->proc = p;` and, for
  #   a cfunc proc, `ci->stack[0] = self; val = MRB_PROC_CFUNC(p)(mrb,
  #   self);`. So the frame the class body runs in has the same self and the
  #   same target class the interpreter's own OP_EXEC frame would have.
  #   Using it rather than calling the compiled function directly is what
  #   makes `private`/`public`/`module_function` inside a reopen body see
  #   the right scope: src/class.c's find_visibility_scope reads
  #   `mrb_vm_ci_target_class(ci)`, which only exists because this frame was
  #   pushed properly.
  #
  # The MRB_PROC_SCOPE flag itself has no analogue to set on a cfunc proc
  # and needs none. Its two real consumers are check_visibility_break
  # (src/class.c), which treats a SCOPE proc and a proc with no `upper`
  # identically -- both return TRUE, "this frame is the visibility scope" --
  # and a cfunc proc built by mrb_proc_new_cfunc has `upper == NULL`; and
  # OP_RETURN's own scope-unwinding, which never runs because there is no
  # bytecode frame here to unwind.
  #
  # EXEC's own result value needs no special handling: cipush/OP_RETURN
  # leave the class body's return value in `regs[a]`, and mrb_yield_with_
  # class returns exactly that value, so one assignment reproduces it.
  def emit_exec_fallback_glue(region, fn_name)
    dest_reg = region[:dest_reg]
    sc_var = "bc2cpp_sclass_#{region[:block_addr]}"
    proc_var = "bc2cpp_exec_proc_#{region[:block_addr]}"
    out = String.new
    out << "  // SCLASS_FALLBACK + EXEC_FALLBACK -- `class << recv` body compiled as a standalone cfunc, " \
           "executed against the real runtime singleton class (self == target class, per OP_EXEC)\n"
    out << "  {\n"
    out << "    mrb_value #{sc_var} = mrb_singleton_class(M, r#{dest_reg});\n"
    out << "    struct RProc* #{proc_var} = mrb_proc_new_cfunc(M, #{fn_name});\n"
    out << "    r#{dest_reg} = mrb_yield_with_class(M, mrb_obj_value(#{proc_var}), 0, NULL, " \
           "#{sc_var}, mrb_class_ptr(#{sc_var}));\n"
    out << "  }\n"
    out
  end

  # `idx` is this instruction's own position in `irep.instructions`, the start
  # point every backward-scan proof here needs. `reg_offset` is non-zero for
  # exactly one caller -- compile_block_body_insn's inlined-block-body
  # delegation, whose `insn.args` registers are shifted by the enclosing
  # irep's `nregs` -- and is applied via `unshift_proof_reg` (see its own
  # header) at every point a register number is handed to a proof rather than
  # printed into the generated C++.
  def compile_insn(insn, irep, owner_def, idx = nil, reg_offset = 0)
    a = insn.args
    case insn.op
    when 'ENTER'
      "  // #{insn.raw.strip} (args already bound above)\n"
    when 'GETUPVAR', 'SETUPVAR'
      # UPVAR_CAPTURE_SUPPORT: only ever real here inside a BLOCK_FALLBACK
      # body (emit_proc_fallback_fn's own consume-and-clear
      # @block_fallback_upvars, set for exactly that one body-compile
      # loop) -- an ordinary top-level method irep never legitimately
      # contains GETUPVAR/SETUPVAR at all (only a block/lambda child irep
      # does), and a directly-INLINED block body (`.each`/`.times`/...)
      # never reaches this shared compile_insn for these two opcodes in
      # the first place -- compile_block_body_insn (a different function)
      # has its own, register-offset-aware translation for the inlined
      # case, unaffected by this one. `reg`/`upvar_idx`/`level` match
      # real `mrbc -v` disassembly exactly (`GETUPVAR R3 4 0`): `level`
      # must be `0` (see BLOCK_FALLBACK_UNSAFE_OPS's own comment on why a
      # deeper capture is refused outright, not just unsupported here),
      # and `upvar_idx` is literally the enclosing method's own register
      # number -- confirmed against 3rd/mruby/src/vm.c's own
      # `OP_GETUPVAR`/`OP_SETUPVAR` (`e->stack[b]`, the exact same
      # indexing a bare `R(b)` read would use in the DEFINING scope).
      # DEEP_UPVAR_CAPTURE_SUPPORT: matched on the real `[level, index]`
      # pair, not on `index` with `level` forced to 0. Both operands are
      # taken verbatim from the disassembly and looked up in the captured
      # set this body's own function really declares parameters for, so a
      # level the enclosing frame never captured still falls through to
      # the honest `#error` below rather than naming a variable that does
      # not exist. The generated access is identical at every level -- the
      # captured value IS an `mrb_value*` aimed at the defining frame's
      # own register, whichever frame that is (see upvar_var_name and
      # emit_rproc_construction for how a deeper one is forwarded).
      reg, upvar_idx, level = a.split(/\s+/)
      key = [level.to_i, upvar_idx.to_i]
      if level =~ /\A\d+\z/ && @block_fallback_upvars&.include?(key)
        vname = upvar_var_name(*key)
        if insn.op == 'GETUPVAR'
          "  r#{reg[/\d+/]} = *#{vname};\n"
        else
          "  *#{vname} = r#{reg[/\d+/]};\n"
        end
      else
        "  #error unhandled opcode #{insn.op} -- not in this prototype's supported subset\n"
      end
    when 'KEY_P'
      # KEYWORD_ARG_SUPPORT: real presence check for one optional keyword
      # -- the entry wrapper's own real mrb_kwargs extraction (compile_
      # method) already computed this as a plain bool parameter, named
      # purely from this same instruction's own `:sym` operand (see
      # kwarg_param_name's own comment -- no external table needed here).
      d = a[/^R(\d+)/, 1]
      sym = a[/:(\S+)/, 1]
      "  r#{d} = mrb_bool_value(#{kw_given_param_name(sym)});\n"
    when 'KARG'
      # KEYWORD_ARG_SUPPORT: fetch one keyword's own real value -- required
      # or optional, both are already-unpacked plain mrb_value parameters
      # by the time _impl runs (an optional one's own default-value
      # computation, reached only when KEY_P's own JMPIF found it absent,
      # simply overwrites this same register right afterward, exactly like
      # OPTIONAL_ARG_SUPPORT's own default-value codegen).
      d = a[/^R(\d+)/, 1]
      sym = a[/:(\S+)/, 1]
      "  r#{d} = #{kwarg_param_name(sym)};\n"
    when 'KEYEND'
      # KEYWORD_ARG_SUPPORT: real unrecognized-keyword-argument checking
      # (raising ArgumentError on a key this method never declared) is
      # already done by the entry wrapper's own real mrb_kwargs (`rest:
      # NULL`, mruby.h's own documented behavior) before _impl is ever
      # reached -- nothing left for this opcode to do here.
      "  // KEYEND: already enforced by the entry wrapper's own mrb_kwargs (rest: NULL)\n"
    when 'MOVE'
      d, s = regs(a, 2)
      "  r#{d} = r#{s};\n"
    when 'LOADNIL'
      d, = regs(a, 1)
      "  r#{d} = mrb_nil_value();\n"
    when 'LOADFALSE'
      d, = regs(a, 1)
      "  r#{d} = mrb_false_value();\n"
    when 'LOADTRUE'
      d, = regs(a, 1)
      "  r#{d} = mrb_true_value();\n"
    when 'LOADSELF'
      # "LOADSELF R2 (R0)" -- R[a] = self (src/vm.c's OP_LOADSELF). Real
      # code hits this from an explicit-receiver self-send that mrbc
      # doesn't fold into SSEND (`self.foo = ...`, a plain local-variable-
      # looking assignment on an attr writer, compiles to LOADSELF + SEND
      # rather than SSEND -- confirmed against a toy `self.baz = 1` case).
      # r0 is already wired to `self` at the top of every generated
      # function body (CodeGen#compile_method's own `mrb_value r0 = self;`
      # declaration), so this is exactly as trivial as LOADNIL/LOADFALSE/
      # LOADTRUE's own bare-assignment shape above.
      d, = regs(a, 1)
      "  r#{d} = self;\n"
    when 'LOADSYM'
      d = a[/^R(\d+)/, 1]
      name = a[/:(\S+)/, 1]
      "  r#{d} = mrb_symbol_value(mrb_intern_cstr(M, \"#{name}\"));\n"
    when /^LOADI/
      d = a[/^R(\d+)/, 1]
      # The small-immediate variants (LOADI_0..7, LOADI__1, plain LOADI)
      # show the literal parenthesized, e.g. "R6\t(3)" -- but the
      # wider-range ones (LOADI8/LOADI16/LOADI32/...) don't: "R1\t128" with
      # no parens at all. Real game code hits both; this toy's own literals
      # were all small enough to only ever exercise the parenthesized form.
      lit = a[/\(([^)]+)\)/, 1] || a[/^R\d+\s+(-?\d+)/, 1]
      "  r#{d} = mrb_fixnum_value(#{lit});\n"
    when 'LOADL'
      # "LOADL R5 L[0]" -- a numeric literal too wide for LOADI's own
      # immediate operand (src/vm.c's OP_LOADL: pool[k].tt is INT32/INT64/
      # BIGINT/FLOAT). Only FLOAT is modeled here -- parse_c_dump's own
      # pool scan already tags a non-string entry as {type:, raw:} (the
      # same mixed-type-pool handling STRING's own #error fallback above
      # relies on), and every real FLOAT entry seen in this codebase's own
      # pools (mrbc's C dump, a %.17g-shaped literal, e.g. ".f=0.330000000
      # 00000002") is already a valid, directly-reusable C double literal
      # -- no reformatting needed. INT32/INT64/BIGINT pool entries never
      # showed up under LOADL in real code (mrb_int literals wide enough
      # to need LOADL instead of LOADI/LOADI8/16/32 are bignums here,
      # IREP_TT_BIGINT -- a real big-endian sign+exponent encoded string
      # this prototype doesn't decode); left as an honest #error, the same
      # "loud gap, not a silent wrong translation" every other unmodeled
      # shape here gets, rather than guessed at.
      d = a[/^R(\d+)/, 1]
      pidx = a[/L\[(\d+)\]/, 1].to_i
      entry = irep.pool.fetch(pidx)
      if entry.is_a?(Hash) && entry[:type] == :float
        lit = entry[:raw][/\.f\s*=\s*(.+)/, 1]
        "  r#{d} = mrb_float_value(M, #{lit});\n"
      else
        kind = entry.is_a?(Hash) ? entry[:type] : :string
        "  #error LOADL references a non-float pool entry (#{kind}) -- not in this prototype's supported subset\n"
      end
    when 'STRING'
      d = a[/^R(\d+)/, 1]
      idx = a[/L\[(\d+)\]/, 1].to_i
      entry = irep.pool.fetch(idx)
      if entry.is_a?(String)
        "  r#{d} = mrb_str_new_cstr(M, #{c_string_literal(entry)});\n"
      else
        "  #error STRING references a non-string pool entry (#{entry[:type]}) -- not in this prototype's supported subset\n"
      end
    when 'SYMBOL'
      # "SYMBOL R2 L[0] ; atk_mod" -- real OP_SYMBOL semantics (ops.h: `R[a]
      # = intern(Pool[b])`) -- a DIFFERENT opcode from LOADSYM: LOADSYM
      # embeds an already-interned mrb_sym directly as an operand (no pool
      # lookup at all, this file's SEND-argument code and the `when
      # 'LOADSYM'` case above already read plenty of literal `:name`
      # symbols straight off it), while SYMBOL instead names a *string*-pool
      # entry to intern at runtime. Confirmed against src/codedump.c's own
      # disassembler (`CASE(OP_SYMBOL, BB): ... fprintf(out, "SYMBOL\tR%d\t
      # L[%d]\t; %s", ...)`) -- an identical `L[idx]` pool-index shape to
      # STRING's own disassembly (real dump above: "SYMBOL R2 L[0] ;
      # atk_mod"), so the literal string value is read out of `irep.pool`
      # via the exact same mechanism STRING's own `when 'STRING'` case just
      # above already uses (reused verbatim, not reinvented), then interned
      # through the real public API (`mrb_symbol_value(mrb_intern_cstr(...))
      # `, the identical call LOADSYM's own case above already makes for its
      # own `:name` operand).
      #
      # Real trigger, confirmed against both real whole-program SYMBOL
      # occurrences (Game::Battle#apply_knockout_reset's `%i[atk_mod
      # def_mod spi_mod agi_mod]`, 4 words -> 4 SYMBOL + one ARRAY(4); and
      # RPG2k::Scene::Map#vehicle_blocks?'s own 2-word `%i[...]` -> 2 SYMBOL
      # + one ARRAY(2)) AND a fresh `mrbc -v` disassembly of that exact
      # literal (matches byte-for-byte):
      # a bare `:foo` or quoted `:"foo"` symbol literal never reaches here
      # at all -- parse.y's own `sym: tSTRING_BEG tSTRING` interns those at
      # PARSE time, straight into a LOADSYM operand (confirmed by a fresh
      # disassembly of both shapes: `LOADSYM R2 :foo` / `LOADSYM R2 :bar`,
      # neither ever produces a SYMBOL opcode). SYMBOL is instead mrbc's own
      # `%i[...]`/`%I[...]` symbol-*array*-literal codegen (codegen.c's
      # gen_literal_array, called from codegen_symbols): each non-
      # interpolated word first codegens as a plain OP_STRING, then
      # gen_intern's own peephole (`data.insn == OP_STRING && data.a ==
      # cursp()`) rewrites that STRING into SYMBOL in place -- a compile-
      # time string-to-symbol fold, same spirit as LOADSYM's own compile-
      # time-interned literal -- immediately followed by this opcode's own
      # ARRAY(N) to collect them (this file's own `when 'ARRAY'` case
      # handles that half already; nothing SYMBOL-specific needed there).
      d = a[/^R(\d+)/, 1]
      sidx = a[/L\[(\d+)\]/, 1].to_i
      sentry = irep.pool.fetch(sidx)
      if sentry.is_a?(String)
        "  r#{d} = mrb_symbol_value(mrb_intern_cstr(M, #{c_string_literal(sentry)}));\n"
      else
        "  #error SYMBOL references a non-string pool entry (#{sentry[:type]}) -- not in this prototype's supported subset\n"
      end
    when 'INTERN'
      # "INTERN R<a>" -- OP_INTERN's own real body (src/vm.c): `mrb_ensure_
      # string_type(mrb, regs[a]); mrb_sym sym = mrb_intern_str(mrb, regs[a]);
      # regs[a] = mrb_symbol_value(sym);` -- an in-place String->Symbol
      # conversion (mrbc's own codegen: `:"#{expr}"`/`expr.to_sym`-shaped
      # dynamic symbol construction, confirmed against src/codedump.c's own
      # disassembler, `CASE(OP_INTERN, B): fprintf(out, "INTERN\tR%d\t", a)`
      # -- a single register operand, read AND written, unlike STRING/SYMBOL
      # above which only ever write their own `d`). Always safe regardless
      # of program shape or receiver class -- a pure runtime conversion, no
      # whole-program fact to verify (unlike SUPER_TARGETS' own gated
      # cases) -- so this is unconditional, the same way STRCAT immediately
      # above is.
      d = a[/^R(\d+)/, 1]
      "  r#{d} = mrb_ensure_string_type(M, r#{d});\n  r#{d} = mrb_symbol_value(mrb_intern_str(M, r#{d}));\n"
    when 'STRCAT'
      # Matches OP_STRCAT's own real semantics exactly (src/vm.c):
      # mrb_ensure_string_type then mrb_str_concat (mutates r<d> in place).
      d = a[/^R(\d+)/, 1]
      s = a[/\(R(\d+)\)/, 1]
      "  r#{d} = mrb_ensure_string_type(M, r#{d});\n  mrb_str_concat(M, r#{d}, r#{s});\n"
    when 'GETIV'
      d = a[/^R(\d+)/, 1]
      ivar = a[/@(\w+)/, 1]
      if (type = embed_type(owner_def.owner, ivar))
        sname = struct_name(owner_def.owner)
        box = TYPE_OPS.fetch(type)[:box]
        note = "  // @#{ivar} embedded (#{type}) -- direct struct field read, no mrb_iv_get\n"
        "#{note}  r#{d} = #{box}(((#{sname}*)DATA_PTR(self))->#{ivar});\n"
      else
        "  r#{d} = mrb_iv_get(M, self, mrb_intern_cstr(M, \"@#{ivar}\"));\n"
      end
    when 'SETIV'
      ivar = a[/@(\w+)/, 1]
      # See the matching comment in IvarLayout.analyze -- not `$`-anchored,
      # a trailing "; R1:name" local-variable comment breaks that.
      s = a[/R(\d+)/, 1]
      if (type = embed_type(owner_def.owner, ivar))
        sname = struct_name(owner_def.owner)
        ops = TYPE_OPS.fetch(type)
        note = "  // @#{ivar} embedded (#{type}) -- direct struct field write, no mrb_iv_set\n"
        # Optimistic but guarded: the whole-program analysis proved every
        # *compiled* write site is this type, but it can't see writes from
        # outside this program (reflection, a future uncompiled caller) --
        # so this checks rather than blindly trusting its own analysis.
        # Not E_TYPE_ERROR: that macro hardcodes the identifier `mrb`, and
        # every generated function here names its mrb_state* parameter `M`.
        "#{note}  if (!#{ops[:check]}(r#{s})) mrb_raise(M, mrb_exc_get_id(M, mrb_intern_lit(M, \"TypeError\")), \"@#{ivar}: expected #{ops[:err]}\");\n" \
          "  ((#{sname}*)DATA_PTR(self))->#{ivar} = #{ops[:unbox]}(r#{s});\n"
      else
        "  mrb_iv_set(M, self, mrb_intern_cstr(M, \"@#{ivar}\"), r#{s});\n"
      end
    when 'ADDI'
      d = a[/^R(\d+)/, 1]
      lit = a.split(/\s+/).last
      # FIXNUM_OPERAND_PROOF: the immediate is a Fixnum by construction, so
      # only the destination register needs proving here (see
      # proven_fixnum_operand?'s own header).
      if proven_fixnum_operand?(irep, idx, unshift_proof_reg(d, reg_offset), owner_def)
        "#{FIXNUM_PROOF_NOTE}  r#{d} = mrb_fixnum_value(mrb_fixnum(r#{d}) + #{lit});\n"
      else
        <<~CPP
          if (mrb_integer_p(r#{d})) {
            r#{d} = mrb_fixnum_value(mrb_fixnum(r#{d}) + #{lit});
          } else {
            #{compile_operator_fallback('+', d, nil, "mrb_fixnum_value(#{lit})", irep, idx, owner_def, reg_offset)}
          }
        CPP
      end
    when 'ADD'
      d = a[/^R(\d+)/, 1]
      s = a[/\(R(\d+)\)/, 1]
      if proven_fixnum_pair?(irep, idx, unshift_proof_reg(d, reg_offset), unshift_proof_reg(s, reg_offset), owner_def)
        "#{FIXNUM_PROOF_NOTE}  r#{d} = mrb_fixnum_value(mrb_fixnum(r#{d}) + mrb_fixnum(r#{s}));\n"
      else
        <<~CPP
          if (mrb_fixnum_p(r#{d}) && mrb_fixnum_p(r#{s})) {
            r#{d} = mrb_fixnum_value(mrb_fixnum(r#{d}) + mrb_fixnum(r#{s}));
          #ifndef MRB_NO_FLOAT
          } else if (mrb_float_p(r#{d}) && mrb_integer_p(r#{s})) {
            r#{d} = mrb_float_value(M, mrb_float(r#{d}) + mrb_integer(r#{s}));
          } else if (mrb_integer_p(r#{d}) && mrb_float_p(r#{s})) {
            r#{d} = mrb_float_value(M, mrb_integer(r#{d}) + mrb_float(r#{s}));
          } else if (mrb_float_p(r#{d}) && mrb_float_p(r#{s})) {
            r#{d} = mrb_float_value(M, mrb_float(r#{d}) + mrb_float(r#{s}));
          #endif
          } else {
            #{compile_operator_fallback('+', d, s, nil, irep, idx, owner_def, reg_offset)}
          }
        CPP
      end
    when 'SUBI'
      d = a[/^R(\d+)/, 1]
      lit = a.split(/\s+/).last
      if proven_fixnum_operand?(irep, idx, unshift_proof_reg(d, reg_offset), owner_def)
        "#{FIXNUM_PROOF_NOTE}  r#{d} = mrb_fixnum_value(mrb_fixnum(r#{d}) - #{lit});\n"
      else
        <<~CPP
          if (mrb_integer_p(r#{d})) {
            r#{d} = mrb_fixnum_value(mrb_fixnum(r#{d}) - #{lit});
          } else {
            #{compile_operator_fallback('-', d, nil, "mrb_fixnum_value(#{lit})", irep, idx, owner_def, reg_offset)}
          }
        CPP
      end
    when 'SUB'
      d = a[/^R(\d+)/, 1]
      s = a[/\(R(\d+)\)/, 1]
      if proven_fixnum_pair?(irep, idx, unshift_proof_reg(d, reg_offset), unshift_proof_reg(s, reg_offset), owner_def)
        "#{FIXNUM_PROOF_NOTE}  r#{d} = mrb_fixnum_value(mrb_fixnum(r#{d}) - mrb_fixnum(r#{s}));\n"
      else
        <<~CPP
          if (mrb_fixnum_p(r#{d}) && mrb_fixnum_p(r#{s})) {
            r#{d} = mrb_fixnum_value(mrb_fixnum(r#{d}) - mrb_fixnum(r#{s}));
          #ifndef MRB_NO_FLOAT
          } else if (mrb_float_p(r#{d}) && mrb_integer_p(r#{s})) {
            r#{d} = mrb_float_value(M, mrb_float(r#{d}) - mrb_integer(r#{s}));
          } else if (mrb_integer_p(r#{d}) && mrb_float_p(r#{s})) {
            r#{d} = mrb_float_value(M, mrb_integer(r#{d}) - mrb_float(r#{s}));
          } else if (mrb_float_p(r#{d}) && mrb_float_p(r#{s})) {
            r#{d} = mrb_float_value(M, mrb_float(r#{d}) - mrb_float(r#{s}));
          #endif
          } else {
            #{compile_operator_fallback('-', d, s, nil, irep, idx, owner_def, reg_offset)}
          }
        CPP
      end
    when 'MUL'
      # ADD/SUB's own fixnum-fastpath-else-mrb_funcall shape exactly:
      # src/vm.c's OP_ADD/OP_SUB/OP_MUL all expand from the identical
      # OP_MATH(op_name) macro (confirmed reading vm.c directly), so MUL's
      # real VM semantics differ from ADD/SUB only in which C operator and
      # which method name the slow path calls -- no separate design
      # question to answer here (unlike DIV, which deliberately skips the
      # fastpath for its own real rounding-direction reason, see below).
      d = a[/^R(\d+)/, 1]
      s = a[/\(R(\d+)\)/, 1]
      if proven_fixnum_pair?(irep, idx, unshift_proof_reg(d, reg_offset), unshift_proof_reg(s, reg_offset), owner_def)
        "#{FIXNUM_PROOF_NOTE}  r#{d} = mrb_fixnum_value(mrb_fixnum(r#{d}) * mrb_fixnum(r#{s}));\n"
      else
        <<~CPP
          if (mrb_fixnum_p(r#{d}) && mrb_fixnum_p(r#{s})) {
            r#{d} = mrb_fixnum_value(mrb_fixnum(r#{d}) * mrb_fixnum(r#{s}));
          #ifndef MRB_NO_FLOAT
          } else if (mrb_float_p(r#{d}) && mrb_integer_p(r#{s})) {
            r#{d} = mrb_float_value(M, mrb_float(r#{d}) * mrb_integer(r#{s}));
          } else if (mrb_integer_p(r#{d}) && mrb_float_p(r#{s})) {
            r#{d} = mrb_float_value(M, mrb_integer(r#{d}) * mrb_float(r#{s}));
          } else if (mrb_float_p(r#{d}) && mrb_float_p(r#{s})) {
            r#{d} = mrb_float_value(M, mrb_float(r#{d}) * mrb_float(r#{s}));
          #endif
          } else {
            #{compile_operator_fallback('*', d, s, nil, irep, idx, owner_def, reg_offset)}
          }
        CPP
      end
    when 'DIV'
      # DIV_FASTPATH_SUPPORT: real Ruby integer division (`Integer#/`)
      # floors toward negative infinity, not C's own truncating `/` --
      # this file's own earlier round punted on replicating that rounding
      # by hand and always went through `mrb_funcall`. Turns out nothing
      # needs replicating: `int_div` (the real `Integer#/` native
      # implementation, 3rd/mruby/src/numeric.c) itself calls a real,
      # already-public API for exactly the plain-Integer/plain-Integer
      # case -- `mrb_div_int_value(mrb, mrb_integer(x), mrb_integer(y))`
      # -- confirmed by reading `int_div` directly, not assumed from the
      # function's name. Calling that same function here (declared via an
      # `extern "C"` forward declaration exactly like `mrb_str_aref`'s own
      # -- `mruby/internal.h` has no MRB_BEGIN_DECL/MRB_END_DECL guard
      # either, confirmed by reading it) reproduces `Integer#/`'s real
      # rounding AND its real `ZeroDivisionError`/overflow raises exactly,
      # not an approximation -- the same "call mruby's own real
      # implementation function directly" substitution `GETIDX`'s own
      # String arm already makes for `mrb_str_aref`. Same fixnum/fixnum
      # runtime guard ADD/SUB/MUL already use (no bigint check, matching
      # their own established precedent for this exact reason), `mrb_
      # funcall` fallback for anything else (Float, a user #/ override, a
      # real Bignum).
      d = a[/^R(\d+)/, 1]
      s = a[/\(R(\d+)\)/, 1]
      if proven_fixnum_pair?(irep, idx, unshift_proof_reg(d, reg_offset), unshift_proof_reg(s, reg_offset), owner_def)
        "#{FIXNUM_PROOF_NOTE}  r#{d} = mrb_div_int_value(M, mrb_fixnum(r#{d}), mrb_fixnum(r#{s}));\n"
      else
        <<~CPP
          if (mrb_fixnum_p(r#{d}) && mrb_fixnum_p(r#{s})) {
            r#{d} = mrb_div_int_value(M, mrb_fixnum(r#{d}), mrb_fixnum(r#{s}));
          } else {
            #{compile_operator_fallback('/', d, s, nil, irep, idx, owner_def, reg_offset)}
          }
        CPP
      end
    when 'EQ', 'LT', 'LE', 'GT', 'GE'
      compile_cmp(insn.op, a, irep, idx, owner_def, reg_offset)
    # BLOCK_BODY_INDEX_SUPPORT: compile_send keeps its ordinary `idx` nil
    # inside shifted block bodies. The TYPED receiver tracer gets a separate
    # read-only `trace_idx`/register-offset pair below; the other call-site
    # scans still decline because they re-parse `args` themselves, derive a whole
    # `r<d>..r<d+n>` receiver/argument window from it, and hands those raw
    # numbers to six different backward scans -- two of which
    # (compile_keyword_send, compile_splat_send) hand REGISTER LISTS back out
    # to be printed straight into the generated C++, so they would need the
    # shift re-applied on the way out as well as removed on the way in.
    # `trace_new_target` needs only the receiver register and instruction
    # index, both of which can be safely unshifted, so it is the one scan that
    # now receives this separate proof context. Keyword/splat dispatch and
    # other scans keep the previous nil-index behavior.
    when 'SEND0', 'SEND'
      compile_send(a, self_implicit: false, irep: irep, idx: reg_offset.zero? ? idx : nil, owner_def: owner_def,
                   trace_idx: idx, trace_reg_offset: reg_offset)
    when 'SSEND0', 'SSEND'
      compile_send(a, self_implicit: true, irep: irep, idx: reg_offset.zero? ? idx : nil, owner_def: owner_def,
                   trace_idx: idx, trace_reg_offset: reg_offset)
    when 'BLKPUSH'
      # BLKPUSH_YIELD_SUPPORT: `BLKPUSH Ra m1:r:m2:kd (lv)` (real disasm,
      # confirmed via a fresh `mrbc -v` of `def foo(a,b); yield(a,b); end`:
      # `BLKPUSH R4 2:0:0:0 (0)`) -- 3rd/mruby/src/vm.c's own `OP_BLKPUSH`:
      # `lv == 0` reads `regs[1 + offset]`, this call frame's OWN received
      # block (never an outer scope's -- `lv > 0` walks `uvenv` instead, a
      # genuinely different value this compiler has no register/pointer for
      # today, same "not modeled, honest #error" territory as a depth>0
      # upvar). Only ever compiled with `@blk_param_name` set -- exactly
      # when compile_method's own prescan (`needs_blk_param`) found this
      # exact shape ahead of time and arranged for the entry wrapper to
      # extract the real block value into that C++ local -- so the `lv`
      # check here is really just re-confirming the same shape prescan
      # already required, not a fresh capability test.
      #
      # Real vm.c also raises `LocalJumpError` ("unexpected yield") if the
      # slot holds `nil` -- reproduced directly (`mrb_get_args`' own `&`
      # format specifier, unlike BLKPUSH's own raw stack read, happily
      # returns nil for "no block given" rather than raising itself, so
      # this check can't be skipped).
      #
      # BLOCK_FALLBACK_YIELD_SUPPORT: `lv > 0` is no longer unconditionally
      # unmodelable. Inside a BLOCK_FALLBACK body, emit_proc_fallback_fn
      # sets @blk_param_name/@blk_param_level for exactly the bodies whose
      # enclosing method's own block really was captured into the RProc's
      # env -- so the SAME `bc2cpp_blk` read answers `lv == 1` there. The
      # match is on the exact level, never `lv > 0` generally: vm.c walks
      # `uvenv(mrb, lv-1)`, a different frame for every distinct `lv`, and
      # this compiler holds exactly one of them.
      d = a[/^R(\d+)/, 1]
      lv = a[/\((\d+)\)/, 1]
      if lv == @blk_param_level.to_s && @blk_param_name
        <<~CPP
          if (mrb_nil_p(#{@blk_param_name})) {
            mrb_raise(M, mrb_exc_get_id(M, mrb_intern_lit(M, "LocalJumpError")), "bc2cpp: unexpected yield");
          }
          r#{d} = #{@blk_param_name};
        CPP
      else
        "#error unhandled opcode BLKPUSH #{a}\n"
      end
    when 'BLKCALL'
      # "BLKCALL R7 0" / "BLKCALL R4 2" -- real OP_BLKCALL semantics (ops.h:
      # `R[a] = R[a].call(R[a+1],...,R[a+b]); direct block call`). Confirmed
      # against both real whole-program BLKCALL occurrences AND a fresh
      # `mrbc -v` disassembly of the same source shape: this is mrbc's own
      # fast path for a *bare* `yield(...)` (codegen.c's codegen_yield) --
      # BLKPUSH first fetches the current method's own block into R[a], then
      # -- only for the plain shape (no keyword args, <15 positional args,
      # no splat) -- BLKCALL invokes it directly; any other shape
      # (kwargs/splat/>=15 args) falls back to an ordinary `SEND :call`
      # instead and never reaches here (codegen_yield's own `if (nk == 0 &&
      # n < 15) { ...OP_BLKCALL...} else { ...OP_SEND :call...}`). This is
      # the ONLY codegen.c call site that ever emits OP_BLKCALL, and real
      # bytecode always has it immediately preceded by a BLKPUSH into the
      # very same register (confirmed against all three real BLKCALL sites
      # in this whole program's compiled output: Scene::Battle#cached_
      # bitmap's `cache[key] = yield`, Scene::Map#cached_bitmap's identical
      # one-liner, and Scene::Map#page_field's `yield` -- rescued by its own
      # `rescue StandardError`. Every real *caller* of all three -- 8 call
      # sites for #cached_bitmap across battle.rb/map.rb, 15 for
      # #page_field in map.rb -- passes a literal `do...end`/`{...}` block,
      # never a forwarded `&proc`) -- so despite the generic-sounding name,
      # this is not a "call whatever Proc happens to be in a register"
      # primitive, it is specifically mrbc's `yield` fast path.
      #
      # Real vm.c's own CASE(OP_BLKCALL, ...) does NOT go through ordinary
      # method dispatch at all -- no mrb_funcall/method-table lookup by
      # name -- it raises TypeError directly if R[a] isn't literally a Proc
      # (`if (!mrb_proc_p(recv)) mrb_raisef(mrb, E_TYPE_ERROR, "wrong type
      # %T (expected Proc)", recv);`), then invokes the proc's own body
      # straight off its RProc*, bypassing whatever #call method (if any)
      # the receiver's own class happens to define. A plain `mrb_funcall(M,
      # r<a>, "call", ...)` substitute -- this file's own usual "dynamic
      # dispatch is always a safe fallback" pattern, see dynamic_dispatch_
      # line -- would NOT be sound here: if R[a] were ever some other
      # object whose class defines #call, mrb_funcall would silently invoke
      # that #call method instead of raising, which real BLKCALL never
      # does. So real BLKCALL's own type check is reproduced directly
      # (same exception class, TypeError; not vm.c's own %T-formatted
      # message text, which no #error/raise site in this whole file
      # reproduces byte-for-byte either -- see every existing "bc2cpp:
      # expected ... receiver" TypeError raise above for the same fixed-
      # string convention), and the actual invocation is done through
      # `mrb_yield_argv` -- mruby's own public, officially documented "run
      # this block synchronously and return its result" API (mruby.h),
      # used throughout mruby's own core C extensions to implement `yield`
      # from C -- rather than hand-reimplementing vm.c's own register-
      # window/callinfo bookkeeping by hand, the same "same observable
      # result, different but officially-sanctioned internal mechanism"
      # substitution this file's SEND/SSEND translations already make
      # throughout via plain mrb_funcall. For every real occurrence here
      # (an irep-backed Proc from a literal `do...end`/`{}` block, the only
      # kind ever seen at a real BLKCALL site in this codebase), vm.c's own
      # non-cfunc branch runs the proc's irep with `self` taken from its
      # captured environment (`MRB_PROC_ENV(p)->stack[0]`) -- exactly what
      # `mrb_yield_argv` itself computes too (its own `mrb_proc_get_self`,
      # src/proc.c, follows the identical env branch for a non-CFUNC proc),
      # so the two are observably equivalent for this case, including
      # `break`: `mrb_yield_argv` unwinds via mruby's ordinary MRB_THROW/
      # longjmp exception machinery exactly like every other raise this
      # file already emits elsewhere, correctly skipping past this
      # generated C++ frame's own POD `mrb_value` locals (nothing here has
      # a non-trivial destructor to skip) up to whatever real C frame
      # receives it (this method's own caller) -- the same mechanism a
      # `break` inside a block given to any ordinary C-implemented
      # `#each`-style method already depends on working correctly.
      #
      # Deliberately NOT modeled: a CFUNC-backed Proc (e.g. from `&:sym`/
      # `&method(...)` forwarding) reaching this opcode -- real vm.c calls
      # such a proc's cfunc with `self` = the proc object itself (`recv`,
      # not yet reassigned at that point in vm.c's own code -- ordinary
      # "receiver is the thing #call was invoked on" semantics), whereas
      # `mrb_yield_argv`'s own `mrb_proc_get_self` returns `mrb_nil_value()`
      # for a CFUNC-backed proc instead -- a real, different self. Hand-
      # reproducing vm.c's own cfunc branch instead (calling `MRB_PROC_
      # CFUNC(p)` directly) was considered and rejected: real vm.c's cfunc
      # only receives its actual arguments because the surrounding `cipush`
      # sets up a real callinfo/stack frame first, which `mrb_get_args`
      # inside the cfunc then reads -- calling the raw function pointer
      # directly here, with no such frame, would leave any such cfunc
      # reading stale/wrong argument state, an actual correctness hazard
      # worse than the self-value mismatch it would dodge. No real
      # occurrence in this whole codebase's own compiled output is a
      # CFUNC-backed proc (all four real call sites use a literal block),
      # and no mruby-core CFUNC-backed proc (Symbol#to_proc and friends)
      # observably branches on its own `self` parameter -- so this
      # narrower `mrb_yield_argv`-only translation is sound for every real
      # occurrence, with the CFUNC-self divergence being real but inert in
      # practice rather than provably unreachable -- documented here rather
      # than silently assumed away.
      d = a[/^R(\d+)/, 1].to_i
      blkn = a[/^R\d+\s+(\d+)/, 1].to_i
      out = String.new
      out << "  if (!mrb_proc_p(r#{d})) {\n"
      out << "    mrb_raise(M, mrb_exc_get_id(M, mrb_intern_lit(M, \"TypeError\")), \"bc2cpp: BLKCALL (yield) expected a Proc\");\n"
      out << "  }\n"
      if blkn.zero?
        out << "  r#{d} = mrb_yield_argv(M, r#{d}, 0, NULL);\n"
      else
        out << "  {\n"
        out << "    mrb_value blkcall_args[] = { #{(1..blkn).map { |i| "r#{d + i}" }.join(', ')} };\n"
        out << "    r#{d} = mrb_yield_argv(M, r#{d}, #{blkn}, blkcall_args);\n"
        out << "  }\n"
      end
      out
    when 'RETURN'
      r = a.empty? ? '0' : a[/^R(\d+)/, 1]
      "  return r#{r};\n"
    when 'RETNIL'
      "  return mrb_nil_value();\n"
    when 'RETFALSE'
      "  return mrb_false_value();\n"
    when 'RETTRUE'
      "  return mrb_true_value();\n"
    when 'RETSELF'
      # "RETSELF" (Z, no operand) -- ops.h's own terse comment: `/* return
      # self */`. Real OP_RETSELF (src/vm.c) is `a = 0; goto NORMAL_RETURN;`
      # -- the exact same bare-value return path OP_RETURN itself takes,
      # just with the return register hardwired to 0 (self always lives in
      # r0, real mruby calling convention -- the same fact RETURN's own
      # `a.empty? ? '0' : ...` above already leans on). mrbc's own codegen
      # (mrbgems/mruby-compiler/core/codegen.c, gen_return) only ever
      # produces this opcode as a peephole fusion of a LOADSELF immediately
      # followed by a RETURN reading that same register (`data.insn ==
      # OP_LOADSELF && src == data.a && op == OP_RETURN`) -- i.e. a plain
      # `self`/implicit-self return, never anything else. Every leaf irep
      # this compiler ever emits a function body for is a real `def`-
      # compiled method (see RETURN_BLK's own comment below for why: never
      # a block/proc irep), so `self` here is exactly this generated
      # function's own real `self` parameter -- translating straight to it
      # is exactly as mechanical and safe as RETURN/RETNIL/RETFALSE/
      # RETTRUE just above.
      "  return self;\n"
    when 'JMP'
      # .to_i (not the raw text) on purpose: the disassembly zero-pads
      # addresses ("018"), but jump_targets/compile_method label instructions
      # by their *integer* insn.addr ("L18:") -- interpolating the raw
      # zero-padded string here produced a `goto L018;` with no matching
      # label (`L18:` was what actually got emitted), a real
      # compile-time "label not found" bug caught by building this.
      target = ensure_remapped_jump_target(irep, a.strip[/\d+/].to_i)
      "  goto L#{target};\n"
    when 'JMPUW'
      # JMPUW_SUPPORT: a `break`/`next`/`redo`/`retry` jump. Identical to
      # JMP above (same `S` operand, same zero-padding, so the same `.to_i`
      # is just as load-bearing here) whenever this irep has no catch
      # handler table -- see jmpuw_is_plain_jump? for the full vm.c
      # derivation and for the real `ensure`-inside-a-loop shape that is
      # NOT expressible as a `goto` and keeps its honest `#error`.
      if jmpuw_is_plain_jump?(irep)
        "  goto L#{a.strip[/\d+/].to_i};\n"
      else
        "  #error unhandled opcode JMPUW -- not in this prototype's supported subset\n"
      end
    when 'JMPNOT'
      reg = a[/^R(\d+)/, 1]
      target = ensure_remapped_jump_target(irep, jmp_target_after_reg(a))
      "  if (!mrb_test(r#{reg})) goto L#{target};\n"
    when 'JMPIF'
      reg = a[/^R(\d+)/, 1]
      target = ensure_remapped_jump_target(irep, jmp_target_after_reg(a))
      "  if (mrb_test(r#{reg})) goto L#{target};\n"
    when 'JMPNIL'
      # "JMPNIL R3 024" -- OP_JMPNIL's own real shape (src/vm.c): jump if
      # r<d> is exactly nil (not merely falsy -- mrb_test/JMPNOT/JMPIF
      # already cover the falsy case; this is the dedicated opcode mrbc
      # emits for `x.nil? ? a : b` / `x || y`-shaped nil-specific tests,
      # e.g. `@opacity.nil? ? 255 : @opacity`).
      reg = a[/^R(\d+)/, 1]
      target = ensure_remapped_jump_target(irep, jmp_target_after_reg(a))
      "  if (mrb_nil_p(r#{reg})) goto L#{target};\n"
    when 'GETCONST'
      # "GETCONST R4 Integer" -- a bare top-level/lexical constant lookup.
      # The real VM (OP_GETCONST, vm.c) resolves this against the *current
      # lexical scope chain* (mrb_vm_const_get, which walks the call info
      # stack's target classes) -- info this AOT-compiled function doesn't
      # have at codegen time.
      #
      # Real bug, caught running against real code (Game::EnemyAction/
      # RGSS::Sprite): the original single-scope-from-Object codegen
      # compiled clean but raised a real runtime NameError for a same-
      # class constant (`KIND_SKILL` inside `Game::EnemyAction#skill?`,
      # really `Game::EnemyAction::KIND_SKILL`) and an enclosing-module
      # one (`Tone`/`Color`/`Rect` inside `RGSS::Sprite#tone`/`#color`/
      # `#src_rect`, really `RGSS::Tone`/`RGSS::Color`/`RGSS::Rect`) --
      # confirmed empirically against a real built mruby: mrb_const_get's
      # own const_get_nohook (src/variable.c) stops walking the ancestor
      # chain *before* ever checking Object's own table unless the search
      # started AT Object, so a class-body or enclosing-module constant is
      # invisible to a bare from-Object lookup no matter how "top-level-
      # looking" the #error-free compile made it look. Fix: try every
      # scope in the owner's own real lexical nesting chain, innermost
      # first (owner "RGSS::Sprite" -> [RGSS::Sprite, RGSS]), before
      # falling back to Object -- mirroring real Ruby's own Module.nesting
      # -based resolution for the plain "def is textually nested exactly
      # where its owner name says" shape every real case here has (no
      # `class Foo << self` reopening tricks). A bare `mrb_const_get`
      # can't just be tried-then-polled with mrb_check_error to walk this
      # chain -- a failing lookup raises via a real setjmp/longjmp,
      # jumping straight past any code that would poll mrb->exc
      # afterward (confirmed by instrumenting a debug build: a printf
      # placed right after the failing call never ran).
      # `mrb_protect_error` (mruby/error.h, a real always-available core
      # API, not gated behind the mruby-error gem) is what actually lets
      # this poll: emit_const_lookup_helper's own bc2cpp_const_try wraps
      # one scope attempt and reports success via an out-param instead of
      # choosing the fallback itself, so this call site can walk the
      # whole chain. The very last attempt, against Object, stays
      # unprotected -- a constant this chain still can't find is a real
      # bug in the SOURCE, not something to paper over (this compiler's
      # own "never silently wrong, loud is fine" philosophy).
      #
      # A top-level `def` (owner "Object") needs none of this -- the
      # original single lookup already searches exactly the right scope.
      #
      # Name extraction: `\S+` (stops at the first whitespace/tab), not a
      # `split(/\s+/, 2)` that swallows the rest of the line -- a real
      # bug, caught running against real code: a trailing "; R3:name"
      # local-variable-name comment (real shape whenever the destination
      # register is a named local, e.g. "GETCONST R3 MAX_DIGITS\t;
      # R3:d") would otherwise get interned as part of the constant name,
      # a garbage symbol lookup raising a real NameError at runtime,
      # never caught by any #error check (this compiles and links fine).
      d = a[/^R(\d+)/, 1]
      name = a[/^R\d+\s+(\S+)/, 1]
      # INTEGER_CONSTANT_VALUE_PROOF: a name IntegerConstants.analyze_values
      # proved always binds this exact number needs no lookup at all -- not
      # even a cached one, since the value never changes for the life of the
      # program, only what register holds it. Checked first: a name can
      # never be admitted here AND by StableClassConstants below (this proof
      # poisons on CLASS/MODULE, that one requires it), so the two never
      # compete for the same name.
      if (value = self.class.integer_constant_values&.[](name))
        return "  r#{d} = mrb_fixnum_value(#{value});\n"
      end

      owner_path = lexical_scope_path(owner_def.owner)
      if self.class.stable_class_constants&.include?(name)
        # CONST_SITE_CACHE: see tools/bc2cpp/const_site_cache.rb. One helper per
        # (lexical scope, name); it runs the ordinary lookup until it finds a
        # class/module, then returns the stored value.
        @const_site_cache ||= {}
        key = [owner_path, name]
        unless @const_site_cache.key?(key)
          @const_site_cache[key] = { index: @const_site_cache.size, body: const_lookup_block('0', name, owner_path) }
        end
        return "  r#{d} = bc2cpp_cconst_#{@const_site_cache[key][:index]}(M);\n"
      end

      const_lookup_block(d, name, owner_path)
    when 'OCLASS'
      # OCLASS_SUPPORT: "OCLASS R3" -- real `::Foo` root-scope constant
      # syntax (`::File.open(...)`, `LCF::File#save_to`'s own real body)
      # compiles to this instruction immediately followed by a `GETMCNST`
      # reading the named constant off of whatever OCLASS pushed -- real
      # `OP_OCLASS` semantics (3rd/mruby/src/vm.c, confirmed directly, not
      # inferred from the mnemonic): `regs[a] = mrb_obj_value(mrb->
      # object_class)`, the exact same "the root/Object scope, as a real
      # mrb_value" GETCONST's own top-level-owner branch already
      # constructs by hand a few lines up -- GETMCNST (already supported,
      # unconditionally) needs no special-casing at all once this register
      # holds the right starting scope.
      d = a[/^R(\d+)/, 1]
      "  r#{d} = mrb_obj_value(M->object_class);\n"
    when 'GETMCNST'
      # "GETMCNST R6 (R6)::Sections" -- module-qualified lookup: r<d> already
      # holds the owning module/class (from a prior GETCONST/GETMCNST in the
      # same chain, e.g. LCF::Schema::DATABASE compiles to
      # GETCONST R2 LCF; GETMCNST R2 (R2)::Schema; GETMCNST R2 (R2)::DATABASE),
      # read the named constant off of it, and overwrite the same register.
      d = a[/^R(\d+)/, 1]
      name = a[/::(\w+)\s*$/, 1]
      # INTEGER_CONSTANT_VALUE_PROOF: same substitution as GETCONST's own
      # case above -- see that comment. R<d> already holds the resolved
      # owning scope from the immediately preceding GETCONST/GETMCNST; its
      # own instruction still runs and still raises if that scope does not
      # exist, this just skips USING the value once it is at hand, so the
      # dominant real hot GETMCNST shape (`Cmd::SHOW_MESSAGE`-style event
      # command dispatch: hundreds of these per frame, one per `case
      # cmd.code when Cmd::X` arm scanned) costs nothing at all rather than
      # one mrb_const_get / iv_get search apiece.
      if (value = self.class.integer_constant_values&.[](name))
        return "  r#{d} = mrb_fixnum_value(#{value});\n"
      end

      "  r#{d} = mrb_const_get(M, r#{d}, mrb_intern_cstr(M, \"#{name}\"));\n"
    when 'HASH'
      # "HASH R2 22" -- build a Hash from N key/value pairs held in 2N
      # consecutive registers starting at Rd (Rd,Rd+1)=(k0,v0),
      # (Rd+2,Rd+3)=(k1,v1), ...; the result overwrites Rd itself (real
      # OP_HASH semantics, src/vm.c). Every pair register still holds its
      # original value at this point (nothing here writes r<d> until the
      # very end), so reading them all before the final assignment is safe.
      d = a[/^R(\d+)/, 1].to_i
      n = a[/^R\d+\s+(\d+)/, 1].to_i
      out = String.new
      out << "  {\n"
      out << "    mrb_value h = mrb_hash_new_capa(M, #{n});\n"
      n.times { |i| out << "    mrb_hash_set(M, h, r#{d + 2 * i}, r#{d + 2 * i + 1});\n" }
      out << "    r#{d} = h;\n"
      out << "  }\n"
      out
    when 'ARRAY'
      # "ARRAY R3 2" -- build an Array from N consecutive registers starting
      # at Rd (Rd, Rd+1, ..., Rd+N-1), the result overwriting Rd itself
      # (real OP_ARRAY semantics, src/vm.c: `ary_new_from_regs(mrb, b, a)`
      # is `mrb_ary_new_from_values(mrb, b, &regs[a])`). Every source
      # register still holds its original value at this point (nothing
      # here writes r<d> until the final assignment), so copying them all
      # into a temporary contiguous C array before it is safe -- the same
      # "read everything before the final overwrite" reasoning HASH's own
      # codegen above already relies on. `r<d>..r<d+N-1>` are separate C++
      # locals here (this codegen's registers are never actually
      # contiguous in memory the way the real VM's register file is), so
      # they have to be copied into a real array rather than pointed at
      # directly the way the interpreter's own `&regs[idx]` does.
      #
      # Only the plain literal-array shape mrbc's own codegen.c emits for
      # `[e0, e1, ..., eN-1]` with no splat is modeled (confirmed against
      # codegen_array's own `else` branch, the no-splat path: `pop_n(n);
      # genop_2(s, OP_ARRAY, cursp(), n)`); mrbc emits an *unrelated*
      # 3-operand ARRAY2 (`R[a] = ary_new(R[b]..R[b+c])`, a peephole variant
      # for `local = [literal]`, MOVE-then-ARRAY collapsed into one op) and
      # separate ARYCAT/ARYPUSH/ARYSPLAT ops for a splat (`[*a, b]`) --
      # none of those are in this prototype's real scope, so this opcode's
      # own 2-operand disassembly shape (`ARRAY Rd N`) is the only one
      # handled; anything else (a 3-operand ARRAY2, or ARYCAT/ARYPUSH/
      # ARYSPLAT themselves) falls through to the generic #error below,
      # exactly LOADL's own established narrow-scope precedent for an
      # out-of-model opcode variant.
      #
      # ARRAY2_OPERAND_FORM: the pinned mruby's OP_ARRAY2 (a, b, c) is
      # disassembled under the SAME `ARRAY` mnemonic with a source register:
      # `ARRAY Rd Rs N` (src/codedump.c: "ARRAY\tR%d\tR%d\t%d") builds
      # Rd = [Rs .. Rs+N-1]. mrbc emits it for `local = [literal]`, so this is
      # every such assignment. The 2-operand regex below does not match `Rs`,
      # which used to turn n into 0 and silently compile the literal to an
      # empty Array (quarters = [[nil, nil], [nil, nil]] became `[]`, and the
      # desktop RPGMAKER_BC2CPP build then failed with `undefined method
      # '[]=' for NilClass` starting a new game). Handle it explicitly.
      d = a[/^R(\d+)/, 1].to_i
      three = a.match(/^R\d+\s+R(\d+)\s+(\d+)/)
      src = three ? three[1].to_i : d
      n = three ? three[2].to_i : a[/^R\d+\s+(\d+)/, 1].to_i
      if n.zero?
        "  r#{d} = mrb_ary_new(M);\n"
      else
        out = String.new
        out << "  {\n"
        out << "    mrb_value elems[] = { #{(0...n).map { |i| "r#{src + i}" }.join(', ')} };\n"
        out << "    r#{d} = mrb_ary_new_from_values(M, #{n}, elems);\n"
        out << "  }\n"
        out
      end
    when 'ARYPUSH'
      # "ARYPUSH R3 2" -- same 2-operand "Rd N" disassembly shape as ARRAY
      # just above (src/codedump.c: `"ARYPUSH\tR%d\t%d"`, a, b), but the
      # semantics differ: push N consecutive registers (Ra+1..Ra+N) onto
      # the array ALREADY held in Ra, rather than building a fresh one
      # (real OP_ARYPUSH, src/vm.c: `mrb_ensure_array_type(mrb, regs[a]);
      # for (i=0;i<b;i++) mrb_ary_push(mrb, regs[a], regs[a+i+1]);` -- a
      # pure in-place mutation, no write to regs[a] itself).
      #
      # R[a] is PROVABLY already a real Array at every real occurrence,
      # never merely assumed: mrbc's own codegen (mrbgems/mruby-compiler/
      # core/codegen.c) emits OP_ARYPUSH from exactly two functions --
      # gen_values (call-argument splat flushing, `foo(*a, b)`-shaped) and
      # codegen_array (array-literal splat flushing, `[*a, b]`-shaped) --
      # and every one of the 7 real call sites in both is gated behind a
      # `first`/`!first`-style flag that only ever clears once a
      # `genop_2(s, OP_ARRAY, ...)` has already written that exact same
      # register (either directly above it in the same function, or -- the
      # one indirect case, codegen_call_assign's own >13-argument overflow
      # packing -- forces its own OP_ARRAY first before ever reaching
      # ARYPUSH). So the real VM's own `mrb_ensure_array_type` guard is
      # unconditionally a no-op here -- translating straight to N
      # unconditional `mrb_ary_push` calls (mruby/array.h, MRB_API,
      # already #include'd; call pattern matches this file's own existing
      # `mrb_ary_push(M, ary, elem)` usage, e.g. emit_sort_inline) is
      # exactly as safe as ARRAY's own codegen above, just mutating an
      # existing array instead of allocating a new one.
      d = a[/^R(\d+)/, 1].to_i
      n = a[/^R\d+\s+(\d+)/, 1].to_i
      out = String.new
      n.times { |i| out << "  mrb_ary_push(M, r#{d}, r#{d + i + 1});\n" }
      out
    when 'ARYCAT'
      # "ARYCAT R3 (R4)" -- the same "Rd (Rs)" disassembly shape as MUL/
      # DIV/EQ/LT/LE/GT/GE above (src/codedump.c: `"ARYCAT\tR%d\t(R%d)"`,
      # a, a+1), extracted the same way (anchored `^R` for the
      # destination, parenthesized `(R\d+)` for the source -- a trailing
      # print_lv_a local-variable annotation is unparenthesized, so it can
      # never collide with the source capture).
      #
      # Real OP_ARYCAT semantics (src/vm.c) are NOT the bare concatenation
      # the terse ops.h comment (`/* ary_cat(R[a],R[a+1]) */`) alone
      # suggests:
      #   mrb_value splat = mrb_ary_splat(mrb, regs[a+1]);
      #   if (mrb_nil_p(regs[a])) regs[a] = splat;
      #   else { mrb_ensure_array_type(mrb, regs[a]); mrb_ary_concat(mrb, regs[a], splat); }
      # R[a+1] is SPLATTED first (mrb_ary_splat, src/array.c: an Array is
      # duplicated as-is; anything else is converted via a real #to_a call
      # if it responds to one, otherwise wrapped as a single-element
      # array) -- and R[a] has a nil-becomes-the-splat special case ahead
      # of the real concat.
      #
      # ARYCAT_NIL_START_SUPPORT: an earlier version of this comment
      # claimed R[a] is PROVABLY never nil here, reasoning from
      # codegen_array/gen_values always emitting a `genop_2(s, OP_ARRAY,
      # ...)` immediately before ARYCAT -- wrong, caught by a real `mrbc
      # -v` run rather than trusting the prior (incomplete) static
      # reading: `bar(*list, *list2)` (the call's own FIRST argument is
      # itself a splat, no leading non-splat element for an `OP_ARRAY` to
      # build) compiles to `LOADNIL R5` then `ARYCAT R5 (R6)` -- R[a]
      # genuinely starts nil at the very first ARYCAT in that shape, real
      # OP_ARYCAT's own nil-becomes-the-splat branch is real, live code
      # here, not dead. (`bar(a, *list)`, a LEADING non-splat argument, is
      # the case the prior comment actually confirmed: `ARRAY R5 1` does
      # run first there -- both shapes coexist, gated by whether the
      # call's own first argument is a splat or not.) `mrb_ensure_array_
      # type` on the non-nil branch is still unconditionally a no-op
      # (every real ARYCAT chain's own non-nil R[a] only ever got there
      # via a prior ARRAY or ARYCAT, both of which always leave a real
      # Array), so this only restores the nil branch, not the whole
      # guard.
      #
      # R[a+1] (the splat source) has no such guarantee either way --
      # it's whatever expression follows the `*` (a local, a method call,
      # another literal array, ...) -- so `mrb_ary_splat` (mruby/array.h,
      # MRB_API, already #include'd) is still called for real here,
      # mirroring the real VM's own two-step "splat, then either assign
      # or concat" exactly.
      d = a[/^R(\d+)/, 1]
      s = a[/\(R(\d+)\)/, 1]
      <<~CPP
        {
          mrb_value bc2cpp_arycat_splat = mrb_ary_splat(M, r#{s});
          if (mrb_nil_p(r#{d})) {
            r#{d} = bc2cpp_arycat_splat;
          } else {
            mrb_ary_concat(M, r#{d}, bc2cpp_arycat_splat);
          }
        }
      CPP
    when 'AREF'
      # "AREF R2 R6 0 ; R2:x" -- R[a] = R[b][c], c a plain immediate index,
      # never a register (real OP_AREF semantics, src/vm.c): when R[b]
      # isn't an Array, index 0 yields R[b] itself (a bare non-Array value
      # is treated as a one-element pseudo-array) and any other index
      # yields nil; when it is an Array, mrb_ary_ref does the real bounds-
      # checked lookup. This is exactly the destructuring assignment shape
      # `x, y, w, h = some_call(...)` compiles to -- one AREF per
      # destructured local, all reading the same call-result register.
      d, s = regs(a, 2)
      c = a[/^R\d+\s+R\d+\s+(\d+)/, 1]
      "  r#{d} = mrb_array_p(r#{s}) ? bc2cpp_ary_entry(M, r#{s}, #{c}) : (#{c} == 0 ? r#{s} : mrb_nil_value());\n"
    when 'GETIDX'
      # "GETIDX R2 (R3)" -- R[a] = R[a][R[a+1]] (real OP_GETIDX semantics,
      # src/vm.c): unlike AREF above, the index here is itself a *register*
      # (a computed/variable value), not a compile-time immediate -- the
      # real shape `recv[idx]` compiles to whenever `idx` isn't a literal
      # mrbc's own peephole can fold into AREF (e.g. `@equipment[WEAPON_SLOT]`,
      # a class constant resolved at runtime via GETCONST first, so its
      # value only exists in a register by the time this opcode runs).
      # Mirrors vm.c's own fast paths: Array with an Integer index
      # (mrb_ary_ref -- bounds-checked, negative-index-normalizing, same
      # public API AREF's own codegen above already uses), Hash
      # (mrb_hash_get, the same public API HASH's own codegen above already
      # uses), and String with an Integer/String/Range index (mrb_str_aref
      # -- see below); anything else (Range#[], or a class overriding #[])
      # falls back to the real method the interpreter itself would call --
      # never unsound, just without the in-VM fast path. Array/Hash/String
      # fast paths additionally require the exact base class, matching
      # vm.c's guard and preserving subclass or singleton `[]` overrides.
      # `r<d>` (the
      # receiver) is read by every branch before any of them writes it, the
      # same "read before overwrite" safety AREF/HASH/ARRAY's own codegen
      # already relies on.
      #
      # GETIDX_STRING_AREF: the real vm.c's own OP_GETIDX handler
      # (3rd/mruby/src/vm.c) has a third arm this codegen used to skip
      # entirely -- String with an Integer/String/Range index (character
      # index, substring search, or a Range slice respectively) calls
      # `mrb_str_aref(mrb, str, idx, mrb_undef_value())` (the real "no
      # length argument" sentinel -- the exact form `str[idx]` compiles to,
      # as opposed to `str[idx, len]`'s own explicit third argument, a
      # different real call shape codegen.c's own OP_GETIDX emission never
      # produces at all -- confirmed directly against mrbgems/mruby-
      # compiler/core/codegen.c, GETIDX is only ever emitted for the
      # exactly-one-argument `[]` shape). `mrb_str_aref` is a real,
      # externally-linked function (see this file's own top-of-output
      # `extern "C"` forward declaration and its own comment for why a
      # plain #include of the header that declares it doesn't work).
      # Reproduces the real VM's own index-type gate exactly (`case
      # MRB_TT_INTEGER: case MRB_TT_STRING: case MRB_TT_RANGE:` -- anything
      # else, e.g. a Regexp, falls through to `default: break` there too,
      # same as this codegen's own `mrb_funcall` fallback). The emitted
      # exact-class checks below match vm.c's additional guards for Array,
      # Hash, and String, so subclasses and singleton overrides use Ruby
      # dispatch.
      #
      # GETIDX_STATIC_RECEIVER_SUPPORT: when `static_indexable_class`
      # proves the receiver Array or Hash ahead of time (the exact same
      # whole-program facts `.each`/`.map`/... inlining already trusts,
      # just asked at this new call site), skip straight to a single
      # cheap guarded fast path instead of the full four-way runtime gate
      # below. A wrong annotation or stale hint still falls back to the
      # original Ruby `[]` dispatch; subclasses use Ruby dispatch to preserve
      # overridden `[]`/`[]=` methods. A proven Hash needs no index-type
      # branch at all
      # (`mrb_hash_get` already accepts any key type); a proven Array
      # still needs the `mrb_integer_p` check (a Range/other index still
      # has to fall through to the real `[]=` -- `bc2cpp_ary_entry` only
      # ever handles a fixnum index).
      d, s = regs(a, 2)
      index_class = static_indexable_class(irep, idx, unshift_proof_reg(d, reg_offset), owner_def)
      case index_class
      when 'Array'
        <<~CPP
          if (mrb_array_p(r#{d}) && mrb_obj_ptr(r#{d})->c == M->array_class && mrb_integer_p(r#{s})) {
            r#{d} = bc2cpp_ary_entry(M, r#{d}, mrb_integer(r#{s}));
          } else {
            r#{d} = mrb_funcall(M, r#{d}, "[]", 1, r#{s});
          }
        CPP
      when 'Hash'
        <<~CPP
          if (mrb_hash_p(r#{d}) && mrb_obj_ptr(r#{d})->c == M->hash_class) {
            r#{d} = mrb_hash_get(M, r#{d}, r#{s});
          } else {
            r#{d} = mrb_funcall(M, r#{d}, "[]", 1, r#{s});
          }
        CPP
      else
        # INDEX_CHAIN: the tail of an untyped `x[i]` was a bare funcall, so a
        # receiver whose class is one of the program's own `#[]` definitions
        # (Game::Variables, LCF::Array1D, ...) paid full dynamic dispatch. Send it
        # through the same exact-class chain any other one-argument send gets;
        # nil (no compiled candidate, or a blocked name) keeps the funcall.
        tail = compile_poly_small_n('[]', d.to_i, "r#{d}", ["r#{s}"], 1)
        tail = tail ? tail.gsub(/^/, '  ').lstrip : "r#{d} = mrb_funcall(M, r#{d}, \"[]\", 1, r#{s});"
        # STRUCT_INDEX_CACHE -- see that method's own comment. A miss (no
        # literal Symbol key, or no known Struct owner declares that member)
        # is simply an empty string, leaving this whole `else if` chain out.
        struct_read = compile_struct_literal_index_read(irep, idx, s, d)
        fallback = <<~CPP
          if (mrb_array_p(r#{d}) && mrb_obj_ptr(r#{d})->c == M->array_class && mrb_integer_p(r#{s})) {
            r#{d} = bc2cpp_ary_entry(M, r#{d}, mrb_integer(r#{s}));
          } else if (mrb_hash_p(r#{d}) && mrb_obj_ptr(r#{d})->c == M->hash_class) {
            r#{d} = mrb_hash_get(M, r#{d}, r#{s});
          } else if (mrb_string_p(r#{d}) && mrb_obj_ptr(r#{d})->c == M->string_class &&
                     (mrb_integer_p(r#{s}) || mrb_string_p(r#{s}) || mrb_range_p(r#{s}))) {
            r#{d} = mrb_str_aref(M, r#{d}, r#{s}, mrb_undef_value());
          } #{struct_read}else {
            #{tail}
          }
        CPP
        typed = compile_typed_index_send(irep, idx, owner_def, d, d, "r#{s}", reg_offset, index_class, fallback)
        typed || fallback
      end
    when 'GETIDX0'
      # "GETIDX0 R7 R4[0]" -- R[a] = R[b][0] (real OP_GETIDX0 semantics,
      # src/vm.c): mrbc's own peephole for the common literal `x[0]` index
      # shape (e.g. `ev[0]` off a computed local) -- distinct instruction
      # from GETIDX above, with its own separate dest/src register pair
      # (`BB` operand shape) rather than GETIDX's in-place a/a+1 pair, and
      # no index register at all since the index is always the literal 0.
      # Same exact-class Array/Hash fast paths as GETIDX (mrb_ary_ref -- same public,
      # bounds-checked API, an empty array correctly yielding nil; a Hash
      # via mrb_hash_get with a literal Fixnum(0) key), falling back to a
      # real `[]` send with a literal 0 argument for anything else --
      # mirrors vm.c's own `getidx0_fallback` label exactly (regs[a]=recv,
      # regs[a+1]=Fixnum(0), then real :[] dispatch through the ordinary
      # SEND path).
      #
      # GETIDX_STATIC_RECEIVER_SUPPORT: same static-receiver fast path as
      # GETIDX above, applied to `s` (the receiver here, not `d` -- see
      # this opcode's own separate dest/src register pair).
      d, s = regs(a, 2)
      index_class = static_indexable_class(irep, idx, unshift_proof_reg(s, reg_offset), owner_def)
      case index_class
      when 'Array'
        <<~CPP
          if (mrb_array_p(r#{s}) && mrb_obj_ptr(r#{s})->c == M->array_class) {
            r#{d} = bc2cpp_ary_entry(M, r#{s}, 0);
          } else {
            r#{d} = mrb_funcall(M, r#{s}, "[]", 1, mrb_fixnum_value(0));
          }
        CPP
      when 'Hash'
        <<~CPP
          if (mrb_hash_p(r#{s}) && mrb_obj_ptr(r#{s})->c == M->hash_class) {
            r#{d} = mrb_hash_get(M, r#{s}, mrb_fixnum_value(0));
          } else {
            r#{d} = mrb_funcall(M, r#{s}, "[]", 1, mrb_fixnum_value(0));
          }
        CPP
      else
        fallback = <<~CPP
          if (mrb_array_p(r#{s}) && mrb_obj_ptr(r#{s})->c == M->array_class) {
            r#{d} = bc2cpp_ary_entry(M, r#{s}, 0);
          } else if (mrb_hash_p(r#{s}) && mrb_obj_ptr(r#{s})->c == M->hash_class) {
            r#{d} = mrb_hash_get(M, r#{s}, mrb_fixnum_value(0));
          } else {
            r#{d} = mrb_funcall(M, r#{s}, "[]", 1, mrb_fixnum_value(0));
          }
        CPP
        typed = compile_typed_index_send(irep, idx, owner_def, d, s, 'mrb_fixnum_value(0)', reg_offset,
                                         index_class, fallback)
        typed || fallback
      end
    when 'SETIDX'
      # "SETIDX R4 (R5) (R6)" -- R[a][R[a+1]] = R[a+2], then R[a] = R[a+2]
      # too (real OP_SETIDX semantics, src/vm.c: the fast Array/Hash paths
      # explicitly overwrite regs[a] with the assigned value afterward --
      # `arr[i] = v` is always `v` as a Ruby expression, regardless of what
      # the underlying method itself returns). Same Array/Hash fast paths as
      # GETIDX above (mrb_ary_set/mrb_hash_set, the same public APIs ARRAY/
      # HASH's own codegen already uses), falling back to a real `[]=` send
      # for anything else, including container subclasses -- there the assigned-back value is whatever that
      # real method returns, matching the interpreter's own SENDB-based
      # fallback exactly (no explicit regs[a]=vc override on that path
      # either, confirmed reading vm.c's own setidx_fallback).
      #
      # GETIDX_STATIC_RECEIVER_SUPPORT: same static-receiver fast path as
      # GETIDX above. Destructured as `idx_reg` (not `idx`) here
      # specifically -- this `when` branch is the one case in this whole
      # switch that would otherwise shadow `compile_insn`'s own `idx`
      # parameter (this instruction's own position, exactly what
      # `static_indexable_class` needs to start its backward scan from)
      # with the index REGISTER instead, silently breaking the trace for
      # every SETIDX site the moment it ran.
      d, idx_reg, val = regs(a, 3)
      index_class = static_indexable_class(irep, idx, unshift_proof_reg(d, reg_offset), owner_def)
      case index_class
      when 'Array'
        <<~CPP
          if (mrb_array_p(r#{d}) && mrb_obj_ptr(r#{d})->c == M->array_class && mrb_integer_p(r#{idx_reg})) {
            mrb_ary_set(M, r#{d}, mrb_integer(r#{idx_reg}), r#{val});
            r#{d} = r#{val};
          } else {
            r#{d} = mrb_funcall(M, r#{d}, "[]=", 2, r#{idx_reg}, r#{val});
          }
        CPP
      when 'Hash'
        <<~CPP
          if (mrb_hash_p(r#{d}) && mrb_obj_ptr(r#{d})->c == M->hash_class) {
            mrb_hash_set(M, r#{d}, r#{idx_reg}, r#{val});
            r#{d} = r#{val};
          } else {
            r#{d} = mrb_funcall(M, r#{d}, "[]=", 2, r#{idx_reg}, r#{val});
          }
        CPP
      else
        fallback = <<~CPP
          if (mrb_array_p(r#{d}) && mrb_obj_ptr(r#{d})->c == M->array_class && mrb_integer_p(r#{idx_reg})) {
            mrb_ary_set(M, r#{d}, mrb_integer(r#{idx_reg}), r#{val});
            r#{d} = r#{val};
          } else if (mrb_hash_p(r#{d}) && mrb_obj_ptr(r#{d})->c == M->hash_class) {
            mrb_hash_set(M, r#{d}, r#{idx_reg}, r#{val});
            r#{d} = r#{val};
          } else {
            r#{d} = mrb_funcall(M, r#{d}, "[]=", 2, r#{idx_reg}, r#{val});
          }
        CPP
        typed = compile_typed_index_write(irep, idx, owner_def, d, idx_reg, val, reg_offset, index_class, fallback)
        typed || fallback
      end
    when 'GETGV'
      # "GETGV R4 $stderr" -- R[a] = mrb_gv_get(M, sym) (real OP_GETGV
      # semantics, src/vm.c). A global variable's own symbol name already
      # spells the leading `$` (mrbc's own disassembly prints it that way,
      # matching how the real compiler interns it -- confirmed reading
      # vm.c's own mrb_gv_get(mrb, irep->syms[b]) call, no separate sigil
      # stripping/reattaching anywhere in that path), so this is exactly as
      # mechanical as GETCONST's own bare mrb_const_get call, just against
      # the flat global table instead of a lexical scope chain.
      d = a[/^R(\d+)/, 1]
      name = a[/(\$\S+)/, 1]
      "  r#{d} = mrb_gv_get(M, mrb_intern_cstr(M, \"#{name}\"));\n"
    when 'SETGV'
      # "SETGV $stderr R4" -- write-direction symmetric opcode to GETGV
      # just above, but codedump.c prints the two operands in REVERSED
      # order vs. GETGV's own "GETGV R4 $stderr" (confirmed directly:
      # OP_GETGV is `"GETGV\t\tR%d\t%s"` but OP_SETGV is `"SETGV\t\t%s\tR%d"`,
      # symbol first, register second) -- so unlike GETGV's own `^R`-
      # anchored capture, the register here can't be assumed to start the
      # string; both extractions below search unanchored instead (still
      # unambiguous: exactly one `$`-prefixed token and one `R<digits>`
      # token appear in this opcode's own disassembly text, same as
      # GETGV's own reasoning for why an unqualified regex is already
      # safe there). Real OP_SETGV semantics (src/vm.c): `mrb_gv_set(mrb,
      # irep->syms[b], regs[a])` -- same flat global table GETGV reads,
      # same already-`$`-spelled interned symbol name (no separate sigil
      # handling needed, GETGV's own comment already established this),
      # `mrb_gv_set` declared in mruby/variable.h (already #include'd).
      s = a[/R(\d+)/, 1]
      name = a[/(\$\S+)/, 1]
      "  mrb_gv_set(M, mrb_intern_cstr(M, \"#{name}\"), r#{s});\n"
    when 'STOP'
      ''
    when 'NOP'
      # "NOP" -- OP_NOP's own real semantics (src/vm.c): `/* do nothing */
      # NEXT;`, no operands, no register read or write at all. Real code
      # hits this from a `while` loop's own condition-check jump target
      # (confirmed against real disassembly, Game::Party#include_actor?/
      # #any_alive?/#actor_by_id: mrbc's own codegen places a bare NOP
      # right after the loop-entry JMPNOT, before the loop body proper --
      # a label placeholder with nothing to actually execute). Translating
      # to a real, empty C++ statement is exactly as safe as the real
      # opcode's own do-nothing behavior -- nothing to get wrong here.
      ''
    when 'ADDILV'
      # "ADDILV Rd Rb N ; Rd:name" -- OP_ADDILV's own real shape (src/vm.c,
      # OP_MATHILV(add) macro): `a=local, b=working space, c=immediate` per
      # that macro's own comment, but the macro body itself never reads or
      # writes regs[b] at all -- only regs[a] (in place: regs[a] += c on the
      # Integer fast path, falling to a real `mrb_funcall(mid=:+, ...)` for
      # anything else, mirroring ADDI's own established fixnum-fastpath-
      # else-mrb_funcall shape exactly). `b` is confirmed dead for codegen
      # purposes by reading that macro directly -- real code hits this from
      # a `while` loop's own `i += 1`-shaped increment (confirmed against
      # real disassembly: Game::Party#include_actor?/#any_alive?/
      # #actor_by_id/#insert_item_in_bag all have one, always immediately
      # before the loop's own back-edge JMP). The one real difference from
      # ADDI's own codegen -- a real Integer-overflow bignum promotion
      # (OP_MATH_OVERFLOW_INT) instead of falling through to mrb_funcall --
      # is the same simplification ADDI's own codegen already accepts (see
      # its own comment): not worth duplicating mruby's own bignum-overflow
      # path for this prototype's scope, and C's own wraparound on overflow
      # is no worse a divergence here than ADDI's plain C `+` already is.
      # Immediate extraction is its own real, third-operand regex (`^R\d+
      # \s+R\d+\s+(-?\d+)`), NOT ADDI's own established `a.split(/\s+/).last`
      # -- a real bug, caught building this: unlike ADDI's own destination
      # register (never observed carrying a trailing named-local comment in
      # this codebase's real disassembly), ADDILV's own `a` register is BY
      # DEFINITION a real named local (the whole point of the *LV opcode
      # variant), so its trailing "; Rd:name" comment (the same shape SETIV/
      # GETCONST's own already-documented not-`$`-anchored bugs guard
      # against) is the common case, not a rare one -- `.split.last` would
      # grab "Rd:name" itself as the literal here, a C++ syntax error caught
      # immediately trying to compile this round's own toy harness (`R4:i`
      # is not valid C++), never a silently-wrong translation.
      d = a[/^R(\d+)/, 1]
      lit = a[/^R\d+\s+R\d+\s+(-?\d+)/, 1]
      # FIXNUM_OPERAND_PROOF: same single-operand question ADDI asks -- rarely
      # provable in practice (the real shape here is a `while` loop's own
      # in-place increment, whose back-edge target sits between the initial
      # write and this use, so the dominance check declines), wired for
      # uniformity rather than for a measured win.
      if proven_fixnum_operand?(irep, idx, unshift_proof_reg(d, reg_offset), owner_def)
        "#{FIXNUM_PROOF_NOTE}  r#{d} = mrb_fixnum_value(mrb_fixnum(r#{d}) + #{lit});\n"
      else
        <<~CPP
          if (mrb_integer_p(r#{d})) {
            r#{d} = mrb_fixnum_value(mrb_fixnum(r#{d}) + #{lit});
          } else {
            #{compile_operator_fallback('+', d, nil, "mrb_fixnum_value(#{lit})", irep, idx, owner_def, reg_offset)}
          }
        CPP
      end
    when 'SUBILV'
      # OP_SUBILV -- ADDILV's own OP_MATHILV(sub) sibling, identical shape
      # (see ADDILV's own comment above for the real b-register-is-dead
      # confirmation and the accepted overflow simplification). Real code
      # hits this from a `while` loop's own countdown decrement (confirmed
      # against real disassembly, Game::Actor#set_exp's own `new_level -= 1
      # while ...` post-condition-loop shape). Same real trailing-comment
      # extraction fix as ADDILV above, same reason.
      d = a[/^R(\d+)/, 1]
      lit = a[/^R\d+\s+R\d+\s+(-?\d+)/, 1]
      if proven_fixnum_operand?(irep, idx, unshift_proof_reg(d, reg_offset), owner_def)
        "#{FIXNUM_PROOF_NOTE}  r#{d} = mrb_fixnum_value(mrb_fixnum(r#{d}) - #{lit});\n"
      else
        <<~CPP
          if (mrb_integer_p(r#{d})) {
            r#{d} = mrb_fixnum_value(mrb_fixnum(r#{d}) - #{lit});
          } else {
            #{compile_operator_fallback('-', d, nil, "mrb_fixnum_value(#{lit})", irep, idx, owner_def, reg_offset)}
          }
        CPP
      end
    when 'RANGE_INC'
      # "RANGE_INC Ra" -- R[a] = Range.new(R[a], R[a+1], exclude_end=false)
      # (real OP_RANGE_INC semantics, src/vm.c: `mrb_range_new(mrb, regs[a],
      # regs[a+1], FALSE)`, the result overwriting r<a> itself). A plain,
      # narrow, mechanical two-register-read-then-overwrite translation via
      # the real public mrb_range_new API (mruby/range.h) -- the same "read
      # both operands before the final overwrite" safety ARRAY/HASH/AREF/
      # GETIDX's own codegen above already relies on (nothing here writes
      # r<a> until the very last step). Real code hits this from an
      # inclusive Range literal (`a..b`), e.g. Game::Party#skill_invoking_item?
      # /#use_special_switch_item's own identical `(1..5).cover?(it.type)`
      # check (both real, independent call sites of the same shape --
      # `mruby-rpg2k/mrblib/game/battle_support.rb`/`game.rb`).
      d = a[/^R(\d+)/, 1].to_i
      "  r#{d} = mrb_range_new(M, r#{d}, r#{d + 1}, FALSE);\n"
    when 'RANGE_EXC'
      # OP_RANGE_EXC -- RANGE_INC's own exclude_end=TRUE sibling (real
      # OP_RANGE_EXC semantics, src/vm.c), the exact real shape a `a...b`
      # (exclusive) Range literal compiles to. Added alongside RANGE_INC
      # even though no Game::Party method itself needs it (both share the
      # identical real VM shape, differing only in the one literal exclude
      # flag -- the natural mirrored pair, matching this file's own
      # established RETFALSE/RETTRUE and LOADFALSE/LOADTRUE precedent for
      # never shipping just one half of a real opcode pair without reason).
      d = a[/^R(\d+)/, 1].to_i
      "  r#{d} = mrb_range_new(M, r#{d}, r#{d + 1}, TRUE);\n"
    when 'RETURN_BLK'
      # "RETURN_BLK Ra" -- looks block-specific by name, but its own real
      # VM semantics (src/vm.c, OP_RETURN_BLK) start with:
      # `if (!MRB_PROC_ENV_P(ci->proc) || MRB_PROC_STRICT_P(ci->proc)) goto
      # NORMAL_RETURN;` -- i.e. falls through to the exact same bare-value
      # return OP_RETURN itself uses, whenever the executing proc is
      # strict. This case is reached from THREE real contexts now:
      # (1) Every ordinary leaf irep this compiler translates at the top
      #     level *is* a real `def`-compiled method body (mrb_proc_new_irep
      #     tags it MRB_PROC_SCOPE|MRB_PROC_STRICT -- confirmed reading
      #     3rd/mruby/src/vm.c's own OP_METHOD/OP_L_METHOD lambda-creation
      #     path), never a block/proc irep (those are separate child ireps
      #     this whole-program TDEF-only registry never registers as a
      #     leaf method body in the first place -- see build_registry's
      #     own comment). Real code hits this from a `return` that isn't
      #     the method's own last statement (confirmed against real
      #     disassembly: Game::Party#include_actor?/#any_alive?/
      #     #actor_by_id's own early `return true`/`return a` inside a
      #     `while` loop body, mrbc's own codegen choice for a non-tail-
      #     position `return`, not a real block boundary). Always strict
      #     -- @block_fallback_active false here -- a plain `return`.
      # (2) LAMBDA_FALLBACK_SUPPORT's own emit_proc_fallback_fn, compiling
      #     a real LAMBDA's child irep (lambda_fallback_safe? is the only
      #     thing in this whole file that lets RETURN_BLK through for a
      #     LAMBDA body at all -- see its own comment for why a
      #     LAMBDA-constructed proc is unconditionally MRB_PROC_STRICT,
      #     confirmed against both `3rd/mruby/include/mruby/opcode.h`'s
      #     `OP_L_LAMBDA` flags and real `mrbc -v` disassembly of a real
      #     `->() { return ... }`). Always strict here too --
      #     @block_fallback_active false -- unchanged, a plain `return`.
      # (3) EXCEPTION_RETURN_SUPPORT: BLOCK_FALLBACK_SUPPORT's own
      #     emit_proc_fallback_fn compiling a real BLOCK's child irep
      #     (@block_fallback_active true -- block_fallback_safe? now lets
      #     RETURN_BLK through too, no longer unconditionally strict: a
      #     plain block's own real Ruby `return` exits the WHOLE
      #     ENCLOSING METHOD, not this cfunc, not even just the SENDB
      #     call site the way BREAK's own throw only needs to (see
      #     BLOCK_FALLBACK_UNSAFE_OPS's own comment). `throw
      #     bc2cpp_method_return{...}` unwinds all the way out, caught by
      #     compile_method's own new top-level `try`/`catch` (see
      #     `needs_return_catch`'s own comment there) -- never at
      #     emit_block_fallback_glue's own per-call-site BREAK catch,
      #     which must let this exception type pass straight through
      #     uncaught (a real `catch (bc2cpp_block_break&)` clause can
      #     never accidentally match a `bc2cpp_method_return&` -- C++
      #     catch-type matching is exact, no shared base type between
      #     the two).
      r = a.strip.empty? ? '0' : a[/^R(\d+)/, 1]
      if @block_fallback_active
        "  throw bc2cpp_method_return{r#{r}};\n"
      else
        "  return r#{r};\n"
      end
    when 'BREAK'
      # "BREAK Ra" -- OP_BREAK's own real VM semantics (src/vm.c,
      # `CASE(OP_BREAK)`) start with the identical `if
      # (MRB_PROC_STRICT_P(ci->proc)) goto NORMAL_RETURN;` check
      # RETURN_BLK's own case above already documents -- an ordinary,
      # same-frame return, exactly RETURN's own semantics, whenever the
      # executing proc is strict. This case is reached from TWO real
      # contexts now:
      # (1) LAMBDA_FALLBACK_SUPPORT's own emit_proc_fallback_fn compiling
      #     a real LAMBDA's child irep (@block_fallback_active false --
      #     lambda_fallback_safe? is the only thing that lets BREAK
      #     through for that context, and a LAMBDA-constructed proc IS
      #     unconditionally strict, RETURN_BLK's own case above cites the
      #     confirming evidence -- real Ruby's own well-known "a lambda's
      #     own break exits the lambda itself, exactly like return" rule
      #     is exactly this same STRICT check). Unchanged: a plain
      #     `return`.
      # (2) EXCEPTION_BREAK_SUPPORT: BLOCK_FALLBACK_SUPPORT's own
      #     emit_proc_fallback_fn compiling a real BLOCK's child irep
      #     (@block_fallback_active true -- block_fallback_safe? now lets
      #     BREAK through too, see BLOCK_FALLBACK_UNSAFE_OPS's own
      #     comment for the real non-strict-path semantics this
      #     reproduces and the C++-exceptions-enabled-project-wide fact
      #     that makes it safe). A plain `return` here would only exit
      #     THIS standalone cfunc, back to mruby's own VM dispatch inside
      #     `mrb_funcall_with_block` -- not far enough; real non-strict
      #     `OP_BREAK` unwinds all the way back to the SENDB/SSENDB call
      #     site itself. `throw` does exactly that, caught by
      #     emit_block_fallback_glue's own `catch (bc2cpp_block_break&)`
      #     wrapped around that same call.
      r = a.strip.empty? ? '0' : a[/^R(\d+)/, 1]
      if @block_fallback_active
        "  throw bc2cpp_block_break{r#{r}};\n"
      else
        "  return r#{r};\n"
      end
    when 'RESCUE'
      # "RESCUE Ra Rb" -- OP_RESCUE's own real body (3rd/mruby/src/vm.c)
      # is exactly `R[b] = R[a].isa?(R[b])`, unconditionally: Ra already
      # holds the raised exception object (RESCUE_SUPPORT's own glue code
      # -- see recognize_rescue_regions -- is the only thing that can ever
      # put a real exception there; nothing else in this whole file emits
      # an EXCEPT this opcode could otherwise be reacting to), Rb already
      # holds a Class/Module object (always the tail of a class-name chain
      # immediately before this -- a bare `GETCONST`, or a `GETCONST` root
      # followed by `GETMCNST` segments for a namespaced name like
      # `RGSS::Timeout`, per RESCUE_SUPPORT's own recognized shape) -- so this
      # translation is safe and correct wherever this opcode appears, not
      # gated on the recognizer at all (unlike EXCEPT, which the
      # recognizer's own glue is the only source of a real Ra value).
      ra, rb = a.split(/\s+/)
      d = ra[/^R(\d+)/, 1]
      s = rb[/^R(\d+)/, 1]
      "  r#{s} = mrb_bool_value(mrb_obj_is_kind_of(M, r#{d}, mrb_class_ptr(r#{s})));\n"
    when 'RAISEIF'
      # "RAISEIF Ra" -- OP_RAISEIF's own real body re-raises Ra unless
      # it's nil (a rescue clause that matched already cleared this via
      # this same opcode's own real semantics one level up -- RESCUE_
      # SUPPORT's own recognized shape only ever reaches this opcode on
      # the *non-matching* path, with Ra still holding the original
      # exception). The real opcode's own `mrb_break_p` branch (a
      # `break`/`next`/`redo` unwinding through a Ruby block) can never
      # apply to anything this whole file ever compiles -- every leaf
      # irep here is a real `def`-compiled method body, and this file has
      # no BLOCK/SENDB support at all (see this file's own top comment),
      # so Ra can never hold anything but nil or a real MRB_TT_EXCEPTION
      # object here.
      ra = a[/^R(\d+)/, 1]
      "  if (!mrb_nil_p(r#{ra})) { mrb_exc_raise(M, r#{ra}); }\n"
    when 'SUPER'
      # "SUPER Ra n=N" -- OP_SUPER's own real body (vm.c) looks up this
      # method's own name (`ci->mid`) starting one level above the
      # CURRENT class, using `self` as receiver and N explicit args
      # already sitting in R(a+1)..R(a+N) (mrbc's own codegen_super/
      # codegen_zsuper -- confirmed directly against real disassembly,
      # mruby-rpg2k/mrblib/scene/battle.rb's own `super parent` and
      # RPG2k3::Scene::Battle's own bare `super`), always followed by one
      # further register forwarding the CURRENT method's own block
      # parameter -- never read here: a compiled `_impl` function has no
      # block parameter of its own to forward in the first place (see
      # SUPER_TARGETS' own comment), and every real target this ever
      # fires for was independently checked to need none. `super_target`
       # itself is gated on the SUPER_TARGETS allowlist -- see its own
       # comment for the whole-program facts this depends on that this
       # opcode alone has no way to re-verify at codegen time.
       target_def = super_target(owner_def)
       dest, nstr = a.split(/\s+/, 2)
       d_reg = dest[/^R(\d+)/, 1]
       n = nstr && nstr[/^n=(\d+)$/, 1]
       zsuper_kind = reg_offset.zero? ? zsuper_native_kind(owner_def, irep, idx) : nil
       zsuper_plan = reg_offset.zero? && zsuper_kind.nil? ? zsuper_forward_plan(owner_def, irep, idx) : nil
       if target_def && d_reg && n
         args = (1..n.to_i).map { |i| "r#{d_reg.to_i + i}" }
         "  r#{d_reg} = #{cpp_name(target_def.owner, target_def.name)}_impl(M, self#{args.map { |x| ", #{x}" }.join});\n"
       elsif zsuper_kind && d_reg
         compile_zsuper_native(zsuper_kind, d_reg)
       elsif zsuper_plan && d_reg
         compile_zsuper_forward(zsuper_plan[:target_def], d_reg, zsuper_plan[:m])
       else
         "  #error unhandled opcode SUPER -- not in this prototype's supported subset\n"
       end
     when 'ARGARY'
      # ZSUPER_NATIVE_SUPPORT: the array this opcode builds is the argument
      # list for the `SUPER ... n=*` on the very next line, and nothing else
      # ever reads it (mrbc emits the pair together and the SUPER consumes
      # it immediately -- re-checked per site by zsuper_native_kind, which
      # matches the exact adjacency and the `SUPER R(a)` / `ARGARY R(a+1)`
      # register relationship rather than assuming it). Both recognized
      # translations below consume the ORIGINAL registers directly instead
      # of that array -- `mrb_false` ignores its arguments entirely, and
      # `mrb_obj_missing` would only have split the array straight back
      # apart -- so building it here would be dead code, and vm.c's own
      # OP_ARGARY body has no other observable effect to preserve (see
      # ZSUPER_NATIVE_TARGETS' own comment for the full read of that body,
      # including the one raise it can perform and why a real `def`-compiled
      # method body can never reach it).
      #
      # Deliberately NOT a general OP_ARGARY implementation: an ARGARY that
      # is not this exact recognized zsuper prelude still falls through to
      # the same honest `#error` it always produced.
      if reg_offset.zero? && zsuper_native_kind(owner_def, irep, idx)
        "  // #{insn.raw.strip} (zsuper argument array not built -- consumed by the SUPER below)\n"
      elsif reg_offset.zero? && zsuper_forward_plan(owner_def, irep, idx)
        # ZSUPER_GENERAL_SUPPORT: same dead-array suppression, for the general
        # zsuper-forward pair whose SUPER arm emits a direct superclass `_impl`
        # call from the ORIGINAL registers instead of reading this array.
        "  // #{insn.raw.strip} (zsuper argument array not built -- forwarded to the superclass _impl below)\n"
      else
        "  #error unhandled opcode ARGARY -- not in this prototype's supported subset\n"
      end
    else
      "  #error unhandled opcode #{insn.op} -- not in this prototype's supported subset\n"
    end
  end

  # ZSUPER_NATIVE_SUPPORT: the replacement body for a recognized `ARGARY` +
  # `SUPER ... n=*` pair, `d_reg` being the SUPER's own destination register.
  # See ZSUPER_NATIVE_TARGETS' own comment for where each of these two
  # translations comes from in real mruby source, and zsuper_native_kind for
  # the per-site checks that have already passed by the time this runs.
  def compile_zsuper_native(kind, d_reg)
    case kind
    when :kernel_respond_to_missing
      # Kernel#respond_to_missing? is 3rd/mruby/src/kernel.c's own
      # `mrb_false`, whose entire body is `return mrb_false_value();` --
      # unconditional, no `self`, no arguments, no `mrb_get_args`. The same
      # `mrb_false_value()` spelling LOADFALSE/RETFALSE already emit.
      "  // super -> Kernel#respond_to_missing? (3rd/mruby/src/kernel.c's own `mrb_false`: " \
        "unconditionally false, reads neither self nor arguments)\n" \
        "  r#{d_reg} = mrb_false_value();\n"
    when :basic_object_method_missing
      # BasicObject#method_missing is 3rd/mruby/src/class.c's own
      # `mrb_obj_missing`, which cannot be called directly (it reads its
      # arguments through `mrb_get_args` off `mrb->c->ci`). Everything it
      # computes is reproduced here and handed to the one function it
      # actually tail-calls, `mrb_method_missing`, which takes all four
      # inputs as plain C parameters.
      #
      # The ARGARY spec this kind is gated on is `1:1:0:0` with lv=0, which
      # vm.c's OP_ARGARY builds from `regs+1` as m1=1 copied values followed
      # by the spliced rest array -- i.e. `[r1, *r2]`, so `mrb_get_args`'
      # own `"n*!"` split of that array yields exactly `name = r1` and
      # `args = r2`. Read off the live registers rather than the entry
      # wrapper's parameters, so a body that reassigned either one before
      # the `super` would still forward what the interpreter would.
      #
      # The `mrb_array_p` guard is not defensive padding -- it is vm.c's own
      # OP_ARGARY `r != 0` branch reproduced exactly: that code does
      # `if (mrb_array_p(stack[m1])) { pp = ARY_PTR(ary); len = ARY_LEN(ary); }`
      # and otherwise leaves `len` at 0, so a non-Array in the rest slot
      # really does yield `[r1]` alone, i.e. an EMPTY forwarded argument
      # list. It is also what keeps `RARRAY_LEN`/`RARRAY_PTR` (unchecked
      # accessor macros) off a non-Array value.
      #
      # `self` rather than `r0`: OP_SUPER reads `recv = regs[0]`, and the
      # generated prologue's own `mrb_value r0 = self;` makes those the same
      # value -- the existing fixed-count SUPER arm above already passes
      # `self` for exactly this reason.
      #
      # `mrb_method_missing` is `mrb_noreturn` -- it always raises -- so
      # nothing may follow it on this path. Nothing is emitted after it and
      # `d_reg` is deliberately left unassigned; the RETURN the next
      # instruction compiles to is unreachable code g++ accepts and never
      # executes, the same already-established shape RAISEIF's own
      # unconditional `mrb_exc_raise` arm produces.
      "  // super -> BasicObject#method_missing (3rd/mruby/src/class.c's own `mrb_obj_missing`, " \
        "reproduced via the `mrb_method_missing` it tail-calls -- always raises NoMethodError)\n" \
        "  mrb_method_missing(M, mrb_obj_to_sym(M, r1), self,\n" \
        "                     mrb_array_p(r2)\n" \
        "                       ? mrb_ary_new_from_values(M, RARRAY_LEN(r2), RARRAY_PTR(r2))\n" \
        "                       : mrb_ary_new(M));\n"
    end
  end

  # EQ/LT/LE/GT/GE all share OP_CMP's own real shape (3rd/mruby/src/vm.c):
  # Integer/Integer and, when floats are enabled, Integer/Float, Float/Integer,
  # and Float/Float operands compare directly and produce a real C++ bool
  # converted to mrb_value. For EQ's other operand shapes, the fallback
  # preserves mrb_equal's object-equality shortcut with mrb_obj_eq before
  # dispatching `==`. This both avoids a method call for equal immediate or
  # identical object values and preserves the VM rule that `x == x` is true
  # even when the object's overridden `==` method would return false.
  # FIXNUM_OPERAND_PROOF: `irep`/`idx`/`owner_def` are threaded through purely
  # so this can ask the same "are BOTH operands provably Fixnum here" question
  # ADD/SUB/MUL/DIV now ask -- when they are, the whole runtime check and its
  # `mrb_funcall` else-branch disappear and only the native comparison remains.
  # `mrb_bool_value` of a C++ `<`/`<=`/... on two `mrb_int`s is exactly what
  # today's fast path already computes, so this changes nothing but which of
  # the two existing branches survives into the generated C++.
  def compile_cmp(op, args, irep = nil, idx = nil, owner_def = nil, reg_offset = 0)
    sym = { 'EQ' => '==', 'LT' => '<', 'LE' => '<=', 'GT' => '>', 'GE' => '>=' }.fetch(op)
    d = args[/^R(\d+)/, 1]
    s = args[/\(R(\d+)\)/, 1]
    if proven_fixnum_pair?(irep, idx, unshift_proof_reg(d, reg_offset), unshift_proof_reg(s, reg_offset), owner_def)
      return "#{FIXNUM_PROOF_NOTE}  r#{d} = mrb_bool_value(mrb_fixnum(r#{d}) #{sym} mrb_fixnum(r#{s}));\n"
    end

    # OP_CMP's `MRB_TT_INTEGER` is the full built-in Integer tag (not the
    # narrower Fixnum proof above), and its float-enabled arm also compares
    # all three Integer/Float combinations natively. Mirror those exact type
    # pairs. The tag checks must precede mrb_integer/mrb_float: like the VM's
    # accessors, those functions are only valid for their matching value tag.
    #
    # EQ is special: OP_EQ performs its object-identity shortcut before
    # reaching OP_CMP. Keep that observable ordering, including for NaN and
    # symbols, while using native numeric comparison only after identity fails.
    # `MRB_NO_FLOAT` builds compile out both the VM's float arms and ours.
    # OP_CMP uses a real dynamic send for non-numeric operands. Forward those
    # sends through compile_send's existing MONO/TYPED resolver so compiled
    # operator methods can be called directly. EQ reaches this fallback only
    # after the outer mrb_obj_eq identity shortcut has already failed (the
    # VM's OP_EQ order), so it takes the same resolver as the other
    # comparisons and stores the `==` method's own result like OP_CMP does.
    # For EQ the generated chain below already answers String/Symbol, so its
    # fallback send must not repeat the registered-expression switch.
    @suppress_native_expression_send = sym if op == 'EQ'
    begin
      fallback = compile_operator_fallback(sym, d, s, nil, irep, idx, owner_def, reg_offset)
    ensure
      @suppress_native_expression_send = nil
    end
    # String/Symbol `==` are generated from their C wrappers; the resolver
    # fallback above stays the `else` for every other receiver.
    fallback = generated_eq_dispatch(d, s, fallback) || fallback if op == 'EQ'

    integer_accessor = "mrb_integer(r#{d}) #{sym} mrb_integer(r#{s})"
    no_float_accessor = "mrb_fixnum(r#{d}) #{sym} mrb_fixnum(r#{s})"
    numeric_dispatch = <<~CPP
      if (mrb_type(r#{d}) == MRB_TT_INTEGER && mrb_type(r#{s}) == MRB_TT_INTEGER) {
      #ifdef MRB_NO_FLOAT
        r#{d} = mrb_bool_value(#{no_float_accessor});
      #else
        r#{d} = mrb_bool_value(#{integer_accessor});
      #endif
      }
      #ifndef MRB_NO_FLOAT
      else if (mrb_type(r#{d}) == MRB_TT_INTEGER && mrb_type(r#{s}) == MRB_TT_FLOAT) {
        r#{d} = mrb_bool_value(mrb_integer(r#{d}) #{sym} mrb_float(r#{s}));
      } else if (mrb_type(r#{d}) == MRB_TT_FLOAT && mrb_type(r#{s}) == MRB_TT_INTEGER) {
        r#{d} = mrb_bool_value(mrb_float(r#{d}) #{sym} mrb_integer(r#{s}));
      } else if (mrb_type(r#{d}) == MRB_TT_FLOAT && mrb_type(r#{s}) == MRB_TT_FLOAT) {
        r#{d} = mrb_bool_value(mrb_float(r#{d}) #{sym} mrb_float(r#{s}));
      }
      #endif
      else {
        #{fallback}
      }
    CPP

    if op == 'EQ'
      <<~CPP
        if (mrb_obj_eq(M, r#{d}, r#{s})) {
          r#{d} = mrb_true_value();
        } else if (mrb_symbol_p(r#{d})) {
          // OP_EQ: a symbol receiver that is not identical is unequal, no send.
          r#{d} = mrb_false_value();
        } else {
          // Numeric tag pair handling mirrors the pinned mruby OP_CMP.
          #{numeric_dispatch}
        }
      CPP
    else
      "  // Numeric tag pair handling mirrors the pinned mruby OP_CMP.\n#{numeric_dispatch}"
    end
  end

  # EQ's non-numeric operands used to reach `mrb_funcall` every time the
  # identity shortcut missed -- i.e. on every FALSE String or Symbol
  # comparison (`@mode == :menu`, `name == "x"`). `==` is registered by
  # several built-in classes; the exact-class generator derives the ones whose
  # C wrapper is a single public-API expression (String#== is
  # `mrb_str_equal`, Symbol#== is `mrb_obj_equal`) and this emits them behind
  # the same per-class guards every other generated expression uses. The
  # identity/dispatch statement stays the fallback for every other receiver.
  # Returns nil when nothing was generated or a Ruby definition/prepend could
  # sit in front of the built-in (builtin_class_send_safe?).
  def generated_eq_dispatch(d, s, identity_dispatch)
    entries = @native_registered_expressions['==']
    return unless entries && !entries.empty? && entries.all? { |entry| entry[:arity] == 1 }
    return unless builtin_class_send_safe?('==', entries.map { |entry| entry[:owner][:class_name] }.uniq)

    # One if/else-if chain rather than compile_native_registered_expression's
    # switch: that form repeats the fallback statement in every case, which
    # would add an `mrb_funcall` site per generated class to every EQ.
    recv = "r#{d}"
    chain = entries.map do |entry|
      owner = entry[:owner]
      guard = "mrb_type(#{recv}) == #{owner[:tag]}"
      guard += " && mrb_obj_ptr(#{recv})->c == M->#{owner[:field]}" unless %w[Float Symbol].include?(owner[:class_name])
      expression = entry[:expression].gsub('recv', recv).gsub('BC2CPP_ARG0', "r#{s}")
      "  if (#{guard}) {\n    r#{d} = #{expression};\n  } else "
    end.join
    "  // == -- generated from native registrations and C method bodies\n#{chain}{\n#{identity_dispatch}  }\n"
  end

  # Operator opcodes fall back to an ordinary one-argument method send
  # whenever their built-in fast path does not apply. Reuse compile_send's
  # MONO/TYPED resolution; ADDI/SUBI's immediate is passed as an expression
  # so this does not borrow a register that may still be live.
  def compile_operator_fallback(name, dest_reg, arg_reg, arg_expr, irep, idx, owner_def, reg_offset)
    argument = arg_reg ? "r#{arg_reg}" : arg_expr
    send_args = "R#{dest_reg} :#{name} n=1"
    send = compile_send(send_args, self_implicit: false, irep: irep,
                        idx: reg_offset.zero? ? idx : nil, owner_def: owner_def,
                        call_receiver: "r#{dest_reg}", call_arguments: [argument])
    send.lines.map { |line| "  #{line}" }.join
  end

  # KEYWORD_CALLSITE_SUPPORT: compile a `SEND`/`SSEND` call site that
  # passes keyword arguments (`n=2|nk=1` shape) into a direct `_impl`
  # call against an already-compiled callee. Returns the emitted C++ on
  # success, nil when this call site is not a supported shape (the
  # caller falls back to its honest #error).
  #
  # Why direct-call-only, never dynamic dispatch: mruby's own
  # `mrb_funcall*` family can never carry keywords (`ci->nk = 0` in
  # funcall_args_capture, 3rd/mruby/src/vm.c) -- only the VM's own
  # OP_SEND packs nk pairs into a Hash at runtime. So unlike a
  # positional call, there is no `mrb_funcall` spelling that preserves
  # keywords at all; the only sound translation is calling the
  # callee's own compiled `_impl` directly, whose signature already
  # takes each keyword as an explicit `(value, given)` parameter pair
  # (see compile_method's own entry-wrapper comment).
  #
  # Call-site layout (confirmed against real disassembly, e.g.
  # `SSEND R9 :deal_attack n=3|nk=1` with `R10/R11/R12` positionals,
  # `R13 = LOADSYM :charged`, `R14` = value): n positional registers
  # immediately after the destination, then nk (sym, value) pairs.
  # Only literal-symbol keys (a `LOADSYM :name` writing the sym
  # register, verified by backward scan in this same irep) are
  # supported -- a computed key has no static name to match against
  # the callee's keyword table, so it keeps the #error.
  #
  # Callee resolution is MONO-only with the keyword-aware gate
  # (callee compiles clean AND has a computable `keyword_arg_table`
  # covering the call site's keys, AND positional count matches the
  # callee's mandatory arity) instead of `pure_mandatory_arity?.
  # Missing keywords pass `mrb_nil_value()` + `given=0`, exactly what
  # the entry wrapper's own `mrb_undef_p` check produces for an omitted
  # keyword; required keywords missing at the call site are rejected
  # (nil return -- the interpreter would raise ArgumentError, so
  # compiling a call that drops one would be silently wrong).
  # Was this specific register's own most recent write (scanning backward
  # from `before_idx`, inclusive) a `LOADSYM :name` literal? Shared by
  # compile_keyword_send's own ordinary keyword-pair extraction and
  # splat_hash_literal_pairs' own double-splat-literal key extraction --
  # the identical "prove this register's own value" question, not two
  # unrelated tables the way hash_element_source_scan's own comment warns
  # against sharing.
  def literal_symbol_write(irep, before_idx, reg)
    before_idx.downto(0) do |i|
      insn = irep.instructions[i]
      next unless insn
      # A write to this register ends the scan -- it must be LOADSYM.
      next unless insn.args =~ /^R#{reg}\b/

      return nil unless insn.op == 'LOADSYM'

      return insn.args[/:(\S+)/, 1]&.sub(/\A:/, '')
    end
    nil
  end

  # KEYWORD_CALLSITE_SUPPORT: the shared tail of compile_keyword_send --
  # MONO target resolution, keyword-table/arity/required-keyword checks,
  # and the direct `_impl` call emission -- factored out so
  # compile_splat_send (below) can reuse the exact same devirtualization
  # rule against an unrolled splat/double-splat's own register list,
  # which (unlike an ordinary keyword call site) is never a fixed
  # dest-relative offset. `argv`/`kw_val_exprs` are already-resolved C++
  # expression strings (usually `r<N>`, one register each), not register
  # numbers -- compile_keyword_send's own caller still passes plain
  # `r<N>` strings, so this is a pure extraction, not a behavior change.
  def compile_keyword_call(name:, d:, recv:, n:, argv:, kw_names:, kw_val_exprs:,
                           self_implicit: false, owner_def: nil)
    # MONO resolution only -- deliberately no TYPED path: a traced-
    # receiver guard's `else` branch would need a dynamic keyword
    # dispatch, which mruby's own `mrb_funcall*` family cannot express
    # (`ci->nk = 0`, see compile_keyword_send's own top comment). MONO
    # needs no guard at all (exactly one def exists program-wide), so it
    # is unconditionally sound. A POLY keyword call keeps the honest
    # #error.
    target = monomorphic_target(name)
    # LEXICAL_SELF_KEYWORD_SUPPORT: ...and a name that is POLY program-wide
    # can STILL have exactly one reachable definition at THIS call site,
    # when the site is an implicit-self send inside a class that provably
    # has no subclasses -- see lexical_self_keyword_target's own comment for
    # the full argument. Same certain-not-traced guarantee MONO has (proven
    # from the closed-world registry, not observed from a backward trace),
    # so the emitted call needs no runtime guard and no mrb_funcall fallback
    # either, and every arity/keyword-shape check below applies to it
    # unchanged. Strictly additive: only ever consulted when
    # `monomorphic_target` already declined, so no call site this path
    # already compiled changes at all.
    lexical_self = false
    if target.nil?
      target = lexical_self_keyword_target(name, self_implicit: self_implicit, owner_def: owner_def)
      lexical_self = !target.nil?
    end
    return nil unless target&.irep

    # monomorphic_target already verified compiles_clean? -- fetch the
    # irep struct for the keyword-table/arity checks below (fetch, not
    # compiles_clean?, which takes a label).
    callee_irep = @ireps.fetch(target.irep)
    kw_table = keyword_arg_table(callee_irep)
    return nil unless kw_table
    # KEYWORD_CALLSITE_OPTIONAL_POSITIONAL_SUPPORT: the callee's own real
    # positional arity is a RANGE, [mand, mand + opt], not a single number
    # -- the exact same widening CALLSITE_OPTIONAL_ARG_SUPPORT already made
    # to compile_send's own (no-keyword) MONO guard, applied to the keyword
    # path, which was still demanding an exact `n == mandatory_arity` match
    # and so refused every keyword call site whose callee declares even one
    # `= default` positional. `optional_arity` is 0 for a pure-mandatory
    # callee, so this collapses back to the original exact-match check
    # unchanged for every call site this path already compiled.
    #
    # Why this is sound, read straight out of 3rd/mruby/src/vm.c's own
    # `CASE(OP_ENTER, W)` for the both-`opt`-and-`kw` shape rather than
    # assumed: keyword arguments and positional arguments never interact
    # at all once `kd` (`MRB_ASPEC_KEY(a) > 0 || MRB_ASPEC_KDICT(a)`) is
    # set. `OP_SEND`'s own prologue packs this site's `nk` (sym, value)
    # pairs into a single Hash stored at `regs[mrb_ci_kidx(ci)]` and sets
    # `ci->nk = CALL_MAXARGS`, leaving `ci->n` -- the `argc` OP_ENTER then
    # reads -- counting POSITIONALS ONLY. The `!kd` arm that folds a
    # trailing kdict back into the positional list (`ci->n++; argc++`) is
    # unreachable here by construction, because `keyword_arg_table` above
    # already required ENTER's own `kw` field to be positive. So OP_ENTER's
    # optional-slot resolution is a pure function of `argc` alone:
    # `len = m1 + o + r + m2` (here `r == m2 == 0`, both required zero by
    # keyword_arg_table), the strict check admits exactly
    # `m1 <= argc <= len`, and the initializer skip is `ci->pc +=
    # (argc - m1 - m2) * 3` when `argc < len` / `ci->pc += o * 3` when
    # `argc == len` -- i.e. jump-table entry `argc - m1` in both arms.
    # That index IS `bc2cpp_given_opt`, which the callee's already-emitted
    # `emit_optional_dispatch` switch consumes, so the call site's own
    # statically-known `n - t_mand` reproduces the VM's own choice exactly.
    #
    # `optional_arg_table`'s jump targets are required to have actually
    # RESOLVED (not just `opt` positive) before trusting that switch: that
    # table returns `[opt, nil, nil]` for an ENTER whose `opt` field is
    # nonzero but whose real following bytecode isn't the recognized
    # `opt + 1` consecutive JMP shape, and `bc2cpp_given_opt` only means
    # what this path needs it to mean when the dispatch switch it feeds
    # was genuinely emitted. A safe miss (nil, honest #error) otherwise.
    t_mand = mandatory_arity(callee_irep)
    t_opt = optional_arity(callee_irep)
    return nil unless n.between?(t_mand, t_mand + t_opt)
    return nil if t_opt.positive? && !optional_arg_table(callee_irep)[1]
    return nil unless (kw_names - kw_table.map { |k| k[:name] }).empty?

    # Every required keyword must be present at the call site --
    # otherwise the interpreter raises ArgumentError and compiling
    # the call would be silently wrong.
    required = kw_table.select { |k| k[:required] }.map { |k| k[:name] }
    return nil unless (required - kw_names).empty?

    # Same emission-eligibility guard as compile_send's own: no _impl
    # exists for an owner this run is not emitting.
    if @only_owners && !@only_owners.include?(target.owner)
      return nil unless @other_owners&.include?(target.owner)
    end
    impl = cpp_name(target.owner, target.name) + '_impl'
    # KEYWORD_CALLSITE_ARITY_FIX: the emitted argument list has to match the
    # callee's own real `_impl` parameter list EXACTLY, and that list is not
    # a uniform `(value, given)` pair per keyword -- compile_method's own
    # signature builder emits the extra `mrb_int bc2cpp_kw_given_<name>`
    # parameter for an OPTIONAL keyword only (`unless kw[:required]`, same
    # place the entry wrapper's own `_impl` call already mirrors: `kw[:
    # required] ? [value] : [value, given]`). A required keyword is always
    # given -- `mrb_get_args` itself raises ArgumentError otherwise, before
    # `_impl` is ever reached -- so it carries no presence flag at all.
    # Emitting one unconditionally here (what this did before) shifted every
    # later argument by one slot per required keyword, a hard g++ error at
    # every one of this program's real keyword MONO call sites: 12 x `could
    # not convert '1' from 'int' to 'mrb_value'` (the literal `1` landing in
    # a later `mrb_value` parameter, e.g. `Game::Battle#command_skill_all`'s
    # required `name`/`cost` pair, or `RPG2k::Scene::Map#anim_target`'s three
    # required `height`/`index`/`flash_target`) plus 5 x `too many arguments
    # to function` (`RPG2k::Scene::Map#vehicle_blocks?`, whose single
    # required `block_airship` keyword left the call one argument past the
    # end of a signature with no trailing slot to absorb it). The two
    # spellings are the same bug, differing only in whether the shifted
    # argument still had a parameter to land in.
    #
    # `ci` is never nil for a required keyword -- the required-keyword check
    # above already returned nil for a call site that omits one -- so the
    # `mrb_nil_value()`/`0` "keyword not passed here" arm is reachable for an
    # optional keyword only, exactly the one that really does declare a flag.
    kw_args = kw_table.flat_map do |kw|
      ci = kw_names.index(kw[:name])
      val = ci ? kw_val_exprs[ci] : 'mrb_nil_value()'
      kw[:required] ? [val] : [val, ci ? '1' : '0']
    end
    # KEYWORD_CALLSITE_OPTIONAL_POSITIONAL_SUPPORT: `_impl`'s own real
    # positional parameter list always has room for the callee's FULL
    # `mand + opt` count (compile_method's own `total_args = mand + opt`),
    # followed by one `mrb_int bc2cpp_given_opt` when `opt` is positive,
    # and only THEN the keyword parameters -- that exact order, confirmed
    # against this program's own real generated signature for the four
    # `:deal_attack` sites this enables:
    #
    #   mrb_value Game__Battle_deal_attack_impl(mrb_state* M, mrb_value self,
    #       mrb_value b, mrb_value target, mrb_value swing_index,
    #       mrb_int bc2cpp_given_opt,
    #       mrb_value bc2cpp_kwarg_charged, mrb_int bc2cpp_kw_given_charged)
    #
    # So the padding has to be spliced in BEFORE `kw_args`, never appended
    # after it -- appending would shift every keyword argument one slot and
    # land `bc2cpp_given_opt`'s integer literal in an `mrb_value` parameter,
    # the identical class of hard g++ error KEYWORD_CALLSITE_ARITY_FIX
    # (just above) already had to fix once for the required-keyword flag.
    #
    # `mrb_nil_value()` is the same placeholder compile_send's own
    # CALLSITE_OPTIONAL_ARG_SUPPORT branch and compile_method's own entry
    # wrapper both already use for an omitted optional: never read, because
    # the callee's own `bc2cpp_given_opt` switch jumps straight into that
    # slot's default-value code, which overwrites the register first.
    # Measured on this program's real closed world: all four enabled sites
    # pass `n == t_mand + t_opt` (a literal `0`/`1` swing_index), so the
    # padding array is empty at every one of them today and only the
    # `bc2cpp_given_opt` literal is actually new -- the padding is kept
    # because an omitting call site is a legal shape the VM accepts, and
    # silently emitting a short argument list for one would be a g++ error
    # rather than the safe miss this file's gates are built to produce.
    opt_args = []
    if t_opt.positive?
      opt_args = Array.new(t_mand + t_opt - argv.size, 'mrb_nil_value()')
      opt_args << (argv.size - t_mand).to_s
    end
    call = "r#{d} = #{impl}(M, #{([recv] + argv + opt_args + kw_args).join(', ')});"
    # LEXICAL_SELF_KEYWORD_SUPPORT: a distinct marker from MONO, because the
    # two resolutions rest on genuinely different facts and an auditor
    # reading the generated C++ should be able to tell them apart -- MONO
    # means "one definition exists program-wide", LEXICAL_SELF means "several
    # do, but this implicit-self receiver is provably an instance of exactly
    # one owner, which has no subclasses". Same spelling compile_send's own
    # non-keyword LEXICAL_SELF branch already emits, so both halves of the
    # mechanism are greppable as one thing, and (like that one) it is
    # deliberately absent from RUNTIME_DEF_DYNAMIC_MARKERS so
    # runtime_def_devirt_audit still treats it as a static bind to check.
    note =
      if lexical_self
        "  // LEXICAL_SELF :#{name} -> #{target.owner}##{target.name} (keyword call; self, statically " \
          "known -- #{target.owner} has no subclasses anywhere in this closed world, so this " \
          "implicit-self send can reach no other definition of this POLY name), direct C++ call " \
          "(no mrb_funcall)\n"
      else
        "  // MONO :#{name} -> #{target.owner}##{target.name} (keyword call), direct C++ call (no mrb_funcall)\n"
      end
    "#{note}  #{call}\n"
  end

  def compile_keyword_send(args, self_implicit:, irep:, idx:, owner_def:, name:, d:, n:, nk:)
    dest_reg = d.to_i
    # Keyword (sym, value) pairs sit right after the n positionals.
    kw_sym_regs = (0...nk).map { |k| dest_reg + 1 + n + k * 2 }
    kw_val_regs = (0...nk).map { |k| dest_reg + 2 + n + k * 2 }
    # Verify every key register is written by a LOADSYM with a literal
    # symbol, scanning backward from the call site in this same irep.
    kw_names = kw_sym_regs.map { |reg| literal_symbol_write(irep, idx, reg) }
    return nil if kw_names.any?(&:nil?)

    recv = self_implicit ? 'self' : "r#{d}"
    argv = (1..n).map { |k| "r#{dest_reg + k}" }
    direct = compile_keyword_call(name: name, d: d, recv: recv, n: n, argv: argv,
                                  kw_names: kw_names, kw_val_exprs: kw_val_regs.map { |r| "r#{r}" },
                                  self_implicit: self_implicit, owner_def: owner_def)
    return direct if direct

    # KEYWORD_DIRECT_CONSTRUCT_SUPPORT: compile_keyword_call just declined,
    # and for a `:new` call site it ALWAYS will -- `:new` has no compiled
    # MONO target at all (it is native `Class#new`), so the keywords a
    # `Foo.new(a, k: v)` site carries belong to the target class's own
    # `#initialize`, not to `:new`. Tried before the Hash-as-trailing-
    # positional fallback below because these are REAL keyword calls (the
    # callee genuinely declares the parameters), which that fallback's own
    # gate correctly refuses outright.
    construct = compile_keyword_direct_construct(
      irep: irep, idx: idx, owner_def: owner_def, self_implicit: self_implicit,
      name: name, d: d, n: n, recv: recv, argv: argv, kw_names: kw_names,
      kw_val_exprs: kw_val_regs.map { |r| "r#{r}" }
    )
    return construct if construct

    # KEYWORD_HASH_POSITIONAL_SUPPORT: compile_keyword_call just declined
    # (see below for the exact reasons this round measured), but a large
    # share of the call sites it declines aren't real keyword calls AT ALL
    # -- they only look like one in the disassembly. The `self_implicit`/
    # `owner_def` pair it now also receives is what lets that path fall
    # back to the lexical-self narrowing (KEYWORD_HASH_LEXICAL_SELF_SUPPORT,
    # its comment) when the name-based every-def gate declines -- the same
    # pair LEXICAL_SELF_KEYWORD_SUPPORT threads into compile_keyword_call.
    hashpos = compile_keyword_hash_positional_send(name: name, d: d, recv: recv, n: n, nk: nk,
                                                   argv: argv, kw_sym_regs: kw_sym_regs,
                                                   kw_val_regs: kw_val_regs, kw_names: kw_names,
                                                   self_implicit: self_implicit, owner_def: owner_def)
    return hashpos if hashpos

    # KEYWORD_NEVER_DEFINED_CONST_RECEIVER_SUPPORT: every keyword-free proof
    # above declined (a real def of the name exists, its ENTER is invisible
    # or its arity does not fit), but this site's RECEIVER provably never
    # exists at runtime -- see compile_keyword_never_defined_const_send's
    # own comment. Tried last so it can never pre-empt an existing path.
    compile_keyword_never_defined_const_send(name: name, d: d, n: n, nk: nk, irep: irep, idx: idx,
                                             argv: argv, kw_sym_regs: kw_sym_regs,
                                             kw_val_regs: kw_val_regs, kw_names: kw_names,
                                             self_implicit: self_implicit)
  end

  # KEYWORD_DIRECT_CONSTRUCT_SUPPORT: a `Foo.new(a, b, k1: v1, k2: v2)` call
  # site whose target class `Foo` is a known, vetted DIRECT_CONSTRUCT_TARGETS
  # entry AND whose own `#initialize` really does declare the keyword
  # parameters this site supplies, matched BY NAME.
  #
  # This is the `:new` half of the standing splat/keyword `#error` bucket,
  # and it is a genuinely different mechanism from its two neighbours:
  #
  #   * compile_keyword_call (above) can never fire here. It resolves the
  #     CALLED name via monomorphic_target, and the called name is `:new` --
  #     native `Class#new`, which has no compiled `_impl` at all and declares
  #     no keywords of its own. The keywords belong one level down, to the
  #     TARGET CLASS's `#initialize`, which only trace_new_target can find.
  #   * compile_keyword_hash_positional_send (below) must not fire here
  #     either, and correctly does not: its whole soundness argument is that
  #     the callee declares NO keyword parameters, so vm.c's `OP_ENTER`
  #     `kd == 0` arm turns the packed Hash into one trailing POSITIONAL
  #     argument. Here `kd == 1` -- these are real keyword parameters, taking
  #     vm.c's real `KEY_P`/`KARG` path -- so Hash-as-trailing-positional
  #     would be silently, badly wrong (the callee would receive an extra
  #     positional it has no parameter for, and no keyword values at all).
  #
  # So this path emits a REAL keyword-respecting construct: the same
  # runtime-guarded `bc2cpp_direct_alloc` + `_impl` shape compile_send's own
  # non-keyword DIRECT_CONSTRUCT_TARGETS branch already emits, with
  # compile_keyword_call's own already-shipped `(value, given)` keyword
  # argument builder reused verbatim for the trailing parameters.
  #
  # The gate is compile_send's own four-part DIRECT_CONSTRUCT_TARGETS gate
  # with `pure_mandatory_arity?` swapped for the keyword-aware
  # `mandatory_optional_and_keyword_arity?`, plus three additions:
  #
  #   a. EXACT-NAME keyword matching (`kw_names - table_names` empty), never
  #      a count match -- two same-arity keyword sets with different names
  #      are completely different calls, and silently passing v1 as k2 would
  #      be exactly the kind of quiet miscompile this file's gates exist to
  #      prevent. Every REQUIRED keyword must also be present at the site
  #      (the interpreter raises ArgumentError otherwise, so compiling a
  #      call that drops one would be wrong) -- the identical pair of checks
  #      compile_keyword_call already makes, reused unchanged.
  #   b. A whole-program "no class ANYWHERE in the closed world defines a
  #      custom `self.new` or `self.allocate`" check, on top of this table's
  #      own per-class one. Three of this round's five new entries
  #      (RPG2k::Scene::Map/MapViewer/ChipsetEditor) are real SUBCLASSES
  #      (`< Base`), unlike every pre-existing plain-`Object`-subclass entry,
  #      and an INHERITED custom `self.new` would defeat a direct construct
  #      just as completely as one declared on the class itself. Asking the
  #      whole-program question needs no ancestor-chain resolution at all and
  #      covers every possible ancestor by construction -- strictly stronger
  #      than walking @superclass_of, whose entries are legitimately absent
  #      for a computed superclass expression (see resolve_superclass_ref),
  #      which would have forced a safe-miss refusal for exactly those three.
  #      Measured: the real closed world contains ZERO `def self.new` and
  #      ZERO `def self.allocate`, so this costs nothing today; if one is
  #      ever added, this whole path shuts off and every site falls back to
  #      the honest `#error`, which is the correct direction to fail.
  #   c. `#initialize`'s own return value is discarded, exactly as the
  #      non-keyword branch already does -- real Ruby `.new` always returns
  #      the newly allocated object, never whatever `#initialize` returned.
  #
  # Returns nil (a safe miss -- caller falls through) the moment anything
  # above doesn't hold.
  def compile_keyword_direct_construct(irep:, idx:, owner_def:, self_implicit:,
                                       name:, d:, n:, recv:, argv:, kw_names:, kw_val_exprs:)
    return nil unless name == 'new' && !self_implicit && irep && idx

    known = trace_new_target(irep, idx, d, nil, 0, nil, resolving_new: true, owner: owner_def&.owner)
    return nil unless known && DIRECT_CONSTRUCT_TARGETS.include?(known)

    # 1/2: no custom `self.new`/`self.allocate` -- on this exact class (the
    # same "X.singleton" pseudo-owner build_registry registers every
    # def-self.x/class<<self method under), and, see (b) above, nowhere in
    # the closed world at all, which is what really covers an inherited one.
    no_custom_new = @registry['new'].none? { |md| md.owner == "#{known}.singleton" }
    no_custom_allocate = @registry['allocate'].none? { |md| md.owner == "#{known}.singleton" }
    return nil unless no_custom_new && no_custom_allocate

    none_anywhere = (@registry['new'] + @registry['allocate'])
                    .none? { |md| md.owner.to_s.end_with?('.singleton') }
    return nil unless none_anywhere

    # 3: `#initialize` must be a real, compiling, positionals-plus-keywords-
    # only leaf whose real positional arity RANGE covers THIS call site's own
    # positional count.
    init_def = @registry['initialize'].find { |md| md.owner == known }
    return nil unless init_def&.irep

    init_irep = @ireps.fetch(init_def.irep)
    return nil unless mandatory_optional_and_keyword_arity?(init_irep)
    return nil unless compiles_clean?(init_def.irep)

    # KEYWORD_CONSTRUCT_OPTIONAL_POSITIONAL_SUPPORT: the callee's own real
    # positional arity is a RANGE, `[mand, mand + opt]`, not a single number
    # -- the identical widening the just-merged KEYWORD_CALLSITE_OPTIONAL_
    # POSITIONAL_SUPPORT round made to compile_keyword_call's own guard (and
    # CALLSITE_OPTIONAL_ARG_SUPPORT before it to compile_send's no-keyword
    # MONO guard), applied to the direct-CONSTRUCT path, which was still
    # demanding an exact `n == mandatory_arity` match. `optional_arity` is 0
    # for every class already on this table, so this collapses back to that
    # original exact-match check, unchanged, for every construct site this
    # path already compiled.
    #
    # Why it is sound, read straight out of 3rd/mruby/src/vm.c's own
    # `CASE(OP_ENTER, W)` rather than assumed -- and note this reasoning is
    # about `#initialize`'s OWN OP_ENTER, which is exactly the same OP_ENTER
    # compile_keyword_call already reasoned about, because real Ruby's
    # `Class#new` forwards its whole argument list (positionals, keywords and
    # all) to `#initialize` untouched: once `kd` is set (guaranteed here,
    # `keyword_arg_table` below requires ENTER's own `kw` field positive),
    # keywords and positionals never interact. `OP_SEND`'s prologue packs
    # this site's `nk` (sym, value) pairs into one Hash at
    # `regs[mrb_ci_kidx(ci)]` and sets `ci->nk = CALL_MAXARGS`, leaving
    # `ci->n` -- the `argc` OP_ENTER reads -- counting POSITIONALS ONLY, so
    # the `!kd` arm that folds a trailing kdict back into the positional list
    # is unreachable by construction. Optional-slot resolution is therefore a
    # pure function of `argc`: with `r == m2 == 0` (both required zero by
    # mandatory_optional_and_keyword_arity? above), `len = m1 + o`, the
    # strict check admits exactly `m1 <= argc <= len`, and the initializer
    # skip (`(argc - m1 - m2) * 3` when `argc < len`, `o * 3` when
    # `argc == len`) selects jump-table entry `argc - m1` in both arms. That
    # index IS `bc2cpp_given_opt`, so this call site's statically-known
    # `n - t_mand` reproduces the VM's own choice exactly.
    #
    # `optional_arg_table`'s jump targets are additionally required to have
    # really RESOLVED (not merely `opt` positive) before trusting that
    # switch: it returns `[opt, nil, nil]` for an ENTER whose `opt` field is
    # nonzero but whose real following bytecode isn't the recognized
    # `opt + 1` consecutive JMP shape, and `bc2cpp_given_opt` only means what
    # this path needs it to mean when the dispatch switch it feeds was
    # genuinely emitted by emit_optional_dispatch. A safe miss (nil, honest
    # `#error`) otherwise.
    t_mand = mandatory_arity(init_irep)
    t_opt = optional_arity(init_irep)
    return nil unless n.between?(t_mand, t_mand + t_opt)
    return nil if t_opt.positive? && !optional_arg_table(init_irep)[1]

    # (a): exact keyword-NAME match, plus every required keyword supplied.
    kw_table = keyword_arg_table(init_irep)
    return nil unless kw_table
    return nil unless (kw_names - kw_table.map { |k| k[:name] }).empty?

    required = kw_table.select { |k| k[:required] }.map { |k| k[:name] }
    return nil unless (required - kw_names).empty?

    # 4: same ONLY_OWNERS/OTHER_OWNERS emission-eligibility guard every other
    # devirtualizing path applies -- an owner this run doesn't itself emit
    # (and no other gem exposes) has no real `_impl`/class-accessor symbol.
    owner_emitted = !@only_owners || @only_owners.include?(known) || @other_owners&.include?(known)
    return nil unless owner_emitted

    @direct_construct_used << known
    accessor = direct_construct_class_fn(known)
    init_impl = cpp_name(known, 'initialize') + '_impl'
    # Identical `(value, given)` construction to compile_keyword_call's own
    # (see KEYWORD_CALLSITE_ARITY_FIX there for why a REQUIRED keyword
    # carries no presence flag at all, and an optional one always does).
    kw_args = kw_table.flat_map do |kw|
      ci = kw_names.index(kw[:name])
      val = ci ? kw_val_exprs[ci] : 'mrb_nil_value()'
      kw[:required] ? [val] : [val, ci ? '1' : '0']
    end
    # KEYWORD_CONSTRUCT_OPTIONAL_POSITIONAL_SUPPORT: `_impl`'s own real
    # positional parameter list always has room for the callee's FULL
    # `mand + opt` count (compile_method's own `total_args = mand + opt`),
    # followed by one `mrb_int bc2cpp_given_opt` when `opt` is positive, and
    # only THEN the keyword parameters -- that exact order, confirmed against
    # this program's own real generated signature for the one site this
    # enables:
    #
    #   mrb_value Game__Battle_initialize_impl(mrb_state* M, mrb_value self,
    #       mrb_value allies, mrb_value enemies, mrb_value rng,
    #       mrb_value states, mrb_value variance, mrb_value criticals,
    #       mrb_value accuracy, mrb_value first_strike, mrb_value attributes,
    #       mrb_value ai, mrb_int bc2cpp_given_opt,
    #       mrb_value bc2cpp_kwarg_rpg2003, mrb_int bc2cpp_kw_given_rpg2003,
    #       mrb_value bc2cpp_kwarg_party,   mrb_int bc2cpp_kw_given_party,
    #       mrb_value bc2cpp_kwarg_battle_type,
    #       mrb_int bc2cpp_kw_given_battle_type);
    #
    # So the padding has to be spliced in BEFORE `kw_args`, never appended
    # after it -- appending would shift every keyword argument one slot and
    # land `bc2cpp_given_opt`'s integer literal in an `mrb_value` parameter,
    # the identical class of hard g++ error KEYWORD_CALLSITE_ARITY_FIX
    # already had to fix once for the required-keyword flag, and the
    # identical splice compile_keyword_call now performs.
    #
    # `mrb_nil_value()` is the same placeholder compile_send's own
    # CALLSITE_OPTIONAL_ARG_SUPPORT branch, compile_keyword_call and
    # compile_method's own entry wrapper all already use for an omitted
    # optional: never read, because the callee's own `bc2cpp_given_opt`
    # switch jumps straight into that slot's default-value code, which
    # overwrites the register first. Measured on this program's real closed
    # world: the single real site this enables (`Game::Battle.new`,
    # mruby-rpg2k/mrblib/scene/battle.rb:178, `n=10|nk=3`) supplies ALL TEN
    # positionals explicitly against `ENTER 2:8:0:0:3:0:0:0`, so
    # `n == t_mand + t_opt`, the padding array is EMPTY there and only the
    # `bc2cpp_given_opt` literal (`8`, selecting the switch's own `default:`
    # arm, i.e. skip every default-value assignment) is actually new. The
    # padding is emitted anyway because an omitting call site is a legal
    # shape the VM accepts, and silently emitting a short argument list for
    # one would be a hard g++ error rather than the safe miss this file's
    # gates are built to produce.
    opt_args = []
    if t_opt.positive?
      opt_args = Array.new(t_mand + t_opt - argv.size, 'mrb_nil_value()')
      opt_args << (argv.size - t_mand).to_s
    end
    note = "  // MONO :new -> #{known}, direct compiled construct with real KEYWORD arguments " \
           "(bc2cpp_direct_alloc + #{init_impl}) -- skips Class#new's own allocate+initialize " \
           "dispatch chain entirely; #{known}#initialize's own return value is discarded (real " \
           "Ruby .new always returns the new object, never whatever #initialize itself returns).\n" \
           "  // The keywords here are REAL keyword parameters of #{known}#initialize (matched by " \
           "NAME against its own KEY_P/KARG table, not by count), passed as the same explicit " \
           "(value, given) pairs its compiled _impl signature already declares -- NOT packed into " \
           "a trailing positional Hash, which is only correct for a callee declaring no keywords " \
           "at all (vm.c OP_ENTER's own kd == 0 arm; see compile_keyword_hash_positional_send).\n" \
           "  // Runtime-guarded exactly the way the non-keyword direct-construct path is: " \
           "#{known} could have been reassigned at the constant level since #{accessor}'s own " \
           "class was captured at gem-init, so #{recv} (this call site's own already-resolved " \
           "receiver) is compared against it rather than trusted outright, falling back to " \
           "ordinary mrb_funcall if they differ.\n"
    # The guard-miss arm needs care that the non-keyword direct-construct
    # path never did. `mrb_funcall` CANNOT carry keywords -- mruby 4.0.0's
    # own vm.c sets `ci->nk = 0` for it, and (confirmed by reading OP_ENTER
    # directly, 3rd/mruby/src/vm.c) there is NO trailing-Hash-to-keywords
    # conversion on the `kd == 1` side: a keyword-declaring callee reached
    # through funcall simply sees `kdict` stay nil. So "just funcall it"
    # would SILENTLY DROP every keyword here, which for these five classes
    # (whose keywords are all optional) would not even raise -- it would
    # quietly construct with default values instead. That is exactly the
    # class of silent miscompile this file's gates exist to prevent, so it
    # is not what this emits.
    #
    # Instead the miss arm packs the keyword pairs into one Hash and passes
    # it as a trailing positional -- which is precisely what the VM's own
    # OP_SEND does before OP_ENTER ever gets to decide what it means
    # (`hash_new_from_regs`, packed unconditionally, knowing nothing about
    # the callee; see compile_keyword_hash_positional_send's own comment and
    # the real vm.c quote there). It is therefore the most faithful spelling
    # available for a receiver whose real class is, by definition of having
    # missed this guard, no longer statically known, and it is exactly
    # correct whenever that class declares no keywords.
    #
    # This arm is in any case unreachable short of a real constant-level
    # reassignment (`Game::MoveRoute = SomethingElse`) between gem-init and
    # this call: `#{recv}` is this site's own already-resolved GETCONST
    # result, so an ordinary subclass receiver never lands here (it would
    # have come from a different constant, which trace_new_target resolves
    # separately). The keys are re-interned from the same literal symbol
    # names literal_symbol_write already PROVED each key register holds, so
    # this Hash is built from static facts, not from re-reading registers.
    kw_hash = String.new
    kw_hash << "    mrb_value bc2cpp_kwh = mrb_hash_new_capa(M, #{kw_names.size});\n"
    kw_names.each_with_index do |kn, k|
      kw_hash << "    mrb_hash_set(M, bc2cpp_kwh, " \
                 "mrb_symbol_value(mrb_intern_cstr(M, \"#{kn}\")), #{kw_val_exprs[k]});\n"
    end
    "#{note}" \
      "  if (mrb_class_ptr(#{recv}) == #{accessor}()) {\n" \
      "    r#{d} = bc2cpp_direct_alloc(M, mrb_class_ptr(#{recv}));\n" \
      "    #{init_impl}(M, #{(["r#{d}"] + argv + opt_args + kw_args).join(', ')});\n" \
      "  } else {\n" \
      "#{kw_hash}" \
      "    #{dynamic_dispatch_line(d, recv, name, argv + ['bc2cpp_kwh'])}" \
      "  }\n"
  end

  # KEYWORD_HASH_POSITIONAL_SUPPORT: a `SEND`/`SSEND` call site carrying
  # `nk` keyword pairs (`n=N|nk=K`) whose real callee declares NO keyword
  # parameters of its own -- in which case the keywords are not keywords in
  # any runtime sense: the VM hands the callee ONE ordinary trailing
  # POSITIONAL Hash argument, and the method signature that receives it is a
  # plain `def foo(opts)`.
  #
  # This is the single biggest real sub-shape inside the "SEND/SSEND has a
  # splat and/or keyword argument list" #error bucket, and it is a pure
  # CALL-SITE concern: the callee side needs nothing at all (it is an
  # ordinary all-mandatory-positional method this compiler already compiles
  # clean today). Measured, not assumed -- a whole-program run with this
  # round's own instrumentation showed the 20 sites in that bucket are ALL
  # `n=N|nk=K` (literal counts) and NOT ONE is a splat (`n=*`/`nk=*`) at
  # all, splitting by why compile_keyword_call declined:
  #   8  `:new`     -- native `Class#new`, no MONO target at all (the
  #                    keywords belong to the class's own `#initialize`,
  #                    which for `Game::MoveRoute#initialize(commands,
  #                    repeat: true, skippable: false)` really does declare
  #                    keywords) -- a genuinely different mechanism, left
  #                    open, see this round's own changelog entry.
  #   4  `:deal_attack` -- one real def (`Game::Battle#deal_attack(b,
  #                    target, swing_index = 0, charged: nil)`) that does
  #                    declare a real keyword but is itself not compiling
  #                    clean, so `monomorphic_target` refuses it. Left open.
  #   7  THIS SHAPE -- the callee has no keyword parameters whatsoever.
  #   1  `:close_message` -- genuinely POLY across two real defs that
  #                    DISAGREE (`RPG2k::Scene::Menu#close_message` takes no
  #                    arguments; `RPG2k::Scene::Map#close_message(animate:
  #                    true)` declares a real keyword), so no single
  #                    translation is correct for both receivers. Correctly
  #                    stays an honest #error -- this is the case the gate
  #                    below exists to catch.
  #
  # The seven real sites this closes and their real callee signatures (read
  # from the real Ruby source, not inferred):
  #   Game::Interpreter#do_change_parallax   -> Game::State#set_parallax(opts)
  #   Game::State.singleton#from_lsd         -> Game::State#set_parallax(opts)
  #   Game::Interpreter#do_show_picture      -> Game::State#show_picture(id, opts)
  #   RPG2k::Scene::Map#apply_map_access     -> RPG2k::Scene::Map#play_bgm(music)
  #   Game::State.singleton#from_lsd         -> Game::Party#load_state(data)
  #   RPG2k::Scene::Battle#start_battle_page_animation
  #                                          -> RPG2k::Scene::Battle#battle_animation_pixel(entry)
  #   Game::State.singleton#from_lsd         -> `:load_h`, POLY across FIVE
  #       real defs (Game::MessageConfig/Screen/Weather/Vehicle/Timer) that
  #       all AGREE -- every one is `def load_h(h)`, one mandatory
  #       positional and no keywords -- so the translation below is correct
  #       for every possible receiver and the POLY-ness costs nothing.
  #
  # An EIGHTH real site of this same shape sits one level down, inside a
  # BLOCK's own child irep rather than a method body, and so never showed up
  # in that 20-site bucket at all: `Game::State.restore_pictures`'s own
  # `pictures.each do |id, pic| ... state.show_picture(id, name: name, ...)
  # ... end` (mruby-rpg2k/mrblib/game/lsd_io.rb:1647-1674, a 13-keyword call
  # site -- `n=1|nk=13`). Compiling it has a real second-order effect worth
  # naming explicitly, because it is where this round's measured #error
  # reduction exceeds the seven sites above: BLOCK_CFUNC_FALLBACK_SUPPORT
  # only compiles a block whose own child irep compiles CLEAN, so that one
  # unsupported call site used to poison the whole block, and
  # `Game::State.singleton#restore_pictures` fell back to `#error unhandled
  # opcode BLOCK` + `#error unhandled opcode SENDB`. With the call site
  # compiling, the block irep is clean and both of those opcodes now compile
  # through the ordinary cfunc-backed RProc path. So the real whole-program
  # movement is 48 -> 39 #error markers (-9): -7 in the splat/keyword bucket
  # (20 -> 13), -1 BLOCK (4 -> 3) and -1 SENDB (4 -> 3), all four numbers
  # from a real whole-program diagnostic run, not projected.
  #
  # Real bytecode shape, confirmed by a fresh `mrbc -v` disassembly of a
  # minimal reproduction (mruby 4.0.0, `/tmp/freshbuild` host mrbc), NOT
  # assumed to transfer from the existing keyword path:
  #
  #   class Foo; def bar(h); h; end; def baz(a, h); [a, h]; end; end
  #   f.bar(name: 1, x: 2)     ->  19 022 LOADSYM  R3  :name
  #                                19 025 LOADI_1  R4  (1)
  #                                19 027 LOADSYM  R5  :x
  #                                19 030 LOADI_2  R6  (2)
  #                                19 032 SEND     R2  :bar   n=0|nk=2
  #   f.baz(9, name: 1, x: 2)  ->  20 039 LOADI8   R3  9
  #                                20 042 LOADSYM  R4  :name   ... R7
  #                                20 052 SEND     R2  :baz   n=1|nk=2
  #
  #   and the two callees' own real entry shapes:
  #     def bar(h)      ->  3 000 ENTER  1:0:0:0:0:0:0:0   (kw=0, kwrest=0)
  #     def baz(a, h)   ->  8 000 ENTER  2:0:0:0:0:0:0:0   (kw=0, kwrest=0)
  #   contrasted against a callee that really DOES take keywords:
  #     def kw(a, name: nil, x: 0)
  #                     -> 13 000 ENTER  1:0:0:0:2:0:0:0   (kw=2)
  #                        13 004 KEY_P  R4 :name  ... KARG ... KEYEND
  #
  # So the call-site register layout is exactly the one compile_keyword_send
  # above already computes (n positionals at d+1.., then K (sym, value)
  # pairs) -- unchanged -- and the DECIDING fact is on the callee: ENTER's
  # own `kw`/`kwrest` fields.
  #
  # Real VM semantics, read from real 3rd/mruby/src/vm.c (mruby 4.0.0,
  # submodule 831da26b9), in two separate places:
  #
  #   1. OP_SEND, vm.c:2283-2288 -- the packing is UNCONDITIONAL and knows
  #      nothing about the callee:
  #        else if (nk > 0) {  /* pack keyword arguments */
  #          mrb_int kidx = a+(n==CALL_MAXARGS?1:n)+1;
  #          mrb_value kdict = hash_new_from_regs(mrb, nk, kidx);
  #          regs[kidx] = kdict;
  #          nk = CALL_MAXARGS;
  #      i.e. the K (sym, value) register pairs ALWAYS become one real Hash
  #      object sitting at `kidx = d+n+1`, before the callee is entered.
  #      `hash_new_from_regs` (vm.c:1641) is the same `mrb_hash_new_capa` +
  #      `mrb_hash_set` loop this file's own OP_HASH codegen already emits.
  #
  #   2. OP_ENTER, vm.c:2573 and 2589-2611 -- the callee decides what that
  #      Hash MEANS:
  #        mrb_int kd = (MRB_ASPEC_KEY(a) > 0 || MRB_ASPEC_KDICT(a))? 1 : 0;
  #        ...
  #        if (!kd) {
  #          if (!mrb_nil_p(kdict) && mrb_hash_p(kdict) && mrb_hash_size(mrb, kdict) > 0) {
  #            if (argc < 14) {
  #              ci->n++;
  #              argc++;    /* include kdict in normal arguments */
  #            }
  #            ...
  #          }
  #          kdict = mrb_nil_value();
  #          ci->nk = 0;
  #      i.e. when the callee declares neither named keywords nor `**rest`
  #      (`kd == 0`), the packed Hash is APPENDED TO THE POSITIONAL ARGUMENT
  #      LIST and the call is, from that point on, an ordinary positional
  #      call with `ci->nk == 0`.
  #
  # Therefore the exact, complete translation for this shape is: build the
  # Hash from the same K register pairs, then perform an ORDINARY positional
  # call with N+1 arguments. Nothing keyword-specific survives into the
  # emitted code at all -- which is precisely why `mrb_funcall` is usable
  # here even though compile_keyword_call's own top comment correctly rules
  # it out for a REAL keyword call: vm.c:740's own `ci->nk = 0; /* funcall
  # does not support keyword arguments */` is not a limitation here, it is
  # exactly the state OP_ENTER would have produced anyway.
  #
  # The soundness gate is `keyword_hash_positional_callee?(irep, n + 1)` on
  # EVERY def the closed-world registry knows for this name:
  #   - it requires ENTER's key/kdict fields to be zero (so `MRB_ASPEC_KEY == 0
  #     && MRB_ASPEC_KDICT == 0`, exactly the `kd == 0` the vm.c arm above turns
  #     on) and rest/post/block/noblock to be zero, leaving only an optional
  #     `= default` positional count. KEYWORD_HASH_POSITIONAL_OPTIONAL_ARG_SUPPORT
  #     widened this off `pure_mandatory_arity?`'s all-fields-zero demand: a
  #     trailing `= default` optional positional is NOT a hazard for the
  #     trailing-Hash translation -- the VM just binds the packed Hash to the
  #     next free slot (mandatory, else optional) exactly as it binds
  #     `foo(k: v)`'s Hash to `def foo(a, b = 1)`'s own `b`. What still IS a
  #     hazard and stays excluded is a `*rest`/`&blk` callee, where the trailing
  #     Hash's landing slot is not statically fixed.
  #   - `total.between?(mand, mand + opt)` is the "+1" the `ci->n++` above
  #     performs, checked against the real signature: the exact argc range OP_ENTER
  #     accepts without raising, so a Ruby call site that would raise never
  #     becomes a silently-passing C++ call.
  #   - Requiring it of EVERY registry def (not just a MONO one) is what
  #     makes the emitted DYNAMIC dispatch sound: `mrb_funcall` resolves the
  #     real method at runtime, so every def that could possibly answer this
  #     name has to agree that the trailing Hash is a positional. That is
  #     exactly what separates `:load_h` (five defs, all `(h)`, compiled)
  #     from `:close_message` (two defs that disagree, left alone).
  #   - Any `<native>` def of the name fails the `t.irep` check outright: a
  #     native method's real argument spec is invisible to this compiler, so
  #     it can never be proven keyword-free. This is what (correctly) keeps
  #     the eight `:new` sites out.
  #   - `n < 14` mirrors vm.c's own `if (argc < 14)` fast arm above; the
  #     `argc == 14` / `argc == 15` arms pack arguments into an Array
  #     instead, a different shape this does not model.
  #
  # KEYWORD_HASH_LEXICAL_SELF_SUPPORT: when that every-registry-def gate
  # fails -- the `:close_message`-style case above, or optcarrot probe's
  # `Optcarrot::PPU#initialize`'s own `reset(mapping: false)` (disassembles
  # to `SEND :reset n=0|nk=1`; every OTHER `#reset` in that closed world --
  # NES/CPU/APU/Pads -- is 0-arg, so no 1-positional arity agrees with all
  # of them program-wide, exactly why the gate exists) -- one more sound
  # question can still decide THIS site: an implicit-self send inside a
  # method of class C, where `lexical_self_keyword_target` has proven C has
  # no subclass anywhere in the closed world and C's own def of this name is
  # compiled clean, can only ever reach C's def, however many unrelated
  # classes disagree under the same name. The gate then runs against THAT
  # def alone -- `keyword_hash_positional_callee?(C's irep, n + 1)` -- and
  # the emitted `mrb_funcall(self, name, n + 1, hash)` resolves at runtime
  # to exactly the def that was proven reachable, so the POLY-ness of the
  # name costs nothing. Same selector, same guards (implicit-self-only,
  # `devirt_blocked_name?`, no-subclass, compiles-clean) and same reasoning
  # LEXICAL_SELF_KEYWORD_SUPPORT already applies on the real-keyword side;
  # the emitted text keeps the `KEYWORD_HASH_POSITIONAL` marker kind (a
  # dynamic bind, per RUNTIME_DEF_DYNAMIC_MARKERS), only its prose differs.
  #
  # Deliberately dynamic-dispatch-only (`mrb_funcall`, never a devirtualized
  # MONO/TYPED direct `_impl` call), the same scoping choice SPLAT_UNROLL_
  # SUPPORT's own plain-positional case already documents and for the same
  # reason: getting these previously-#error'd call sites compiling AT ALL is
  # this round's goal, and layering the existing MONO/POLY/TYPED
  # devirtualization on top of an N+1-argument positional call built this
  # way is a clean, independent follow-up. Note that once the Hash is built
  # this really is an ordinary positional call, so unlike a real keyword
  # call there is no obstacle to that follow-up at all.
  #
  # KEYWORD_HASH_DEVIRT_SUPPORT: that follow-up, now built. Once the Hash
  # is packed, the call is an ordinary positional send of `total = n + 1`
  # arguments, so every positional devirtualization this file already
  # knows applies unchanged -- tried in the same order compile_send
  # itself uses, MONO first, then the POLY_SMALL_N runtime-class-checked
  # chain:
  #   - MONO: `monomorphic_target` (RUNTIME_DEF guard, one bytecode def,
  #     compiles clean -- all reused verbatim) plus the callee-shape
  #     checks the positional MONO path also makes: pure-mandatory-or-
  #     optional arity, `total` inside `[mand, mand + opt]` (the trailing
  #     Hash fills a mandatory or optional slot exactly the way
  #     CALLSITE_OPTIONAL_ARG_SUPPORT already models for a caller-
  #     supplied optional), the ONLY_OWNERS emission gate, and no
  #     NATIVE_ARG_TARGETS-typed positions (this path does no call-site
  #     unboxing -- a NATIVE_ARG callee would need `mrb_as_int` splices
  #     this emitter does not build; declining is today's behavior).
  #     The optional-positional padding (`mrb_nil_value()` placeholders
  #     plus the trailing `bc2cpp_given_opt` literal) is spliced exactly
  #     the way compile_keyword_call's own KEYWORD_CALLSITE_OPTIONAL_
  #     POSITIONAL_SUPPORT already does for the same callee shape.
  #   - POLY_SMALL_N: `compile_poly_small_n` reused verbatim with the
  #     Hash appended and effective arity `total` -- its own candidate
  #     filter (pure-mandatory, exact arity, clean, emitted, no native
  #     args) already encodes everything this path needs, and its
  #     `mrb_funcall` fallback already passes the same extended argv.
  # TYPED is deliberately absent: it needs irep/idx/owner_def trace
  # context this function does not receive, and every real site this
  # round measured resolves under MONO or POLY_SMALL_N already -- see
  # this method's own comment for the shape that would motivate
  # threading it through.
  # A distinct `KEYWORD_HASH_DEVIRT` marker (never bare `MONO`/`POLY`)
  # so the generated text stays auditable per mechanism, the same
  # marker discipline every other path in this file already follows.
  #
  # Returns the emitted C++, or nil for "not this shape" (the caller keeps
  # the honest #error). Never guesses.
  def compile_keyword_hash_positional_send(name:, d:, recv:, n:, nk:, argv:, kw_sym_regs:,
                                           kw_val_regs:, kw_names:, self_implicit:, owner_def:)
    # vm.c's own `if (argc < 14)` arm -- see this method's own comment.
    return nil unless nk.positive? && n < 14

    defs = @registry[name]
    return nil if defs.nil? || defs.empty?

    total = n + 1
    all_keyword_free = defs.all? do |t|
      # A native def's real argument spec is invisible here, so it can never
      # be proven keyword-free.
      next false unless t.irep

      callee_irep = @ireps[t.irep]
      next false unless callee_irep

      keyword_hash_positional_callee?(callee_irep, total)
    end

    # KEYWORD_HASH_LEXICAL_SELF_SUPPORT: the name-based gate above declined;
    # retry the whole question against the ONE def this implicit-self site
    # can actually reach (see this method's own comment for the full
    # argument). A nil -- or a def of that name the owner does not itself
    # declare, or one that fails the same callee gate -- is the safe miss,
    # exactly the honest `#error` this path always was.
    lexical_self = nil
    unless all_keyword_free
      lexical_self = lexical_self_keyword_target(name, self_implicit: self_implicit, owner_def: owner_def)
      return nil unless lexical_self

      callee_irep = @ireps[lexical_self.irep]
      return nil unless callee_irep && keyword_hash_positional_callee?(callee_irep, total)
    end

    out = String.new
    if lexical_self
      out << "  // KEYWORD_HASH_POSITIONAL :#{name} (n=#{n}|nk=#{nk}) -- POLY name program-wide, but this " \
             "is an implicit-self call inside a #{lexical_self.owner} method and #{lexical_self.owner} has " \
             "NO SUBCLASS anywhere in this closed world, so the only def this send can reach is " \
             "#{lexical_self.owner}##{name}, which declares NO keyword parameters and accepts #{total} " \
             "positional arguments; real src/vm.c OP_ENTER (`if (!kd) { ... ci->n++; argc++; }`) delivers " \
             "the #{nk} keyword pair(s) to exactly it as ONE ordinary trailing positional Hash, as built " \
             "here by OP_SEND's own hash_new_from_regs. Not a keyword call at runtime at all.\n"
    else
      owners = defs.map(&:owner).join(', ')
      out << "  // KEYWORD_HASH_POSITIONAL :#{name} (n=#{n}|nk=#{nk}) -- every real def of this name " \
             "(#{owners}) declares NO keyword parameters and accepts #{total} positional arguments, " \
             "so real src/vm.c OP_ENTER (`if (!kd) { ... ci->n++; argc++; }`) delivers the " \
             "#{nk} keyword pair(s) as ONE ordinary trailing positional Hash, exactly as built here by " \
             "OP_SEND's own hash_new_from_regs. Not a keyword call at runtime at all.\n"
    end
    out << "  {\n"
    out << "    mrb_value bc2cpp_kwh = mrb_hash_new_capa(M, #{nk});\n"
    nk.times do |k|
      out << "    mrb_hash_set(M, bc2cpp_kwh, r#{kw_sym_regs[k]}, r#{kw_val_regs[k]});" \
             "  // :#{kw_names[k]}\n"
    end
    out << "    #{keyword_hash_devirt_line(name: name, d: d, recv: recv, argv: argv, total: total)}"
    out << "  }\n"
    out
  end

  # KEYWORD_HASH_DEVIRT_SUPPORT's own dispatch tail: given the packed-Hash
  # call `(recv, *argv, bc2cpp_kwh)` of effective arity `total`, try MONO,
  # then the POLY_SMALL_N chain, else the same dynamic dispatch this path
  # always emitted. Factored out of compile_keyword_hash_positional_send
  # itself (rather than inlined there) so the two resolutions read as one
  # ordered list instead of nesting three levels deep inside the Hash
  # prologue builder.
  def keyword_hash_devirt_line(name:, d:, recv:, argv:, total:)
    ext_argv = argv + ['bc2cpp_kwh']
    target = monomorphic_target(name)
    if target
      t_irep = @ireps.fetch(target.irep)
      t_mand = mandatory_arity(t_irep)
      t_opt = optional_arity(t_irep)
      if pure_mandatory_or_optional_arity?(t_irep) &&
         total.between?(t_mand, t_mand + t_opt) &&
         native_arg_types(target, t_mand).compact.empty? &&
         (!@only_owners || @only_owners.include?(target.owner) || @other_owners&.include?(target.owner))
        impl = cpp_name(target.owner, target.name) + '_impl'
        call_argv = ext_argv.dup
        if t_opt.positive?
          call_argv += Array.new(t_mand + t_opt - ext_argv.size, 'mrb_nil_value()')
          call_argv << (ext_argv.size - t_mand).to_s
        end
        return "  // KEYWORD_HASH_DEVIRT :#{name} -> #{target.owner}##{target.name} (MONO, trailing-Hash " \
               "positional, direct C++ call, no mrb_funcall)\n" \
               "    r#{d} = #{impl}(M, #{([recv] + call_argv).join(', ')});\n"
      end
    end
    chained = compile_poly_small_n(name, d, recv, ext_argv, total)
    return chained.sub('POLY_SMALL_N', 'KEYWORD_HASH_DEVIRT/POLY_SMALL_N') if chained

    dynamic_dispatch_line(d, recv, name, ext_argv)
  end

  # KEYWORD_NEVER_DEFINED_CONST_RECEIVER_SUPPORT: the memoized closed-world
  # universe of defined constant names (IntegerConstants.defined_name_universe
  # -- same ENV gate as INTEGER_CONSTANT_PROOF's own skip-outright rule: a
  # missing NATIVE_SRCS/FOREIGN_RUBY_SRCS means the picture is knowingly
  # incomplete, so no proof runs at all rather than one run half-informed).
  def keyword_never_defined_universe
    return @keyword_never_defined_universe if defined?(@keyword_never_defined_universe)

    @keyword_never_defined_universe =
      if ENV['NATIVE_SRCS'] && ENV['FOREIGN_RUBY_SRCS']
        IntegerConstants.defined_name_universe(@ireps, Shellwords.split(ENV['NATIVE_SRCS']),
                                               Shellwords.split(ENV['FOREIGN_RUBY_SRCS']))
      end
  end

  # KEYWORD_NEVER_DEFINED_CONST_RECEIVER_SUPPORT: a keyword SEND whose
  # receiver is the value of a bare capitalized constant that is DEFINED
  # NOWHERE in the closed world. Both keyword-free proofs above need a callee
  # argument spec to fold against and honestly decline when one cannot be
  # seen -- but they are answering a question this site does not need asked,
  # because the send is DYNAMICALLY UNREACHABLE, and the proof is a chain of
  # three closed-world facts, each read from machinery this file already
  # trusts:
  #
  #   1. NEVER-DEFINED: the receiver's constant name is absent from
  #      IntegerConstants.defined_name_universe -- every definition form a
  #      constant can arrive through in this program: SETCONST/SETMCNST/
  #      CLASS/MODULE opcodes across every scanned irep, the native
  #      mrb_define_const/mrb_const_set/mrb_define_class/mrb_define_module
  #      text scan, and the foreign-source `NAME =`/class/module scan.
  #   2. UNREACHABLE SEND: compile_insn compiles such a GETCONST to the
  #      bc2cpp_const_try scope chain, whose final arm is the real
  #      mrb_const_get against Object -- and mruby's own src/variable.c
  #      mrb_const_get raises NameError for a name no scope in the chain
  #      defines (the same chain every never-defined `Foo` read in this
  #      program already compiles to, and the only reason a `defined?`-free
  #      optional integration hook like this one works in Ruby at all is the
  #      guard ABOVE it -- see 3). So step 1 alone makes the GETCONST raise
  #      every time it executes.
  #   3. THIS SEND IS BEHIND IT: the backward scan (the house pattern,
  #      literal_symbol_write's own) shows the receiver register's FIRST
  #      write before the call is that GETCONST and only that GETCONST
  #      (any other first writer, or no writer, is a safe miss), and no
  #      jump/catch-handler target lands strictly between the GETCONST and
  #      the send -- so no control-flow edge reaches the send without
  #      executing the GETCONST (which raised) first. Control can only ever
  #      enter an irep at its own start, so cross-irep entries cannot slip
  #      in mid-range either.
  # The emitted dispatch is therefore never executed; what it emits is the
  # faithful OP_SEND shape anyway (keyword pairs packed by vm.c's own
  # unconditional hash_new_from_regs into ONE trailing positional Hash, then
  # the ordinary dynamic dispatch) so a hypothetical proof break shows a
  # wrong-but-well-formed send, never a mispacked argument list. Dispatch
  # stays `mrb_funcall` -- no devirt, no marker-vs-runtime-def interaction to
  # reason about (a runtime-installed def could change WHAT the send finds,
  # but nothing runs this far to observe it).
  #
  # Holes, stated and MEASURED rather than assumed (the closed-world
  # assumption every whole-program gate here already shares): a name built at
  # runtime (`const_set`) or installed by a source outside the scanned set
  # (`require`d gem not in NATIVE_SRCS, an `eval`'d string) escapes the
  # universe scan. `grep -rn const_set` across 3rd/mruby/mrblib, mruby
  # mrbgems' Ruby sources and 3rd/optcarrot/lib: no uses. optcarrot's own
  # `eval`s (cpu.rb/ppu.rb, codegen of handlers) sit on the `--opt` build
  # path only -- already documented as outside the probe's default-compile
  # scope in tools/optcarrot_probe/README.md -- and none define constants.
  # The real shape this exists for: optcarrot probe's `NES#run` --
  # `046 GETCONST R3 StackProf` ... `072 SEND R3 :start n=0|nk=3`, guarding
  # the optional stackprof integration (`if @conf.stackprof_mode`), with
  # `StackProf` defined nowhere in that closed world.
  def compile_keyword_never_defined_const_send(name:, d:, n:, nk:, irep:, idx:, argv:,
                                               kw_sym_regs:, kw_val_regs:, kw_names:,
                                               self_implicit:)
    return nil if self_implicit
    return nil unless nk.positive?

    universe = keyword_never_defined_universe
    return nil if universe.nil?

    send_insn = irep.instructions[idx]
    return nil unless send_insn && send_insn.op == 'SEND'

    recv_reg = d.to_i
    write = nil
    (idx - 1).downto(0) do |i|
      insn = irep.instructions[i]
      next unless insn
      # A write to the receiver register ends the scan -- it must be the
      # constant read itself (same first-writer rule literal_symbol_write
      # uses for the keyword keys).
      next unless insn.args =~ /^R#{recv_reg}\b/

      write = insn
      break
    end
    return nil unless write && write.op == 'GETCONST'

    const_name = write.args[/^R\d+\s+(\S+)/, 1]
    return nil unless const_name&.match?(/\A[A-Z][A-Za-z_0-9]*\z/)
    return nil if universe.include?(const_name)

    # No jump target, and no raise-handler entry, may land strictly inside
    # (write, send] -- such an edge would reach the send WITHOUT executing
    # the GETCONST that proves it dead.
    blocked = jump_targets(irep)
    irep.catch_handlers&.each { |ch| blocked << ch.target }
    return nil if blocked.any? { |t| t > write.addr && t <= send_insn.addr }

    out = String.new
    out << "  // KEYWORD_NEVER_DEFINED_CONST :#{name} (n=#{n}|nk=#{nk}) -- receiver is the value of " \
           "GETCONST `#{const_name}` (addr #{write.addr}), a constant with NO definition anywhere in this " \
           "closed world (no SETCONST/SETMCNST, no CLASS/MODULE, no native mrb_define_const/const_set/" \
           "define_class/define_module, no foreign-source assignment), so that GETCONST's own scope-chain " \
           "raises NameError and this send is dynamically unreachable -- no jump or handler entry lands " \
           "between the two. The keyword packing and real dynamic dispatch emitted below are the " \
           "faithful OP_SEND shape for a call that cannot execute.\n"
    out << "  {\n"
    out << "    mrb_value bc2cpp_kwh = mrb_hash_new_capa(M, #{nk});\n"
    nk.times do |k|
      out << "    mrb_hash_set(M, bc2cpp_kwh, r#{kw_sym_regs[k]}, r#{kw_val_regs[k]});" \
             "  // :#{kw_names[k]}\n"
    end
    out << "    #{dynamic_dispatch_line(d, "r#{d}", name, argv + ['bc2cpp_kwh'])}"
    out << "  }\n"
    out
  end

  # SPLAT_UNROLL_SUPPORT: "what argument expressions does the literal
  # Array built at `reg` (traced backward from just before `idx`, MOVE
  # chains followed) actually hold?" -- the register-LIST analogue of
  # array_element_source_scan's own ARRAY arm, for compile_splat_send
  # below. A splat call site (`n=*`) never gets a fixed register list
  # from mrbc's own disassembly the way an ordinary `n=N` call does
  # (confirmed against real src/vm.c OP_SEND: when `n==CALL_MAXARGS`, the
  # VM spreads whatever real Array object already sits in R(d+1) at
  # *runtime*) -- so the only way to recover a fixed list at COMPILE time
  # is proving that source register was itself just built by a literal
  # `ARRAY Rd N` a few instructions back, never a computed/variable
  # array.
  #
  # Deliberately `mrb_ary_ref(M, r<base>, k)`, never the raw `r<base+k>`
  # source registers ARRAY's own N-1 non-zeroth registers would still
  # hold: real OP_ARRAY semantics overwrite `r<base>` ITSELF with the
  # constructed Array object (`compile_insn`'s own ARRAY case, "the
  # result overwrites Rd itself" -- Rd is element 0's own register). A
  # bare `r<base>` for element 0 would silently read that already-
  # clobbered Array object instead of the real first argument -- caught
  # live building this exact feature (Game::Battle::AllTargetSkillCommand.
  # new(*args)'s own real generated call passed the freshly-built Array as
  # its own first positional argument instead of the real value, before
  # this fix). Reading every element back out of the array object mrbc's
  # own codegen already built sidesteps the clobber entirely, for
  # elements 0 and 1..N-1 alike -- one rule, not an off-by-one special
  # case for index 0 only.
  #
  # Returns an Array of C++ expression Strings ("mrb_ary_ref(M, r5, 0)",
  # ...), or nil for "not a traceable literal" (the caller keeps the
  # honest #error).
  def splat_array_literal_regs(irep, idx, reg)
    hops = 0
    (idx - 1).downto(0) do |i|
      insn = irep.instructions[i]
      next unless insn
      # Same reasoning as array_element_source_scan's own BLOCK skip: a
      # block-carrying call's own block-proc register sits between the
      # call and its receiver write, evidence FOR the shape rather than
      # a writer of it.
      next if insn.op == 'BLOCK'
      next unless insn.args[/^R(\d+)/, 1] == reg

      case insn.op
      when 'MOVE'
        hops += 1
        return nil if hops > 8

        src = insn.args.scan(/R(\d+)/).flatten[1]
        return nil unless src

        reg = src
        next
      when 'ARRAY', 'ARRAY2'
        n = insn.args[/^R\d+\s+(\d+)/, 1]&.to_i
        return nil if n.nil?

        base = reg.to_i
        return (0...n).map { |k| "mrb_ary_ref(M, r#{base}, #{k})" }
      else
        return nil
      end
    end
    nil
  end

  # SPLAT_UNROLL_SUPPORT: the Hash-double-splat analogue of
  # splat_array_literal_regs above -- traces the register backward for a
  # literal `HASH Rd N` (N key/value PAIRS spanning Rd..Rd+2N-1, the same
  # real layout HashElementLayout's own hash_element_source_scan already
  # confirmed against src/vm.c's OP_HASH), and additionally requires
  # every key to be a literal `LOADSYM` -- a computed key has no static
  # name to match against the callee's own keyword table (the same bar
  # compile_keyword_send's own ordinary keyword-pair extraction already
  # holds itself to). Returns an Array of `{name:, val_reg:}` Hashes (one
  # per pair, in source order), or nil for "not a traceable all-literal-
  # key Hash".
  def splat_hash_literal_pairs(irep, idx, reg)
    hops = 0
    (idx - 1).downto(0) do |i|
      insn = irep.instructions[i]
      next unless insn
      next if insn.op == 'BLOCK'
      next unless insn.args[/^R(\d+)/, 1] == reg

      case insn.op
      when 'MOVE'
        hops += 1
        return nil if hops > 8

        src = insn.args.scan(/R(\d+)/).flatten[1]
        return nil unless src

        reg = src
        next
      when 'HASH'
        n = insn.args[/^R\d+\s+(\d+)/, 1]&.to_i
        return nil if n.nil?

        base = reg.to_i
        return (0...n).map do |k|
          key_reg = base + (2 * k)
          val_reg = base + (2 * k) + 1
          kname = literal_symbol_write(irep, i - 1, key_reg.to_s)
          return nil unless kname

          { name: kname, val_reg: "r#{val_reg}" }
        end
      else
        return nil
      end
    end
    nil
  end

  # SPLAT_UNROLL_SUPPORT: a `SEND`/`SSEND` call site whose own arg list is
  # a splat (`n=*`) and/or a double-splat (`nk=*`) -- previously an
  # unconditional #error (see this method's own caller, the `n_match`
  # branch in compile_send) -- compiles as an ordinary call when the
  # splatted Array/Hash traces back to a compile-time-fixed-size LITERAL
  # (splat_array_literal_regs/splat_hash_literal_pairs above), rather
  # than a runtime-variable expression this codegen has no fixed
  # register list for. Anything not traceable to such a literal (a
  # splatted local variable, a computed array/hash, a non-literal key in
  # a double-splat) keeps the honest #error -- this never guesses.
  #
  # Deliberately dynamic-dispatch-only for the plain-positional case
  # (dynamic_dispatch_line, never a devirtualized MONO/POLY/TYPED call):
  # getting these previously-#error'd call sites compiling correctly at
  # all is this round's own goal; layering MONO/POLY/TYPED
  # devirtualization on top of an unrolled splat call is a natural
  # follow-up once this lands, exactly like every other "proven, wired,
  # not yet the fastest path" round this file's own history already has
  # plenty of. A keyword-carrying unroll (double-splat, or a literal
  # keyword-pair tail riding alongside a positional splat) reuses
  # compile_keyword_call's own MONO-direct-_impl-call machinery instead
  # -- mruby's own `mrb_funcall*` family can never carry keywords at all
  # (compile_keyword_send's own top comment), so a dynamic-dispatch
  # fallback isn't an option there the way it is for the plain-
  # positional case.
  #
  # DYNAMIC_SPLAT_SUPPORT: a plain positional splat (`n=*`, no `|nk=` at
  # all) whose source ISN'T a compile-time literal -- `foo(*list)`, the
  # overwhelming majority of real splat call sites in this program --
  # still doesn't need to stay an honest #error: real `mrbc` codegen
  # (confirmed by a fresh `mrbc -v` run, not assumed) ALWAYS builds the
  # complete, real Array of positional arguments into `R(dest+1)` before
  # a `SEND ... n=*` ever executes (an `ARRAY`-then-`ARYCAT` chain for a
  # leading non-splat argument, `bar(a, *list)`; a `LOADNIL`-then-`ARYCAT`
  # chain when the call's own first argument is itself a splat, `bar(*list,
  # *list2)` -- see ARYCAT's own compile_insn comment, the same real
  # bytecode reading that caught and fixed that case's own latent `R[a]`
  # nil-handling gap). So `R(dest+1)` is ALWAYS a genuine, fully-built
  # `mrb_value` Array by the time this SEND runs, real receiver and
  # argument count included -- `mrb_funcall_argv` (mruby.h, MRB_API,
  # exactly the public "call with a real argc/argv pair" entry point this
  # file's own dynamic-dispatch fallback already leans on for every other
  # shape) accepts that `RARRAY_LEN`/`RARRAY_PTR` pair directly, with no
  # per-element unrolling needed at all. Scoped to the plain-positional
  # case only, same reason the literal path above stays dynamic-dispatch-
  # only for keywords: `mrb_funcall*` can never carry keywords, so a
  # non-literal double-splat (`nk=*`) or keyword tail alongside a
  # non-literal positional splat has no sound translation here and keeps
  # the honest #error.
  def compile_dynamic_splat_send(name, recv, d, argv_reg)
    <<~CPP
      // SPLAT n=* :#{name} runtime-sized (not a literal), dynamic dispatch via mrb_funcall_argv
      r#{d} = mrb_funcall_argv(M, #{recv}, mrb_intern_cstr(M, "#{name}"), RARRAY_LEN(r#{argv_reg}), RARRAY_PTR(r#{argv_reg}));
    CPP
  end

  def compile_splat_send(args, self_implicit:, irep:, idx:, name:, d:, owner_def: nil)
    return nil unless irep && idx

    n_match = args.match(/n=(\d+|\*)(?:\|nk=(\d+|\*))?/)
    return nil unless n_match

    n_spec, nk_spec = n_match[1], n_match[2]
    return nil unless n_spec == '*' || nk_spec == '*'

    dest_reg = d.to_i
    recv = self_implicit ? 'self' : "r#{d}"

    next_reg = dest_reg + 1
    if n_spec == '*'
      positional = splat_array_literal_regs(irep, idx, next_reg.to_s)
      if positional.nil?
        return nil if nk_spec

        return compile_dynamic_splat_send(name, recv, d, next_reg)
      end

      next_reg += 1 # the single register the splatted array itself occupied.
    else
      n = n_spec.to_i
      positional = (1..n).map { |k| "r#{dest_reg + k}" }
      next_reg += n
    end

    kw_pairs =
      if nk_spec == '*'
        pairs = splat_hash_literal_pairs(irep, idx, next_reg.to_s)
        return nil unless pairs

        pairs
      elsif nk_spec
        nk = nk_spec.to_i
        (0...nk).map do |k|
          key_reg = next_reg + (k * 2)
          val_reg = next_reg + (k * 2) + 1
          kname = literal_symbol_write(irep, idx, key_reg.to_s)
          return nil unless kname

          { name: kname, val_reg: "r#{val_reg}" }
        end
      else
        []
      end

    if kw_pairs.empty?
      note = "  // SPLAT #{n_match[0]} :#{name} unrolled from a literal-sized splat, dynamic dispatch\n"
      "#{note}  #{dynamic_dispatch_line(d, recv, name, positional)}"
    else
      result = compile_keyword_call(name: name, d: d, recv: recv, n: positional.size, argv: positional,
                                     kw_names: kw_pairs.map { |p| p[:name] },
                                     kw_val_exprs: kw_pairs.map { |p| p[:val_reg] },
                                     self_implicit: self_implicit, owner_def: owner_def)
      return nil unless result

      note = "  // SPLAT #{n_match[0]} :#{name} unrolled from a literal-sized splat/double-splat\n"
      "#{note}#{result}"
    end
  end

  def compile_send(args, self_implicit:, irep: nil, idx: nil, owner_def: nil,
                   call_receiver: nil, call_arguments: nil, trace_idx: nil, trace_receiver_reg: nil,
                   trace_reg_offset: 0, typed_fallback: nil)
    # ELEMENT_CLASS_SUPPORT: consume-and-clear. The hint is published by
    # with_element_hint for exactly the one instruction being translated
    # right now, and taking it down here (before ANY other work, including
    # the compiles_clean? probes further down that re-enter compile_method
    # for unrelated bodies) is what makes it impossible for a second,
    # unrelated call site to read a hint that was never about it.
    elem_class_hint = @elem_class_hint
    @elem_class_hint = nil
    d = args[/^R(\d+)/, 1]
    # Real bug, caught by running against real code: this charset omitted
    # `?` -- every predicate-style method name (`rpg2003?`, `key?`, `eof?`,
    # `is_a?`, `respond_to?`, ...) got silently truncated to its non-`?`
    # prefix here, so a compiled call site would `mrb_funcall` a *different,
    # usually-undefined* method name (e.g. "key" instead of "key?"), a real
    # NoMethodError at runtime that a #error-based check can never catch
    # (the generated C++ itself compiles and links fine -- it just calls the
    # wrong Ruby method). `!`-suffixed names (`empty!`, ...) were already
    # covered; `?` needed the same treatment.
    #
    # A second, materially worse real bug in this same charset, caught
    # building Game::ChipSet and confirmed independently against the real
    # generated output for every already-shipped class, not just the
    # triggering one: this charset also omitted every bitwise/unary
    # operator character (`&`, `|`, `^`, `~`, `%`, and the unary-method
    # suffix `@` for `-@`/`+@`). A call site sending one of those names
    # (`flags & DIR_BIT[dir]`, a real Integer#& send; mrbc's own
    # disassembly prints "R6\t:&\tn=1", exactly the same shape as any
    # other operator SEND) matched *nothing* after the colon, so `name`
    # came back `nil` -- silently interpolated as `""` a few lines below
    # into `mrb_funcall(M, r6, "", 1, r7)`, an empty-string method name no
    # real Ruby method ever has. That compiles and links clean (the same
    # class of bug as the `?`-omission above -- a `#error`-marker check
    # can never catch it) but raises a real NoMethodError the first time
    # it actually runs.
    #
    # Confirmed LIVE in already-shipped, already-building code, and far
    # more widespread than the one triggering case: a direct grep of the
    # real generated `rpg2k_compiled_gen.cpp` for this exact broken
    # `mrb_funcall(M, <reg>, "", ...)` shape found 41 call sites across 33
    # distinct already-registered compiled methods spanning a dozen
    # classes, not just RPG2k::Scene::ChipsetEditor's own #toggled_byte/
    # #cell_color_for -- the single most common shape by far is `%` used
    # for cursor-wraparound arithmetic (`(index + delta) % list.size`),
    # hit by RPG2k::Scene::Order#move_cursor, RPG2k::Scene::EquipMenu#
    # move_slot_cursor/#update_slots/#refresh_cand_cursor/#tick_arrows,
    # RPG2k::Scene::ItemMenu#refresh_item_cursor/#refresh_teleport_cursor/
    # #tick_arrows/#update_target/#draw_target_face, RPG2k::Scene::
    # SkillMenu's own equivalent five, RPG2k::Scene::Menu#update_command/
    # #update_actor_selection/#draw_actor_face, RPG2k::Scene::StatusMenu#
    # draw_actor_face, RPG2k::Scene::DebugMenu#cycle_mode/#move_block/
    # #move_row/#update_editor, RPG2k::Scene::SaveLoad#tick_arrows/
    # #build_face_cell, RPG2k::Scene::Base#advance_list_arrow_anim,
    # RPG2k::Window#update, Game::Screen#update_shake (a `% 256` phase
    # wrap), Game::Transition#block_shuffle_rank (`% total`), and
    # RPG2k::Scene::ChipsetEditor#draw_cursor/#move_cursor (`@idx % COLS`)
    # -- i.e. every already-shipped menu's own scrolling-cursor/blink-arrow
    # logic, plus this same `%`-for-wraparound idiom wherever else it
    # appears. The remaining two sites are `&`/`|`/`~` bitwise flag work
    # (ChipsetEditor's own #toggled_byte/#cell_color_for). Every one of
    # these methods
    # was silently generating a guaranteed-NoMethodError call the moment a
    # player actually scrolled a list, moved an equip-menu cursor, or used
    # the F9 chipset editor -- this compiler's single highest-impact bug
    # so far, precisely because the affected pattern (modulo-based cursor
    # wraparound) is the single most common idiom across every menu class
    # already shipped, not an edge case. Fixed at the root (this one
    # character class, reused by every SEND-name extraction site in this
    # file, kept in sync at each of its own three other copies above); the
    # very next regen of every already-shipped class's own generated
    # output picks up the fix automatically, the same "no hand-edit
    # needed" shape this file's own IvarLayout.join fix already
    # established. See docs/adr/0139's own follow-up for the full
    # before/after verification.
    name = args[/:([\w+\-*\/<>=!?\[\]&|^~%@]+)/, 1]
    # Real, live bug, caught running against real code (Game::Battle#
    # enemy_basic_action's own `deal_attack(b, target, 0, charged: charged)`):
    # a bare `/n=(\d+)/` only recognizes a call site's real disassembly
    # shape when it passes a small fixed count of plain positional arguments
    # ("n=3"). Two other real shapes exist in mrbc's own print_args (src/
    # codedump.c) and were silently misparsed by that narrow regex instead of
    # being rejected outright:
    #   - A keyword-argument call site ("n=3|nk=1", one Symbol/value register
    #     pair per keyword) -- src/vm.c's own OP_SEND packs those nk pairs
    #     into a real Hash (hash_new_from_regs) *at runtime*, a step this
    #     codegen never replicated at all.
    #   - A splat call site ("n=*", mrbc's own CALL_MAXARGS sentinel) -- a
    #     genuinely variable argument count this codegen has no fixed
    #     register list for.
    # Neither shape matches `/n=(\d+)/` (no digits right after "n=" for a
    # splat; the keyword pair registers are simply never looked at for a
    # keyword call), and `nil.to_i` silently evaluates to 0 -- so a splat
    # call site (`move_to(*args)`, `Class.new(*args)`, ...) used to compile
    # to a real ZERO-argument mrb_funcall, silently dropping every splatted
    # argument, and a keyword call site compiled with only its real
    # positional args, silently dropping the keyword hash entirely. Confirmed
    # live, not hypothetical, in already-shipped compiled classes: `Game::
    # Battle#enemy_basic_action`/`#enemy_fallback_attack`'s own `deal_attack(
    # ..., charged: charged)` compiled to `mrb_funcall(M, self, "deal_attack",
    # 3, r10, r11, r12)` with the `:charged`/`charged` register pair computed
    # and then silently discarded -- every charged enemy attack routed
    # through either method called the real #deal_attack with its own
    # `charged: nil` default instead of the caller's real charged state.
    # `Game::Actor#knock_out!`/`Game::Battle#inflict_state`'s own `Game::
    # States.prune(ids, table, keep: permanent_states)` silently dropped
    # `keep:`, so a real permanently-protected state (`keep.include?(id)`,
    # e.g. an innate racial trait modeled as a state) could be pruned away
    # as if no exemption list existed at all. `Game::Actor#restore_class`'s
    # own `set_level(@level, preserve_mod: false)` (a real, load-bearing
    # `false` -- the very next source line's own comment explains it's
    # deliberately different from #set_level's own default of `true`)
    # silently called with `preserve_mod: true` instead, incorrectly
    # carrying stat modifiers across a class restore. `RPG2k::Scene::
    # DebugMenu#play_animation`'s own `scene.anim_target(x, y, height: nil,
    # index: nil, flash_target: nil)` is a real MANDATORY-keyword call
    # (`RPG2k::Scene::Map#anim_target(tx, ty, height:, index:,
    # flash_target:)`, no defaults at all) -- silently dropping those three
    # used to compile a call that would raise a real ArgumentError (missing
    # keyword) at runtime, not just pass a wrong value. All six of these
    # (`Game::Actor#change_class` shares #restore_class's own `set_level`
    # bug shape too, but was already excluded from compilation for an
    # unrelated reason -- a real `.each` block later in the same method
    # body, so it never actually shipped with this bug either way) were
    # removed from `mruby-rpg2k-compiled/src/register.cxx`'s own
    # registration list as part of this fix; see that file's own comments at
    # each removed line. None of this shape is in this
    # prototype's modeled subset (the top-of-file comment already excludes
    # "keyword ... params" -- this is that same exclusion, just for a CALL
    # SITE rather than a method definition), so it gets the same treatment
    # every other unmodeled shape here does: a loud #error instead of a
    # silently wrong translation, leaving the method on the interpreter
    # (SKIP_UNSUPPORTED's own established fallback) rather than shipping a
    # call that quietly drops real arguments. SEND0/SSEND0's own
    # disassembly never prints "n=" at all (mrbc's own codedump.c, and
    # src/vm.c's OP_SEND0 hardcodes c=0) -- a real, always-0-argument call,
    # not a shape to reject, so a nil match here still means n=0, exactly
    # the same fallback value `nil.to_i` used to compute (now explicit
    # instead of incidental).
    n_match = args.match(/n=(\d+|\*)(?:\|nk=(\d+|\*))?/)
    if n_match && (n_match[1] == '*' || n_match[2])
      # Keyword-argument call site (nk>0, no splat): try devirtualizing
      # into the compiled callee's own _impl (compile_keyword_send
      # below) before falling back to the honest #error.
      if n_match[1] != '*' && n_match[2] != '*' && irep && !idx.nil?
        kw_result = compile_keyword_send(args, self_implicit: self_implicit, irep: irep, idx: idx,
                                         owner_def: owner_def, name: name, d: d,
                                         n: n_match[1].to_i, nk: n_match[2].to_i)
        return kw_result if kw_result
      end
      # SPLAT_UNROLL_SUPPORT: a splat (`n=*`) and/or double-splat
      # (`nk=*`) call site: try unrolling it into an ordinary call when
      # the splatted Array/Hash traces to a compile-time-fixed-size
      # literal (compile_splat_send below) before falling back to the
      # honest #error. A splatted variable/computed expression still
      # always #errors -- no fixed register list exists for it by
      # construction.
      if irep && !idx.nil?
        splat_result = compile_splat_send(args, self_implicit: self_implicit, irep: irep, idx: idx,
                                          name: name, d: d, owner_def: owner_def)
        return splat_result if splat_result
      end
      return "  #error SEND/SSEND :#{name} has a splat and/or keyword argument list (#{n_match[0]}) -- not in this prototype's supported subset\n"
    end

    n = n_match ? n_match[1].to_i : 0
    recv = call_receiver || (self_implicit ? 'self' : "r#{d}")
    argv = call_arguments || (1..n).map { |k| "r#{d.to_i + k}" }

    # LITERAL_EQQ_SUPPORT: `case x; when LITERAL ... end`'s own desugared
    # `LITERAL === x` (a `:===` SEND whose own receiver is a bare literal
    # Fixnum or Symbol, trace_eqq_literal_receiver's own comment has the
    # exact real disassembly shape this matches) devirtualizes straight
    # past ordinary MONO/POLY registry resolution and real dynamic
    # dispatch, replicating mruby's own native `Object#===`/`#==`
    # semantics directly (3rd/mruby/src/kernel.c's own `mrb_eqq_m` ->
    # 3rd/mruby/src/object.c's own `mrb_equal`) -- see
    # eqq_literal_devirt_safe?'s own comment for the full whole-program
    # soundness argument (both `:==` and `:===` have to be registry-
    # confirmed MONO-native, re-checked live every run, not just once) and
    # trace_eqq_literal_receiver's own comment for the backward-scan
    # mechanism. Deliberately runs BEFORE monomorphic_target/the ordinary
    # POLY fallback below (`:===` itself can never devirtualize through
    # either of those anyway -- monomorphic_target always refuses a
    # native-only def, its own comment explains why -- so this changes
    # nothing about their own behavior for every other name; it only ever
    # intercepts a `:===` name that would otherwise fall straight to
    # `dynamic_dispatch_line`'s own plain `mrb_funcall` at the bottom of
    # this method). `n == 1`: real `#===`/`#==` always take exactly one
    # argument (`MRB_ARGS_REQ(1)` on both native entries, 3rd/mruby/src/
    # kernel.c) -- a `:===` SEND with any other arg count than 1 isn't
    # this shape at all (never produced by real `when` desugaring, and
    # this compiler's own SEND-arg-count parsing above already guarantees
    # `n_match` matched a plain `n=1` shape to even reach here with
    # `argv.size == 1`). `irep && idx`: same "only meaningful for an
    # explicit-receiver send with real bytecode position to scan
    # backward from" gate every other backward-scan devirtualization in
    # this method already uses (never true when self_implicit is, per
    # this method's own top comment).
    if name == '===' && n == 1 && irep && idx && eqq_literal_devirt_safe?
      literal = trace_eqq_literal_receiver(irep, idx, d)
      if literal
        arg = argv.first
        case literal[:type]
        when :symbol
          # Sound with NO runtime fallback ever needed: Symbol's own real
          # `#==` is confirmed (by the very same whole-program `:==` MONO
          # check eqq_literal_devirt_safe? just ran) to still be mruby's
          # own plain, unoverridden default (`mrb_obj_equal_m`,
          # 3rd/mruby/src/symbol.c's own ROM table) -- so `mrb_equal`'s
          # own `mrb_func_basic_p(mrb, obj1, MRB_OPSYM(eq),
          # mrb_obj_equal_m)` guard (object.c) is unconditionally TRUE for
          # a Symbol receiver, meaning `mrb_equal` NEVER dispatches at
          # all: the whole call resolves entirely off its own initial
          # `mrb_obj_eq` identity/type check (`MRB_TT_SYMBOL` case:
          # `mrb_symbol(v1) == mrb_symbol(v2)`, requiring an EXACT type
          # match first) -- true iff `arg` is this exact Symbol, false for
          # literally every other value including every other type. No
          # cross-type coercion exists for Symbol the way it does for
          # Integer below, so there is nothing a runtime fallback could
          # ever catch that this doesn't already get right.
          note = "  // LITERAL === :symbol -- `:#{literal[:name]} === arg` (case/when literal), " \
                 "Object#===/Symbol#== both confirmed native/unoverridden anywhere in this program's " \
                 "own whole-program registry -- sound unconditionally, no mrb_funcall fallback ever " \
                 "needed (see eqq_literal_devirt_safe?'s own comment).\n"
          return "#{note}  r#{d} = mrb_bool_value(mrb_symbol_p(#{arg}) && " \
                 "mrb_symbol(#{arg}) == mrb_intern_cstr(M, \"#{literal[:name]}\"));\n"
        when :fixnum
          # Sound ONLY for an exactly-Integer `arg` -- `mrb_equal`'s own
          # real logic (object.c) applies a genuine Integer<->Float
          # numeric cross-comparison BEFORE ever reaching Integer's own
          # `#==` dispatch, and -- since this project's own
          # build_config.rb unconditionally includes `mruby-bigint` for
          # every build target (`conf.gem core: 'mruby-bigint'`, inside
          # the shared `rpg_maker_gems` every target calls) -- a further
          # Integer<->Bigint cross-comparison exists too (both in
          # `mrb_equal` itself under `MRB_USE_BIGINT` and, redundantly,
          # inside Integer's own real `#==`, `int_equal`, 3rd/mruby/src/
          # numeric.c's own `MRB_TT_BIGINT` case). So `5 === 5.0` (a
          # Float, real value 5.0) is real-Ruby-TRUE, not something this
          # codegen can assume FALSE from a bare type mismatch --
          # replicating that cross-type math inline would need pulling in
          # float/bigint comparison helpers this call site has no other
          # reason to reference, so instead: only the exact same-type
          # shape (`arg` is itself `MRB_TT_INTEGER`) is handled directly
          # here (matching `mrb_obj_eq`'s own fast path for an equal
          # value, and `int_equal`'s own plain `MRB_TT_INTEGER` case for a
          # differing one -- both are exact integer comparisons, no
          # coercion, so no possible override changes the answer given
          # `:==`'s own confirmed-MONO-native status); every other runtime
          # type (Float, Bigint, String, nil, ...) falls back to ordinary
          # `mrb_funcall`, deferring to the real interpreter for exactly
          # the cases this reasoning can't safely resolve alone -- the
          # identical "fixnum-fixnum fast path, mrb_funcall otherwise"
          # shape `compile_cmp`'s own EQ codegen already established
          # above, not a new pattern.
          note = "  // LITERAL === :fixnum -- `#{literal[:value]} === arg` (case/when literal), " \
                 "Object#===/Integer#== both confirmed native/unoverridden anywhere in this program's " \
                 "own whole-program registry -- only the exact-Integer-type shape is handled directly; " \
                 "a Float/Bigint/other-typed arg falls back to real mrb_funcall (mrb_equal's own " \
                 "Integer<->Float/Bigint cross-type comparison, see this block's own top comment).\n"
          return "#{note}  if (mrb_fixnum_p(#{arg})) {\n" \
                 "    r#{d} = mrb_bool_value(mrb_fixnum(#{arg}) == #{literal[:value]});\n" \
                 "  } else {\n" \
                 "    #{dynamic_dispatch_line(d, recv, name, argv)}" \
                 "  }\n"
        end
      end
    end

    # Devirtualize a `SEND :new` whose receiver is provably (GETCONST-
    # traced, right here at this exact call site -- not the ivar/argument
    # terminal sources trace_new_target also supports) one of
    # NATIVE_CONSTRUCT_TARGETS' own native DataType<T>-backed classes.
    # `self.new`/implicit-receiver `new` (self_implicit) is never this
    # shape (these three classes' own `.new` is always sent to an explicit
    # constant receiver in every real call site this covers) so it's
    # excluded outright, same as monomorphic_target's own MONO path
    # implicitly is by never matching a bare `new` name against anything
    # meaningful for self_implicit sends. `irep`/`idx` are nil exactly
    # when self_implicit is true (see this method's own two call sites),
    # so checking them here is redundant with checking self_implicit, but
    # kept explicit since trace_new_target needs both regardless.
    if name == 'new' && !self_implicit && irep && idx
      known = trace_new_target(irep, idx, d, nil, 0, nil, resolving_new: true, owner: owner_def&.owner)
      native = known && NATIVE_CONSTRUCT_TARGETS[known]
      # Exact-arity-only (see NATIVE_CONSTRUCT_TARGETS' own comment) -- a
      # call site passing a different argument count just isn't this
      # shape, falls through to ordinary POLY dynamic dispatch below like
      # any other unmodeled variant. `arity` may also be an Array, for a
      # native #initialize with several real fixed-arity shapes (each
      # element an exact count, matched the same way -- see that table's
      # own comment).
      if native && (native[:arity] == n || (native[:arity].is_a?(Array) && native[:arity].include?(n)))
        @native_construct_used << known
        # `fn`'s own real C++ signature takes native mrb_int/mrb_float
        # parameters, not mrb_value (mruby-rgss/src/lib.cxx's own comment
        # on these three functions has the full reasoning) -- unboxed
        # right here, at the call site, with the exact same mrb_as_int/
        # mrb_as_float calls that function used to make internally before
        # this change; moving them here changes nothing observable (same
        # TypeError-raising for a bad argument), it only changes which
        # side of the call spells them out. `:object` (Sprite) needs no
        # unboxing at all -- the viewport value passes through as a plain
        # `mrb_value`, exactly as `spr_init`'s own "|o" receives it. A
        # 0-argument call site passes an explicit `mrb_nil_value()` for the
        # missing viewport -- matching what the ordinary `mrb_get_args(M,
        # "|o", &vp)` dispatch produces for the same call (`vp` stays its
        # own nil initializer) -- because the callee's own C++ signature
        # always takes the full max-arity parameter list (see
        # include/rgss_construct.hxx): a call with fewer arguments than
        # parameters would be a hard g++ arity-mismatch error, never a
        # silent default-fill.
        #
        # `type_guard` (Bitmap only, see that entry): instead of
        # unboxing-unconditionally (which RAISES on a mistyped argument),
        # check every argument's Integer tag first and fall back to
        # ordinary `mrb_funcall` when any check fails. The fallback is
        # load-bearing: a String first argument is Bitmap's own
        # legitimate file-load shape, not an error. `mrb_integer()`
        # (not `mrb_as_int()`) reads the value past the tag check --
        # the same check-then-read shape GETIDX's own Array fast path
        # already uses (`mrb_integer_p` guard, `mrb_integer` read).
        if native[:type_guard] == :int
          arg_checks = argv.map { |a| "mrb_integer_p(#{a})" }.join(' && ')
          unboxed_argv = argv.map { |a| "mrb_integer(#{a})" }
          guard = "mrb_class_ptr(#{recv}) == #{native[:class_fn]}() && #{arg_checks}"
          note_extra = " Argument tags checked first (#{arg_checks}), " \
                       "falling back to ordinary dispatch for any other shape -- " \
                       "see that entry's own `type_guard` comment."
        else
          unboxed_argv = case native[:arg_type]
                         when :int then argv.map { |a| "mrb_as_int(M, #{a})" }
                         when :float then argv.map { |a| "mrb_as_float(M, #{a})" }
                         else argv
                         end
          unboxed_argv = ['mrb_nil_value()'] if unboxed_argv.empty?
          guard = "mrb_class_ptr(#{recv}) == #{native[:class_fn]}()"
          note_extra = ''
        end
        # `:object` (Sprite) takes no unboxing, and `type_guard` (Bitmap)
        # unboxes past its tag check instead, so the note's own "unboxes
        # each argument" sentence only applies to :int/:float.
        unbox_phrase = case native[:arg_type]
                       when :int then 'unboxes each argument register with the same mrb_as_int that function used to call internally'
                       when :float then 'unboxes each argument register with the same mrb_as_float that function used to call internally'
                       else 'passes each argument register straight through as mrb_value'
                       end
        note = "  // MONO :new -> #{known}, direct native construct (mruby-rgss/src/lib.cxx's own " \
               "#{native[:fn]}) -- skips Class#new's own allocate+initialize dispatch chain entirely.\n" \
               "  // Runtime-guarded: #{known} could have been reassigned at the constant level (e.g. " \
               "`RGSS::#{known} = SomeOtherClass`) since #{native[:class_fn]}'s own class was registered " \
               "-- #{recv} is whatever this method's own existing GETCONST resolution chain above just " \
               "produced, so a reassignment there is already reflected in it; falls back to ordinary " \
               "mrb_funcall (whatever #{recv} now actually is) rather than misconstruct if it doesn't " \
               "match the real native class.#{note_extra} #{native[:fn]}'s own parameters are native mrb_int/" \
               "mrb_float, not mrb_value (except :object, passed straight through), so this call site #{unbox_phrase}, " \
               "and passes mrb_class_ptr(#{recv}) " \
               "straight through (already computed for the guard just above -- no second, redundant " \
               "mrb_class_ptr call needed).\n"
        return "#{note}" \
               "  if (#{guard}) {\n" \
               "    r#{d} = #{native[:fn]}(M, mrb_class_ptr(#{recv}), #{unboxed_argv.join(', ')});\n" \
               "  } else {\n" \
               "    #{dynamic_dispatch_line(d, recv, name, argv)}" \
               "  }\n"
      end
    end

    # Same shape as the NATIVE_CONSTRUCT_TARGETS block just above, generalized
    # to ordinary bc2cpp-COMPILED classes (DIRECT_CONSTRUCT_TARGETS' own
    # comment has the full design writeup and the real call sites this
    # covers) -- a separate `if`, not an `elsif`/shared branch, deliberately:
    # NATIVE_CONSTRUCT_TARGETS and DIRECT_CONSTRUCT_TARGETS' own owner-name
    # sets can never overlap in practice (one is hand-written native C++
    # classes, the other real Ruby classes this compiler itself compiles a
    # body for), but keeping them as two independent, self-contained checks
    # means neither can ever accidentally shadow the other's own matching
    # logic, and the already-shipped native-construct branch above stays
    # completely untouched by this addition (a second trace_new_target call
    # here re-walks the same backward scan the block above already did when
    # `known` fell through to nil there -- a harmless, cheap re-walk of a
    # single straight-line instruction range, not a correctness concern).
    if name == 'new' && !self_implicit && irep && idx
      known = trace_new_target(irep, idx, d, nil, 0, nil, resolving_new: true, owner: owner_def&.owner)
      if known && DIRECT_CONSTRUCT_TARGETS.include?(known)
        init_def = @registry['initialize'].find { |md| md.owner == known }
        # The full four-part soundness gate DIRECT_CONSTRUCT_TARGETS' own
        # comment lays out, checked live against the real registry/ONLY_
        # OWNERS this run was actually given rather than trusted from that
        # comment alone -- a future edit to either of these two classes' own
        # source (a new `self.new`/`self.allocate`, a changed #initialize
        # shape) is caught here automatically, never silently missed.
        #
        # 1/2: no custom `def self.new`/`def self.allocate` on this exact
        # class -- the same "X.singleton" pseudo-owner every def-self.x/
        # class<<self method in this file already registers under (see
        # build_registry's own SDEF/SCLASS/unfused-DEF cases).
        no_custom_new = @registry['new'].none? { |md| md.owner == "#{known}.singleton" }
        no_custom_allocate = @registry['allocate'].none? { |md| md.owner == "#{known}.singleton" }
        # 3: #initialize's own real candidate has to be a genuine, compiling,
        # pure-mandatory-arity leaf whose arity matches THIS call site's own
        # argument count -- the identical three checks the TYPED path below
        # already applies to a class-exact candidate, reused as-is (a real,
        # differently-shaped #initialize -- e.g. Game::Picture's own
        # optional-argument shape -- must never be skipped past this way).
        init_ok = init_def&.irep && pure_mandatory_arity?(@ireps.fetch(init_def.irep)) &&
                  compiles_clean?(init_def.irep) && n == mandatory_arity(@ireps.fetch(init_def.irep))
        if no_custom_new && no_custom_allocate && init_ok
          # 4: same ONLY_OWNERS/OTHER_OWNERS emission-eligibility guard the
          # MONO/TYPED paths below already apply -- an owner this run
          # doesn't itself emit (and no other gem exposes) has no real
          # `_impl`/class-accessor symbol to link against.
          owner_emitted = !@only_owners || @only_owners.include?(known) || @other_owners&.include?(known)
          if owner_emitted
            @direct_construct_used << known
            accessor = direct_construct_class_fn(known)
            init_impl = cpp_name(known, 'initialize') + '_impl'
            note = "  // MONO :new -> #{known}, direct compiled construct (bc2cpp_direct_alloc + " \
                   "#{init_impl}) -- skips Class#new's own allocate+initialize dispatch chain entirely; " \
                   "#{known}#initialize's own return value is discarded (real Ruby .new always returns " \
                   "the new object, never whatever #initialize itself returns).\n" \
                   "  // Runtime-guarded the same way NATIVE_CONSTRUCT_TARGETS' own native-construct path " \
                   "is (see that block's own comment): #{known} could have been reassigned at the constant " \
                   "level since #{accessor}'s own class was captured at gem-init, so #{recv} (this call " \
                   "site's own already-resolved GETCONST/GETMCNST receiver) is compared against it rather " \
                   "than trusted outright, falling back to ordinary mrb_funcall if they differ.\n"
            return "#{note}" \
                   "  if (mrb_class_ptr(#{recv}) == #{accessor}()) {\n" \
                   "    r#{d} = bc2cpp_direct_alloc(M, mrb_class_ptr(#{recv}));\n" \
                   "    #{init_impl}(M, #{([recv] + argv).join(', ')});\n" \
                   "  } else {\n" \
                   "    #{dynamic_dispatch_line(d, recv, name, argv)}" \
                   "  }\n"
          end
        end
      end
    end

    # NATIVE_PRIMITIVE_SENDS: devirtualize `!`/`nil?`/`is_a?`/`kind_of?`
    # straight to their real native primitive at ANY call site, entirely
    # independent of trace_new_target/TYPED's own receiver-class-guard
    # machinery -- unlike TYPED (which needs to prove the receiver's
    # *class* before it can trust a class-exact candidate), none of these
    # four need any receiver-class knowledge at all: each one's real
    # native body is exactly the same single primitive expression for
    # EVERY possible receiver, so "the name is uncontested whole-program"
    # (monomorphic_target's own registry check, reused as-is via
    # native_only_mono? below) is already the whole soundness argument,
    # with no runtime class check needed the way TYPED's own
    # `mrb_class_ptr(recv) == ...` guard is.
    #
    # monomorphic_target itself always refuses these (its own comment: a
    # native-only MONO name has no compiled `_impl` to call, and calling
    # the real native C function's raw pointer directly would leave any
    # `mrb_get_args` inside it reading a stale `mrb->c->ci` call-info
    # frame -- a real correctness bug for an ARBITRARY native method).
    # That conservatism is correct in general but overly conservative for
    # exactly these four, checked directly against the real mruby source
    # rather than assumed:
    #   - `!` (Kernel#!): 3rd/mruby/src/class.c's own `mrb_bob_not` is
    #     exactly `mrb_bool_value(!mrb_test(cv))` -- `mrb_test`
    #     (3rd/mruby/include/mruby/value.h's own `mrb_bool`,
    #     `mrb_type(o) != MRB_TT_FALSE`) is a real, always-defined macro,
    #     no `mrb_get_args` call anywhere in this body at all.
    #   - `nil?` (Kernel#nil?/NilClass#nil?): 3rd/mruby/src/kernel.c
    #     registers `mrb_false` (always `mrb_false_value()`) for Object's
    #     own `nil?`, and 3rd/mruby/src/object.c separately registers
    #     `mrb_true` (always `mrb_true_value()`) for NilClass's own
    #     `nil?` -- two distinct native C functions in real mruby, but
    #     extract_native_method_names only ever records the flat NAME
    #     "nil?" once (no owner, by design -- see that function's own
    #     comment), so the registry can't and doesn't distinguish them.
    #     Collapsing both into one expression here is still sound, not
    #     because the registry happens not to see the difference, but
    #     because both real bodies TOGETHER are exactly the single
    #     predicate `mrb_nil_p(recv)` (3rd/mruby/include/mruby/value.h:
    #     `mrb_type(o) == MRB_TT_FALSE && !mrb_fixnum(o)`, true only for
    #     the real nil value, false for every other receiver including
    #     `false` itself) -- inlining it reproduces both real native
    #     bodies' observable behavior at once, for every receiver, not
    #     just the common case.
    #   - `is_a?`/`kind_of?`: 3rd/mruby/src/kernel.c's own
    #     `mrb_obj_is_kind_of_m` (registered under both `MRB_SYM_Q(is_a)`
    #     and `MRB_SYM_Q(kind_of)`) is exactly `mrb_get_args(mrb, "c",
    #     &c); return mrb_bool_value(mrb_obj_is_kind_of(mrb, self, c));`
    #     -- `"c"` is mrb_get_args' own class/module-only format
    #     character, which raises a real TypeError for anything else
    #     BEFORE mrb_obj_is_kind_of ever runs, so the argument really is
    #     always a Class/Module by the time that call happens. Reproduced
    #     below as an explicit `mrb_class_p(arg) || mrb_module_p(arg)`
    #     runtime guard (3rd/mruby/include/mruby/value.h, both real,
    #     always-defined macros/fallback macros -- confirmed not
    #     boxing-mode-specific: value.h's own `#ifndef` guards mean the
    #     word-boxing build's own faster boxing_word.h definitions are
    #     used instead where available, value.h's plain `mrb_type(o) ==
    #     MRB_TT_CLASS`/`MRB_TT_MODULE` otherwise -- both always present
    #     either way) around the direct `mrb_obj_is_kind_of(M, recv,
    #     mrb_class_ptr(arg))` call; a non-Class/Module argument falls
    #     back to ordinary `mrb_funcall` here instead of faking the
    #     TypeError -- the exact same "loud gap over silently wrong"
    #     posture as every other unmodeled shape in this file, and the
    #     fallback raises the identical real TypeError mrb_get_args
    #     itself would have (same code path, just reached through
    #     mrb_funcall's own dispatch instead of straight-line here).
    #     `mrb_class_ptr`/`mrb_obj_is_kind_of`/`mrb_bool_value` are not
    #     new to this generated output either -- OP_RESCUE's own
    #     translation above (`when 'RESCUE'`) already emits the identical
    #     `mrb_bool_value(mrb_obj_is_kind_of(M, r#{d}, mrb_class_ptr(r#{s})))`
    #     unconditionally (safe there with no guard at all only because
    #     RESCUE_SUPPORT's own recognized shape already guarantees Rb is
    #     a Class/Module via a GETCONST immediately before it -- a
    #     narrower, call-site-specific guarantee than the general
    #     `is_a?`/`kind_of?` case here can rely on, hence the explicit
    #     runtime guard added instead).
    #   - `equal?` (Kernel#equal?/BasicObject#equal?): 3rd/mruby/src/
    #     class.c's own `mrb_obj_equal_m` is exactly `mrb_get_arg1` (this
    #     call site's own `argv.first`, already extracted) then
    #     `mrb_bool_value(mrb_obj_equal(mrb, self, arg))` --
    #     `mrb_obj_equal` is a real, public `MRB_API` (mruby.h), no struct
    #     cast, safe for any receiver/argument pair (identity comparison,
    #     `mrb_obj_eq` underneath). Also confirmed genuinely name-
    #     uncontested for real via a direct grep of every mrb_define_*/
    #     MRB_MT_ENTRY registration across this project's own NATIVE_SRCS
    #     and mrblib -- `equal?` has exactly one native registration
    #     (class.c's own Kernel-level one) and no bytecode override
    #     anywhere.
    #   - `class` (Kernel#class): 3rd/mruby/src/kernel.c's own
    #     `mrb_obj_class_m` is exactly `mrb_obj_value(mrb_obj_class(mrb,
    #     self))` -- `mrb_obj_class` is a real, public `MRB_API`, safe for
    #     any receiver (immediate or heap-allocated alike, no struct
    #     cast).
    #   - `object_id` (Kernel#object_id): 3rd/mruby/src/kernel.c's own
    #     `mrb_obj_id_m` is exactly `mrb_fixnum_value(mrb_obj_id(self))`
    #     -- `mrb_obj_id` is a real, public `MRB_API`, boxing-mode-generic
    #     (its own body branches on MRB_NAN_BOXING/MRB_WORD_BOXING/
    #     MRB_NO_BOXING internally, never a struct cast).
    #   - `keys` (Hash#keys): 3rd/mruby/src/hash.c's own `mrb_hash_keys`
    #     IS the whole native body (registered directly, no `_m` wrapper)
    #     -- also a real, public `MRB_API` (mruby/hash.h), but UNLIKE the
    #     three above it is Hash-specific: its own first line,
    #     `mrb_hash_ptr(hash)`, is an unchecked `(struct RHash*)(mrb_ptr(v))`
    #     cast with no type check inside it at all -- see
    #     compile_native_primitive_send's own KEYS_TYPE_TAG_GUARD comment
    #     for why this one, alone among the names here, needs a real
    #     runtime `mrb_hash_p` guard (an RBasic-derived-struct type-tag
    #     check, the same *kind* of check `mrb_class_p`/`mrb_module_p`
    #     above already are) before the direct call, falling back to
    #     ordinary `mrb_funcall` otherwise.
    #   - `to_s`: the one entry here that ISN'T "one native implementation,
    #     whole-program uncontested" -- native_only_mono? only ever proves
    #     the second half (no bytecode override anywhere), never the
    #     first, and `to_s` is real, live proof they're different claims:
    #     a direct grep across 3rd/mruby/src finds `mrb_ary_to_s` (Array),
    #     `mrb_str_to_s` (String), `mrb_hash_to_s` (Hash), `int_to_s`
    #     (Integer), `flo_to_s` (Float), `range_to_s` (Range), `mrb_mod_
    #     to_s` (Module/Class), and `mrb_any_to_s` (Kernel's own default,
    #     inherited by everything else) -- eight distinct native bodies
    #     the registry's `'<native>'` marker still collapses into one
    #     entry. See compile_native_primitive_send's own TO_S_TYPE_TAG_
    #     DISPATCH comment for the full per-type accounting -- only
    #     String/Integer are handled directly there (both individually
    #     verified side-effect-free by reading their real bodies, not
    #     assumed from being native-registered), with Array/Hash
    #     deliberately excluded despite having a single named
    #     implementation each: both mutate `mrb->c->ci->mid` as their own
    #     first line, real VM call-frame state a direct call from here
    #     would silently corrupt rather than merely risk a stale read.
    #     Every other tag -- Float/Range/Class-ish included -- falls
    #     through to the same `default: mrb_funcall` case, exactly like a
    #     tag this switch never heard of.
    #   - `length`: same shape as `to_s` -- `mrb_ary_size`/`mrb_str_size`/
    #     `mrb_hash_size_m` (Array/String/Hash) collapsed into one entry.
    #     Array and Hash handled directly (see compile_native_primitive_
    #     send's own LENGTH_TYPE_TAG_DISPATCH comment); String excluded
    #     because its own real body reads a macro (`RSTRING_CHAR_LEN`)
    #     defined only inside string.c itself, never in a public header,
    #     with two different real bodies gated on this project's own
    #     `MRB_UTF8_STRING` build flag -- reproducing it here would be a
    #     silent, unstated coupling to that flag's current (disabled)
    #     value rather than a proven-safe simplification.
    #   - `first`: `mrb_ary_first` (Array, optional-arg form) vs
    #     `range_beg` (Range, real separate ARGS_NONE-only registration).
    #     Both zero-argument forms are handled directly -- Array's result is
    #     reproduced under an exact-class guard because its helper reads
    #     `mrb_get_argc(mrb)`, which would observe the wrong call frame.
    #     See compile_native_primitive_send's FIRST_TYPE_TAG_DISPATCH
    #     comment for the guard and the `first(n)` arity fallback.
    #   - `dup`: exactly two real native registrations found (confirmed
    #     via a full grep across every native source this project's own
    #     closed world can see, not just 3rd/mruby/src) -- `mrb_obj_dup`
    #     (Kernel's own default, a real public `MRB_API`, safe and
    #     correct for literally any receiver except a Class/Module/
    #     singleton-class instance) and `mrb_mod_dup` (Module's own
    #     override for that one case -- static, but its three-line body
    #     is reproduced directly). See compile_native_primitive_send's own
    #     DUP_TYPE_TAG_DISPATCH comment -- the only entry in this whole
    #     table with no `mrb_funcall` fallback arm at all, because there
    #     is no third real implementation left to miss.
    #
    # `respond_to?` uses a separate positive-only fast path in
    # compile_native_primitive_send: the one-argument form converts with
    # mrb_obj_to_sym and returns true directly only when mrb_respond_to finds
    # the method. A miss keeps ordinary Ruby dispatch so the optional
    # respond_to_missing? hook runs; the two-argument include_private form
    # remains ordinary dispatch too. See that case's own comment for the
    # semantic boundary.
    if name == '[]' && n == 2 && builtin_class_send_safe?(name, %w[Array])
      start, length = argv
      fallback = dynamic_dispatch_line(d, recv, name, argv)
      return <<~CPP
          // ARRAY_SLICE_READ :[] -- exact Array and Fixnum slice only; preserve coercion and overrides
          if (mrb_array_p(#{recv}) && mrb_obj_ptr(#{recv})->c == M->array_class &&
              mrb_fixnum_p(#{start}) && mrb_fixnum_p(#{length}) &&
              !ARY_SHARED_P(mrb_ary_ptr(#{recv})) && mrb_fixnum(#{length}) >= 0 &&
              mrb_fixnum(#{length}) <= 10) {
            mrb_int bc2cpp_slice_start = mrb_fixnum(#{start});
            mrb_int bc2cpp_slice_length = mrb_fixnum(#{length});
            mrb_int bc2cpp_slice_array_length = RARRAY_LEN(#{recv});
            if (bc2cpp_slice_start < 0 && bc2cpp_slice_start >= -bc2cpp_slice_array_length) {
              bc2cpp_slice_start += bc2cpp_slice_array_length;
            }
            if (bc2cpp_slice_start < 0 || bc2cpp_slice_array_length < bc2cpp_slice_start ||
                bc2cpp_slice_length < 0) {
              r#{d} = mrb_nil_value();
            } else {
              if (bc2cpp_slice_length > bc2cpp_slice_array_length - bc2cpp_slice_start) {
                bc2cpp_slice_length = bc2cpp_slice_array_length - bc2cpp_slice_start;
              }
              if (bc2cpp_slice_length == 0) {
                r#{d} = mrb_ary_new(M);
              } else {
                r#{d} = mrb_ary_new_from_values(M, bc2cpp_slice_length,
                    RARRAY_PTR(#{recv}) + bc2cpp_slice_start);
              }
            }
          } else {
            #{fallback.chomp}
          }
      CPP
    end

    if name == '[]=' && n == 3 && builtin_class_send_safe?(name, %w[Array])
      # Array slice writes occur in optcarrot's mapper when PRG/CHR banks
      # change. The public mrb_ary_splice API implements the native body for
      # this three-argument form. Restrict the fast path to exact Arrays and
      # fixnum start/length values; all coercion, subclass, and non-Array
      # behavior stays on Ruby dispatch. Array#[]= returns the assigned
      # replacement object, while mrb_ary_splice returns the receiver.
      start, length, replacement = argv
      fallback = dynamic_dispatch_line(d, recv, name, argv)
      return <<~CPP
          // ARRAY_SLICE_WRITE :[]= -- exact Array and fixnum indices only; preserve coercion and overrides
          if (mrb_array_p(#{recv}) && mrb_obj_ptr(#{recv})->c == M->array_class &&
              mrb_fixnum_p(#{start}) && mrb_fixnum_p(#{length})) {
            mrb_ary_splice(M, #{recv}, mrb_fixnum(#{start}), mrb_fixnum(#{length}), #{replacement});
            r#{d} = #{replacement};
          } else {
            #{fallback.chomp}
          }
      CPP
    end

    if name == 'push' && n == 1 && builtin_class_send_safe?(name, %w[Array])
      value = argv.first
      fallback = dynamic_dispatch_line(d, recv, name, argv)
      return <<~CPP
          // ARRAY_PUSH :push -- exact base Array and one value; preserve overrides and other arities
          if (mrb_array_p(#{recv}) && mrb_obj_ptr(#{recv})->c == M->array_class) {
            mrb_ary_push(M, #{recv}, #{value});
            r#{d} = #{recv};
          } else {
            #{fallback.chomp}
          }
      CPP
    end

    if ['+', '-', '*'].include?(name) && n == 1 && builtin_class_send_safe?(name, %w[Integer Numeric])
      left, right = recv, argv.first
      fallback = dynamic_dispatch_line(d, recv, name, argv)
      helper = { '+' => 'mrb_num_add', '-' => 'mrb_num_sub', '*' => 'mrb_num_mul' }.fetch(name)
      return <<~CPP
          // FIXNUM_ARITHMETIC :#{name} -- exact Fixnums use mruby's overflow-aware numeric helper
          if (mrb_fixnum_p(#{left}) && mrb_fixnum_p(#{right})) {
            r#{d} = #{helper}(M, #{left}, #{right});
          } else {
            #{fallback.chomp}
          }
      CPP
    end

    # INTEGER_LSHIFT: `bits << n` on two immediate Integers (~25 executed funcalls
    # per RPG2k map frame). Uses mrb_num_shift, the same kernel Integer#<< itself
    # calls (3rd/mruby/src/numeric.c int_lshift), so a shift by zero, of zero,
    # negative counts and the shift-width limit behave identically. What int_lshift
    # would do beyond that -- MRB_INT_MIN counts, and overflow, which mruby turns
    # into a bigint or a RangeError -- is never done from C here: those calls take
    # the ordinary dispatch. That also keeps a 32-bit mrb_int build free of bigint
    # values handed back to C. Emitted next to the exact-Array push arm, so a site
    # that used to be ARRAY_PUSH-only still is when Integer#<< has a Ruby override.
    if name == '<<' && n == 1 && builtin_class_send_safe?(name, %w[Integer])
      value = argv.first
      fallback = dynamic_dispatch_line(d, recv, name, argv).chomp
      array_arm = ''
      if builtin_class_send_safe?(name, %w[Array])
        array_arm = <<~CPP
            // ARRAY_PUSH :<< -- exact Array only; preserve subclass and override dispatch
            if (mrb_array_p(#{recv}) && mrb_obj_ptr(#{recv})->c == M->array_class) {
              mrb_ary_push(M, #{recv}, #{value});
              r#{d} = #{recv};
            } else\x20
        CPP
      end
      return <<~CPP
          #{array_arm.chomp}// INTEGER_LSHIFT :<< -- two immediate Integers; overflow keeps ordinary dispatch
          if (mrb_integer_p(#{recv}) && mrb_integer_p(#{value}) && mrb_integer(#{value}) != MRB_INT_MIN) {
            mrb_int bc2cpp_shl_v = mrb_integer(#{recv}), bc2cpp_shl_w = mrb_integer(#{value}), bc2cpp_shl_out;
            if (bc2cpp_shl_w == 0 || bc2cpp_shl_v == 0) {
              r#{d} = #{recv};
            } else if (mrb_num_shift(M, bc2cpp_shl_v, bc2cpp_shl_w, &bc2cpp_shl_out)) {
              r#{d} = mrb_int_value(M, bc2cpp_shl_out);
            } else {
              #{fallback}
            }
          } else {
            #{fallback}
          }
      CPP
    end

    if name == '<<' && n == 1 && builtin_class_send_safe?(name, %w[Array])
      value = argv.first
      fallback = dynamic_dispatch_line(d, recv, name, argv)
      return <<~CPP
          // ARRAY_PUSH :<< -- exact Array only; preserve subclass and override dispatch
          if (mrb_array_p(#{recv}) && mrb_obj_ptr(#{recv})->c == M->array_class) {
            mrb_ary_push(M, #{recv}, #{value});
            r#{d} = #{recv};
          } else {
            #{fallback.chomp}
          }
      CPP
    end

    if name == 'concat' && n == 1 && owner_def&.owner == 'Optcarrot::APU' && owner_def.name == 'flush_sound' &&
       builtin_class_send_safe?(name, %w[Array])
      source = argv.first
      fallback = dynamic_dispatch_line(d, recv, name, argv)
      return <<~CPP
          // ARRAY_CONCAT_COPY :concat -- APU output buffer; preserve exact-Array capacity without sharing
          if (mrb_array_p(#{recv}) && mrb_obj_ptr(#{recv})->c == M->array_class &&
              mrb_array_p(#{source}) && mrb_obj_ptr(#{source})->c == M->array_class &&
              mrb_obj_ptr(#{recv}) != mrb_obj_ptr(#{source}) && ARY_LEN(mrb_ary_ptr(#{recv})) == 0) {
            r#{d} = mrb_ary_splice(M, #{recv}, 0, 0, #{source});
          } else {
            #{fallback.chomp}
          }
      CPP
    end

    if name == 'clear' && n.zero? && builtin_class_send_safe?(name, %w[Array])
      fallback = dynamic_dispatch_line(d, recv, name, argv)
      retain_frame_capacity = (owner_def&.owner == 'Optcarrot::PPU' && owner_def.name == 'setup_frame') ||
                              (owner_def&.owner == 'Optcarrot::APU' && owner_def.name == 'flush_sound')
      if retain_frame_capacity
        return <<~CPP
            // ARRAY_CLEAR_RETAIN :clear -- frame/audio buffer; clear length but reuse backing storage
            if (mrb_array_p(#{recv}) && mrb_obj_ptr(#{recv})->c == M->array_class) {
              struct RArray *bc2cpp_frame_pixels = mrb_ary_ptr(#{recv});
              mrb_ary_modify(M, bc2cpp_frame_pixels);
              ARY_SET_LEN(bc2cpp_frame_pixels, 0);
              r#{d} = #{recv};
            } else {
              #{fallback.chomp}
            }
        CPP
      end
    end

    if ['%', '&', '|', '^'].include?(name) && n == 1 && native_only_mono?(name)
      left, right = recv, argv.first
      fallback = dynamic_dispatch_line(d, recv, name, argv)
      operation = if name == '%'
                    <<~CPP.chomp
                      mrb_int bc2cpp_mod_left = mrb_fixnum(#{left});
                      mrb_int bc2cpp_mod_right = mrb_fixnum(#{right});
                      if (bc2cpp_mod_left == MRB_INT_MIN && bc2cpp_mod_right == -1) {
                        r#{d} = mrb_fixnum_value(0);
                      } else {
                        mrb_int bc2cpp_mod_value = bc2cpp_mod_left % bc2cpp_mod_right;
                        if ((bc2cpp_mod_left < 0) != (bc2cpp_mod_right < 0) && bc2cpp_mod_value != 0) {
                          bc2cpp_mod_value += bc2cpp_mod_right;
                        }
                        r#{d} = mrb_fixnum_value(bc2cpp_mod_value);
                      }
                    CPP
                  else
                    operator = { '&' => '&', '|' => '|', '^' => '^' }.fetch(name)
                    "r#{d} = mrb_fixnum_value(mrb_fixnum(#{left}) #{operator} mrb_fixnum(#{right}));"
                  end
      return <<~CPP
          // FIXNUM_BINARY :#{name} -- fixnum-only native semantics with Ruby fallback
          if (mrb_fixnum_p(#{left}) && mrb_fixnum_p(#{right})#{' && mrb_fixnum(' + right + ') != 0' if name == '%'}) {
            #{operation}
          } else {
            #{fallback.chomp}
          }
      CPP
    end

    if name == '>>' && n == 1 && builtin_class_send_safe?(name, %w[Integer Numeric])
      value, width = recv, argv.first
      fallback = dynamic_dispatch_line(d, recv, name, argv)
      return <<~CPP
          // FIXNUM_SHIFT :>> -- guarded shifts; overflow and non-Fixnum cases retain Ruby dispatch
          {
          mrb_bool bc2cpp_shift_fast = FALSE;
          mrb_int bc2cpp_shift_result = 0;
          if (mrb_fixnum_p(#{value}) && mrb_fixnum_p(#{width})) {
            mrb_int bc2cpp_shift_value = mrb_fixnum(#{value});
            mrb_int bc2cpp_shift_width = mrb_fixnum(#{width});
            if (bc2cpp_shift_width == 0) {
              bc2cpp_shift_result = bc2cpp_shift_value;
              bc2cpp_shift_fast = TRUE;
            } else if (bc2cpp_shift_width > 0) {
              if (bc2cpp_shift_width >= MRB_INT_BIT - 1) {
                bc2cpp_shift_result = bc2cpp_shift_value < 0 ? -1 : 0;
              } else {
                bc2cpp_shift_result = bc2cpp_shift_value >> bc2cpp_shift_width;
              }
              bc2cpp_shift_fast = TRUE;
            } else if (bc2cpp_shift_width != MRB_INT_MIN) {
              if (bc2cpp_shift_value == 0) {
                bc2cpp_shift_fast = TRUE;
              } else {
                mrb_int bc2cpp_left_width = -bc2cpp_shift_width;
                if (bc2cpp_left_width <= MRB_INT_BIT - 1 &&
                    !(bc2cpp_shift_value > 0 && bc2cpp_shift_value > (MRB_INT_MAX >> bc2cpp_left_width)) &&
                    !(bc2cpp_shift_value < 0 && bc2cpp_shift_value < (MRB_INT_MIN >> bc2cpp_left_width))) {
                  if (bc2cpp_left_width == MRB_INT_BIT - 1) {
                    bc2cpp_shift_result = MRB_INT_MIN;
                  } else if (bc2cpp_shift_value > 0) {
                    bc2cpp_shift_result = bc2cpp_shift_value << bc2cpp_left_width;
                  } else {
                    bc2cpp_shift_result = bc2cpp_shift_value * ((mrb_int)1 << bc2cpp_left_width);
                  }
                  bc2cpp_shift_fast = TRUE;
                }
              }
            }
          }
          if (bc2cpp_shift_fast) {
            r#{d} = mrb_fixnum_value(bc2cpp_shift_result);
          } else {
            #{fallback.chomp}
          }
          }
      CPP
    end

    if ['<', '<=', '>', '>='].include?(name) && n == 1 && native_only_mono?(name)
      left, right = recv, argv.first
      fallback = dynamic_dispatch_line(d, recv, name, argv)
      operator = { '<' => '<', '<=' => '<=', '>' => '>', '>=' => '>=' }.fetch(name)
      return <<~CPP
          // FIXNUM_COMPARE :#{name} -- fixnum-only native comparison with Ruby fallback
          if (mrb_fixnum_p(#{left}) && mrb_fixnum_p(#{right})) {
            r#{d} = mrb_bool_value(mrb_fixnum(#{left}) #{operator} mrb_fixnum(#{right}));
          } else {
            #{fallback.chomp}
          }
      CPP
    end

    if name == 'slice!' && n == 2 && builtin_class_send_safe?(name, %w[Array])
      start, length = argv
      fallback = dynamic_dispatch_line(d, recv, name, argv)
      return <<~CPP
          // ARRAY_PREFIX_SLICE_WRITE :slice! -- exact Array, zero start, nonnegative fixnum length
          if (mrb_array_p(#{recv}) && mrb_obj_ptr(#{recv})->c == M->array_class &&
              !mrb_frozen_p(mrb_obj_ptr(#{recv})) && mrb_fixnum_p(#{start}) &&
              mrb_fixnum(#{start}) == 0 && mrb_fixnum_p(#{length}) && mrb_fixnum(#{length}) >= 0) {
            mrb_value bc2cpp_slice_receiver = #{recv};
            mrb_int bc2cpp_slice_len = mrb_fixnum(#{length});
            mrb_int bc2cpp_array_len = RARRAY_LEN(bc2cpp_slice_receiver);
            if (bc2cpp_slice_len > bc2cpp_array_len) bc2cpp_slice_len = bc2cpp_array_len;
            r#{d} = mrb_ary_new_from_values(M, bc2cpp_slice_len, RARRAY_PTR(bc2cpp_slice_receiver));
            mrb_ary_splice(M, bc2cpp_slice_receiver, 0, bc2cpp_slice_len, mrb_undef_value());
          } else {
            #{fallback.chomp}
          }
      CPP
    end

    if name == 'key?' && n == 1 && !@native_registered_expressions.key?(name) &&
       builtin_class_send_safe?(name, %w[Hash])
      return compile_native_primitive_send(name, d, recv, argv)
    end

    # Resolve compiled MONO/TYPED Ruby targets first. Only the final POLY
    # fallback below uses the exact-class expressions generated from native
    # C registrations and implementations.
    native_expression_entries = @native_registered_expressions[name]
    # EQ_CHAIN_FALLBACK: compile_cmp wraps this send in its own String/Symbol chain
    # (generated_eq_dispatch), so the send must not emit that switch a second time.
    native_expression_entries = nil if @suppress_native_expression_send == name
    native_expression_owners = native_expression_entries&.map { |entry| entry[:owner][:class_name] }&.uniq
    builtin_native_expression_send = native_expression_entries && native_expression_entries.all? { |entry| entry[:arity] == n } &&
                                     builtin_class_send_safe?(name, native_expression_owners)

    if (expected_n = NATIVE_PRIMITIVE_SEND_ARITY[name]) && n == expected_n && native_only_mono?(name) &&
       !@native_registered_expressions.key?(name)
      return compile_native_primitive_send(name, d, recv, argv)
    end

    target = monomorphic_target(name)
    # A monomorphic *name* is still only safe to devirtualize if its one
    # real definition fits this prototype's pure-mandatory-or-optional-args
    # calling convention -- see pure_mandatory_or_optional_arity?'s own
    # comment (widened from a pure-mandatory-only check to also cover
    # CALLSITE_OPTIONAL_ARG_SUPPORT; the original pure-mandatory bug this
    # replaced is unchanged, caught by running against real code, not a
    # hypothetical).
    target = nil if target && !pure_mandatory_or_optional_arity?(@ireps.fetch(target.irep))
    # ...and if the call site's own argument count actually matches that
    # target's real mandatory arity. Real, pre-existing bug (present before
    # this round's own changes too, confirmed against a true before/after):
    # a bytecode-only registry has no visibility into a same-named NATIVE
    # method (see extract_native_method_names's own comment) -- run this
    # diagnostic without NATIVE_SRCS (as this project's own established
    # 421-error baseline measurement always has) and `:repeat?` looks MONO
    # (only Game::MoveRoute#repeat?, a real 0-arg getter, is bytecode-
    # visible), even though `Input.repeat?(key)` -- a real native 1-arg
    # method on a different class entirely -- sends the very same bare name
    # with 1 argument all over mruby-rpg2k/mrblib's own scene code. Every
    # one of those call sites used to devirtualize straight into
    # `Game__MoveRoute_repeat__impl(M, recv, key)`, a real arity mismatch
    # against that function's own 0-argument signature -- a g++ compile
    # error, not a hypothetical (120 real occurrences in this project's own
    # unrestricted, no-NATIVE_SRCS diagnostic output). Real gem builds
    # always pass NATIVE_SRCS (mrbgem.rake), which already flips a true
    # collision like this to POLY and avoids the bug that way -- but the
    # arg-count check here is a strictly cheaper, always-correct second
    # line of defense that needs no NATIVE_SRCS input at all: a call site's
    # own argument count is real, load-bearing data already sitting right
    # here, and simply never matches a genuinely different method's real
    # arity by construction, whatever its name happens to collide with.
    # CALLSITE_OPTIONAL_ARG_SUPPORT: a real optional-argument target accepts
    # any call-site argument count in [mandatory_arity, mandatory_arity +
    # optional_arity], not just an exact match -- the pure-mandatory case
    # (optional_arity == 0) collapses back to the original exact-match check
    # unchanged, so this is a strict widening, never a behavior change for
    # any target this file already devirtualized before.
    target = nil if target && !n.between?(mandatory_arity(@ireps.fetch(target.irep)),
                                           mandatory_arity(@ireps.fetch(target.irep)) + optional_arity(@ireps.fetch(target.irep)))
    # LEXICAL_SELF_SUPPORT: still POLY by name, but this particular call
    # site is an IMPLICIT-self send (`member(db, m)`, not
    # `some_receiver.member(db, m)`) -- and unlike an explicit receiver,
    # `self`'s class inside a method body is not merely traced, it is
    # KNOWN outright whenever `lexical_self_owner` says so (no subclass of
    # the enclosing owner exists anywhere in the whole program, and
    # self-rebinding -- `instance_eval`/`instance_exec` -- never occurs in
    # this closed world; see that function's own comment and
    # self_receiver_class's, which this mirrors). That is a strictly
    # stronger guarantee than TYPED/trace_new_target's own runtime-checked
    # trace below (a fact *proven*, not merely *observed*), so the direct
    # call this resolves to needs no runtime `mrb_class_ptr` guard and no
    # `mrb_funcall` fallback at all -- the same unconditional-call shape
    # MONO gets, just reached by a different, receiver-independent route.
    # Never attempted for an explicit-receiver send: `self_implicit` is
    # exactly the one bit of information (also see self_receiver_class's
    # own header) that makes "self" mean "owner_def.owner" here at all --
    # an explicit receiver register could hold literally anything.
    lexical_self = false
    lexical_self_ivar_accessor = nil
    if target.nil? && self_implicit
      lex_owner = lexical_self_owner(owner_def)
      if lex_owner
        lex_candidate = @registry[name]&.find { |md| md.owner == lex_owner }
        if lex_candidate&.irep && pure_mandatory_or_optional_arity?(@ireps.fetch(lex_candidate.irep)) &&
           compiles_clean?(lex_candidate.irep) &&
           n.between?(mandatory_arity(@ireps.fetch(lex_candidate.irep)),
                      mandatory_arity(@ireps.fetch(lex_candidate.irep)) + optional_arity(@ireps.fetch(lex_candidate.irep)))
          target = lex_candidate
          lexical_self = true
        elsif lex_candidate&.kind == :ivar_accessor && n == (name.end_with?('=') ? 1 : 0)
          # LEXICAL_SELF_IVAR_ACCESSOR: the ivar_accessor-kind analogue of
          # the branch just above -- see IVAR_ACCESSOR_DEVIRT's own
          # comment (below) for why an attr_reader/writer candidate can
          # never satisfy the ordinary `.irep`-based branch. Same
          # certain-not-traced guarantee applies here too: no runtime
          # `mrb_class_ptr` guard needed, straight to `mrb_iv_get`/
          # `mrb_iv_set`.
          lexical_self_ivar_accessor = lex_candidate
        end
      end
    end
    # Name-based devirtualization failed (still POLY by name) -- try a
    # call-site-specific fallback: THIS receiver, traced backward through
    # the same straight-line method body, might still be provably a fresh
    # instance of one exact class (trace_new_target's own comment). Never a
    # superclass/MRO walk -- an exact owner match only, so a method this
    # class inherits rather than defines itself still safely misses here
    # and falls through to ordinary dynamic dispatch, same as today.
    #
    # Three real sources feed the same trace now, not just a fresh
    # same-body `.new`: a GETIV of an ivar ClassLayout already proved
    # always holds one exact class (`@state.foo`), or an opaque incoming
    # argument a real ClassAnnotations comment names. The first is a hard
    # Ruby-semantics guarantee (`.new` never allocates a subclass in
    # disguise); the other two are real whole-program facts but not a
    # *proof* the same way -- an ivar this run never sees written from
    # outside the compiled set, or an annotation that's simply wrong. So
    # every hit through this path (not just the two newer ones) gets a
    # real runtime `mrb_obj_class` check before the direct call, falling
    # back to ordinary `mrb_funcall` if it doesn't match -- strictly
    # *safer* than the name-only MONO path above, which trusts the
    # registry with no runtime check at all. A guard on the fresh-`.new`
    # case too costs nothing (it's simply always true there) and means
    # every future extension to trace_new_target's own reach inherits the
    # same safety net for free.
    typed = false
    via_element = false
    ivar_accessor_target = nil
    known_class = nil
    if target.nil? && !self_implicit && irep && (idx || trace_idx)
      proof_idx = idx || trace_idx
      proof_reg = unshift_proof_reg(trace_receiver_reg || d, trace_reg_offset)
      cur_enter = irep.instructions.find { |i| i.op == 'ENTER' }
      cur_mand = cur_enter ? cur_enter.args.split(':').first.to_i : 0
      cur_arg_classes = owner_def && @class_annotations[irep.label]&.args
      ivar_classes = owner_def && @class_layout[owner_def.owner]
      # CHAINED_ACCESSOR_SUPPORT: `@class_layout` (the full owner -> ivar-
      # hint table, not just this call site's own already-sliced
      # `ivar_classes`) and `@registry` let this same TYPED path also
      # devirtualize a multi-level accessor chain (`@state.screen.foo`),
      # not just a single-level GETIV/`.new`/ARRAY hit -- see
      # trace_new_target's own top comment for the full mechanism. Both
      # are already real CodeGen instance state (`initialize`, above), no
      # new plumbing needed to reach them from here.
      known_class = trace_new_target(irep, proof_idx, proof_reg, ivar_classes, cur_mand, cur_arg_classes, owner: owner_def&.owner,
                                      class_layout: @class_layout, registry: @registry,
                                      element_annotations: @element_annotations,
                                      known_owners: @known_owners,
                                      capture_hints: @block_hash_capture_hints)
    end
    # ELEMENT_CLASS_SUPPORT: the same TYPED/IVAR_ACCESSOR resolution, fed
    # by a fact the backward scan above structurally cannot reach. When the
    # receiver is an inlined-loop parameter, no instruction writes that
    # register, so trace_new_target still has nothing to find; the hint
    # published by with_element_hint supplies that fact. Other block-local
    # values, including indexed reads through an annotated `[]`, can now use
    # the separate trace index above.
    #
    # Placed AFTER the ordinary trace on purpose, as a strict fallback:
    # `known_class` is only ever nil here (the two sources are mutually
    # exclusive in practice -- one only fires outside a block body, the
    # other only inside), but ordering it this way means the pre-existing
    # path keeps priority by construction rather than by coincidence, so
    # nothing about a non-block call site can change.
    #
    # Everything downstream is shared verbatim with the TYPED path: the
    # exact-owner registry match, the pure-mandatory/compiles_clean?/
    # arity guards, the ONLY_OWNERS emission gate, and -- the part that
    # matters for soundness -- the real runtime `mrb_class_ptr(...) ==
    # mrb_obj_class(M, recv)` check with an `mrb_funcall` fallback. A
    # wrong element fact can therefore only ever cost one failed pointer
    # comparison, exactly like a wrong ivar-class hint.
    if target.nil? && !self_implicit && known_class.nil? && elem_class_hint
      known_class = elem_class_hint
      via_element = true
    end
    if target.nil? && !self_implicit && known_class
      candidate = @registry[name]&.find { |md| md.owner == known_class }
      # Same two guards as the MONO path above (its own comments have the
      # real bugs both catch, e.g. Game::State#set_parallax/
      # #set_screen_transition/#show_picture/#erase_picture -- all four
      # real TYPED-path arity mismatches this exact check fixed, caught
      # building Game::Screen's own compiled target): a class-exact
      # candidate still isn't safe to call directly unless its own body
      # actually compiles AND the call site's argument count matches its
      # real mandatory arity.
      if candidate&.irep && pure_mandatory_or_optional_arity?(@ireps.fetch(candidate.irep)) &&
         compiles_clean?(candidate.irep) &&
         n.between?(mandatory_arity(@ireps.fetch(candidate.irep)),
                    mandatory_arity(@ireps.fetch(candidate.irep)) + optional_arity(@ireps.fetch(candidate.irep)))
        target = candidate
        typed = true
      elsif candidate&.kind == :ivar_accessor &&
            n == (name.end_with?('=') ? 1 : 0)
        # IVAR_ACCESSOR_DEVIRT: `candidate` has no `.irep` at all (never
        # will -- build_registry's own attr_reader/writer/accessor case
        # registers it that way on purpose, see MethodDef's own `kind`
        # comment), so it can never satisfy the ordinary TYPED branch
        # just above -- an attr_reader/writer/accessor name is *always*
        # POLY-native by the existing MONO/TYPED paths' own standards,
        # regardless of how many real classes happen to define it. This
        # is a real, separate devirtualization: not "call this class's
        # own compiled body" (there is none), but "this class's own
        # accessor is *provably* a bare mrb_iv_get/mrb_iv_set against
        # the ordinary dynamic iv_tbl" (MethodDef's own `kind` comment
        # has the real 3rd/mruby/src/class.c citation) -- safe to inline
        # directly, runtime-guarded exactly like TYPED above, with no
        # `_impl` function involved at all. Arity here is exactly 0 for
        # a getter, exactly 1 for a setter (`name.end_with?('=')`) --
        # `mandatory_arity`/`pure_mandatory_arity?` don't apply (there is
        # no irep to ask), but a real attr_reader/writer call site can
        # never have any other shape, so this is the complete, correct
        # check on its own, not an approximation.
        ivar_accessor_target = candidate
      end
    end
    # A monomorphic target whose *owner* is being filtered out of this run's
    # emitted output (ONLY_OWNERS) has no _impl function in the generated
    # file at all -- a real bug, caught wiring up the first real caller
    # (docs/adr/0139): LCF::File#to_lcf's own devirtualized calls to
    # LCF.write_ber/LCF.binstr (owner "LCF", not one of the LCF::File-family
    # classes actually being emitted) compiled clean but referenced two
    # functions this run would never define, an undefined-reference link
    # failure waiting to happen. Falling back to ordinary dynamic dispatch
    # here is always safe (just slower) -- the same fallback an unmodeled
    # opcode or a bad arity already gets. `@other_owners` is the one
    # exception: an owner this run explicitly trusts *another* gem's own
    # run to compile and expose non-static (see emit_decls_header) -- a
    # real, externally-linked function the final link will resolve, not a
    # guess.
    if target && @only_owners && !@only_owners.include?(target.owner)
      target = nil unless @other_owners&.include?(target.owner)
    end

    if target
      impl = cpp_name(target.owner, target.name) + '_impl'
      # NATIVE_ARG_TARGETS' own call-site half: `impl`'s own real signature
      # (compile_method, above) already boxes any native-typed parameter
      # right back into an mrb_value as its first statement, so passing an
      # already-boxed mrb_value straight through here as before would be a
      # real type mismatch (a g++ compile error, since C++ has no implicit
      # mrb_value -> mrb_int/mrb_sym conversion) the moment `target` is one
      # of these methods. `call_argv` unboxes each position that needs it
      # right here at the call site instead -- the exact same relocation
      # (callee's own internal coercion moved to the caller) the just-
      # merged Rect/Color/Tone round already established for
      # NATIVE_CONSTRUCT_TARGETS' own direct-construct path, just generalized
      # from a hardcoded native constructor to an ordinary devirtualized
      # `_impl` call. `mrb_as_int`/`mrb_obj_to_sym` are the exact same
      # coercions `mrb_get_args`'s own "i"/"n" format characters use
      # internally (see compile_method's own entry-wrapper comment) --
      # identical TypeError-raising for a genuinely wrong-typed argument,
      # `mrb_state* M` has no notion of a calling-frame boundary to cross,
      # so this changes nothing observable versus reaching the same
      # coercion through an ordinary mrb_funcall-dispatched call into
      # `target`'s own entry wrapper. Wraps whatever expression `argv`
      # already holds at this position (a bare register, or itself the
      # result of another expression -- e.g. Game::Actor#change_mp's own
      # real `-weapon_sp_cost` call site), never assumes a bare register
      # name. `target.irep`'s own mandatory arity is now only ever a LOWER
      # bound on `argv.size` (checked above, both for the MONO and TYPED
      # paths -- CALLSITE_OPTIONAL_ARG_SUPPORT widened the exact-match guard
      # to a range), so `native_arg_types` is asked for exactly the target's
      # own mandatory-position count -- NATIVE_ARG_TARGETS never names an
      # optional-arg method (see that table's own comment), so every
      # position at or past `t_mand` always stays plain `mrb_value` here
      # regardless; passing `t_mand` rather than `argv.size` just makes that
      # explicit instead of relying on `call_types[i]` reading past its own
      # array bounds (nil either way, but not by coincidence).
      t_irep = @ireps.fetch(target.irep)
      t_mand = mandatory_arity(t_irep)
      t_opt = optional_arity(t_irep)
      call_types = native_arg_types(target, t_mand)
      call_argv = argv.each_with_index.map do |a, i|
        case call_types[i]
        when :fixnum then "mrb_as_int(M, #{a})"
        when :symbol then "mrb_obj_to_sym(M, #{a})"
        else a
        end
      end
      # CALLSITE_OPTIONAL_ARG_SUPPORT: `impl`'s own real signature (see
      # compile_method's own `arg_params << 'mrb_int bc2cpp_given_opt' if
      # opt.positive?`) always has room for the target's FULL optional
      # count, whether or not this exact call site supplied all of them --
      # so a call site that only gave some of them still needs one real
      # placeholder mrb_value per omitted trailing optional, plus the
      # target's own `bc2cpp_given_opt` figure as a trailing integer
      # literal. `mrb_nil_value()` is the identical placeholder
      # compile_method's own entry wrapper already initializes an omitted
      # optional's out-param to (see its own comment: never read before the
      # jump table's own default-value code overwrites it) -- reusing it
      # here keeps the devirtualized direct-call path and the ordinary
      # mrb_funcall-through-entry-wrapper path observably identical. The
      # given-count is `argv.size - t_mand` rather than a runtime
      # `mrb_get_argc` call because the call site's own real argument count
      # is already known statically here, unlike inside the entry wrapper.
      if t_opt.positive?
        call_argv += Array.new(t_mand + t_opt - argv.size, 'mrb_nil_value()')
        call_argv << (argv.size - t_mand).to_s
      end
      native_positions = call_types.each_index.select { |i| call_types[i] }.map { |i| i + 1 }
      native_note = native_positions.empty? ? '' : " (position#{'s' unless native_positions.one?} " \
                                                    "#{native_positions.join(', ')} unboxed here to match " \
                                                    "#{impl}'s own native argument type)"
      if typed
        check = "#{owner_class_ptr_expr(target.owner)} == mrb_obj_class(M, #{recv})"
        # ELEMENT_CLASS_SUPPORT: same codegen, different provenance -- the
        # tag says which fact proved the receiver so a reader of the
        # generated file can tell an ordinary traced receiver from an
        # inlined-loop element without re-deriving it.
        kind = via_element ? 'ELEMENT' : 'TYPED'
        traced_note = via_element ? "inlined block element of Array<#{target.owner}>" : "receiver traced to #{target.owner}"
        note = "  // #{kind} :#{name} -> #{target.owner}##{target.name} (#{traced_note}), " \
               "runtime-class-checked direct C++ call, mrb_funcall fallback#{native_note}\n"
        fallback = typed_fallback || dynamic_dispatch_line(d, recv, name, argv)
        "#{note}  if (#{check}) {\n" \
          "    r#{d} = #{impl}(M, #{([recv] + call_argv).join(', ')});\n" \
          "  } else {\n" \
          "    #{fallback}" \
          "  }\n"
      elsif lexical_self
        note = "  // LEXICAL_SELF :#{name} -> #{target.owner}##{target.name} (self, statically " \
               "#{target.owner} -- no subclass exists program-wide), direct C++ call (no mrb_funcall, " \
               "no runtime check)#{native_note}\n"
        "#{note}  r#{d} = #{impl}(M, #{([recv] + call_argv).join(', ')});\n"
      elsif @ivar_layout.key?(target.owner)
        # MONO_EMBED_GUARD: `monomorphic_target`'s own "exactly one COMPILED
        # bytecode definition of this bare name anywhere in the program"
        # proof says nothing about method_missing -- a class that answers a
        # name only through method_missing (LCF::Array1D/Array2D's own
        # schema-driven field access, mruby-lcf/mrblib/lcf.rb) never adds an
        # entry to @registry[name] at all, so it is invisible to that count
        # and MONO would otherwise call `impl` directly on a receiver that
        # was never proven to be `target.owner`. Ordinarily that just reads/
        # writes the wrong object's own iv_tbl entry -- wrong, but memory-
        # safe. It stops being memory-safe the moment `target.owner` embeds
        # ANY ivar as a real struct field: GETIV/SETIV for an embedded field
        # cast `DATA_PTR(self)` (RDATA(self)->data) unconditionally, and a
        # receiver that is not really an RData of this shape (an ordinary
        # RObject, e.g. an Array1D row) makes that a real out-of-bounds/
        # type-confused read, not merely a wrong answer -- caught for real
        # reproducing Game::Actor#faceset_index: `@db_row.faceset_index`
        # (an Array1D method_missing call, never Game::Actor) targeted
        # Game::Actor's own compiled accessor because `faceset_index` had
        # exactly one COMPILED definition program-wide, and
        # `((Game__Actor_ivars*)DATA_PTR(self))->faceset_index` then read
        # through a receiver that was never a Game::Actor at all -- a real,
        # reproduced crash. Guard every MONO call into an embedding class,
        # not just the specific methods that happen to touch a field today:
        # precisely proving "this exact compiled body never reaches a
        # DATA_PTR dereference, even transitively" is a much deeper
        # reachability question than this gate is willing to get wrong in
        # the unsafe direction, and the file's own established pattern
        # (`typed`, just above) already pays this same one-compare cost for
        # every other receiver-uncertain devirtualized call.
        check = "#{owner_class_ptr_expr(target.owner)} == mrb_obj_class(M, #{recv})"
        note = "  // MONO_EMBED_GUARD :#{name} -> #{target.owner}##{target.name} (embeds ivars; " \
               "method_missing elsewhere could otherwise mistarget this), runtime-class-checked " \
               "direct C++ call, mrb_funcall fallback#{native_note}\n"
        fallback = dynamic_dispatch_line(d, recv, name, argv)
        "#{note}  if (#{check}) {\n" \
          "    r#{d} = #{impl}(M, #{([recv] + call_argv).join(', ')});\n" \
          "  } else {\n" \
          "    #{fallback}" \
          "  }\n"
      else
        # target.owner embeds no ivar at all, so this callee's own GETIV/
        # SETIV codegen never casts DATA_PTR(self) regardless of what self
        # really is (embed_type(target.owner, ...) is nil for every ivar
        # here) -- a wrong receiver reads/writes the wrong object's own
        # iv_tbl entry, memory-safe (if semantically wrong) exactly as
        # every other unguarded MONO call already was before this file
        # tracked ivar embedding at all. No guard needed.
        note = "  // MONO :#{name} -> #{target.owner}##{target.name}, direct C++ call (no mrb_funcall)" \
               "#{native_note}\n"
        "#{note}  r#{d} = #{impl}(M, #{([recv] + call_argv).join(', ')});\n"
      end
    elsif lexical_self_ivar_accessor
      # LEXICAL_SELF_IVAR_ACCESSOR's own codegen -- the implicit-self
      # analogue of IVAR_ACCESSOR_DEVIRT below, with the same
      # lexical_self_owner certainty LEXICAL_SELF's own comment (above)
      # already established: no runtime `mrb_class_ptr` guard, no
      # `mrb_funcall` fallback, straight to iv_tbl.
      owner = lexical_self_ivar_accessor.owner
      if name.end_with?('=')
        ivar = name[0..-2]
        val = argv.first
        note = "  // LEXICAL_SELF_IVAR_ACCESSOR :#{name} -> #{owner}#@#{ivar} (self, statically #{owner}), " \
               "attr_writer devirtualized to a direct mrb_iv_set (no _impl, no mrb_funcall, no runtime " \
               "check) -- see MethodDef's own kind: :ivar_accessor comment for the real " \
               "3rd/mruby/src/class.c citation this reproduces exactly.\n"
        "#{note}  mrb_iv_set(M, #{recv}, mrb_intern_cstr(M, \"@#{ivar}\"), #{val});\n" \
          "  r#{d} = #{val};\n"
      else
        note = "  // LEXICAL_SELF_IVAR_ACCESSOR :#{name} -> #{owner}#@#{name} (self, statically #{owner}), " \
               "attr_reader devirtualized to a direct mrb_iv_get (no _impl, no mrb_funcall, no runtime " \
               "check) -- see MethodDef's own kind: :ivar_accessor comment for the real " \
               "3rd/mruby/src/class.c citation this reproduces exactly.\n"
        "#{note}  r#{d} = mrb_iv_get(M, #{recv}, mrb_intern_cstr(M, \"@#{name}\"));\n"
      end
    elsif ivar_accessor_target
      # IVAR_ACCESSOR_DEVIRT's own codegen -- see the `elsif candidate&.kind
      # == :ivar_accessor` branch above for the full soundness writeup.
      # Runtime-guarded the same way TYPED is (a wrong static trace only
      # ever costs a missed optimization, never a wrong answer): `recv`'s
      # real runtime class might still differ from `known_class` (a
      # subclass, a reassigned constant since gem-init, ...), so this
      # checks before ever touching iv_tbl directly, falling back to
      # ordinary `mrb_funcall` (which correctly dispatches to whatever
      # `name` actually resolves to on the real receiver) otherwise.
      owner = ivar_accessor_target.owner
      check = "#{owner_class_ptr_expr(owner)} == mrb_obj_class(M, #{recv})"
      # ELEMENT_CLASS_SUPPORT: see the TYPED branch above -- same tag, same
      # reason, so both provenances stay greppable in generated output.
      traced_note = via_element ? "inlined block element of Array<#{owner}>" : "receiver traced to #{owner}"
      if name.end_with?('=')
        ivar = name[0..-2]
        val = argv.first
        note = "  // IVAR_ACCESSOR#{via_element ? '/ELEMENT' : ''} :#{name} -> #{owner}#@#{ivar} (#{traced_note}), " \
               "attr_writer devirtualized to a direct mrb_iv_set (no _impl, no mrb_funcall) -- see " \
               "MethodDef's own kind: :ivar_accessor comment for the real 3rd/mruby/src/class.c " \
               "citation this reproduces exactly (attr_writer's own mrb_iv_set then returning the " \
               "assigned value, never the ivar read back).\n"
        "#{note}  if (#{check}) {\n" \
          "    mrb_iv_set(M, #{recv}, mrb_intern_cstr(M, \"@#{ivar}\"), #{val});\n" \
          "    r#{d} = #{val};\n" \
          "  } else {\n" \
          "    #{dynamic_dispatch_line(d, recv, name, argv)}" \
          "  }\n"
      else
        note = "  // IVAR_ACCESSOR#{via_element ? '/ELEMENT' : ''} :#{name} -> #{owner}#@#{name} (#{traced_note}), " \
               "attr_reader devirtualized to a direct mrb_iv_get (no _impl, no mrb_funcall) -- see " \
               "MethodDef's own kind: :ivar_accessor comment for the real 3rd/mruby/src/class.c " \
               "citation this reproduces exactly.\n"
        "#{note}  if (#{check}) {\n" \
          "    r#{d} = mrb_iv_get(M, #{recv}, mrb_intern_cstr(M, \"@#{name}\"));\n" \
          "  } else {\n" \
          "    #{dynamic_dispatch_line(d, recv, name, argv)}" \
          "  }\n"
      end
    else
      return compile_native_primitive_send(name, d, recv, argv) if builtin_native_expression_send

      poly_small_n = compile_poly_small_n(name, d, recv, argv, n)
      return poly_small_n if poly_small_n

      note = "  // POLY :#{name} -- real dynamic dispatch, receiver's runtime class decides\n"
      "#{note}  #{dynamic_dispatch_line(d, recv, name, argv)}"
    end
  end

  # `Owner::Path` -> a real, chained `mrb_const_get` mrb_value expression
  # for that class object -- the exact same per-segment lookup GETCONST/
  # GETMCNST codegen already does (mrb_class_get_under has no built-in
  # "::"-path parsing of its own to delegate to instead), just built as
  # one C++ expression rather than emitted as its own sequence of
  # instructions. Only ever used inside a runtime guard condition, so
  # re-resolving the constant on every call (no caching) is the same
  # already-accepted tradeoff GETCONST's own codegen makes.
  #
  # Follow-up (docs/adr/0139: ".singleton owner support"): uses
  # lexical_scope_path (not a bare `owner.split('::')`) for the same reason
  # GETCONST's own owner-scope-first codegen does -- see that helper's own
  # comment for the real bug this avoids. Not currently reachable with a
  # `.singleton`-suffixed `owner` in practice (this is only ever called
  # with a TYPED-path `target.owner`, and `target.owner` here can only come
  # from `trace_new_target`'s own `known_class` -- a fresh `.new`, an ivar
  # ClassLayout hint, or a ClassAnnotations comment, none of which ever
  # name a `.singleton` pseudo-owner, confirmed by this same follow-up's
  # own registry audit), but hardened here anyway rather than left relying
  # on that invariant holding forever elsewhere.
  def const_chain_value_expr(owner)
    lexical_scope_path(owner).reduce('mrb_obj_value(M->object_class)') do |expr, seg|
      "mrb_const_get(M, #{expr}, mrb_intern_cstr(M, \"#{seg}\"))"
    end
  end

  # OWNER_CLASS_CACHE: the RClass* for `owner`, as a call to a per-owner
  # helper (emit_owner_class_cache) instead of re-running the chained
  # mrb_const_get + mrb_intern_cstr on every guard. Every TYPED/POLY_SMALL_N
  # guard compares against this pointer, so those lookups used to sit on the
  # hot path of each devirtualized call.
  def owner_class_ptr_expr(owner)
    @owner_class_cache ||= {}
    slot = (@owner_class_cache[owner] ||= { index: @owner_class_cache.size })
    "bc2cpp_owner_class_#{slot[:index]}(M)"
  end

  # File-scope cache emitted ahead of the compiled bodies. A plain static per
  # owner, not per mrb_state -- the same "one live VM at a time" contract
  # mruby-rpg2k-compiled's g_direct_construct_* globals document -- but
  # additionally keyed on the state pointer so two VMs alternating still
  # resolve correctly, and reset by the gem's own gem_final (via
  # bc2cpp_reset_owner_classes) so a later mrb_open never sees a stale
  # pointer left by a closed VM that reused the address. Every caller is a
  # class-equality guard with a dynamic-dispatch fallback, so a class that is
  # not defined in this process yields nullptr (the guard is simply false)
  # instead of raising NameError: an RGSS-only run never defines the RPG2k
  # runtime's `Game`, and a POLY_SMALL_N chain naming Game::Map used to raise
  # for any receiver that fell past the RGSS branches. nullptr is not cached,
  # so a class defined later is still found. Like GETCONST's own pre-cache
  # codegen this does not notice a later reassignment of the constant,
  # matching the existing g_direct_construct_* behaviour.
  def emit_owner_class_cache
    entries = (@owner_class_cache || {}).to_a
    out = +"// OWNER_CLASS_CACHE -- see bc2cpp.rb's own owner_class_ptr_expr comment.\n"
    out << "static mrb_state* bc2cpp_owner_class_state = nullptr;\n"
    out << "static struct RClass* bc2cpp_owner_class_slots[#{[entries.size, 1].max}] = {};\n"
    out << "static void bc2cpp_reset_owner_classes() {\n" \
           "  bc2cpp_owner_class_state = nullptr;\n" \
           "  for (struct RClass*& c : bc2cpp_owner_class_slots) c = nullptr;\n" \
           "}\n"
    unless entries.empty?
      out << <<~CPP
        static struct RClass* bc2cpp_owner_class_lookup(mrb_state* M, const char* const* path, int n) {
          mrb_value v = mrb_obj_value(M->object_class);
          for (int i = 0; i < n; ++i) {
            mrb_sym s = mrb_intern_cstr(M, path[i]);
            if (!mrb_const_defined(M, v, s)) return nullptr;
            v = mrb_const_get(M, v, s);
          }
          return mrb_class_ptr(v);
        }
      CPP
    end
    entries.each do |owner, slot|
      i = slot[:index]
      path = lexical_scope_path(owner)
      out << <<~CPP
        static inline struct RClass* bc2cpp_owner_class_#{i}(mrb_state* M) {
          if (bc2cpp_owner_class_state != M) {
            bc2cpp_reset_owner_classes();
            bc2cpp_owner_class_state = M;
          }
          struct RClass* c = bc2cpp_owner_class_slots[#{i}];
          if (!c) {
            static const char* const path[] = {#{path.map { |seg| "\"#{seg}\"" }.join(', ')}};
            c = bc2cpp_owner_class_slots[#{i}] = bc2cpp_owner_class_lookup(M, path, #{path.size});
          }
          return c;
        }
      CPP
    end
    out
  end

  # The uncached GETCONST lookup: resolve the owner's lexical scope chain, probe
  # each scope innermost-first, fall back to Object. `d` is the destination
  # register number (a string). Used inline, and as the slow path of a
  # CONST_SITE_CACHE helper (which passes d = "0").
  def const_lookup_block(d, name, owner_path)
    if owner_path == ['Object']
      "  r#{d} = mrb_const_get(M, mrb_obj_value(M->object_class), mrb_intern_cstr(M, \"#{name}\"));\n"
    else
      @const_lookup_helper_used = true
      out = String.new
      out << "  {\n"
      scope_vars = []
      current = 'mrb_obj_value(M->object_class)'
      owner_path.each_with_index do |seg, i|
        out << "    mrb_value scope#{i} = mrb_const_get(M, #{current}, mrb_intern_cstr(M, \"#{seg}\"));\n"
        scope_vars << "scope#{i}"
        current = "scope#{i}"
      end
      out << "    mrb_bool ok = FALSE;\n"
      out << "    mrb_value r#{d}_tmp = mrb_nil_value();\n"
      scope_vars.reverse_each do |sv|
        out << "    if (!ok) r#{d}_tmp = bc2cpp_const_try(M, #{sv}, mrb_intern_cstr(M, \"#{name}\"), &ok);\n"
      end
      out << "    if (!ok) r#{d}_tmp = mrb_const_get(M, mrb_obj_value(M->object_class), mrb_intern_cstr(M, \"#{name}\"));\n"
      out << "    r#{d} = r#{d}_tmp;\n"
      out << "  }\n"
      out
    end
  end

  # File-scope state and helpers for CONST_SITE_CACHE. Each helper returns the
  # constant's class or module, running the full lookup only until that first
  # succeeds (a failed lookup still raises from the same code and stores
  # nothing). Only a class/module value is stored. Keyed on the mrb_state* with
  # its own reset, dropped by each compiled gem's gem_final via
  # bc2cpp_reset_const_site_cache(); always emitted so gem_final can call it.
  def emit_const_site_cache
    entries = (@const_site_cache || {}).values
    count = [entries.size, 1].max
    out = +"// CONST_SITE_CACHE -- see tools/bc2cpp/const_site_cache.rb.\n"
    out << "static mrb_state* bc2cpp_cconst_state = nullptr;\n"
    out << "static mrb_value bc2cpp_cconst_slots[#{count}];\n"
    out << "static bool bc2cpp_cconst_have[#{count}] = {};\n"
    out << "static void bc2cpp_reset_const_site_cache() {\n" \
           "  bc2cpp_cconst_state = nullptr;\n" \
           "  for (bool& h : bc2cpp_cconst_have) h = false;\n" \
           "}\n"
    entries.each do |slot|
      i = slot[:index]
      out << "static mrb_value bc2cpp_cconst_#{i}(mrb_state* M) {\n" \
             "  if (bc2cpp_cconst_state != M) {\n" \
             "    bc2cpp_reset_const_site_cache();\n" \
             "    bc2cpp_cconst_state = M;\n" \
             "  }\n" \
             "  if (bc2cpp_cconst_have[#{i}]) return bc2cpp_cconst_slots[#{i}];\n" \
             "  mrb_value r0 = mrb_nil_value();\n"
      out << slot[:body].lines.map { |l| "  #{l}" }.join
      out << "  if (mrb_type(r0) == MRB_TT_CLASS || mrb_type(r0) == MRB_TT_MODULE) {\n" \
             "    bc2cpp_cconst_slots[#{i}] = r0;\n" \
             "    bc2cpp_cconst_have[#{i}] = true;\n" \
             "  }\n" \
             "  return r0;\n" \
             "}\n"
    end
    out
  end

  def dynamic_dispatch_line(d, recv, name, argv)
    if argv.empty?
      "r#{d} = mrb_funcall(M, #{recv}, \"#{name}\", 0);\n"
    else
      "r#{d} = mrb_funcall(M, #{recv}, \"#{name}\", #{argv.size}, #{argv.join(', ')});\n"
    end
  end

  def regs(args_text, count)
    args_text.scan(/R(\d+)/).flatten.first(count)
  end

  def c_string_literal(s)
    '"' + s.bytes.map { |b| format('\\x%02x', b) }.join + '"'
  end
end

if $PROGRAM_NAME == __FILE__
  srcs = ARGV
  raise 'usage: bc2cpp.rb file1.rb [file2.rb ...]  (env: MRBC, OUT_SYMBOL, OUT_DIR, ONLY_OWNERS)' if srcs.empty?

  symbol = ENV['OUT_SYMBOL'] || File.basename(srcs.first, '.rb').gsub(/[^a-zA-Z0-9_]/, '_')
  out_dir = ENV['OUT_DIR'] || File.dirname(srcs.first)

  c_src, disasm_text = run_mrbc(srcs, symbol, out_dir)
  ireps, root_label = parse_c_dump(c_src, symbol)
  order = dfs_order(ireps, root_label)
  blocks, block_files, block_catches = parse_disasm_blocks(disasm_text)
  merge!(ireps, order, blocks, block_files, block_catches)
  registry, superclass_of, container_constants, included_modules, prepended_modules, unknown_mixins,
    struct_member_lists = build_registry(ireps, root_label)

  # NATIVE_SRCS: shell-word-separated list of C/C++ source files (e.g.
  # mruby-rgss/src/*.cxx) to scan for mrb_define_method-family call sites --
  # see extract_native_method_names's own comment. Optional: omitting it
  # just means the registry stays exactly as unsound as it always was with
  # respect to that native gem, same as before this existed.
  native_name_sources = nil
  native_expression_devirt = {}
  native_registered_expressions = {}
  if ENV['NATIVE_SRCS']
    native_paths = Shellwords.split(ENV['NATIVE_SRCS'])
    native_expression_devirt = NativeExpressionDevirt.analyze(native_paths)
    native_registered_expressions = NativeExpressionDevirt.analyze_exact_class_expressions(native_paths)
    warn "== generated native C-expression devirtualizations (#{native_expression_devirt.size}) =="
    native_expression_devirt.sort.each { |name, expression| warn "  C_EXPR :#{name}  (#{expression})" }
    native_registered_expressions.sort.each do |name, entries|
      entries.each do |entry|
        owner = entry[:owner]
        warn "  C_EXPR :#{name}  (#{owner[:class_name]}##{name}: #{entry[:expression]})"
      end
    end
    warn ''
    # ZSUPER_NATIVE_SUPPORT: the per-name source map is the scan, and the
    # flat name set below is derived from its own keys -- so NATIVE_SRCS is
    # still read exactly once, and the two can never disagree about which
    # names the native world defines.
    native_name_sources = extract_native_method_sources(native_paths)
    native_names = native_name_sources.keys.to_set
    flipped = native_names.select { |n| registry.key?(n) && registry[n].size == 1 }
    native_names.each do |name|
      registry[name] << MethodDef.new(name: name, owner: '<native>', irep: nil, visibility: :public)
    end
    warn "== native method names (#{native_names.size} from NATIVE_SRCS, #{flipped.size} flipped a MONO name to POLY) =="
    flipped.sort.each { |n| warn "  FLIP :#{n}" }
    warn ''
    # NATIVE_CONSTRUCT_SCHEMA_AUDIT (see that module's own header):
    # audit-only, never consulted by codegen. Skipped entirely without
    # NATIVE_SRCS -- no native text to scrape means nothing to audit
    # against, and proving nothing is always the safe direction.
    warn '== native construct schema audit (row vs scraped mrb_get_args) =='
    NATIVE_CONSTRUCT_TARGETS.sort.each do |klass, row|
      verdict, detail = NativeConstructSchema.audit(native_paths, klass, row)
      warn "  #{verdict.to_s.upcase}  #{klass}  (#{detail})"
    end
    warn ''
  end

  warn '== whole-program method registry =='
  registry.sort.each do |name, defs|
    mono = defs.size == 1
    owners = defs.map(&:owner).join(', ')
    warn "  #{mono ? 'MONO' : 'POLY'}  :#{name}  (#{defs.size} def#{'s' unless defs.size == 1}: #{owners})"
  end

  arg_types = ArgTypes.analyze(ireps, registry)
  warn ''
  warn '== call-site argument-type inference (MONO names only) =='
  inferred_any = false
  arg_types.each do |name, types|
    types.each_with_index do |t, i|
      next unless t

      inferred_any = true
      warn "  ARG  :#{name}, position #{i + 1}  (#{t})"
    end
  end
  warn '  (none inferred)' unless inferred_any

  annotations = Annotations.extract(ireps, registry)
  warn ''
  warn '== magic-comment annotations (# bc2cpp: (T, ...) -> T) =='
  if annotations.empty?
    warn '  (none found)'
  else
    annotations.each do |label, ann|
      d = registry.values.flatten.find { |md| md.irep == label }
      name = d ? "#{d.owner}##{d.name}" : label
      warn "  ANNOTATED  #{name}  (#{ann.args.inspect} -> #{ann.ret.inspect})"
    end
  end

  # INTEGER_CONST_EMBED_SUPPORT / ARRAY_RETURN_IVAR_HINT: `foreign_ruby_srcs`/
  # `foreign_methods`/`integer_constants` are computed here, above
  # IvarLayout.analyze, for two independent reasons now: IvarLayout's own
  # GETCONST/GETMCNST case (see trace_type's own INTEGER_CONST_EMBED_SUPPORT
  # comment) needs `integer_constants` to embed a `@x = SOME_INT_CONST`
  # ivar, and ClassLayout's own probing pass (further below) needs
  # `foreign_methods` for ARRAY_RETURN_PROOF. `native_paths` is already
  # whatever NATIVE_SRCS named (nil when it wasn't passed at all -- the
  # established no-NATIVE_SRCS diagnostic mode); FOREIGN_RUBY_SRCS is its
  # Ruby-side twin (`foreign_mrblib_srcs`, compiled_gems.rb). Omitting either
  # one only ever REMOVES poison/proof, i.e. makes both analyses less
  # permissive than a real build -- so when either is missing, both skip
  # outright and prove/embed nothing extra, rather than run against a
  # knowingly incomplete picture. Both are pure reads of ENV and of files on
  # disk with no dependency on anything between the old and new positions,
  # and neither produces any diagnostic output on its own (INTEGER_CONSTANT_
  # PROOF's own `warn` block, moved down here with it, still prints in the
  # same relative order right before `== ivar embedding ==` instead of after
  # `== annotation candidates ==` -- every diagnostic consumer looks up a
  # section by its own header text, never by position, so this is silent).
  foreign_ruby_srcs = ENV['FOREIGN_RUBY_SRCS'] ? Shellwords.split(ENV['FOREIGN_RUBY_SRCS']) : nil
  foreign_methods = foreign_ruby_srcs ? foreign_method_names(foreign_ruby_srcs) : nil

  integer_constants =
    if ENV['NATIVE_SRCS'] && foreign_ruby_srcs
      IntegerConstants.analyze(ireps, native_paths, foreign_ruby_srcs)
    else
      Set.new
    end
  warn "== integer-valued constants proven (INTEGER_CONSTANT_PROOF) =="
  if integer_constants.empty?
    warn '  (none)'
  else
    integer_constants.sort.each { |n| warn "  CONST #{n}" }
  end

  integer_constant_values = IntegerConstants.analyze_values(ireps, integer_constants)
  warn "== integer constant literal values proven (INTEGER_CONSTANT_VALUE_PROOF): #{integer_constant_values.size} of #{integer_constants.size} =="
  integer_constant_values.sort.each { |n, v| warn "  CONST #{n} = #{v}" }

  # FIXNUM_RETURN_IVAR_HINT: this is Level 0 -- IvarLayout computed with no
  # FIXNUM_RETURN_PROOF evidence at all, byte-for-byte what this driver
  # always computed before this mechanism existed. The `== ivar embedding ==`
  # diagnostic is printed further below, once the enriched, final (Level 2)
  # table is available -- see that later call site's own header -- so this
  # one is deliberately silent, the same "diagnostic reflects only the real,
  # final fact set codegen uses" discipline the CLASS_HINT/CLASS_CANDIDATE
  # block below already holds itself to for ClassLayout's own analogous
  # ARRAY_RETURN_IVAR_HINT stratification.
  ivar_layout = IvarLayout.analyze(ireps, registry, arg_types, annotations, integer_constants)

  known_owners = registry.values.flatten.map(&:owner).uniq
  class_annotations = ClassAnnotations.extract(ireps, registry, known_owners)
  warn ''
  warn '== magic-comment class annotations (# bc2cpp: (ClassName, ...)) =='
  if class_annotations.empty?
    warn '  (none found)'
  else
    class_annotations.each do |label, ann|
      d = registry.values.flatten.find { |md| md.irep == label }
      name = d ? "#{d.owner}##{d.name}" : label
      warn "  CLASS_ANNOTATED  #{name}  (#{ann.args.inspect})"
    end
  end

  warn ''
  warn '== known container-class constants (Array/Hash/Range-valued, whole program) =='
  if container_constants.empty?
    warn '  (none)'
  else
    container_constants.sort.each { |name, cls| warn "  CONST_HINT  #{name}  (#{cls})" }
  end

  # ANNOTATED_ARRAY_RETURN_THREADING: the exact same MONO-keyed `-> Array`
  # lookup CodeGen#annotated_array_return performs (see its own comment for
  # the full soundness argument -- one real irep per name, so a magic
  # comment on it can only ever speak for a call site nothing else in the
  # whole program could also be reaching), rebuilt here as a bare lambda
  # because CodeGen itself is not constructed yet at this point in the
  # driver (ClassLayout.analyze, like every other whole-program analysis
  # above it, runs before codegen starts) -- `annotations` (Annotations.
  # extract's own result, already computed above) and `registry` are both
  # already in scope, so this is nothing but the identical lookup CodeGen's
  # own instance method performs against its own `@annotations`/`@registry`
  # ivars, duplicated here rather than shared only because no shared
  # instance exists yet to call it on.
  annotated_array_return = lambda do |name|
    defs = registry[name]
    next false unless defs && defs.size == 1 && defs.first.irep

    annotations[defs.first.irep]&.ret == :array
  end
  # ANY_OPAQUE_SUPPORT: owner -> {ivar => :any | :opaque}, filled in by
  # ClassLayout.analyze as a side effect -- see that method's own
  # `poison_reason` header. Reported below as two extra, purely additive
  # breakdowns of the exact same `class_layout_unknowns` list -- neither
  # that list's own membership nor the `CLASS_CANDIDATE` lines change.
  # FIXNUM_RETURN_PROOF / ARRAY_RETURN_PROOF: the out-of-closed-world poison
  # set both need. Hoisted above ClassLayout.analyze (it used to sit just
  # before CodeGen.new) because the probing pass immediately below consumes
  # ARRAY_RETURN_PROOF, which refuses to prove anything at all without it.
  # Without FOREIGN_RUBY_SRCS this stays nil and compute_array_return_names
  # proves nothing, so the probe below is simply vacuous rather than
  # optimistic -- the established no-FOREIGN_RUBY_SRCS diagnostic mode.

  # ---------------------------------------------------------------------------
  # ARRAY_RETURN_IVAR_HINT: ClassLayout and ARRAY_RETURN_PROOF are MUTUALLY
  # dependent, and this is the stratification that breaks the cycle.
  #
  # THE CYCLE IS REAL, not hypothetical. `compute_array_return_names` proves
  # "every RETURN site of this body holds an Array" with `proven_array_operand?`
  # -> `trace_new_target`, whose GETIV terminal reads the ClassLayout table
  # (`ivar_classes = @class_layout[d.owner]`, array_return_sites_proven?). So
  # ARRAY_RETURN_PROOF already consumes ClassLayout. Feeding ARRAY_RETURN_PROOF
  # back INTO ClassLayout's own SETIV arm -- which is the whole point of this
  # change -- closes the loop. Left naive, that loop would admit exactly the
  # circular nonsense it looks like it should:
  #
  #     def initialize; @queue = turn_order; end
  #     def turn_order; @queue; end          # @queue is really nil
  #
  # "@queue is an Array because turn_order returns one, and turn_order returns
  # an Array because @queue is one" is a derivation with no base case.
  #
  # THE FIX: STRATIFY. Level 0 is the ClassLayout table computed with NO
  # ARRAY_RETURN_PROOF evidence at all -- byte-for-byte the table this driver
  # produced before this change. Level 1 is ARRAY_RETURN_PROOF computed against
  # level 0. Level 2 is the ClassLayout table computed WITH level 1. Every fact
  # at level N+1 is derived only from facts at level N, so every derivation is
  # well-founded by construction and the cycle above is refused: `@queue` is
  # UNKNOWN at level 0, so `turn_order` is not admitted at level 1, so `@queue`
  # is still UNKNOWN at level 2. Stable, and correctly so.
  #
  # WHY EACH LEVEL IS SOUND GIVEN THE ONE BELOW IT, by induction on N:
  #   - Level 0 is today's shipped, already-argued table.
  #   - Level 1 is ARRAY_RETURN_PROOF, whose own soundness argument (see
  #     compute_array_return_names' header) is parameterized on exactly one
  #     external input, "the ClassLayout facts I read are true" -- supplied by
  #     level 0.
  #   - Level 2 is ClassLayout.analyze, whose SETIV arm now has one additional
  #     evidence source whose truth is supplied by level 1. The aggregation
  #     itself is untouched: two sites that disagree still poison to UNKNOWN.
  #
  # THE RESULT IS MONOTONE, which is what makes this strictly additive rather
  # than a re-derivation. The new evidence can only fire where
  # `proven_array_source_scan` previously returned nil and the site therefore
  # yielded UNKNOWN; it turns those, and only those, into 'Array'. So no ivar
  # that had a real class hint can lose or change it -- level 2's table is a
  # superset of level 0's. Everything downstream (ArrayElementLayout,
  # HashElementLayout, every diagnostic below, and CodeGen itself) is fed level
  # 2 and is therefore internally consistent; nothing reads a stale table.
  #
  # WHY NOT ITERATE TO A JOINT FIXPOINT (the ENTRY_ARG_ALTERNATION shape)? It
  # would be sound -- each further level is sound by the same induction -- but
  # it is deliberately NOT done here. Two levels is what the measured payoff
  # needs, stopping early is the conservative direction (strictly fewer facts
  # than a full alternation), and an unbounded alternation over a table this
  # many analyses hang off is a much larger change to justify. The real
  # CodeGen below does recompute ARRAY_RETURN_PROOF against the level-2 table
  # as it always has, so the proven-Array name set genuinely does get the
  # benefit of the richer table; only ClassLayout itself stops at level 2.
  # ---------------------------------------------------------------------------
  class_layout_probe = ClassLayout.known(
    ClassLayout.analyze(ireps, registry, class_annotations, container_constants, annotated_array_return)
  )
  # Built far enough to answer `array_return_names` and no further -- see
  # CodeGen#initialize's own `analysis_only` comment for why stopping there is
  # exact. The layouts this probe is not given ({} for element/hash-element,
  # an empty integer-constant set, nil outside-tokens) are all inputs
  # `compute_array_return_names` never reads.
  require_relative 'compiled_gems'
  # BC2CPP_SELF_REGISTERING: EMBED_WIRED's own allowlist (compiled_gems.rb's
  # BC2CPP_WIRED_EMBEDDINGS) exists because the real compiled gems' own
  # register.cxx is hand-written and does not install every compiled entry
  # point of an embedding class by construction -- an unregistered one keeps
  # running interpreted, reading the ordinary ivar table while a compiled
  # sibling writes the embedded struct, and sees nil (see that constant's own
  # comment for the real, shipped bug this caused). A caller whose OWN
  # register.cxx-equivalent is generated FROM the exact same `embeds`/
  # `compiled entry points` diagnostic this driver already prints -- so
  # "compiled and embeddable" and "installed" are the same fact by
  # construction, with no hand-maintenance gap possible -- doesn't have that
  # problem and can say so here, skipping the allowlist and letting every
  # class `IvarLayout`/`drop_unsafe_embeddings` themselves already proved
  # safe actually embed. `drop_unsafe_embeddings`'s OTHER checks (every
  # accessor compiles clean, no native attr_reader/writer collision) still
  # run unconditionally either way; this only ever removes the extra,
  # hand-maintenance-specific allowlist gate. tools/optcarrot_probe/
  # compiled_run.rb sets this: its own emit_register already installs every
  # compiled method of any class its own `embeds` diagnostic names (see that
  # function's own comment), the identical guarantee BC2CPP_WIRED_EMBEDDINGS
  # exists to provide by hand for the real gems.
  CodeGen.wired_embeddings = BC2CPP_WIRED_EMBEDDINGS unless ENV['BC2CPP_SELF_REGISTERING'] == '1'
  return_names_probe = CodeGen.new(ireps, registry, ivar_layout, class_layout_probe, class_annotations,
                                    annotations, superclass_of, {}, {}, container_constants, {},
                                    Set.new, foreign_methods, nil, nil,
                                    analysis_only: true,
                                    native_expression_devirt: native_expression_devirt,
                                    native_registered_expressions: native_registered_expressions)
  array_return_probe = return_names_probe.array_return_names
  # RETCLASS_SELF_CALL_SUPPORT: computed from the same level-0 probe as
  # array_return_probe just above, same stratification, same reason -- see
  # ClassLayout.analyze's own `ret_class_proof` header.
  class_return_probe = return_names_probe.class_return_names
  class_poison_reason = {}
  class_layout_raw = ClassLayout.analyze(ireps, registry, class_annotations, container_constants,
                                         annotated_array_return, poison_reason: class_poison_reason,
                                         array_ret_proof: ->(n) { array_return_probe.include?(n) },
                                         ret_class_proof: ->(n) { class_return_probe[n] })
  class_layout = ClassLayout.known(class_layout_raw)
  warn ''
  warn '== known-ivar-class hints (devirtualization only, never embedded) =='
  if class_layout.empty?
    warn '  (none)'
  else
    class_layout.each do |klass, ivars|
      ivars.each { |name, cls| warn "  CLASS_HINT  #{klass}#@#{name}  (#{cls})" }
    end
  end

  class_layout_unknowns = ClassLayout.unknowns(class_layout_raw)
  warn ''
  warn '== ivar-class candidates (real SETIV evidence found, but poisoned to unknown) =='
  if class_layout_unknowns.empty?
    warn '  (none)'
  else
    class_layout_unknowns.sort.each { |n| warn "  CLASS_CANDIDATE  #{n}" }
  end

  # ANY_OPAQUE_SUPPORT: the same candidate list, split by why. :any means
  # two real sites were traced and proven to genuinely disagree -- a fact
  # about the program, not a gap in this analysis, and no future
  # annotation round should spend time on it. :opaque means at least one
  # site could never be traced at all -- the real, actionable candidate
  # list for a future code-reading/annotation round (see
  # ClassLayout.analyze's own `poison_reason` header for the full
  # distinction).
  warn ''
  warn '== ivar-class candidates split: ANY (proven heterogeneous, not fixable) =='
  any = ClassLayout.unknowns_by_reason(class_layout_raw, class_poison_reason, :any)
  if any.empty?
    warn '  (none)'
  else
    any.sort.each { |n| warn "  CLASS_CANDIDATE_ANY  #{n}" }
  end

  warn ''
  warn '== ivar-class candidates split: OPAQUE (unresolved, may be fixable) =='
  opaque = ClassLayout.unknowns_by_reason(class_layout_raw, class_poison_reason, :opaque)
  if opaque.empty?
    warn '  (none)'
  else
    opaque.sort.each { |n| warn "  CLASS_CANDIDATE_OPAQUE  #{n}" }
  end

  # ELEMENT_CLASS_SUPPORT: the element dimension of the same ivar facts
  # (see ArrayElementLayout's own header). Runs after ClassLayout because
  # it only ever sweeps ivars ClassLayout has already proved hold an
  # `Array`, and after ClassAnnotations because an incoming-argument class
  # hint is one of the real terminals its value tracer bottoms out at.
  element_annotations = ElementAnnotations.extract(ireps, registry, known_owners)
  warn ''
  warn '== magic-comment element annotations (# bc2cpp: ... -> Array<Klass> / -> Klass) =='
  if element_annotations.empty?
    warn '  (none found)'
  else
    element_annotations.each do |label, ann|
      d = registry.values.flatten.find { |md| md.irep == label }
      name = d ? "#{d.owner}##{d.name}" : label
      claim = ann.element ? "Array<#{ann.element}>" : ann.ret_class
      warn "  ELEM_ANNOTATED  #{name}  (-> #{claim})"
    end
  end

  # ANY_OPAQUE_SUPPORT: see class_poison_reason's own comment above --
  # identical mechanism, one analysis over.
  element_poison_reason = {}
  element_raw = ArrayElementLayout.analyze(ireps, registry, class_layout, class_annotations,
                                           element_annotations, superclass_of,
                                           poison_reason: element_poison_reason)
  element_layout = ArrayElementLayout.known(element_raw)
  warn ''
  warn '== known-array-element-class hints (guarded devirtualization only) =='
  if element_layout.empty?
    warn '  (none)'
  else
    element_layout.each do |klass, ivars|
      ivars.each { |name, cls| warn "  ELEM_HINT  #{klass}#@#{name}  (Array<#{cls}>)" }
    end
  end

  # PRIMITIVE_ELEMENT_SUPPORT: every ivar whose elements resolved to a
  # primitive scalar tag rather than a real registry class -- informational
  # only, see ArrayElementLayout.primitives' own comment for why these are
  # deliberately excluded from `element_layout`/`ELEM_HINT` above.
  element_primitives = ArrayElementLayout.primitives(element_raw)
  warn ''
  warn '== known-array-element PRIMITIVE hints (informational only, never embedded) =='
  if element_primitives.empty?
    warn '  (none)'
  else
    element_primitives.each do |klass, ivars|
      ivars.each { |name, cls| warn "  ELEM_HINT_PRIMITIVE  #{klass}#@#{name}  (Array<#{cls}>)" }
    end
  end

  element_unknowns = ArrayElementLayout.unknowns(element_raw)
  warn ''
  warn '== array-element candidates (proven-Array ivar, element class poisoned to unknown) =='
  if element_unknowns.empty?
    warn '  (none)'
  else
    element_unknowns.each { |n| warn "  ELEM_CANDIDATE  #{n}" }
  end

  warn ''
  warn '== array-element candidates split: ANY (proven heterogeneous, not fixable) =='
  elem_any = ArrayElementLayout.unknowns_by_reason(element_raw, element_poison_reason, :any)
  if elem_any.empty?
    warn '  (none)'
  else
    elem_any.sort.each { |n| warn "  ELEM_CANDIDATE_ANY  #{n}" }
  end

  warn ''
  warn '== array-element candidates split: OPAQUE (unresolved, may be fixable) =='
  elem_opaque = ArrayElementLayout.unknowns_by_reason(element_raw, element_poison_reason, :opaque)
  if elem_opaque.empty?
    warn '  (none)'
  else
    elem_opaque.sort.each { |n| warn "  ELEM_CANDIDATE_OPAQUE  #{n}" }
  end

  # HASH_ELEMENT_SUPPORT: the Hash-value dimension of the same ivar facts
  # (see HashElementLayout's own header). Runs after ArrayElementLayout so
  # a Hash value chained through a known-element array can still resolve
  # -- see HashElementLayout.analyze's own comment on `array_elements`.
  # ANY_OPAQUE_SUPPORT: see class_poison_reason's own comment above --
  # identical mechanism, one analysis over.
  hash_poison_reason = {}
  hash_element_raw = HashElementLayout.analyze(ireps, registry, class_layout, class_annotations,
                                               element_annotations, element_raw, superclass_of,
                                               poison_reason: hash_poison_reason)
  hash_element_layout = HashElementLayout.known(hash_element_raw)
  warn ''
  warn '== known-hash-element-class hints (guarded devirtualization only) =='
  if hash_element_layout.empty?
    warn '  (none)'
  else
    hash_element_layout.each do |klass, ivars|
      ivars.each { |name, cls| warn "  HASH_ELEM_HINT  #{klass}#@#{name}  (Hash<#{cls}>)" }
    end
  end

  # PRIMITIVE_ELEMENT_SUPPORT: see element_primitives' own comment above --
  # identical mechanism, one table over.
  hash_element_primitives = HashElementLayout.primitives(hash_element_raw)
  warn ''
  warn '== known-hash-element PRIMITIVE hints (informational only, never embedded) =='
  if hash_element_primitives.empty?
    warn '  (none)'
  else
    hash_element_primitives.each do |klass, ivars|
      ivars.each { |name, cls| warn "  HASH_ELEM_HINT_PRIMITIVE  #{klass}#@#{name}  (Hash<#{cls}>)" }
    end
  end

  hash_element_unknowns = HashElementLayout.unknowns(hash_element_raw)
  warn ''
  warn '== hash-element candidates (proven-Hash ivar, value class poisoned to unknown) =='
  if hash_element_unknowns.empty?
    warn '  (none)'
  else
    hash_element_unknowns.each { |n| warn "  HASH_ELEM_CANDIDATE  #{n}" }
  end

  warn ''
  warn '== hash-element candidates split: ANY (proven heterogeneous, not fixable) =='
  hash_any = HashElementLayout.unknowns_by_reason(hash_element_raw, hash_poison_reason, :any)
  if hash_any.empty?
    warn '  (none)'
  else
    hash_any.sort.each { |n| warn "  HASH_ELEM_CANDIDATE_ANY  #{n}" }
  end

  warn ''
  warn '== hash-element candidates split: OPAQUE (unresolved, may be fixable) =='
  hash_opaque = HashElementLayout.unknowns_by_reason(hash_element_raw, hash_poison_reason, :opaque)
  if hash_opaque.empty?
    warn '  (none)'
  else
    hash_opaque.sort.each { |n| warn "  HASH_ELEM_CANDIDATE_OPAQUE  #{n}" }
  end

  candidates = report_annotation_candidates(ireps, registry, arg_types, annotations)
  warn ''
  warn '== annotation candidates (opaque incoming argument, unresolved) =='
  if candidates.empty?
    warn '  (none)'
  else
    candidates.each do |c|
      target = c[:ivar] ? "-> @#{c[:ivar]}" : "-> (used in #{c[:via]})"
      warn "  CANDIDATE  #{c[:owner]}##{c[:name]}, arg #{c[:pos]}/#{c[:mand]} #{target}"
    end
  end

  # `annotations` (computed above, previously fed only to IvarLayout.analyze)
  # also now drives NATIVE_ARG_TARGETS' own native-argument calling
  # convention -- see that constant's own comment.
  # FIXNUM_RETURN_PROOF: same out-of-closed-world poison gate INTEGER_CONSTANT_
  # PROOF uses right above -- without FOREIGN_RUBY_SRCS this analysis would be
  # strictly more optimistic than a real build, so it is skipped entirely
  # (nil, never an empty set, which compute_fixnum_return_names reads as "the
  # scan never ran" and proves nothing at all) rather than run half-informed.
  # ENTRY_ARG_CALLSITE_PROOF: the same two out-of-closed-world inputs again,
  # scanned for EVERY identifier token rather than only for method-defining
  # forms -- see outside_world_tokens for why that mechanism needs the
  # broader question ("can anything out there CALL this name") answered, and
  # why nil rather than an empty Set when either input is absent.
  outside_tokens =
    if native_paths && foreign_ruby_srcs
      outside_world_tokens(native_paths + foreign_ruby_srcs)
    end
  warn ''
  # BC2CPP_SELF_REGISTERING: see the identical guard above, on the probing
  # CodeGen this driver builds first -- same env var, same reasoning, kept in
  # sync here for the real CodeGen actually used to emit code.
  CodeGen.wired_embeddings = BC2CPP_WIRED_EMBEDDINGS unless ENV['BC2CPP_SELF_REGISTERING'] == '1'
  CodeGen.stable_class_constants = StableClassConstants.analyze(ireps, native_paths, foreign_ruby_srcs) |
                                    StableClassConstants.analyze_native(ireps, native_paths, foreign_ruby_srcs)
  warn "== stable class constants (CONST_SITE_CACHE): #{CodeGen.stable_class_constants.size} =="
  CodeGen.struct_members = struct_member_lists
  warn "== Struct.new owners with a known member list (STRUCT_INDEX_CACHE): #{CodeGen.struct_members.size} =="
  CodeGen.integer_constant_values = integer_constant_values
  CodeGen.stable_class_constants.sort.each { |n| warn "  STABLE_CLASS #{n}" }

  # ---------------------------------------------------------------------------
  # FIXNUM_RETURN_IVAR_HINT: IvarLayout and FIXNUM_RETURN_PROOF are MUTUALLY
  # dependent, and this is the stratification that breaks the cycle -- the
  # exact same shape ARRAY_RETURN_IVAR_HINT above already uses for ClassLayout
  # and ARRAY_RETURN_PROOF, applied to a different pair of facts.
  #
  # THE CYCLE IS REAL. IvarLayout.trace_type's SEND case can only trust a bare
  # method name's return type once FIXNUM_RETURN_PROOF has already proven it
  # (compute_fixnum_return_names, CodeGen) -- but that proof's own admission
  # rule 4 reads @ivar_layout (proof source 3, embed_type, inside
  # proven_fixnum_operand?). Feeding FIXNUM_RETURN_PROOF back into IvarLayout,
  # the whole point of this change, would otherwise be circular:
  # tools/optcarrot_probe/README.md's own "Why CPU's own register file stays
  # unembedded" section names the real shape this closes --
  # `@_pc = peek16(RESET_VECTOR)`-style SETIV sites whose source is a SEND
  # result, where `peek16` itself is proven Fixnum-returning only via ITS OWN
  # ivar reads.
  #
  # THE FIX: STRATIFY, not iterate to a full alternation (see "WHY NOT..."
  # below). Level 0 is `ivar_layout` exactly as already computed above --
  # today's shipped table, no FIXNUM_RETURN_PROOF evidence at all. Level 1 is
  # FIXNUM_RETURN_PROOF computed by a probing CodeGen built from level 0 (via
  # `analysis_only: :fixnum_return`, CodeGen#initialize's own comment) --
  # every OTHER whole-program table this probe needs (class_layout,
  # element_layout, hash_element_layout, container_constants, ...) is already
  # final by this exact point in the driver and none of them depend on
  # ivar_layout at all (ClassLayout/ArrayElementLayout/HashElementLayout's own
  # `self.analyze` signatures take no ivar_layout parameter), so this probe
  # gets the SAME real tables the final CodeGen below uses, not placeholders.
  # Level 2 re-runs IvarLayout.analyze with level 1's proof now available to
  # trace_type's SEND case, and is what the real CodeGen below actually
  # receives.
  #
  # WHY SOUND, given level 0 and every non-ivar table are sound: level 1 is
  # exactly today's FIXNUM_RETURN_PROOF computation, unchanged code, just run
  # one step earlier against level 0's ivar table instead of a hypothetical
  # richer one -- a strict subset of the ivar facts the real, final CodeGen
  # itself ends up with, so this probe is only ever AS OR LESS permissive than
  # a single-pass oracle could be, never more. Level 2 only ever turns a SEND
  # site trace_type's existing cases already left UNKNOWN into `:fixnum` (an
  # additive new arm on that case, guarded by MONO uniqueness the same way
  # every other bare-name whole-program proof in this file already is -- see
  # that arm's own comment) -- no existing embeddable ivar can lose or change
  # its type, so level 2's table is a superset of level 0's, the identical
  # monotonicity argument ARRAY_RETURN_IVAR_HINT's own header makes for
  # ClassLayout.
  #
  # WHY NOT ITERATE TO A JOINT FIXPOINT (the ENTRY_ARG_ALTERNATION shape)?
  # Sound either way -- each further level would stay sound by the same
  # induction -- but deliberately not done here, for the identical reasons
  # ARRAY_RETURN_IVAR_HINT's own header already gives for ClassLayout: two
  # levels is what a real, measured target needs, stopping early is the
  # conservative direction, and the real CodeGen below still recomputes
  # FIXNUM_RETURN_PROOF itself against the level-2 table exactly as it always
  # has (this change touches nothing about that recomputation), so the final,
  # shipped proof set does get the full benefit of the richer table; only
  # IvarLayout itself stops at level 2.
  # ---------------------------------------------------------------------------
  fixnum_return_probe = CodeGen.new(ireps, registry, ivar_layout, class_layout, class_annotations, annotations,
                                    superclass_of, element_layout, element_annotations, container_constants,
                                    hash_element_layout, integer_constants, foreign_methods, outside_tokens,
                                    native_name_sources, included_modules, prepended_modules, unknown_mixins,
                                    analysis_only: :fixnum_return,
                                    native_expression_devirt: native_expression_devirt,
                                    native_registered_expressions: native_registered_expressions).fixnum_return_names
  ivar_layout = IvarLayout.analyze(ireps, registry, arg_types, annotations, integer_constants, fixnum_return_probe)
  warn ''
  warn '== ivar embedding =='
  if ivar_layout.empty?
    warn '  (none embeddable)'
  else
    ivar_layout.each do |klass, ivars|
      ivars.each { |name, type| warn "  EMBED  #{klass}#@#{name}  (#{type})" }
    end
  end

  gen = CodeGen.new(ireps, registry, ivar_layout, class_layout, class_annotations, annotations, superclass_of,
                    element_layout, element_annotations, container_constants, hash_element_layout,
                    integer_constants, foreign_methods, outside_tokens, native_name_sources,
                    included_modules, prepended_modules, unknown_mixins,
                    native_expression_devirt: native_expression_devirt,
                    native_registered_expressions: native_registered_expressions)
  warn '== methods proven Fixnum-returning (FIXNUM_RETURN_PROOF) =='
  if gen.fixnum_return_names.empty?
    warn '  (none)'
  else
    gen.fixnum_return_names.sort.each { |n| warn "  RET #{n}" }
  end
  warn ''
  # ARRAY_RETURN_PROOF: the Array analogue of the listing just above, same
  # one-line-per-proven-name shape so the coverage report can count it the
  # same way. See CodeGen#compute_array_return_names.
  warn '== methods proven Array-returning (ARRAY_RETURN_PROOF) =='
  if gen.array_return_names.empty?
    warn '  (none)'
  else
    gen.array_return_names.sort.each { |n| warn "  ARET #{n}" }
  end
  warn ''
  # ENTRY_ARG_CALLSITE_PROOF: one line per proven (method, argument
  # position), spelled by real owner/name rather than by irep label so the
  # coverage report and a human reading this diagnostic see the same thing.
  warn '== entry arguments proven Fixnum by call-site enumeration (ENTRY_ARG_CALLSITE_PROOF) =='
  entry_arg_facts = gen.entry_arg_fixnum_facts
  if entry_arg_facts.empty?
    warn '  (none)'
  else
    owner_by_irep = {}
    registry.each_value { |defs| defs.each { |d| owner_by_irep[d.irep] = d if d.irep } }
    entry_arg_facts.map do |(label, k)|
      d = owner_by_irep[label]
      d ? "  ARG #{d.owner}##{d.name} arg#{k}" : "  ARG <irep #{label}> arg#{k}"
    end.sort.each { |l| warn l }
  end
  warn ''
  # ONLY_OWNERS narrows *emitted* code to specific classes (comma-separated,
  # e.g. "LCF::File,LCF::Database") without narrowing the closed-world
  # registry itself -- srcs above should still be the whole program (or at
  # least everything that could define a colliding method name); see
  # compile_all's own comment for why that distinction is load-bearing.
  only_owners = ENV['ONLY_OWNERS']&.split(',')
  # OTHER_OWNERS: classes this run trusts *another* gem's own bc2cpp run to
  # compile and expose (paired with OTHER_DECLS_HEADER below) -- see
  # compile_send's own comment on why a devirtualized call to one of these
  # is safe to emit despite not being compiled in this run at all.
  other_owners = ENV['OTHER_OWNERS']&.split(',')
  compiled = gen.compile_all(only_owners: only_owners, other_owners: other_owners)
  compiled += gen.emit_synthesized_accessors(only_owners: only_owners)

  # SKIP_UNSUPPORTED=1 drops any method whose body contains a `#error`
  # marker (an unmodeled opcode, or an arity this calling convention can't
  # express -- see pure_mandatory_arity?) from what actually gets emitted,
  # instead of emitting the #error into the output file. Default CLI usage
  # (exploring/measuring coverage) wants those markers visible; a real build
  # integration (mruby-lcf-compiled/mrbgem.rake) sets this, since a `#error`
  # in a file the C++ toolchain actually compiles halts the whole build --
  # the correct behavior for a method bc2cpp can't safely compile is exactly
  # what happens when it's just never emitted here: it keeps running on the
  # ordinary interpreted bytecode path, the documented fallback.
  if ENV['SKIP_UNSUPPORTED'] == '1'
    skipped, compiled = compiled.partition { |m| m[:code].include?('#error') }
    unless skipped.empty?
      warn ''
      warn '== skipped (unsupported, left on the interpreter) =='
      skipped.each { |m| warn "  #{m[:owner]}##{m[:name]}" }
    end
  end

  puts '#include <mruby.h>'
  # isnan/isinf/floor/ceil -- to_i's own Float case (see compile_native_
  # primitive_send's own TO_I_TYPE_TAG_DISPATCH comment) needs these to
  # reproduce flo_to_i's own real NaN/Infinity guard and truncation-
  # toward-zero, nothing else here already pulls this in.
  puts '#include <math.h>'
  puts '#include <mruby/numeric.h>'
  puts '#include <mruby/string.h>'
  puts '#include <mruby/variable.h>'
  puts '#include <mruby/data.h>'
  puts '#include <mruby/hash.h>'
  puts '#include <mruby/array.h>'
  puts '#include <mruby/class.h>'
  # mrb_range_new -- RANGE_INC/RANGE_EXC's own codegen (see compile_insn's
  # own comment on both), same "declared by a header nothing else here
  # already pulls in" gap HASH's own mruby/hash.h addition closed for
  # mrb_hash_new_capa/mrb_hash_set.
  puts '#include <mruby/range.h>'
  # mrb_protect_error -- GETCONST's own owner-scope-first lookup (see its
  # own comment above) needs this to safely try a scope and fall back to
  # Object without letting a genuinely-missing-there NameError propagate
  # out of the wrong branch. A real core API (always available, not gated
  # behind the mruby-error gem the way mrb_protect/mrb_rescue are).
  puts '#include <mruby/error.h>'
  # mrb_proc_new_cfunc -- BLOCK_CFUNC_FALLBACK_SUPPORT's own RProc
  # construction (emit_block_fallback_glue's own comment) needs this;
  # unlike mrb_str_aref above, this header has a real MRB_BEGIN_DECL/
  # MRB_END_DECL C-linkage guard (confirmed by reading it), so a plain
  # #include is safe here.
  puts '#include <mruby/proc.h>'
  # EXCEPTION_BREAK_SUPPORT: the real C++ exception type a BLOCK_FALLBACK
  # body's own compiled BREAK throws (compile_insn's own BREAK case) and
  # emit_block_fallback_glue's own call-site glue catches -- see
  # BLOCK_FALLBACK_UNSAFE_OPS's own comment for why this is safe on a
  # project that already builds mruby itself with MRB_USE_CXX_EXCEPTION.
  # Emitted unconditionally (cheap, a single header-only struct, no
  # linkage of its own to get wrong) rather than gated on whether this
  # run's own output happens to use it -- the same "always correct, no
  # conditional-emission bookkeeping" tradeoff the DIV/mrb_str_aref
  # `extern "C"` declarations just above already make.
  puts 'struct bc2cpp_block_break { mrb_value value; };'
  # EXCEPTION_RETURN_SUPPORT: bc2cpp_block_break's own sibling -- a
  # DIFFERENT type on purpose (compile_method's own top-level `try`/
  # `catch` and emit_block_fallback_glue's own per-call-site one must
  # never catch each other's exception; see BLOCK_FALLBACK_UNSAFE_OPS's
  # own comment for why C++'s exact catch-type matching is exactly what
  # makes that true for free, no discriminant field needed). Same
  # unconditional-emission tradeoff as bc2cpp_block_break just above.
  puts 'struct bc2cpp_method_return { mrb_value value; };'
  # VM_UNWIND_RESTORE: bc2cpp_block_break / bc2cpp_method_return are foreign
  # C++ exceptions, which mruby's own MRB_TRY/MRB_CATCH (`catch (mrb_jmpbuf*)`)
  # does not intercept. When one unwinds through real VM frames -- a compiled
  # block that `return`s or `break`s out of a Ruby-defined iterator such as
  # `each` -- mrb_vm_exec/mrb_funcall_with_block never run their own cleanup:
  # mrb->jmp is left pointing at a dead stack frame and the callinfo stack keeps
  # every frame pushed since. The desktop RPGMAKER_BC2CPP build then aborts in
  # mrb_vm_run's `c->ci == c->cibase || ...` assertion (and would corrupt the
  # stack without it). Every catch site therefore takes a mark before its
  # `try` and restores it here, mirroring what mrb_protect_error does for an
  # mruby exception: reset mrb->jmp and pop the leftover callinfos, unsharing
  # each popped frame's env exactly as the VM's own cipop does.
  puts <<~'CPP'
    struct Bc2cppVmMark { struct mrb_jmpbuf* jmp; ptrdiff_t ci_index; };
    static inline Bc2cppVmMark bc2cpp_vm_mark(mrb_state* M) {
      return { M->jmp, M->c->ci - M->c->cibase };
    }
    static void bc2cpp_vm_restore(mrb_state* M, const Bc2cppVmMark& mark) {
      M->jmp = mark.jmp;
      struct mrb_context* c = M->c;
      while (c->ci - c->cibase > mark.ci_index) {
        mrb_callinfo* ci = c->ci;
        mrb_vm_ci_env_clear(M, ci);
        struct RProc* blk = ci->blk;
        if (blk && !MRB_PROC_STRICT_P(blk) && MRB_PROC_ENV(blk) == mrb_vm_ci_env(&ci[-1])) {
          blk->flags |= MRB_PROC_ORPHAN;
        }
        c->ci--;
      }
      if (M->errinfo && (c->ci - c->cibase) < M->errinfo_ci_depth) M->errinfo = NULL;
    }
  CPP
  # ENSURE_RAII_SUPPORT: the one runtime piece a recognized `ensure`
  # region needs (recognize_ensure_region / emit_ensure_guard_open). A
  # real Ruby `ensure` has to run on EVERY exit from its protected range;
  # a C++ local's destructor is exactly that guarantee, for free, on all
  # of them at once:
  #
  #   - normal fall-through and an explicit `return` from inside the
  #     range: ordinary scope exit (a `return` evaluates its operand
  #     FIRST, then runs destructors -- which is precisely Ruby's own
  #     rule that a plain `ensure` cannot change the returned value).
  #   - this file's OWN non-local exits (`bc2cpp_block_break`,
  #     `bc2cpp_method_return` above): C++ unwinding runs the destructors
  #     of every intervening scope regardless of the exception's type.
  #   - a real Ruby `raise` crossing this frame: THE case `ensure` exists
  #     for, and the one that makes this whole approach viable rather
  #     than a narrower "runs on the easy paths" half-measure. It works
  #     only because mruby here is built with MRB_USE_CXX_EXCEPTION, so
  #     MRB_THROW is a real C++ `throw (mrb_jmpbuf*)` (include/mruby/
  #     throw.h) and unwinding through this frame really does run this
  #     destructor. Verified empirically on this repo's own submodule --
  #     a destructor between an mrb_raise and its catch point RAN under
  #     the project's real (cxx-exception) configuration and did NOT run
  #     under an otherwise-identical setjmp/longjmp build of the same
  #     sources. See docs/adr/0134 and build_config.rb's own wio section
  #     for why that configuration is load-bearing here and not
  #     incidental.
  #
  # The destructor cannot let anything escape (C++ terminates on an
  # exception leaving a destructor during unwinding), so the ensure body
  # runs under mrb_protect_error, which also -- importantly -- pops the
  # VM's own callinfo stack back to where it found it (src/vm.c's own
  # MRB_CATCH arm) and restores the GC arena to its entry index, leaving
  # the interpreter exactly as it was. Registers live BEFORE the guard
  # were allocated below that saved arena index, so the restore never
  # unprotects them.
  #
  # MRB_THROW below is include/mruby/throw.h's own macro, and that header
  # is not pulled in by <mruby.h> alone.
  puts '#include <mruby/throw.h>'
  # std::uncaught_exceptions() -- the guard's own "is an unwind already in
  # flight" test (see its comment below for why that, and not M->exc, is
  # the question that matters there).
  puts '#include <exception>'
  puts <<~'ENSURE_GUARD'
    template <class F>
    struct bc2cpp_ensure_guard {
      mrb_state* M;
      F fn;
      ~bc2cpp_ensure_guard() noexcept(false) {
        struct RObject* saved = M->exc;
        M->exc = NULL;
        /* M->exc is itself a GC root (src/gc.c's own mrb_gc_mark of it in
           both mark phases). Clearing it just above therefore removed the
           ONLY root keeping the in-flight exception alive -- the object
           may long since have been dropped from the GC arena by the
           ordinary mrb_gc_arena_restore every VM send already does. The
           ensure body allocates and so can trigger a real GC, which would
           then collect the very exception this guard is about to put
           back. Re-root it in the arena for the duration, BELOW the index
           mrb_protect_error saves and restores internally, so its own
           restore cannot drop this entry either.

           Found by the differential test, not by reading: it shows up
           only once enough allocation has happened to make a GC actually
           fire inside the ensure body, which is exactly the kind of
           silent, load-dependent corruption a wrong `ensure` translation
           produces. */
        int bc2cpp_ai = mrb_gc_arena_save(M);
        if (saved) mrb_gc_protect(M, mrb_obj_value(saved));
        mrb_bool err = FALSE;
        mrb_value raised = mrb_protect_error(M, [](mrb_state* m, void* ud) -> mrb_value {
          (*(F*)ud)();
          return mrb_nil_value();
        }, (void*)&fn, &err);
        if (!err) {
          /* Restore the real root FIRST, then drop our arena entry. */
          M->exc = saved;
          mrb_gc_arena_restore(M, bc2cpp_ai);
          return;
        }
        /* The ensure body itself raised. Real Ruby semantics: that
           exception SUPERSEDES whatever was already propagating. */
        M->exc = mrb_obj_ptr(raised);
        mrb_gc_arena_restore(M, bc2cpp_ai);
        if (std::uncaught_exceptions() == 0 && M->jmp != NULL) {
          /* Nothing was unwinding yet (normal or `return` exit), so
             nothing will carry this exception outward unless we start
             the unwind ourselves. Throwing here is safe for exactly
             that reason -- hence noexcept(false).

             The test is std::uncaught_exceptions(), NOT "was M->exc
             set": this file's OWN bc2cpp_block_break/
             bc2cpp_method_return unwind the C++ stack while M->exc
             stays NULL, so keying off M->exc would throw straight into
             an in-flight exception and std::terminate -- the classic
             throwing-destructor hazard, and a real one here rather than
             a hypothetical, since those two types cross exactly these
             frames. */
          MRB_THROW(M->jmp);
        }
        /* Otherwise an unwind is already in progress and simply
           continues, now carrying the superseding exception in M->exc. */
      }
    };
  ENSURE_GUARD
  # GETIDX's own String arm (see compile_insn's own comment on that opcode)
  # calls `mrb_str_aref` directly -- a real, non-static, externally-linked
  # function (3rd/mruby/src/string.c), but declared only in mruby/
  # internal.h, which -- unlike every other mruby header this file already
  # includes -- has no MRB_BEGIN_DECL/MRB_END_DECL C-linkage guard at all
  # (confirmed by reading the whole file, not assumed from its name):
  # #include-ing it here would declare `mrb_str_aref` with C++ linkage,
  # then fail to link against the plain-C symbol libmruby.a actually has.
  # A direct `extern "C"` forward declaration sidesteps needing that header
  # at all, matching the real signature exactly (3rd/mruby/include/mruby/
  # internal.h's own declaration).
  puts 'extern "C" mrb_value mrb_str_aref(mrb_state*, mrb_value, mrb_value, mrb_value);'
  # INTEGER_LSHIFT's kernel: exported by numeric.c but declared in no public header.
  puts 'extern "C" mrb_bool mrb_num_shift(mrb_state*, mrb_int, mrb_int, mrb_int*);'
  # DIV_FASTPATH_SUPPORT: same `mruby/internal.h`-has-no-C-linkage-guard
  # situation as `mrb_str_aref` just above -- `DIV`'s own compile_insn
  # case calls this directly (mruby.h's own `mrb_int` typedef is already
  # in scope by this point, matching that header's own declaration).
  puts 'extern "C" mrb_value mrb_div_int_value(mrb_state*, mrb_int, mrb_int);'
  # ZSUPER_NATIVE_SUPPORT: same `mruby/internal.h`-has-no-C-linkage-guard
  # situation as the two above -- the recognized `super` into
  # BasicObject#method_missing calls this directly (see
  # ZSUPER_NATIVE_TARGETS' own comment for why it calls THIS rather than the
  # `mrb_obj_missing` that wraps it). Declared exactly as
  # 3rd/mruby/include/mruby/internal.h:24 declares it, `mrb_noreturn`
  # included -- that attribute is what lets g++ see the unreachable RETURN
  # the next instruction compiles to for what it is, and mruby's own
  # `mrb_noreturn` (3rd/mruby/include/mruby/common.h) is already in scope
  # via mruby.h.
  puts 'extern "C" mrb_noreturn void mrb_method_missing(mrb_state*, mrb_sym, mrb_value, mrb_value);'
  # OTHER_DECLS_HEADER: shell-word-separated list of real file paths (each
  # another gem's own *_decls.h, written by this same OUT_DIR mechanism
  # below) to #include so a devirtualized call to an OTHER_OWNERS target
  # has a real declaration in scope -- paired with OTHER_OWNERS above.
  if ENV['OTHER_DECLS_HEADER']
    Shellwords.split(ENV['OTHER_DECLS_HEADER']).each { |path| puts "#include \"#{path}\"" }
  end
  puts ''
  print gen.emit_structs
  print gen.emit_ary_entry_helper(compiled)
  print gen.emit_bool_check_helper(compiled)
  print gen.emit_const_lookup_helper
  print gen.emit_native_construct_decls
  print gen.emit_direct_construct_decls
  print gen.emit_forward_decls(compiled)
  print gen.emit_instance_tt_setup
  print gen.emit_owner_class_cache
  print gen.emit_owner_registrations(compiled, BC2CPP_WIRED_EMBEDDINGS)
  # SYMBOL_CACHE: rewrite every function first, so the table is complete before
  # it is printed ahead of the code that uses it.
  symbol_table = SymbolCache::Table.new
  compiled.each { |m| m[:code] = SymbolCache.rewrite(m[:code], symbol_table) }
  const_site_cache_code = SymbolCache.rewrite(gen.emit_const_site_cache, symbol_table)
  print SymbolCache.emit(symbol_table)
  print const_site_cache_code
  compiled.each { |m| print m[:code] }

  # Write this run's own cross-TU declarations header, so a *different*
  # gem's own bc2cpp run can point its own OTHER_DECLS_HEADER at this file
  # and devirtualize into these entries -- see emit_decls_header's own
  # comment. Written unconditionally (cheap, and this run doesn't know in
  # advance whether anything will ever want it); only meaningful once some
  # other run actually references it via OTHER_DECLS_HEADER/OTHER_OWNERS.
  File.write(File.join(out_dir, "#{symbol}_decls.h"), gen.emit_decls_header(compiled))

  warn ''
  warn '== compiled entry points =='
  compiled.each do |m|
    # A hand-written register.cxx that just mrb_define_method's every entry
    # here would silently make a private/protected method public -- flagged
    # loudly (not just left to a code comment) since the whole point of
    # this listing is what a real registration needs to get right.
    vis =
      case m[:visibility]
      when :public then ''
      when :private then '  [private -- use mrb_define_private_method, not mrb_define_method]'
      when :protected then '  [protected -- mruby has no mrb_define_protected_method; ' \
                            'registering this with mrb_define_method makes it public, a real behavior change]'
      end
    # Follow-up (docs/adr/0139): an owner ending in ".singleton" is the
    # SDEF/SCLASS/unfused-DEF-singleton pseudo-owner build_registry writes
    # for a real `def self.x`/`class << self; def x; end; end` method (see
    # build_registry's own SDEF/SCLASS cases above) -- `self` at the real
    # call site is the CLASS object, not an instance, so registering one of
    # these with plain mrb_define_method (which installs onto the
    # receiver's own *instance* method table) would define it in the wrong
    # place entirely, reachable only as `SomeInstance.name` rather than
    # `ClassName.name`. mrb_define_class_method (3rd/mruby/include/
    # mruby.h -- installs onto the receiver's own singleton class instead,
    # exactly where SDEF/SCLASS put the real method) is the correct call;
    # unconditional, independent of the `visibility` switch above, since
    # this file never models `private_class_method`/singleton-method
    # privacy at all (every ".singleton"-owned MethodDef's own `visibility`
    # is always :public, see build_registry's own comment) -- a
    # `.singleton` owner and a private/protected instance method are
    # mutually exclusive on any one entry, so appending rather than
    # branching on `vis` is safe.
    singleton_note = m[:owner].end_with?('.singleton') ? '  [class method -- use mrb_define_class_method, ' \
                                                          'not mrb_define_method]' : ''
    warn "  #{m[:entry]} / #{m[:impl]}  (#{m[:owner]}##{m[:name]}, arity #{m[:arity]})#{vis}#{singleton_note}"
  end

  warn ''
  warn '== classes needing MRB_SET_INSTANCE_TT(..., MRB_TT_DATA) =='
  gen.embedding_classes.each { |k| warn "  #{k}" }

  # Step 6h's own diagnostic: every compiled entry point whose name is
  # never a call target anywhere in the whole program's own bytecode
  # (collect_static_call_target_names) and never a literal mrb_funcall
  # name anywhere in NATIVE_SRCS (extract_native_call_names) is a real
  # candidate for deletion -- not proof of it. This tool has no visibility
  # into a downstream game's own bundled Ruby scripts: RGSS's own
  # `Sprite`/`Window`/`Plane`/`Bitmap`/`Audio`/`Graphics`/`Input` classes
  # ARE the public scripting API those external, per-game "stock scripts"
  # call (see docs/rpgxp-rgss-api-gap.md's own measured usage counts for
  # `zoom_x`/`zoom_y`/`ox`/`oy`/`angle`/... ), so a name landing here from
  # one of those classes is the expected, correct shape for a public API
  # surface, not a bug -- only RPG2000/2003 (mruby-rpg2k/mruby-lcf) has no
  # equivalent external-script layer, so a name from those two gems is
  # much stronger evidence of real dead code. Either way: a real signal
  # worth surfacing every run, rather than re-deriving this by hand (a
  # rebuilt host mrbc, a bespoke script reusing this file's own parsing
  # pipeline, a manual cross-check against docs/rpgxp-rgss-api-gap.md) the
  # next time this question comes up.
  static_call_names = collect_static_call_target_names(ireps)
  native_call_names = ENV['NATIVE_SRCS'] ? extract_native_call_names(native_paths) : Set.new
  # A short, closed list of Ruby-language "magic" methods mruby's own C
  # core can call on any object independent of any literal call site
  # anywhere in this program or in NATIVE_SRCS -- #initialize is the
  # everyday case: mrb_obj_new/mrb_instance_new (3rd/mruby/src/class.c)
  # call it through a `mrb_sym mid = MRB_SYM(initialize)` local variable a
  # few lines above their own mrb_funcall_argv call, invisible to
  # extract_native_call_names' own bounded lookahead (which only looks
  # forward from the mrb_funcall* call site itself, not backward through
  # arbitrary local-variable assignments). Every entry below has a real,
  # confirmed call site in this project's own 3rd/mruby/src via this same
  # indirect pattern -- checked directly, not guessed: `initialize`/
  # `initialize_copy` in class.c (mrb_obj_new, mrb_instance_new,
  # mrb_obj_init_copy, mrb_class_new_class); `method_missing`/
  # `respond_to_missing?` in vm.c/kernel.c/class.c; `to_s`/`inspect` in
  # kernel.c/array.c; `==`/`eql?`/`<=>`/`hash` in object.c/array.c/
  # kernel.c/numeric.c/hash.c; `call` in hash.c (a Hash's own default
  # Proc). Deliberately short -- e.g. `coerce`/`each`/`to_ary`/`to_str`/
  # `to_int`/`to_hash`/`[]` were checked too and dropped: this mruby 4.0
  # build's own core never reaches for them via mrb_funcall at all (no
  # generic implicit-conversion-protocol dispatch in this leaner core),
  # so claiming them "always reachable" here would be exactly the kind of
  # unverified guess this file's own design avoids everywhere else.
  always_reachable = %w[
    initialize initialize_copy
    method_missing respond_to_missing?
    to_s inspect
    == eql? <=> hash
    call
  ].to_set
  reachable_names = static_call_names | native_call_names | always_reachable
  never_called = compiled.reject { |m| reachable_names.include?(m[:name]) }
  warn ''
  warn "== never called (#{never_called.size} of #{compiled.size} compiled entry points -- " \
       "zero evidence in this program's own bytecode or NATIVE_SRCS; see Step 6h's own comment) =="
  if never_called.empty?
    warn '  (none)'
  else
    never_called.each { |m| warn "  #{m[:owner]}##{m[:name]}" }
  end
end
